_ip_hits: dict = {}             # ip -> deque[monotonic]  (데이터 경로 접근만)
_VELOCITY_WINDOW = 60.0
_VELOCITY_MAX = 900            # 분당 900건(=15/s 지속). CGNAT 공유IP 오차단 방지 상향.

# ── 단지 순회 스크레이퍼 방어 ────────────────────────────────────────────
# 속도만 보면 못 잡는다. 실제로 잡힌 스크레이퍼는 초당 3.3회(분당 200)로 느긋하게
# 돌면서 5일간 매일 9,500건씩 긁어갔다 — 속도 임계(900/분) 한참 아래다.
# 사람과 갈리는 축은 '속도'가 아니라 **얼마나 많은 서로 다른 단지를 보는가**다.
# 실측(3일): 사람 최대 276개/시간, 스크레이퍼 1,399~4,828개/시간. 그 사이를 끊는다.
_DIVERSITY_MAX = 400            # 시간당 서로 다른 단지 수
_ip_complexes: dict = {}        # ip -> (윈도우_시작_monotonic, set(complex_no))
_BLOCK_FILE = Path(__file__).resolve().parent.parent / "data" / "ip_blocklist.txt"
_blocked_ips: set = set()


def _load_blocklist() -> None:
    """차단 IP 목록을 파일에서 읽는다. 재시작(배포)해도 유지돼야 한다."""
    try:
        if _BLOCK_FILE.exists():
            _blocked_ips.update(
                ln.split("#")[0].strip() for ln in _BLOCK_FILE.read_text().splitlines()
                if ln.split("#")[0].strip())
    except Exception:  # noqa: BLE001
        pass


def _block_ip(ip: str, why: str) -> None:
    if not ip or ip in _blocked_ips:
        return
    _blocked_ips.add(ip)
    try:
        _BLOCK_FILE.parent.mkdir(parents=True, exist_ok=True)
        with _BLOCK_FILE.open("a") as f:
            f.write(f"{ip}  # {why} {_dt_now()}\n")
    except Exception:  # noqa: BLE001 — 기록 실패해도 메모리 차단은 유효
        pass


def _dt_now() -> str:
    import datetime as _d
    return (_d.datetime.now(_d.timezone.utc) + _d.timedelta(hours=9)).strftime("%Y-%m-%d %H:%M")


def _diversity_exceeded(ip: str, path: str, now: float) -> bool:
    """한 시간 안에 서로 다른 단지를 몇 개나 열었는지. 임계를 넘으면 사람이 아니다."""
    m = _re_complex_id.search(path)
    if not m:
        return False
    start, seen = _ip_complexes.get(ip, (now, None))
    if seen is None or now - start > 3600:
        start, seen = now, set()
        _ip_complexes[ip] = (start, seen)
    seen.add(m.group(1))
    if len(_ip_complexes) > 20000:          # 메모리 상한 — 지난 창은 버린다
        for k, (st, _s) in list(_ip_complexes.items()):
            if now - st > 3600:
                _ip_complexes.pop(k, None)
    return len(seen) > _DIVERSITY_MAX


_re_complex_id = _re_bot.compile(r"^/complex(?:es)?/(\d+)")
_load_blocklist()

def _goodbot_key(ua: str):
    m = _GOODBOT_UA.search(ua)
    if not m:
        return None
    t = m.group(1).lower()
    for k in _GOODBOT_RDNS:
        if t.startswith(k):
            return k
    if t.startswith("yandex"):
        return "yandex"
    return None

def _verify_goodbot(ip: str, key: str) -> bool:
    """rDNS 정·역방향 확인. 블로킹 소켓이라 호출부에서 스레드풀로 감싼다."""
    try:
        host = _socket.gethostbyaddr(ip)[0].lower()
    except Exception:
        return False
    if not any(host.endswith(sfx) for sfx in _GOODBOT_RDNS.get(key, ())):
        return False
    try:
        _, _, addrs = _socket.gethostbyname_ex(host)
        return ip in addrs
    except Exception:
        return False

def _is_internal_ip(ip) -> bool:
    if not ip:
        return True   # localhost 직행(warm_api·testclient) — client 없음
    return (ip in ("127.0.0.1", "::1") or ip.startswith(("10.", "192.168.", "127."))
            or ip.startswith(("172.16.", "172.17.", "172.18.", "172.19.", "172.2", "172.30.", "172.31.")))

def _is_data_path(path: str) -> bool:
    # /seo 는 검색봇 동적 렌더링 전용(공개 기본정보만) — 크롤러에게 주려고 만든 엔드포인트라
    # 봇가드 대상에서 뺀다. CF Workers fetch 가 UA 를 안 붙여 empty_ua 로 자기차단되며
    # SEO/OG 프리렌더가 통째로 무력화됐던 원인(2026-07-20 실측 하루 2,136건).
    if path.endswith("/seo"):
        return False
    return path.startswith(("/stats/", "/complex/", "/complexes/", "/nonresi/",
                            "/realtors/", "/map", "/q/", "/ai/")) or path in ("/q",)

def _velocity_exceeded(ip: str, now: float) -> bool:
    dq = _ip_hits.get(ip)
    if dq is None:
        dq = _ip_hits[ip] = _deque()
    cutoff = now - _VELOCITY_WINDOW
    while dq and dq[0] < cutoff:
        dq.popleft()
    dq.append(now)
    if len(_ip_hits) > 20000:      # 메모리 상한 — 오래된 IP 정리
        for k in [k for k, v in list(_ip_hits.items()) if not v or v[-1] < cutoff]:
            _ip_hits.pop(k, None)
    return len(dq) > _VELOCITY_MAX

@app.middleware("http")
async def _bot_guard_middleware(request, call_next):
    if not _BOT_GUARD_ON or request.method not in ("GET", "HEAD"):
        return await call_next(request)
    path = request.url.path
    if path in ("/health",) or not _is_data_path(path):
        return await call_next(request)   # 데이터 경로만 심사(HTML·정적·기타 무영향)
    try:
        ip = _client_ip(request)
        if _is_internal_ip(ip):
            request.state.bot_class = "self"
            return await call_next(request)  # 내부(warm) — 헤더 불필요
        ua = (request.headers.get("user-agent") or "").strip()

        # 한 번 스크레이퍼로 확정된 IP는 계속 막는다(재시작해도 파일에서 되읽는다)
        if ip in _blocked_ips:
            return _deny(403, "blocklist", ip, ua, path, request.method)

        # ⓪ AI 학습·검색 크롤러 → 권리 유보 경고와 함께 차단(규약 준수 봇은 수집 중단)
        if _AI_CRAWLER_UA.search(ua):
            return _deny(403, "ai_crawler", ip, ua, path, request.method)

        # ① 빈 UA로 데이터 API 접근 = 비브라우저 자동화 → 차단
        if not ua:
            return _deny(403, "empty_ua", ip, "", path, request.method)

        # ② 검색봇 사칭 검증
        key = _goodbot_key(ua)
        if key:
            hit = _bot_cache.get(ip)
            now = _time.monotonic()
            if hit and hit[1] > now:
                verified = hit[0]
            else:
                import asyncio as _aio
                verified = await _aio.get_event_loop().run_in_executor(None, _verify_goodbot, ip, key)
                _bot_cache[ip] = (verified, now + (21600 if verified else 3600))
                if len(_bot_cache) > 50000:
                    _bot_cache.clear()
            if not verified:
                return _deny(403, f"fake_{key}", ip, ua, path, request.method)
            request.state.bot_class = f"goodbot:{key}"
            return _mark_usage(await call_next(request))   # 검증된 정상봇 — 스로틀 면제

        if _SOFTBOT_UA.search(ua):
            request.state.bot_class = "softbot"
            return _mark_usage(await call_next(request))   # 링크 미리보기 등 — 통과(태깅만)

        # ③ 스크레이퍼/자동화 도구 UA — 데이터 경로 접근 차단(UA기반=CGNAT 무관 고정밀)
        if _SCRAPER_UA.search(ua):
            return _deny(403, "scraper_ua", ip, ua, path, request.method)

        # ④ 속도 백스톱 — 브라우저 UA 사칭 스크레이퍼용. 로그인 사용자는 면제(CGNAT 보호).
        authed = bool(request.headers.get("authorization"))
        _now = _time.monotonic()
        if not authed and _velocity_exceeded(ip, _now):
            return _deny(429, "velocity", ip, ua, path, request.method)
        # ⑤ 단지 순회 백스톱 — 브라우저 UA를 쓰고 느긋하게 도는 스크레이퍼를 잡는다.
        #    사람이 한 시간에 단지 400곳을 열어 볼 일은 없다. 한 번 걸리면 목록에 박는다.
        if not authed and _diversity_exceeded(ip, path, _now):
            _block_ip(ip, "단지순회")
            return _deny(403, "diversity", ip, ua, path, request.method)
        request.state.bot_class = "client"
    except Exception:      # noqa: BLE001 — 가드 오류는 절대 사이트를 막지 않는다
        return await call_next(request)
    return _mark_usage(await call_next(request))


class Filter(BaseModel):
    op: Literal["eq", "in", "ilike"]
    col: str
    val: Any


class Order(BaseModel):
    col: str
    ascending: bool = True


class QueryReq(BaseModel):
    table: str
    select: str = "*"
    filters: list[Filter] = Field(default_factory=list)
    order: Order | None = None
    limit: int | None = None
    single: bool = False


def _open_db() -> sqlite3.Connection:
    c = sqlite3.connect(DB_PATH, timeout=10)
    c.row_factory = sqlite3.Row
    # 서빙 성능: DB 파일을 memory-map 해 OS 페이지캐시에 핫셋(롤업·인덱스) 상주 →
    # 콜드/캐시미스 쿼리도 디스크바운드 탈출. 워머(_warmer_loop)가 주기적으로 데움.
    try:
        c.execute("PRAGMA mmap_size=6000000000")   # ~6GB memory-map
        c.execute("PRAGMA cache_size=-65536")       # 64MB per-conn page cache
        # temp_store=MEMORY 는 quick-deals 등 대형 GROUP BY 의 temp B-tree 를 RAM 에
        # 쌓아 OOM(6GB+) 유발 → 기본값(파일 temp) 유지. mmap 으로 충분히 빠름.
        c.execute("PRAGMA busy_timeout=5000")
        # WAL 파일 상한 1GB — 체크포인트 후 자동 축소. 라이브 리더가 WAL을 11GB로
        # 고착시키던 문제 방지(무중단). writer(collector.open_db)에도 동일 설정.
        c.execute("PRAGMA journal_size_limit=1073741824")
    except Exception:
        pass
    return c


# 실거래 평형평균 사전집계(tx_avg_rollup, build_tx_rollups.py) 사용 여부.
# False 면 quick_deals 가 레거시(라이브 매칭) 경로로 돌아간다 — 검증/비상용.
USE_TX_ROLLUP = True
_rollup_ok: bool | None = None


def _rollup_ready() -> bool:
    """tx_avg_rollup 존재+비어있지 않음 확인(성공 시 메모이즈)."""
    global _rollup_ok
    if _rollup_ok:
        return True
    try:
        with _open_db() as c:
            r = c.execute("SELECT EXISTS(SELECT 1 FROM tx_avg_rollup LIMIT 1)").fetchone()
        _rollup_ok = bool(r and r[0])
    except sqlite3.Error:
        _rollup_ok = False
    return _rollup_ok


# ── Supabase 카카오 로그인 세션 검증 + 관리자 식별 ──────────────────
# 관리자 엔드포인트들이 admin_user 의존성을 쓰므로 파일 앞부분에 정의한다.
# 프런트는 Supabase Auth(카카오)로 로그인하고 access_token(JWT)을 Bearer 로 보냄.
# JWT 시크릿을 직접 다루지 않고 Supabase /auth/v1/user 로 위임 검증.
import json as _authjson
import urllib.error as _urlerr
import urllib.request as _urlreq


def _kakao_display_name(user: dict) -> str:
    meta = user.get("user_metadata") or {}
    for k in ("name", "full_name", "nickname", "user_name", "preferred_username"):
        v = meta.get(k)
        if v:
            return str(v)[:40]
    email = user.get("email")
    if email:
        return email.split("@")[0][:40]
    return "익명"


def _admin_email_set() -> set:
    return {e.strip().lower() for e in (settings.admin_emails or "").split(",") if e.strip()}


def _is_admin(email: str | None) -> bool:
    return bool(email) and email.lower() in _admin_email_set()


def _admin_uid_set() -> set:
    return {u.strip() for u in (settings.admin_user_ids or "").split(",") if u.strip()}


def _is_admin_uid(user_id: str | None) -> bool:
    """user_id 기준 관리자 여부 — 글/리뷰 작성자에 '관리자' 뱃지 표시용."""
    return bool(user_id) and user_id in _admin_uid_set()


def current_user(authorization: str | None = Header(default=None)) -> dict:
    """로그인 필수 엔드포인트용 의존성. 유효한 Supabase 세션이면 사용자 정보 반환."""
    if not settings.supabase_url or not settings.supabase_anon_key:
        raise HTTPException(503, "로그인 서버(Supabase)가 설정되지 않았습니다")
    if not authorization or not authorization.lower().startswith("bearer "):
        raise HTTPException(401, "로그인이 필요합니다")
    token = authorization.split(" ", 1)[1].strip()
    req = _urlreq.Request(
        f"{settings.supabase_url}/auth/v1/user",
        headers={"Authorization": f"Bearer {token}", "apikey": settings.supabase_anon_key},
    )
    try:
        with _urlreq.urlopen(req, timeout=8) as resp:
            user = _authjson.loads(resp.read().decode("utf-8"))
    except _urlerr.HTTPError:
        raise HTTPException(401, "유효하지 않은 세션입니다. 다시 로그인해주세요.")
    except _urlerr.URLError:
        raise HTTPException(502, "로그인 서버에 연결할 수 없습니다")
    uid = user.get("id")
    if not uid:
        raise HTTPException(401, "유효하지 않은 세션입니다")
    email = (user.get("email") or "").lower()
    meta = user.get("user_metadata") or {}
    app_meta = user.get("app_metadata") or {}
    return {
        "id": uid,
        "name": _kakao_display_name(user),
        "email": email,
        "phone": user.get("phone") or meta.get("phone") or meta.get("phone_number"),
        "avatar": meta.get("avatar_url") or meta.get("picture"),
        "provider": app_meta.get("provider"),  # kakao | google | email ...
        "is_admin": _is_admin(email),
    }


def current_user_optional(authorization: str | None = Header(default=None)) -> dict | None:
    """로그인 선택 엔드포인트용 — 토큰 없거나 무효면 None(401 대신). 토론장 읽기 등."""
    if not authorization or not authorization.lower().startswith("bearer "):
        return None
    try:
        return current_user(authorization)
    except HTTPException:
        return None


def admin_user(user: dict = Depends(current_user)) -> dict:
    """관리자 전용 엔드포인트 의존성. 로그인 + ADMIN_EMAILS 목록에 있어야 통과."""
    if not user.get("is_admin"):
        raise HTTPException(403, "관리자 전용 기능입니다.")
    return user


def verified_user(user: dict = Depends(current_user)) -> dict:
    """전화번호 인증 완료 사용자만 통과. AI 등 인증 필수 기능용.

    미인증이면 403(code=phone_required) — 프런트는 전화번호 인증 안내로 유도.
    """
    with _reviews_db() as c:
        row = c.execute("SELECT phone_verified FROM user_profiles WHERE user_id=?",
                        (user["id"],)).fetchone()
    if not (row and row[0]):
        raise HTTPException(403, detail={
            "code": "phone_required",
            "message": "AI 서비스는 전화번호 인증 후 이용할 수 있어요.",
        })
    return user


# ── Play 심사용 데모 로그인 ──────────────────────────────────────────────
# Google Play 심사자가 OAuth 없이 로그인-게이트 기능(AI 등)을 검토할 수 있게,
# 비밀키가 든 URL로 데모 계정 세션을 발급한다. 비번은 서버에만 있고 프런트 번들엔 노출 안 됨.
_DEMO_EMAIL = "demo.review@koczip.com"
_DEMO_PASSWORD = "KoczipDemo2026!"
_DEMO_KEY = "play-review-2026"   # ?demo=<이 값> 일 때만 발급

@app.get("/auth/demo-login")
def demo_login(key: str = ""):
    """심사용 데모 세션 발급. key 일치 시 데모 계정 password grant → 토큰 반환."""
    if key != _DEMO_KEY:
        raise HTTPException(403, "invalid demo key")
    if not settings.supabase_url or not settings.supabase_anon_key:
        raise HTTPException(503, "auth not configured")
    body = _authjson.dumps({"email": _DEMO_EMAIL, "password": _DEMO_PASSWORD}).encode()
    req = _urlreq.Request(
        f"{settings.supabase_url}/auth/v1/token?grant_type=password",
        data=body,
        headers={"apikey": settings.supabase_anon_key, "Content-Type": "application/json"},
        method="POST")
    try:
        with _urlreq.urlopen(req, timeout=10) as resp:
            t = _authjson.loads(resp.read().decode("utf-8"))
    except _urlerr.HTTPError as e:
        raise HTTPException(502, f"demo login failed: {e.code}")
    return {"access_token": t.get("access_token"), "refresh_token": t.get("refresh_token"),
            "expires_in": t.get("expires_in")}


def _validate_cols(table: str, cols_str: str) -> str:
    s = cols_str.strip()
    if s == "*":
        return "*"
    parts = [p.strip() for p in s.split(",")]
    allowed = TABLE_COLUMNS[table]
    for p in parts:
        if p not in allowed:
            raise HTTPException(400, f"unknown column '{p}' on {table}")
    return ", ".join(f'"{p}"' for p in parts)


# SQLite caps bound parameters at 32766. Stay well under for IN filters so
# we don't hit the limit when other filters also bind params.
IN_CHUNK = 20000


def _build_where(
    table: str,
    other: list[Filter],
    extra_in: tuple[str, list[Any]] | None,
) -> tuple[str, list[Any]]:
    where_parts: list[str] = []
    params: list[Any] = []
    for f in other:
        if f.op == "eq":
            where_parts.append(f'"{f.col}" = ?')
            params.append(f.val)
        elif f.op == "in":
            ph = ",".join(["?"] * len(f.val))
            where_parts.append(f'"{f.col}" IN ({ph})')
            params.extend(f.val)
        elif f.op == "ilike":
            # SQLite LIKE is ASCII case-insensitive, fine for Korean.
            where_parts.append(f'"{f.col}" LIKE ?')
            params.append(f.val)
    if extra_in is not None:
        col, vals = extra_in
        ph = ",".join(["?"] * len(vals))
        where_parts.append(f'"{col}" IN ({ph})')
        params.extend(vals)
    where_sql = (" WHERE " + " AND ".join(where_parts)) if where_parts else ""
    return where_sql, params


@app.post("/q")
def query(req: QueryReq):
    # 느린 /q 진단용 — POST 본문은 미들웨어 로그에 안 남아 테이블을 알 수 없었음.
    # 1초 초과 시에만 kind=slow_q 로 테이블·필터를 기록한다.
    _q_t0 = _time.perf_counter()
    try:
        return _query_impl(req)
    finally:
        _q_ms = int((_time.perf_counter() - _q_t0) * 1000)
        if _q_ms >= 1000:
            _log_event("slow_q", path="/q", method="POST", duration_ms=_q_ms,
                       detail={"table": req.table,
                               "filters": [{"op": f.op, "col": f.col,
                                            "val": (f.val if not isinstance(f.val, list)
                                                    else f"[{len(f.val)} items]")}
                                           for f in req.filters],
                               "order": (req.order.col if req.order else None),
                               "limit": req.limit, "single": req.single})


def _query_impl(req: QueryReq):
    if req.table not in ALLOWED_TABLES:
        raise HTTPException(400, f"table not allowed: {req.table}")
    col_sql = _validate_cols(req.table, req.select)
    for f in req.filters:
        if f.col not in TABLE_COLUMNS[req.table]:
            raise HTTPException(400, f"filter on unknown column '{f.col}'")
        if f.op == "in" and not isinstance(f.val, list):
            raise HTTPException(400, "'in' value must be a list")

    # An IN filter with too many values is split into per-chunk queries;
    # ordering + limit are then applied in memory after the union.
    big_in: Filter | None = None
    other: list[Filter] = []
    for f in req.filters:
        if f.op == "in" and not f.val:
            return {"data": (None if req.single else []), "error": None}
        if f.op == "in" and isinstance(f.val, list) and len(f.val) > IN_CHUNK and big_in is None:
            big_in = f
        else:
            other.append(f)

    order_sql = ""
    if req.order:
        if req.order.col not in TABLE_COLUMNS[req.table]:
            raise HTTPException(400, f"order on unknown column '{req.order.col}'")
        order_sql = f' ORDER BY "{req.order.col}" {"ASC" if req.order.ascending else "DESC"}'
    if req.single:
        limit_sql = " LIMIT 1"
    elif req.limit is not None:
        if req.limit < 0 or req.limit > 200000:
            raise HTTPException(400, "limit out of range")
        limit_sql = f" LIMIT {int(req.limit)}"
    else:
        limit_sql = ""

    with _open_db() as c:
        if big_in is None:
            where_sql, params = _build_where(req.table, other, None)
            sql = f'SELECT {col_sql} FROM "{req.table}"{where_sql}{order_sql}{limit_sql}'
            rows = c.execute(sql, params).fetchall()
        else:
            rows = []
            vals_all: list[Any] = big_in.val
            for i in range(0, len(vals_all), IN_CHUNK):
                where_sql, params = _build_where(
                    req.table, other, (big_in.col, vals_all[i:i + IN_CHUNK])
                )
                sql = f'SELECT {col_sql} FROM "{req.table}"{where_sql}'
                rows.extend(c.execute(sql, params).fetchall())
            if req.order:
                col_name = req.order.col
                rows.sort(
                    key=lambda r: (r[col_name] is None, r[col_name]),
                    reverse=not req.order.ascending,
                )
            if req.single:
                rows = rows[:1]
            elif req.limit is not None:
                rows = rows[: req.limit]

    data = [dict(r) for r in rows]
    if req.single:
        return {"data": data[0] if data else None, "error": None}
    return {"data": data, "error": None}


@app.get("/stats/top-complexes")
def top_complexes(days: int = 7, limit: int = 5):
    """Top-N complexes by recent (deal_ymd >= today-days) filing count,
    split by trade type. Same contract-date window as /stats/recent-tx.
    Unmatched rows are skipped — the rank is over identified complexes only.
    """
    if days < 1 or days > 365:
        raise HTTPException(400, "days out of range")
    if limit < 1 or limit > 50:
        raise HTTPException(400, "limit out of range")

    cutoff = f"-{days} days"
    result = {"days": days, "sale": [], "jeonse": [], "wolse": []}
    with _open_db() as c:
        existing = {
            r[0]
            for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")
        }

        def _run(unions: list[str], params: list) -> list[dict]:
            if not unions:
                return []
            sql = (
                "WITH agg AS (SELECT matched_complex_no AS cno, COUNT(*) AS n "
                "FROM (" + " UNION ALL ".join(unions) + ") "
                "WHERE matched_complex_no IS NOT NULL "
                "GROUP BY matched_complex_no) "
                "SELECT agg.cno, c.complex_name, agg.n "
                "FROM agg LEFT JOIN complexes c ON c.complex_no = agg.cno "
                "ORDER BY agg.n DESC LIMIT ?"
            )
            rows = c.execute(sql, [*params, limit]).fetchall()
            return [{"complex_no": r[0], "complex_name": r[1], "count": r[2]} for r in rows]

        sale_u, sale_p = [], []
        if "transactions" in existing:
            sale_u.append("SELECT matched_complex_no FROM transactions WHERE deal_ymd >= date('now','+9 hours', ?) AND is_cancelled = 0")
            sale_p.append(cutoff)
        if "offi_transactions" in existing:
            sale_u.append("SELECT matched_complex_no FROM offi_transactions WHERE deal_ymd >= date('now','+9 hours', ?) AND is_cancelled = 0")
            sale_p.append(cutoff)
        result["sale"] = _run(sale_u, sale_p)

        jeonse_u, jeonse_p = [], []
        if "rentals" in existing:
            jeonse_u.append("SELECT matched_complex_no FROM rentals WHERE deal_ymd >= date('now','+9 hours', ?) AND +monthly_rent = 0")
            jeonse_p.append(cutoff)
        if "offi_rentals" in existing:
            jeonse_u.append("SELECT matched_complex_no FROM offi_rentals WHERE deal_ymd >= date('now','+9 hours', ?) AND +monthly_rent = 0")
            jeonse_p.append(cutoff)
        result["jeonse"] = _run(jeonse_u, jeonse_p)

        wolse_u, wolse_p = [], []
        if "rentals" in existing:
            wolse_u.append("SELECT matched_complex_no FROM rentals WHERE deal_ymd >= date('now','+9 hours', ?) AND +monthly_rent > 0")
            wolse_p.append(cutoff)
        if "offi_rentals" in existing:
            wolse_u.append("SELECT matched_complex_no FROM offi_rentals WHERE deal_ymd >= date('now','+9 hours', ?) AND +monthly_rent > 0")
            wolse_p.append(cutoff)
        result["wolse"] = _run(wolse_u, wolse_p)

    return result


