def _cx_compare_one(d, complex_no: str, area: str | None = None) -> dict:
    """단지비교용 단일 단지 지표 묶음 — 전부 complex_no 인덱스 쿼리라 빠름.
    area=평형명(complex_areas.pyeong_name) 지정 시 호가·실거래·시리즈를 그 평형으로 한정
    (실거래는 해당 평형 전용면적 ±1.5㎡ 매칭 — 전역 관례)."""
    cx = d.execute(
        "SELECT complex_name, total_household_count, use_approve_ymd, construction_company, "
        "  total_building_count, parking_per_household, real_estate_type_name, cortar_no "
        "FROM complexes WHERE complex_no=?", (complex_no,)).fetchone()
    if not cx:
        raise HTTPException(404, f"complex not found: {complex_no}")
    reg = d.execute(
        "SELECT rsi.cortar_name, rsg.cortar_name, rdo.cortar_name FROM complexes cx "
        "LEFT JOIN regions rsi ON rsi.cortar_no=substr(cx.cortar_no,1,2)||'00000000' "
        "LEFT JOIN regions rsg ON rsg.cortar_no=substr(cx.cortar_no,1,5)||'00000' "
        "LEFT JOIN regions rdo ON rdo.cortar_no=cx.cortar_no WHERE cx.complex_no=?",
        (complex_no,)).fetchone()
    region = " ".join(x for x in [
        (_SIDO_SHORT.get(reg[0], reg[0]) if reg else None),
        (reg[1] if reg else None), (reg[2] if reg else None)] if x)

    areas = d.execute(
        "SELECT pyeong_name, supply_area, exclusive_area, household_count "
        "FROM complex_areas WHERE complex_no=? ORDER BY supply_area", (complex_no,)).fetchall()
    area_row = next((r for r in areas if r[0] == area), None) if area else None
    excl = area_row[2] if area_row else None
    # 평형 선택 시 세대수·회전율 분모도 그 평형 기준으로
    hh_eff = (area_row[3] if area_row and area_row[3] else None) or (cx[1] or 0)
    la = " AND area_name=?" if area else ""
    la_args = [area] if area else []
    tx_area = " AND excl_use_ar BETWEEN ? AND ?" if excl is not None else ""
    tx_area_args = [excl - 1.5, excl + 1.5] if excl is not None else []

    snap = d.execute("SELECT MAX(snapshot_date) FROM complex_daily_agg WHERE complex_no=?",
                     (complex_no,)).fetchone()[0]
    listings = {}
    if snap:
        for t, n, u, pmin, pavg, ravg in d.execute(
            "SELECT trade_type, SUM(listing_count), CAST(SUM(unit_count) AS INT), MIN(price_min), "
            "  CAST(SUM(price_avg*listing_count)/SUM(listing_count) AS INT), "
            "  CAST(SUM(COALESCE(rent_avg,0)*listing_count)/SUM(listing_count) AS INT) "
            f"FROM complex_daily_agg WHERE complex_no=? AND snapshot_date=?{la} GROUP BY trade_type",
            [complex_no, snap] + la_args):
            listings[t] = {"n": n, "units": u, "min": pmin, "avg": pavg,
                           "rent_avg": (ravg if t == "B2" else None)}
    a1 = listings.get("A1", {}).get("avg")
    b1 = listings.get("B1", {}).get("avg")
    jeonse_rate = round(b1 / a1 * 100, 1) if a1 and b1 else None
    gap = (a1 - b1) if a1 and b1 else None

    tx = d.execute(
        "SELECT COUNT(*), CAST(AVG(CASE WHEN deal_ymd>=date('now','+9 hours','-6 months') THEN deal_amount END) AS INT), "
        "  CAST(AVG(CASE WHEN deal_ymd>=date('now','+9 hours','-6 months') AND excl_use_ar>0 "
        "      THEN deal_amount/excl_use_ar*3.3 END) AS INT) "
        "FROM transactions WHERE matched_complex_no=? AND is_cancelled=0 "
        f"  AND deal_ymd>=date('now','+9 hours','-12 months'){tx_area}",
        [complex_no] + tx_area_args).fetchone()
    latest = d.execute(
        "SELECT deal_ymd, deal_amount, excl_use_ar, floor FROM transactions "
        f"WHERE matched_complex_no=? AND is_cancelled=0{tx_area} ORDER BY deal_ymd DESC LIMIT 1",
        [complex_no] + tx_area_args).fetchone()
    rec = d.execute(
        "SELECT record_price, record_date, area_key FROM tx_record_rollup "
        "WHERE complex_no=? AND kind IN ('sale','silv','offi_sale') "
        + ("  AND CAST(area_key AS REAL) BETWEEN ? AND ? " if excl is not None else "")
        + "ORDER BY record_price DESC LIMIT 1",
        [complex_no] + tx_area_args).fetchone()
    hh = hh_eff
    n12 = tx[0] or 0

    sub = d.execute("SELECT station_name, lines, walk_min FROM complex_subway WHERE complex_no=?",
                    (complex_no,)).fetchone()
    sch = d.execute("SELECT school_name, walk_min FROM complex_school WHERE complex_no=?",
                    (complex_no,)).fetchone()
    n_realtor = d.execute(
        "SELECT COUNT(DISTINCT realtor_id) FROM listings_current WHERE complex_no=? AND realtor_id!=''",
        (complex_no,)).fetchone()[0]

    series = [
        {"d": r[0], "n": r[1], "u": (int(r[2]) if r[2] is not None else None), "avg": r[3]}
        for r in d.execute(
            "SELECT snapshot_date, SUM(listing_count), SUM(unit_count), "
            "  CAST(SUM(price_avg*listing_count)/SUM(listing_count) AS INT) "
            "FROM complex_daily_agg WHERE complex_no=? AND trade_type='A1' "
            f"  AND snapshot_date>=date('now','+9 hours','-31 days'){la} GROUP BY snapshot_date ORDER BY 1",
            [complex_no] + la_args)]

    return {
        "complex_no": complex_no, "name": cx[0], "region": region,
        "area": area, "areas": [
            {"name": r[0], "supply": r[1], "excl": r[2], "hh": r[3]} for r in areas],
        "built": (cx[2] or "")[:4] or None, "households": hh_eff, "buildings": cx[4],
        "parking": cx[5], "builder": cx[3], "type": cx[6],
        "listings": listings, "jeonse_rate": jeonse_rate, "gap": gap,
        "tx": {"n12": n12, "avg6m": tx[1], "pyeong6m": tx[2],
               "latest": ({"date": latest[0], "price": latest[1], "area": latest[2],
                           "floor": latest[3]} if latest else None),
               "record": ({"price": rec[0], "date": rec[1], "area": rec[2]} if rec else None),
               "turnover": (round(n12 / hh * 100, 1) if hh else None)},
        "subway": ({"station": sub[0], "lines": sub[1], "walk": sub[2]} if sub else None),
        "school": ({"name": sch[0], "walk": sch[1]} if sch else None),
        "n_realtors": n_realtor,
        "series": series,
    }


def _cx_price_series(d, complex_no: str, months: int = 24):
    """단지비교 차트용 월별 실거래 시세 — 서로 다른 가격대 단지도 한 차트에서
    '어떻게 움직였나'를 보려고 평당 실거래가(평균가)와 지수(첫 유효월=100)를 함께 낸다.
    거래 없는 달은 건너뛰고(프런트에서 월축 병합), 해제거래 제외."""
    rows = d.execute(
        "SELECT substr(deal_ymd,1,7) ym, COUNT(*), "
        "  CAST(AVG(deal_amount) AS INT), "
        "  CAST(AVG(deal_amount/excl_use_ar*3.3) AS INT) "
        "FROM transactions WHERE matched_complex_no=? AND is_cancelled=0 AND excl_use_ar>0 "
        f"  AND deal_ymd>=date('now','+9 hours','-{int(months)} months') "
        "GROUP BY ym ORDER BY ym",
        (complex_no,)).fetchall()
    base = next((r[3] for r in rows if r[3]), None)  # 첫 유효 평당가 = 지수 기준
    return [
        {"ym": r[0], "n": r[1], "avg": r[2], "pyeong": r[3],
         "idx": (round(r[3] / base * 100, 1) if base and r[3] else None)}
        for r in rows]


@app.get("/stats/complex-compare-multi")
def complex_compare_multi(ids: str):
    """단지 N개(2~4개) 비교 — complex_no 를 콤마로. 팝업 비교용.
    2개 비교(complex-compare)와 같은 _cx_compare_one 스키마 + price_series(월별 실거래 추이)."""
    cnos = [x.strip() for x in (ids or "").split(",") if x.strip()][:4]
    if len(cnos) < 2:
        return {"items": []}
    _ck = "cxcmpmulti:" + ",".join(cnos)
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    out = []
    with _open_db() as d:
        for no in cnos:
            try:
                one = _cx_compare_one(d, no, None)
            except Exception:
                continue
            try:
                one["quick_deals"] = len(complex_quick_deals(no)["items"])
            except Exception:
                one["quick_deals"] = None
            try:
                one["price_series"] = _cx_price_series(d, no)
            except Exception:
                one["price_series"] = []
            out.append(one)
    res = {"items": out}
    _cache_put(_ck, res)
    return res


@app.get("/stats/complex-compare")
def complex_compare(a: str, b: str, a_area: str = "", b_area: str = ""):
    """단지비교: 두 단지의 개요·호가·실거래·유동성·입지 지표를 동일 스키마로.
    a_area/b_area=평형명 지정 시 그 평형 기준(각 단지 독립)."""
    _ck = f"cxcompare:{a}:{b}:{a_area}:{b_area}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    with _open_db() as d:
        out = {"a": _cx_compare_one(d, a, a_area or None),
               "b": _cx_compare_one(d, b, b_area or None)}
    # 급매 수는 기존 엔드포인트 재사용(동일 산식 유지) — 평형 선택 시 그 평형만
    for k, no, ar in (("a", a, a_area), ("b", b, b_area)):
        try:
            items = complex_quick_deals(no)["items"]
            out[k]["quick_deals"] = len([i for i in items if not ar or i.get("area_name") == ar])
        except Exception:
            out[k]["quick_deals"] = None
    _cache_put(_ck, out)
    return out


def _region_meta(code: str) -> tuple[str, str]:
    """지역 코드 → (수준, 라벨). sido=2자리 프리픽스, sigungu=5자리, dong=cortar 10자리."""
    code = (code or "").strip()
    if len(code) == 10 and code.endswith("00000000"):
        return "sido", code[:2]
    if len(code) == 10 and code.endswith("00000"):
        return "sigungu", code[:5]
    if len(code) in (2,):
        return "sido", code
    if len(code) == 5:
        return "sigungu", code
    return "dong", code


POP_DB_PATH = DB_PATH.parent / "pop_move.sqlite"

# 행정개편으로 코드가 바뀐 시도 — 같은 지역인데 시기별로 다른 코드로 들어온다.
# (강원도 42 → 강원특별자치도 51 : 2023-06 / 전라북도 45 → 전북특별자치도 52 : 2024-01)
# 합치지 않으면 최근 1년만 봐도 문제없지만, 장기 추이에서 지역이 두 동강 난다.
_POP_ALIAS = {
    "5100000000": ["5100000000", "4200000000"],
    "5200000000": ["5200000000", "4500000000"],
    # 군위군: 경북 → 대구 편입(2023-07). 시도가 바뀌어 접두 규칙으로는 안 잡힌다.
    "2772000000": ["2772000000", "4772000000"],
}
# 시군구도 같은 개편을 겪는다 — 강원 42→51, 전북 45→52 는 뒤 8자리가 그대로라
# 접두만 되돌리면 옛 코드가 나온다(실측 33개 전부 1:1, 이름까지 일치).
# 합치지 않으면 정선·진안 등에서 2023·2024년 이전 구간이 통째로 비어 장기추이가 끊긴다.
_POP_SGG_REVERT = {"51": "42", "52": "45"}


def _pop_keys(c10: str) -> list[str]:
    """인구이동 조회에 쓸 코드 목록 — 행정개편 전후를 함께 본다."""
    if c10 in _POP_ALIAS:
        return _POP_ALIAS[c10]
    old = _POP_SGG_REVERT.get(c10[:2])
    return [c10, old + c10[2:]] if old else [c10]


def _pop_metrics(code: str) -> dict | None:
    """지역 인구이동 지표 — 최근 1년 순유입·청년(20·30대) 순유입·월별 추이.

    행안부 주민등록 인구이동(pop_move.sqlite). 시도(lv1)는 전국 완비,
    시군구(lv2)는 전국(287곳). 데이터가 없으면 None 을 돌려 화면에서 숨긴다.

    일반구(분당·수지·흥덕 등 35곳)는 통계청이 2024-07부터 구 단위 제공을 끊고
    시 단위로 합산한다 → 그대로 두면 최근 1년이 통째로 비어 지표가 사라진다.
    이 경우 상위 시(市) 값으로 대신 보여주고 scope 로 그 사실을 알린다.
    """
    if not POP_DB_PATH.exists():
        return None
    c10 = (code or "").ljust(10, "0")[:10]
    r = _pop_query(c10)
    if r is not None:
        return r
    # 일반구 → 상위 시로 폴백 (41135 분당구 → 41130 성남시)
    if c10.endswith("00000") and c10[4] != "0":
        parent = c10[:4] + "000000"
        r = _pop_query(parent)
        if r is not None:
            r["scope"] = "parent"        # 화면에서 '시 단위 집계' 표기용
            return r
    return None


def _pop_query(code: str) -> dict | None:
    c10 = (code or "").ljust(10, "0")[:10]
    if c10.endswith("00000000"):
        lv, keys = "1", _pop_keys(c10)
    elif c10.endswith("00000"):
        lv, keys = "2", _pop_keys(c10)
    else:
        return None                      # 동 단위는 인구이동 통계 자체가 없다
    ph = ",".join("?" * len(keys))
    try:
        with sqlite3.connect(f"file:{POP_DB_PATH}?mode=ro", uri=True, timeout=5) as p:
            last = p.execute("SELECT MAX(ym) FROM pop_move WHERE lv=?", (lv,)).fetchone()[0]
            if not last:
                return None
            # 최근 12개월 = 마지막 달 포함 직전 11개월
            y, m = int(last[:4]), int(last[4:])
            fr = f"{y - 1}{m + 1:02d}" if m < 12 else f"{y}01"
            row = p.execute(
                f"""SELECT
                  (SELECT COALESCE(SUM(total),0) FROM pop_move
                     WHERE lv=? AND mvin_cd IN ({ph}) AND ym BETWEEN ? AND ?)
                  -(SELECT COALESCE(SUM(total),0) FROM pop_move
                     WHERE lv=? AND mvt_cd IN ({ph}) AND ym BETWEEN ? AND ?),
                  (SELECT COALESCE(SUM(m20+m30+f20+f30),0) FROM pop_move
                     WHERE lv=? AND mvin_cd IN ({ph}) AND ym BETWEEN ? AND ?)
                  -(SELECT COALESCE(SUM(m20+m30+f20+f30),0) FROM pop_move
                     WHERE lv=? AND mvt_cd IN ({ph}) AND ym BETWEEN ? AND ?)""",
                ([lv] + keys + [fr, last]) * 4).fetchone()
            if row is None or (row[0] == 0 and row[1] == 0):
                return None
            trend = [
                {"ym": r[0], "net": r[1]} for r in p.execute(
                    f"""SELECT ym, SUM(inn)-SUM(outn) FROM (
                          SELECT ym, total inn, 0 outn FROM pop_move
                            WHERE lv=? AND mvin_cd IN ({ph}) AND ym BETWEEN ? AND ?
                          UNION ALL
                          SELECT ym, 0, total FROM pop_move
                            WHERE lv=? AND mvt_cd IN ({ph}) AND ym BETWEEN ? AND ?)
                        GROUP BY ym ORDER BY ym""",
                    ([lv] + keys + [fr, last]) * 2)]
    except Exception:
        return None
    return {"net": row[0], "net_young": row[1], "period": f"{fr}~{last}", "trend": trend}


def _region_compare_one(d, code: str) -> dict:
    level, key = _region_meta(code)
    if level == "dong":
        name_row = d.execute(
            "SELECT rsg.cortar_name || ' ' || rdo.cortar_name FROM regions rdo "
            "LEFT JOIN regions rsg ON rsg.cortar_no=substr(rdo.cortar_no,1,5)||'00000' "
            "WHERE rdo.cortar_no=?", (key,)).fetchone()
        cx_where, cx_args = "cortar_no=?", [key]
        tx_where = ("matched_complex_no IN (SELECT complex_no FROM complexes WHERE cortar_no=?)")
        tx_args = [key]
    else:
        name_row = d.execute("SELECT cortar_name FROM regions WHERE cortar_no=?",
                             (key + "0" * (10 - len(key)),)).fetchone()
        cx_where, cx_args = "cortar_no LIKE ?", [key + "%"]
        tx_where, tx_args = "sgg_cd LIKE ?", [key + "%"]
    name = (name_row[0] if name_row else code)
    if level == "sido":
        name = _SIDO_SHORT.get(name, name)

    hh = d.execute(f"SELECT COALESCE(SUM(total_household_count),0), COUNT(*) FROM complexes WHERE {cx_where}",
                   cx_args).fetchone()
    t90 = d.execute(
        f"SELECT COUNT(*), CAST(AVG(deal_amount) AS INT), "
        f"  CAST(AVG(CASE WHEN excl_use_ar>0 THEN deal_amount/excl_use_ar*3.3 END) AS INT) "
        f"FROM transactions WHERE {tx_where} AND is_cancelled=0 "
        f"  AND deal_ymd>=date('now','+9 hours','-90 days')", tx_args).fetchone()
    n12 = d.execute(
        f"SELECT COUNT(*) FROM transactions WHERE {tx_where} AND is_cancelled=0 "
        f"  AND deal_ymd>=date('now','+9 hours','-12 months')", tx_args).fetchone()[0]
    monthly = [
        {"m": r[0], "n": r[1], "avg": r[2]} for r in d.execute(
            f"SELECT substr(deal_ymd,1,7), COUNT(*), CAST(AVG(deal_amount) AS INT) "
            f"FROM transactions WHERE {tx_where} AND is_cancelled=0 "
            f"  AND deal_ymd>=date('now','+9 hours','-12 months') GROUP BY 1 ORDER BY 1", tx_args)]

    pop = _pop_metrics(key if level != "dong" else "")
    snap = d.execute("SELECT MAX(snapshot_date) FROM complex_daily_agg").fetchone()[0]
    lst = d.execute(
        f"SELECT a.trade_type, SUM(a.listing_count), CAST(SUM(a.unit_count) AS INT), "
        f"  CAST(SUM(a.price_avg*a.listing_count)/SUM(a.listing_count) AS INT) "
        f"FROM complex_daily_agg a JOIN complexes c ON c.complex_no=a.complex_no "
        f"WHERE a.snapshot_date=? AND c.{cx_where} GROUP BY a.trade_type",
        [snap] + cx_args).fetchall()
    listings = {r[0]: {"n": r[1], "units": r[2], "avg": r[3]} for r in lst}
    a1 = listings.get("A1", {}).get("avg")
    b1 = listings.get("B1", {}).get("avg")
    return {
        "code": code, "level": level, "name": name,
        "households": hh[0], "complexes": hh[1],
        "tx90": {"n": t90[0], "avg": t90[1], "pyeong": t90[2]},
        "n12": n12,
        "turnover": (round(n12 / hh[0] * 100, 1) if hh[0] else None),
        "listings": listings,
        "listing_per_hh": (round((listings.get("A1", {}).get("n") or 0) / hh[0] * 100, 1) if hh[0] else None),
        "jeonse_rate": (round(b1 / a1 * 100, 1) if a1 and b1 else None),
        "monthly": monthly,
        "pop": pop,
        # 유입압력 = 최근1년 순유입 ÷ 아파트 재고세대. 순유입 절대값은 지역 크기에 좌우돼
        # 비교가 안 되므로(경기 4만 vs 대전 2,869) 재고로 나눠 같은 자에 올린다.
        "pop_pressure": (round(pop["net"] / hh[0] * 100, 2)
                         if pop and hh[0] else None),
    }


@app.get("/stats/region-compare2")
def region_compare2(a: str, b: str):
    """지역비교: 시도/시군구/동 임의 조합 2곳의 거래·매물·가격 지표(아파트 매매)."""
    # 응답에 pop/pop_pressure/scope 가 추가돼 옛 캐시(pop 없음)가 그대로 서빙되면
    # 인구 지표가 영영 안 나온다 → 키를 올려 무효화한다.
    _ck = f"regioncompare2:v3:{a}:{b}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    with _open_db() as d:
        out = {"a": _region_compare_one(d, a), "b": _region_compare_one(d, b)}
    _cache_put(_ck, out)
    return out


@app.get("/stats/timemachine")
def timemachine():
    """부동산타임머신: 정책·규제 연대기 + 전국 아파트 월별 거래량·평균가(콕집 DB 구간)."""
    # 백필이 월 단위로 게시되므로 캐시 키에 게시 월 수를 섞는다(진행 즉시 반영)
    try:
        with _open_db() as c:
            _histn = c.execute("SELECT COUNT(DISTINCT ym) FROM tx_hist_monthly").fetchone()[0]
    except Exception:
        _histn = 0
    _ck = f"timemachine:v2:{_histn}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    with _open_db() as c:
        rows = c.execute(
            """
            SELECT substr(deal_ymd,1,7) m, COUNT(*) n, CAST(AVG(deal_amount) AS INT) avg
            FROM transactions WHERE is_cancelled=0
            GROUP BY m ORDER BY m
            """
        ).fetchall()
        live_from = rows[0][0] if rows else "9999-99"
        # 과거분 백필(tx_hist_monthly, 완결 월만 게시) — 2023-06 이전 구간을 앞에 붙임
        try:
            hist = c.execute(
                "SELECT ym, n, avg_amount FROM tx_hist_monthly "
                "WHERE sgg_cd='ALL' AND ym < ? ORDER BY ym", (live_from,),
            ).fetchall()
        except Exception:
            hist = []
    series = ([{"m": h[0], "n": h[1], "avg": h[2]} for h in hist]
              + [{"m": r[0], "n": r[1], "avg": r[2]} for r in rows])
    out = {
        "series": series,
        "events": _TIMEMACHINE_EVENTS,
        "data_from": series[0]["m"] if series else None,
    }
    _cache_put(_ck, out)
    return out


@app.get("/stats/listing-trend")
def listing_trend(days: int = 60):
    """일별 매물 수 추이 (snapshot_date × trade_type).
    complex_daily_agg를 SUM해서 [{snapshot_date, A1, B1, B2}, ...] 형태로.
    """
    if days < 1 or days > 365:
        raise HTTPException(400, "days out of range")
    # 인메모리+디스크 캐시(데이터버전 연동 — 재빌드 시 자동 무효로 정확성 유지).
    # 60일×전셀 GROUP BY 콜드 ~9s → 캐시 히트 즉시.
    _ck = f"listingtrend2:{days}"   # v2 — 실매물 결측일 비율추정 채움(키 변경으로 구캐시 무효)
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    with _open_db() as c:
        rows = c.execute(
            """
            SELECT snapshot_date, trade_type, SUM(listing_count) AS n,
                   SUM(unit_count) AS u
            FROM complex_daily_agg
            WHERE snapshot_date >= date('now','+9 hours', ?)
            GROUP BY snapshot_date, trade_type
            ORDER BY snapshot_date ASC
            """,
            (f"-{days} days",),
        ).fetchall()
    by_date: dict[str, dict] = {}
    for d, t, n, u in rows:
        e = by_date.setdefault(d, {"snapshot_date": d, "A1": 0, "B1": 0, "B2": 0})
        e[t] = n
        # 실매물(중복 광고 합침) — 백필 전 과거분은 NULL이라 키 생략(차트가 결측 처리)
        if u is not None:
            e[f"{t}_u"] = int(round(u))
    series = list(by_date.values())
    # 실매물 결측일(6/14·6/28 — 파케이 스냅샷 유실로 백필 불가)은 인접일의
    # 실매물/광고 비율을 평균해 추정치로 채운다(차트 연속성, 사용자 지정).
    for t in ("A1", "B1", "B2"):
        uk = f"{t}_u"
        have = [i for i, e in enumerate(series) if uk in e and e.get(t)]
        for i, e in enumerate(series):
            if uk in e or not e.get(t):
                continue
            prev_i = max((j for j in have if j < i), default=None)
            next_i = min((j for j in have if j > i), default=None)
            ratios = [series[j][uk] / series[j][t]
                      for j in (prev_i, next_i) if j is not None and series[j][t]]
            if ratios:
                e[uk] = int(round(e[t] * sum(ratios) / len(ratios)))
    out = {"days": days, "series": series}
    _cache_put(_ck, out)
    return out


@app.get("/stats/listing-counts")
def listing_counts(asset: str | None = None):
    """시도별 현재 매물수 — 최신 스냅샷의 거래유형별 광고수(listing_count)와
    실매물수(unit_count=Σ1/same_addr_cnt) + 전일·7일 전 대비 증감.
    매물호가 '지역별 매물수' 탭용. 시도 정렬은 프런트 SIDO_ORDER(통계청 관례)."""
    _ck = f"listingcounts:{asset or ''}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    with _open_db() as c:
        dates = [r[0] for r in c.execute(
            "SELECT DISTINCT snapshot_date FROM complex_daily_agg "
            "ORDER BY snapshot_date DESC LIMIT 8")]
        if not dates:
            return {"as_of": None, "national": None, "regions": []}
        as_of, prev = dates[0], (dates[1] if len(dates) > 1 else None)
        week = dates[7] if len(dates) > 7 else None
        sido_names = {r[0][:2]: r[1] for r in c.execute(
            "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'")}
        snaps = [d for d in (as_of, prev, week) if d]
        ph = ",".join("?" * len(snaps))
        rows = c.execute(
            f"SELECT a.snapshot_date, substr(cx.cortar_no,1,2) AS sido, a.trade_type, "
            f"       SUM(a.listing_count) AS n, SUM(a.unit_count) AS u "
            f"FROM complex_daily_agg a JOIN complexes cx ON cx.complex_no = a.complex_no "
            f"WHERE a.snapshot_date IN ({ph}){_asset_type_clause(asset)} "
            f"GROUP BY 1, 2, 3", snaps).fetchall()
    by: dict[str, dict] = {}
    nat = {"sido_code": "00", "sido_name": "전국",
           "A1": 0, "B1": 0, "B2": 0, "A1_u": 0, "B1_u": 0, "B2_u": 0,
           "total": 0, "total_u": 0, "prev_total": 0, "week_total": 0}
    for d, sido, t, n, u in rows:
        if not sido or sido not in sido_names or t not in ("A1", "B1", "B2"):
            continue
        e = by.setdefault(sido, {
            "sido_code": sido, "sido_name": sido_names[sido],
            "A1": 0, "B1": 0, "B2": 0, "A1_u": 0, "B1_u": 0, "B2_u": 0,
            "total": 0, "total_u": 0, "prev_total": 0, "week_total": 0})
        if d == as_of:
            e[t] += n
            e["total"] += n
            nat[t] += n
            nat["total"] += n
            if u:
                e[f"{t}_u"] += int(round(u))
                e["total_u"] += int(round(u))
                nat[f"{t}_u"] += int(round(u))
                nat["total_u"] += int(round(u))
        elif d == prev:
            e["prev_total"] += n
            nat["prev_total"] += n
        elif d == week:
            e["week_total"] += n
            nat["week_total"] += n
    out = {"as_of": as_of, "prev_date": prev, "week_date": week, "asset": asset or "all",
           "national": nat, "regions": list(by.values())}
    _cache_put(_ck, out)
    return out


@app.get("/stats/complex-finder")
def complex_finder(sigungu: str, asset: str = "apt"):
    """맞춤단지 찾기(관리자 가오픈) — 시군구 전체를 '단지×평형' 행으로 한 번에 반환.
    필터·정렬은 클라이언트(와이드+클라이언트필터 패턴, 시군구당 수천 행).
    행 필드(짧은 키 — 페이로드 절약):
      c 단지no, n 단지명, d 동, y 사용승인ymd, hh 단지세대, py 평형명, sa 공급㎡, ea 전용㎡,
      ah 평형세대, ask/an/au 매매 최저호가·광고수·실매물, js/jn 전세 최저호가·건수,
      gap 갭, jr 전세가율(호가), la/ld 최근 매매실거래 금액·일, n12/a12 12개월 건수·평균,
      pk/pd 신고가 금액·일, vp 전고점대비%, sw/swm 지하철역·도보분, sc/scm/scd 배정초·도보분·거리m,
      rc/bc 방·욕실수, et 현관유형(계단식/복도식), lat/lng 좌표(지도뷰)"""
    code = (sigungu or "").strip()
    if len(code) >= 5 and code[:5].isdigit():
        code = code[:5]
        reg_cl, reg_p = "substr(cortar_no,1,5)=?", code
    elif len(code) >= 2 and code[:2].isdigit():
        # 시도 단위(2자리) — 시 전체 조회 허용
        code = code[:2]
        reg_cl, reg_p = "substr(cortar_no,1,2)=?", code
    else:
        raise HTTPException(400, "sigungu(cortar 앞 2자리=시도 또는 5자리=시군구) 필요")
    # sp(주인 조건 플래그) 추가로 행 스키마가 바뀌어 키를 올린다 — 옛 캐시가 서빙되면
    # sp 가 없어 조건 필터가 항상 0건이 된다.
    _ck = f"finder6:{code}:{asset or ''}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    with _open_db() as c:
        cxs = c.execute(
            f"SELECT complex_no, complex_name, dong_name, total_household_count, "
            f"use_approve_ymd, latitude, longitude "
            f"FROM complexes cx WHERE {reg_cl}"
            f"{_asset_type_clause(asset)}", (reg_p,)).fetchall()
        ids = [r["complex_no"] for r in cxs]
        if not ids:
            # sg5 는 존재한 적 없는 이름 — 해당 지역에 단지가 없으면 500이 났다.
            # (행정구역 개편으로 사라진 옛 시군구 코드가 들어오면 바로 이 경로를 탄다)
            return {"sigungu": code, "asset": asset, "rows": [], "n_complex": 0}
        ph = ",".join("?" * len(ids))
        cx_by = {r["complex_no"]: r for r in cxs}
        area_cols = {r[1] for r in c.execute("PRAGMA table_info(complex_areas)")}
        room_sel = (", room_cnt, bath_cnt, entrance_type"
                    if "room_cnt" in area_cols else
                    ", NULL AS room_cnt, NULL AS bath_cnt, NULL AS entrance_type")
        areas = c.execute(
            f"SELECT complex_no, pyeong_name, supply_area, exclusive_area, household_count"
            f"{room_sel} "
            f"FROM complex_areas WHERE complex_no IN ({ph}) AND exclusive_area IS NOT NULL",
            ids).fetchall()
        # 주인 조건(주인전세·세안고·주인대출) 보유 단지 — 맞춤단지에서 조건 필터로 쓴다.
        # 단지 단위 플래그만 실어 보내고 걸러내는 건 클라이언트(와이드+클라이언트필터 패턴 유지).
        sp_by: dict = {}
        for cno_, kind_ in c.execute(
            f"SELECT DISTINCT l.complex_no, sd.kind FROM special_deals sd "
            f"JOIN listings_current l ON l.article_no = sd.article_no "
            f"WHERE l.complex_no IN ({ph})", ids):
            sp_by.setdefault(cno_, set()).add(kind_[0])   # owner→o, tenant→t, loan→l

        # 현재 호가 — 평형명(area_name=pyeong_name 동일 어휘) 단위 최저가·광고수·실매물
        lst: dict = {}
        for r in c.execute(
            f"SELECT complex_no, area_name, trade_type, COUNT(*) n, "
            f"MIN(CASE WHEN deal_or_warrant_price > 0 THEN deal_or_warrant_price END) mn, "
            f"SUM(1.0/MAX(same_addr_cnt,1)) u "
            f"FROM listings_current WHERE complex_no IN ({ph}) AND trade_type IN ('A1','B1') "
            f"GROUP BY 1, 2, 3", ids):
            lst[(r["complex_no"], r["area_name"], r["trade_type"])] = r
        # 실거래 — 평형 전용면적 ±3.5㎡ 밴드(전역 표준). asset=all 이면 아파트+오피 UNION.
        if asset == "offi":
            src = "offi_transactions"
        elif asset == "all":
            src = ("(SELECT matched_complex_no, excl_use_ar, is_cancelled, deal_amount, deal_ymd "
                   "FROM transactions UNION ALL "
                   "SELECT matched_complex_no, excl_use_ar, is_cancelled, deal_amount, deal_ymd "
                   "FROM offi_transactions)")
        else:
            src = "transactions"
        a_join = (
            f"FROM complex_areas ca JOIN {src} tx ON tx.matched_complex_no = ca.complex_no "
            f"AND tx.excl_use_ar BETWEEN ca.exclusive_area-3.5 AND ca.exclusive_area+3.5 "
            f"AND tx.is_cancelled = 0 AND tx.deal_amount > 0 "
            f"WHERE ca.complex_no IN ({ph}) AND ca.exclusive_area IS NOT NULL")
        agg: dict = {}
        for r in c.execute(
            f"SELECT ca.complex_no || '|' || ca.pyeong_name AS aid, "
            f"SUM(CASE WHEN tx.deal_ymd >= date('now','+9 hours','-12 months') THEN 1 ELSE 0 END) n12, "
            f"AVG(CASE WHEN tx.deal_ymd >= date('now','+9 hours','-12 months') THEN tx.deal_amount END) a12 "
            f"{a_join} GROUP BY 1", ids):
            agg[r["aid"]] = {"n12": r["n12"], "a12": round(r["a12"]) if r["a12"] else None}
        for r in c.execute(
            f"SELECT aid, amt, d, rl, rp FROM ("
            f"SELECT ca.complex_no || '|' || ca.pyeong_name AS aid, "
            f"tx.deal_amount amt, tx.deal_ymd d, "
            f"ROW_NUMBER() OVER (PARTITION BY ca.complex_no, ca.pyeong_name "
            f"ORDER BY tx.deal_ymd DESC, tx.deal_amount DESC) rl, "
            f"ROW_NUMBER() OVER (PARTITION BY ca.complex_no, ca.pyeong_name "
            f"ORDER BY tx.deal_amount DESC, tx.deal_ymd DESC) rp {a_join}) "
            f"WHERE rl = 1 OR rp = 1", ids):
            e = agg.setdefault(r["aid"], {})
            if r["rl"] == 1:
                e["la"], e["ld"] = r["amt"], r["d"]
            if r["rp"] == 1:
                e["pk"], e["pd"] = r["amt"], r["d"]
        # 지하철·배정초 (사전계산 테이블 — 없으면 생략)
        sw: dict = {}
        sc: dict = {}
        try:
            for r in c.execute(f"SELECT complex_no, station_name, walk_min, lines "
                               f"FROM complex_subway WHERE complex_no IN ({ph})", ids):
                st = r[1] if str(r[1]).endswith("역") else f"{r[1]}역"
                sw[r[0]] = (st, r[2], r[3])
        except Exception:
            pass
        try:
            for r in c.execute(f"SELECT complex_no, school_name, walk_min, distance_m "
                               f"FROM complex_school WHERE complex_no IN ({ph})", ids):
                sc[r[0]] = (r[1], r[2], r[3])
        except Exception:
            pass
    rows = []
    for a in areas:
        cno, py = a["complex_no"], a["pyeong_name"]
        cxr = cx_by[cno]
        A = lst.get((cno, py, "A1"))
        B = lst.get((cno, py, "B1"))
        ask = A["mn"] if A else None
        js = B["mn"] if B else None
        g = agg.get(f"{cno}|{py}", {})
        la, pk = g.get("la"), g.get("pk")
        rows.append({
            "c": cno, "n": cxr["complex_name"], "d": cxr["dong_name"],
            "sp": "".join(sorted(sp_by.get(cno, ()))) or None,   # o=주인전세 t=세안고 l=주인대출
            "y": cxr["use_approve_ymd"], "hh": cxr["total_household_count"],
            "py": py, "sa": a["supply_area"], "ea": a["exclusive_area"],
            "ah": a["household_count"],
            "ask": ask, "an": A["n"] if A else 0,
            "au": int(round(A["u"])) if A and A["u"] else 0,
            "js": js, "jn": B["n"] if B else 0,
            "gap": (ask - js) if ask and js else None,
            "jr": round(js / ask * 100, 1) if ask and js else None,
            "la": la, "ld": g.get("ld"),
            "n12": g.get("n12") or 0, "a12": g.get("a12"),
            "pk": pk, "pd": g.get("pd"),
            "vp": round((la - pk) / pk * 100, 1) if la and pk else None,
            "sw": sw.get(cno, (None, None, None))[0], "swm": sw.get(cno, (None, None, None))[1],
            "swl": sw.get(cno, (None, None, None))[2],
            "sc": sc.get(cno, (None, None, None))[0], "scm": sc.get(cno, (None, None, None))[1],
            "scd": sc.get(cno, (None, None, None))[2],
            "rc": a["room_cnt"], "bc": a["bath_cnt"], "et": a["entrance_type"],
            "lat": float(cxr["latitude"]) if cxr["latitude"] else None,
            "lng": float(cxr["longitude"]) if cxr["longitude"] else None,
        })
    # 시도 단위는 페이로드가 커서(서울 26MB) 의미 있는 행(매물/전세/최근 실거래 보유)만.
    if len(code) == 2:
        rows = [r for r in rows if r["an"] > 0 or r["jn"] > 0 or r["n12"] > 0]
    # null 키 생략(sparse) — 프런트는 undefined/null 동일 처리, 페이로드 30%+ 절감
    rows = [{k: v for k, v in r.items() if v is not None} for r in rows]
    out = {"sigungu": code, "asset": asset, "n_complex": len(ids), "rows": rows}
    _cache_put(_ck, out)
    return out


@app.get("/stats/avg-price-trend")
def avg_price_trend(days: int = 60, sido: str | None = None, sigungu: str | None = None, dong: str | None = None, asset: str | None = None):
    """일별 평균 호가 추이 (snapshot_date × trade_type), 지역·자산(apt/offi) 필터 가능.

    /stats/changes/summary 의 avg_price 계산식을 시계열로 확장.
    각 일자의 거래유형별 가중평균(weights=listing_count)을 원 단위로 반환.
    - A1/B1/B2: price_avg (매매가, 전세금, 월세 보증금) — sane bound 컷
    - B2R: B2 행의 rent_avg (월세) — 별 키로 추가. 보증금과 스케일이 100배 차이라
           프런트에서 차트를 분리해 그리기 좋도록 따로 노출.
    """
    if days < 1 or days > 365:
        raise HTTPException(400, "days out of range")
    # 인메모리 캐시(24h) — 60일×전단지 GROUP BY 라 콜드 7~11s. 프리빌드 키와 어긋나는
    # 조합(시군구·동 등)도 첫 호출 후 즉시화. 데이터는 하루 1번만 갱신(daily 빌드가 비움).
    _ck = f"avgtrend:{days}:{sido or ''}:{sigungu or ''}:{dong or ''}:{asset or ''}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit

    # 지역 필터 (summary 와 동일 패턴)
    region_join = ""
    region_clause = ""
    region_filter_params: list[Any] = []
    if sigungu:
        region_join = " JOIN complexes cx ON cx.complex_no = a.complex_no"
        region_clause = " AND substr(cx.cortar_no,1,5) = substr(?,1,5)"
        region_filter_params.append(sigungu)
    elif sido:
        region_join = " JOIN complexes cx ON cx.complex_no = a.complex_no"
        region_clause = " AND substr(cx.cortar_no,1,2) = substr(?,1,2)"
        region_filter_params.append(sido)
    asset_clause = _asset_type_clause(asset)
    if asset_clause and not region_join:
        region_join = " JOIN complexes cx ON cx.complex_no = a.complex_no"
    region_clause += asset_clause

    parts = []
    params: list[Any] = []
    # 보증금/매매가/전세금: price_avg
    for t in ("A1", "B1", "B2"):
        lo = _PRICE_LO.get(t, 1_000_000)
        parts.append(
            f"SELECT a.snapshot_date, ? AS k, "
            f"       SUM(a.price_avg*a.listing_count)*1.0/SUM(a.listing_count) AS avg_p, "
            f"       SUM(a.listing_count) AS cnt "
            f"FROM complex_daily_agg a{region_join} "
            f"WHERE a.snapshot_date >= date('now','+9 hours', ?) "
            f"  AND a.trade_type = ? "
            f"  AND a.price_avg BETWEEN ? AND ?{region_clause} "
            f"GROUP BY a.snapshot_date"
        )
        params.extend([t, f"-{days} days", t, lo, _PRICE_HI, *region_filter_params])
    # 월세 (B2 의 rent_avg) — 시군구별 '실거래 월세 상한'(rent_ref_sgg, 깨끗한 실거래
    # p99×1.5)을 넘는 그룹은 보증금 오입력·제주 년세 등으로 보고 제외(지역 적응).
    parts.append(
        f"SELECT a.snapshot_date, 'B2R' AS k, "
        f"       SUM(a.rent_avg*a.listing_count)*1.0/SUM(a.listing_count) AS avg_p, "
        f"       SUM(a.listing_count) AS cnt "
        f"FROM complex_daily_agg a "
        f"JOIN complexes cr ON cr.complex_no = a.complex_no "
        f"LEFT JOIN rent_ref_sgg rr ON rr.sgg5 = substr(cr.cortar_no,1,5)"
        f"{region_join} "
        f"WHERE a.snapshot_date >= date('now','+9 hours', ?) "
        f"  AND a.trade_type = 'B2' "
        f"  AND a.rent_avg BETWEEN ? AND COALESCE(rr.rent_cap, ?)"
        f"{region_clause} "
        f"GROUP BY a.snapshot_date"
    )
    params.extend([f"-{days} days", _RENT_LO, _RENT_HI, *region_filter_params])
    sql = " UNION ALL ".join(parts) + " ORDER BY snapshot_date ASC"
    with _open_db() as c:
        rows = c.execute(sql, params).fetchall()
    # 라인(k)별 최대 매물수 → 그 30% 미만인 날은 커버리지 빈약(예: 오피스텔 수집이
    # 5/21 에 42→8,185단지로 확대된 온보딩 구간, 부분 스냅샷)으로 보고 추이에서 제외.
    maxcnt: dict[str, int] = {}
    for _d, k, p, cnt in rows:
        if p is not None and cnt:
            maxcnt[k] = max(maxcnt.get(k, 0), cnt)
    by_date: dict[str, dict] = {}
    for d, k, p, cnt in rows:
        if p is None:
            continue
        if cnt and maxcnt.get(k) and cnt < maxcnt[k] * 0.3:
            continue  # 커버리지 빈약 점 제외
        by_date.setdefault(
            d, {"snapshot_date": d, "A1": None, "B1": None, "B2": None, "B2R": None}
        )[k] = p
    result = {"days": days, "series": list(by_date.values())}
    _cache_put(_ck, result)
    return result


@app.get("/stats/top-listings")
def top_listings(limit: int = 5):
    """최신 snapshot의 단지별 매물 수 top-N (거래유형별).
    각 항목 = {complex_no, complex_name, count}.
    """
    if limit < 1 or limit > 50:
        raise HTTPException(400, "limit out of range")
    out = {"snapshot_date": None, "A1": [], "B1": [], "B2": []}
    with _open_db() as c:
        row = c.execute("SELECT MAX(snapshot_date) FROM complex_daily_agg").fetchone()
        snap = row[0] if row else None
        if not snap:
            return out
        out["snapshot_date"] = snap
        for t in ("A1", "B1", "B2"):
            rs = c.execute(
                """
                SELECT a.complex_no, c.complex_name, SUM(a.listing_count) AS n
                FROM complex_daily_agg a
                LEFT JOIN complexes c ON c.complex_no = a.complex_no
                WHERE a.snapshot_date = ? AND a.trade_type = ?
                GROUP BY a.complex_no
                ORDER BY n DESC
                LIMIT ?
                """,
                (snap, t, limit),
            ).fetchall()
            out[t] = [{"complex_no": r[0], "complex_name": r[1], "count": r[2]} for r in rs]
    return out


@app.get("/complexes/cluster")
def complexes_cluster(swlat: float, swlng: float, nelat: float, nelng: float,
                      cols: int = 7, rows: int = 7):
    """지도 축소 시 단지 군집 — bbox를 cols×rows 격자로 나눠 셀별 단지수+중심좌표 반환.
    캡 없이 영역 내 전체 단지를 집계(축소 화면에서 핀 폭주 방지)."""
    if not (swlat < nelat and swlng < nelng):
        raise HTTPException(400, "bad bounds")
    cols = max(2, min(cols, 16)); rows = max(2, min(rows, 16))
    dlat = (nelat - swlat) / rows or 1e-9
    dlng = (nelng - swlng) / cols or 1e-9
    with _open_db() as c:
        cells = c.execute(
            "SELECT CAST((latitude-?)/? AS INT) gy, CAST((longitude-?)/? AS INT) gx, "
            "COUNT(*) n, AVG(latitude) clat, AVG(longitude) clng "
            "FROM complexes WHERE latitude BETWEEN ? AND ? AND longitude BETWEEN ? AND ? "
            "AND latitude IS NOT NULL AND longitude IS NOT NULL GROUP BY gy, gx",
            (swlat, dlat, swlng, dlng, swlat, nelat, swlng, nelng)).fetchall()
    return {"cells": [{"lat": r[3], "lng": r[4], "count": r[2]} for r in cells if r[2]]}


@app.get("/complexes/in-bounds")
def complexes_in_bounds(swlat: float, swlng: float, nelat: float, nelng: float,
                        limit: int = 1000):
    """지도 보이는 영역(bbox) 안의 단지 — 지도보기 탭용. 매물수 포함, 세대수 큰 순.
    너무 많으면 limit 으로 컷(프론트는 더 줌인하면 줄어듦). too_many 플래그로 안내."""
    if not (swlat < nelat and swlng < nelng):
        raise HTTPException(400, "bad bounds")
    with _open_db() as c:
        total = c.execute(
            "SELECT COUNT(*) FROM complexes WHERE latitude BETWEEN ? AND ? "
            "AND longitude BETWEEN ? AND ?",
            (swlat, nelat, swlng, nelng),
        ).fetchone()[0]
        rows = c.execute(
            """
            SELECT cx.complex_no, cx.complex_name, cx.latitude, cx.longitude,
                   cx.total_household_count,
                   (SELECT COUNT(*) FROM listings_current l
                    WHERE l.complex_no = cx.complex_no AND l.trade_type='A1') AS c_sale,
                   (SELECT COUNT(*) FROM listings_current l
                    WHERE l.complex_no = cx.complex_no AND l.trade_type='B1') AS c_jeonse,
                   (SELECT COUNT(*) FROM listings_current l
                    WHERE l.complex_no = cx.complex_no AND l.trade_type='B2') AS c_wol,
                   (SELECT MAX(l.deal_or_warrant_price) FROM listings_current l
                    WHERE l.complex_no = cx.complex_no AND l.trade_type='A1') AS max_sale,
                   (SELECT MAX(t.deal_amount) FROM transactions t
                    WHERE t.matched_complex_no = cx.complex_no AND t.is_cancelled = 0) AS max_tx
            FROM complexes cx
            WHERE cx.latitude BETWEEN ? AND ? AND cx.longitude BETWEEN ? AND ?
            ORDER BY cx.total_household_count DESC
            LIMIT ?
            """,
            (swlat, nelat, swlng, nelng, limit),
        ).fetchall()
    return {
        "total": total,
        "too_many": total > limit,
        "items": [
            {"complex_no": r[0], "name": r[1], "lat": r[2], "lng": r[3],
             "households": r[4],
             "c_sale": r[5], "c_jeonse": r[6], "c_wol": r[7],
             "listings": (r[5] or 0) + (r[6] or 0) + (r[7] or 0),
             "max_sale": r[8], "max_tx": r[9]}
            for r in rows
        ],
    }


@app.get("/complex/{complex_no}/seo")
def complex_seo(complex_no: str):
    """검색봇 동적 렌더링용 단지 기본정보(이름·지역·주소·세대수·준공). 공개."""
    with _open_db() as c:
        row = c.execute(
            "SELECT complex_name, dong_name, road_address, detail_address, "
            "total_household_count, use_approve_ymd, real_estate_type_name "
            "FROM complexes WHERE complex_no=?", (complex_no,)).fetchone()
    if not row:
        raise HTTPException(404, "not found")
    name, dong, road, addr, hh, approve, kind = row
    approve_y = (approve or "")[:4] if approve else None
    return {
        "complex_no": complex_no, "name": name, "dong": dong,
        "address": road or addr or "", "households": hh,
        "approve_year": approve_y, "kind": kind or "아파트",
    }


@app.get("/complex/{complex_no}/transactions")
def complex_transactions(complex_no: str, months: int = 24, limit: int = 500):
    """단지별 실거래 이력. 매매(transactions + offi_transactions) /
    전세 (rentals + offi_rentals, monthly_rent=0) /
    월세 (rentals + offi_rentals, monthly_rent>0)
    각 deal_ymd DESC로 정렬.
    """
    if months < 1 or months > 240:
        raise HTTPException(400, "months out of range")
    if limit < 1 or limit > 5000:
        raise HTTPException(400, "limit out of range")
    cutoff = f"-{months} months"
    out: dict = {
        "complex_no": complex_no,
        "months": months,
        "sale": [],
        "jeonse": [],
        "wolse": [],
        "silv": [],   # 분양권/입주권 전매
    }
    with _open_db() as c:
        existing = {
            r[0]
            for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")
        }

        # 매매: transactions + offi_transactions (union)
        sale_parts: list[str] = []
        sale_params: list = []
        if "transactions" in existing:
            # 아파트 매매만 동(aptDong)·등기여부(rgstDate) 제공. registered=등기완료.
            sale_parts.append(
                "SELECT deal_ymd, deal_amount, excl_use_ar, floor, dealing_gbn, build_year, 'apt' AS asset, "
                "json_extract(raw,'$.aptDong') AS dong, "
                "(TRIM(COALESCE(json_extract(raw,'$.rgstDate'),''))<>'') AS registered "
                "FROM transactions WHERE matched_complex_no = ? AND deal_ymd >= date('now','+9 hours', ?) AND is_cancelled = 0"
            )
            sale_params.extend([complex_no, cutoff])
        if "offi_transactions" in existing:
            # 오피스텔 매매 API엔 동/등기 필드 없음 → NULL.
            sale_parts.append(
                "SELECT deal_ymd, deal_amount, excl_use_ar, floor, dealing_gbn, build_year, 'offi' AS asset, "
                "NULL AS dong, 0 AS registered "
                "FROM offi_transactions WHERE matched_complex_no = ? AND deal_ymd >= date('now','+9 hours', ?) AND is_cancelled = 0"
            )
            sale_params.extend([complex_no, cutoff])
        if sale_parts:
            sql = " UNION ALL ".join(sale_parts) + " ORDER BY deal_ymd DESC LIMIT ?"
            for row in c.execute(sql, [*sale_params, limit]):
                out["sale"].append({
                    "deal_ymd": row[0], "deal_amount": row[1],
                    "excl_use_ar": row[2], "floor": row[3],
                    "dealing_gbn": row[4], "build_year": row[5], "asset": row[6],
                    "dong": row[7], "registered": bool(row[8]),
                })

        # 전세 + 월세는 rentals/offi_rentals를 한 번에 뽑고 monthly_rent로 나눔
        rent_parts: list[str] = []
        rent_params: list = []
        if "rentals" in existing:
            rent_parts.append(
                "SELECT deal_ymd, deposit, monthly_rent, excl_use_ar, floor, build_year, "
                "contract_type, contract_term, use_rr_right, pre_deposit, pre_monthly_rent, 'apt' AS asset "
                "FROM rentals WHERE matched_complex_no = ? AND deal_ymd >= date('now','+9 hours', ?)"
            )
            rent_params.extend([complex_no, cutoff])
        if "offi_rentals" in existing:
            rent_parts.append(
                "SELECT deal_ymd, deposit, monthly_rent, excl_use_ar, floor, build_year, "
                "contract_type, contract_term, use_rr_right, pre_deposit, pre_monthly_rent, 'offi' AS asset "
                "FROM offi_rentals WHERE matched_complex_no = ? AND deal_ymd >= date('now','+9 hours', ?)"
            )
            rent_params.extend([complex_no, cutoff])
        if rent_parts:
            sql = " UNION ALL ".join(rent_parts) + " ORDER BY deal_ymd DESC LIMIT ?"
            for row in c.execute(sql, [*rent_params, limit]):
                item = {
                    "deal_ymd": row[0], "deposit": row[1], "monthly_rent": row[2],
                    "excl_use_ar": row[3], "floor": row[4], "build_year": row[5],
                    "contract_type": row[6], "contract_term": row[7],
                    "use_rr_right": row[8],
                    "pre_deposit": row[9], "pre_monthly_rent": row[10],
                    "asset": row[11],
                }
                if (row[2] or 0) > 0:
                    out["wolse"].append(item)
                else:
                    out["jeonse"].append(item)

        # 분양권/입주권 전매 (silv_transactions). 해제건 제외(시세 오염 방지).
        if "silv_transactions" in existing:
            sql = (
                "SELECT deal_ymd, deal_amount, excl_use_ar, floor, dealing_gbn, ownership_gbn "
                "FROM silv_transactions "
                "WHERE matched_complex_no = ? AND deal_ymd >= date('now','+9 hours', ?) AND is_cancelled = 0 "
                "ORDER BY deal_ymd DESC LIMIT ?"
            )
            for row in c.execute(sql, [complex_no, cutoff, limit]):
                out["silv"].append({
                    "deal_ymd": row[0], "deal_amount": row[1],
                    "excl_use_ar": row[2], "floor": row[3],
                    "dealing_gbn": row[4],
                    # ownership_gbn: '입'=입주권, 그 외/빈값=분양권
                    "kind": "입주권" if (row[5] or "").strip() == "입" else "분양권",
                })

    return out


# 중개사 랭킹 — listings_current 전체 스캔이라 1~2s 걸려서 짧게 캐시.
import time as _time
_realtor_cache: dict[str, tuple[float, object]] = {}
# realtor 캐시 백스톱 TTL = 24h. 실제 신선도는 랭킹 파일 mtime 으로 관리한다(아래):
# daily_run(매일 아침, 목표 7시까지)이 파일을 새로 쓰면 서버가 mtime 변화를 감지해
# 캐시를 비우고 새 데이터를 반영. 즉 '보존기간'은 매일 아침 파이프라인 완료 기준.
_REALTOR_TTL_S = 86400.0


# ── RAM 캐시 디스크 영속화(재시작 생존) ───────────────────────────────
# 인메모리(_realtor_cache)는 프로세스 RAM이라 재시작 시 날아가 콜드 재계산(3.9s) 발생.
# 이를 디스크(runtime_cache.sqlite)에 미러링해 배포 재시작에도 웜 유지.
# stale 방지: 데이터버전(api_cache.sqlite mtime — daily 빌드가 갱신)이 바뀌면 무효.
_RUNTIME_CACHE_DB = DB_PATH.parent / "runtime_cache.sqlite"


_dv_memo = {"at": 0.0, "v": ""}


def _data_version() -> str:
    """데이터 버전 토큰 — **내용 기반**(api_cache 최신 computed_at + 랭킹파일 mtime).
    파일 mtime만 쓰면 WAL 체크포인트 등으로 내용이 안 변해도 흔들려 런타임 캐시가
    수시로 전멸(2026-07-02 하루종일 재콜드 원인). computed_at 은 파이프라인(daily·
    listings·catchup)이 사전캐시를 실제로 다시 구울 때만 바뀜 → 데이터 갱신 시에만
    무효화(정확성) + 그 사이엔 캐시 안정(속도)."""
    now = _time.monotonic()
    if _dv_memo["v"] and now - _dv_memo["at"] < 10:      # 10초 메모(요청마다 DB조회 방지)
        return _dv_memo["v"]
    parts = []
    try:
        with sqlite3.connect(f"file:{_CACHE_DB_PATH}?mode=ro", uri=True) as c:
            parts.append(str(c.execute(
                "SELECT MAX(computed_at) FROM api_cache").fetchone()[0] or "0"))
    except Exception:
        parts.append("0")
    try:
        parts.append(str(int(os.path.getmtime(_RANK_FILE))))   # persist_ranks(파이프라인)만 갱신
    except OSError:
        parts.append("0")
    v = ".".join(parts)
    _dv_memo["at"], _dv_memo["v"] = now, v
    return v


def _rc_db():
    c = sqlite3.connect(_RUNTIME_CACHE_DB, timeout=5)
    c.execute("PRAGMA busy_timeout=4000")
    c.execute("PRAGMA journal_mode=WAL")
    c.execute("PRAGMA journal_size_limit=268435456")
    c.execute("CREATE TABLE IF NOT EXISTS mem_cache(key TEXT PRIMARY KEY, val TEXT, at REAL, ver TEXT)")
    return c


def _rc_clear() -> None:
    try:
        with _rc_db() as c:
            c.execute("DELETE FROM mem_cache")
    except Exception:
        pass


def _cache_get(key: str):
    # L1(RAM)·L2(디스크) 모두 **데이터버전 일치 + TTL 이내**만 유효 — 파이프라인이 데이터를
    # 재빌드하면(버전 변경) 즉시 무효(정확성). 버전 안 바뀌면 재시작에도 웜(속도).
    ver = _data_version()
    hit = _realtor_cache.get(key)
    if hit and len(hit) == 3 and hit[2] == ver and _time.monotonic() - hit[0] < _REALTOR_TTL_S:
        return hit[1]
    try:
        with _rc_db() as c:
            row = c.execute("SELECT val, at, ver FROM mem_cache WHERE key=?", (key,)).fetchone()
        if row and (_time.time() - (row[1] or 0)) < _REALTOR_TTL_S and row[2] == ver:
            val = _json.loads(row[0])
            _realtor_cache[key] = (_time.monotonic(), val, ver)     # RAM으로 승격
            return val
    except Exception:
        pass
    return None


def _cache_put(key: str, val):
    ver = _data_version()
    _realtor_cache[key] = (_time.monotonic(), val, ver)
    try:
        with _rc_db() as c:
            c.execute("INSERT OR REPLACE INTO mem_cache(key, val, at, ver) VALUES(?,?,?,?)",
                      (key, _json.dumps(val, ensure_ascii=False, default=str), _time.time(), ver))
    except Exception:
        pass


@app.get("/stats/realtors/national")
def realtors_national(limit: int = 20, scope: str = "complex"):
    """전국 매물 보유 상위 N개 중개사. realtor_id 기준. scope=complex/resi/comm/all(매물 범위)."""
    if limit < 1 or limit > 100:
        raise HTTPException(400, "limit out of range")
    ck = f"national:{scope}:{limit}"
    cached = _cache_get(ck)
    if cached is not None:
        return cached
    with _open_db() as c:
        parts = []
        if scope in ("complex", "all"):
            parts.append("SELECT realtor_id, COUNT(*) n FROM listings_current "
                         "WHERE realtor_id IS NOT NULL AND realtor_id!='' GROUP BY realtor_id")
        if scope in ("house", "all"):
            parts.append("SELECT realtor_id, (villa_n+house_n) n FROM realtor_region_counts WHERE villa_n+house_n>0")
        if scope in ("comm", "all"):
            parts.append("SELECT realtor_id, (sangga_n+office_n) n FROM realtor_region_counts WHERE sangga_n+office_n>0")
        if scope in ("building", "all"):
            parts.append("SELECT realtor_id, building_n n FROM realtor_region_counts WHERE building_n>0")
        if scope in ("land", "all"):
            parts.append("SELECT realtor_id, (land_n+factory_n) n FROM realtor_region_counts WHERE land_n+factory_n>0")
        if not parts:
            parts.append("SELECT realtor_id, COUNT(*) n FROM listings_current "
                         "WHERE realtor_id IS NOT NULL AND realtor_id!='' GROUP BY realtor_id")
        union = " UNION ALL ".join(parts)
        # 후보 풀을 limit 보다 넉넉히(+100) 뽑는다. 정렬 1순위=해당 scope 매물수(n),
        # 동률 시 2순위=전체매물수(total). LIMIT 경계에서 동률이 잘려 더 큰 사무소가
        # 누락되지 않도록 풀에서 뽑은 뒤 파이썬에서 (n DESC, total DESC) 재정렬한다.
        pool = c.execute(
            f"SELECT realtor_id, NULL, SUM(n) AS n FROM ({union}) "
            "WHERE realtor_id IS NOT NULL AND realtor_id!='' GROUP BY realtor_id ORDER BY n DESC LIMIT ?",
            (limit + 100,),
        ).fetchall()
        # 전체매물(total) = 단지형(listings_current) + 비단지(realtor_region_counts) 합산.
        # 동률 타이브레이크에 쓰이므로 풀 전체에 대해 먼저 계산한다.
        totals: dict = {}
        pool_ids = [r[0] for r in pool]
        if pool_ids:
            _php = ",".join("?" * len(pool_ids))
            for x in c.execute(f"SELECT realtor_id, COUNT(*) FROM listings_current "
                               f"WHERE realtor_id IN ({_php}) GROUP BY realtor_id", pool_ids):
                totals[x[0]] = x[1]
            for x in c.execute(f"SELECT realtor_id, COALESCE(villa_n,0)+COALESCE(house_n,0)+"
                               f"COALESCE(sangga_n,0)+COALESCE(office_n,0)+COALESCE(land_n,0)+"
                               f"COALESCE(factory_n,0)+COALESCE(building_n,0)+COALESCE(knowledge_n,0)+COALESCE(redev_n,0)+COALESCE(oneroom_n,0) "
                               f"FROM realtor_region_counts WHERE realtor_id IN ({_php})", pool_ids):
                totals[x[0]] = totals.get(x[0], 0) + (x[1] or 0)
        # 동률은 전체매물 많은 쪽이 상위. 그 다음 동률은 id 로 안정 정렬.
        rows = sorted(pool, key=lambda r: (-(r[2] or 0), -totals.get(r[0], r[2] or 0), r[0]))[:limit]
        # 상위 N개에만 소재지(시도)·소속인원·개업연도+별칭을 붙인다. naver_realtors →
        # realtor_match(sys_regno) → vworld_brokers(개업일)/vworld_employees(인원).
        ids = [r[0] for r in rows]
        info: dict[str, dict] = {}
        rnames: dict = {}
        if ids:
            _ph0 = ",".join("?" * len(ids))
            rnames = {x[0]: x[1] for x in c.execute(
                f"SELECT realtor_id, realtor_name FROM realtor_names WHERE realtor_id IN ({_ph0})", ids)}
        if ids:
            ph = ",".join("?" * len(ids))
            sido_names = {
                r[0][:2]: r[1]
                for r in c.execute(
                    "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'"
                )
            }
            for er in c.execute(
                f"""
                SELECT nr.realtor_id, nr.realtor_name, nr.cortar_no,
                       vb.registered_ymd,
                       (SELECT COUNT(*) FROM vworld_employees ve
                        WHERE ve.sys_regno = rm.sys_regno) AS emp
                FROM naver_realtors nr
                LEFT JOIN realtor_match rm ON rm.realtor_id = nr.realtor_id
                LEFT JOIN vworld_brokers vb ON vb.sys_regno = rm.sys_regno
                WHERE nr.realtor_id IN ({ph})
                """,
                ids,
            ):
                cortar = er[2] or ""
                reg = er[3] or ""
                info[er[0]] = {
                    "office_name": er[1],
                    "sido": sido_names.get(cortar[:2]) if cortar else None,
                    "established_year": reg[:4] if len(reg) >= 4 else None,
                    "staff_count": er[4] or None,
                }
            # naver_realtors 프로필이 없는 상업전문 사무소(다온에셋 등)는 소재지를 매물 지역
            # (realtor_region_sido, 매물 최다 시도)에서 유도. 직원·업력은 vworld 매칭 없으면 여전히 없음.
            miss = [i for i in ids if not info.get(i, {}).get("sido")]
            if miss:
                _phm = ",".join("?" * len(miss))
                for rid, sd in c.execute(
                    f"SELECT realtor_id, sido FROM realtor_region_sido WHERE realtor_id IN ({_phm}) "
                    "ORDER BY (villa_n+house_n+sangga_n+office_n+land_n+factory_n+building_n"
                    "+knowledge_n+redev_n+oneroom_n) DESC", miss):
                    e = info.setdefault(rid, {})
                    if not e.get("sido"):
                        e["sido"] = sido_names.get((sd or "")[:2])
    items = []
    for r in rows:
        e = info.get(r[0], {})
        items.append({
            "realtor_id": r[0],
            "realtor_name": e.get("office_name") or rnames.get(r[0]) or r[1] or "공인중개사",
            "count": r[2],
            "total_count": totals.get(r[0], r[2]),
            "sido": e.get("sido"),
            "staff_count": e.get("staff_count"),
            "established_year": e.get("established_year"),
        })
    out = {"limit": limit, "scope": scope, "items": items}
    _cache_put(ck, out)
    return out


def _realtor_enrich(c, ids: list) -> dict:
    """realtor_id 목록 → {id: {office_name, sido, established_year, staff_count, count}}.
    naver_realtors → realtor_match(sys_regno) → vworld_brokers(개업일)/vworld_employees(인원)."""
    if not ids:
        return {}
    ph = ",".join("?" * len(ids))
    sido_names = {r[0][:2]: r[1] for r in c.execute(
        "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'")}
    cnt = {r[0]: r[1] for r in c.execute(
        f"SELECT realtor_id, COUNT(*) FROM listings_current "
        f"WHERE realtor_id IN ({ph}) GROUP BY realtor_id", ids)}
    out: dict[str, dict] = {}
    for er in c.execute(
        f"""
        SELECT nr.realtor_id, nr.realtor_name, nr.cortar_no, vb.registered_ymd,
               (SELECT COUNT(*) FROM vworld_employees ve WHERE ve.sys_regno = rm.sys_regno) AS emp
        FROM naver_realtors nr
        LEFT JOIN realtor_match rm ON rm.realtor_id = nr.realtor_id
        LEFT JOIN vworld_brokers vb ON vb.sys_regno = rm.sys_regno
        WHERE nr.realtor_id IN ({ph})
        """, ids,
    ):
        cortar = er[2] or ""
        reg = er[3] or ""
        out[er[0]] = {
            "office_name": er[1],
            "sido": sido_names.get(cortar[:2]) if cortar else None,
            "established_year": reg[:4] if len(reg) >= 4 else None,
            "staff_count": er[4] or None,
            "count": cnt.get(er[0], 0),
        }
    return out


def _sgg_prefix(region: str) -> str:
    """지역 필터용 sgg_cd 접두 검증(2=시도 / 4=통합시 / 5=시군구)."""
    region = (region or "").strip()
    if region and (not region.isdigit() or len(region) not in (2, 4, 5)):
        raise HTTPException(400, "region must be 2/4/5-digit sgg prefix")
    return region


@app.get("/stats/realtors/by-staff")
def realtors_by_staff(limit: int = 20, region: str = "", by: str = "staff"):
    """직원/자격 기준 상위 중개사. vworld_employees 기준.
    by: staff(인원) | licensed(공인중개사수) | assistant(중개보조원수) | ratio(공인중개사 비율, 인원3+).
    region: sgg_cd 접두(2/4/5자리)."""
    if limit < 1 or limit > 100:
        raise HTTPException(400, "limit out of range")
    region = _sgg_prefix(region)
    by = by if by in ("staff", "licensed", "assistant", "ratio") else "staff"
    ck = f"realtor_staff:{limit}:{region}:{by}"
    cached = _cache_get(ck)
    if cached is not None:
        return cached
    order = {"staff": "e.emp", "licensed": "e.licensed", "assistant": "e.assistant",
             "ratio": "(e.licensed*1.0/e.emp)"}[by]
    having = "HAVING emp>=3" if by == "ratio" else ""
    sub = ("(SELECT sys_regno, COUNT(*) AS emp, "
           "SUM(CASE WHEN role='공인중개사' THEN 1 ELSE 0 END) AS licensed, "
           "SUM(CASE WHEN role='중개보조원' THEN 1 ELSE 0 END) AS assistant, "
           "MAX(business_name) AS bn FROM vworld_employees WHERE sys_regno IS NOT NULL "
           f"GROUP BY sys_regno {having}) e")
    with _open_db() as c:
        if region:
            rows = c.execute(
                f"SELECT e.sys_regno, e.emp, e.licensed, e.assistant, e.bn FROM {sub} "
                f"JOIN vworld_brokers vb ON vb.sys_regno=e.sys_regno "
                f"WHERE substr(vb.sgg_cd,1,?)=? ORDER BY {order} DESC LIMIT ?",
                (len(region), region, limit)).fetchall()
        else:
            rows = c.execute(
                f"SELECT e.sys_regno, e.emp, e.licensed, e.assistant, e.bn FROM {sub} "
                f"ORDER BY {order} DESC LIMIT ?", (limit,)).fetchall()
        cities = {r[0][:2]: r[1] for r in c.execute(
            "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'")}
        items = []
        for rg, emp, lic, asst, bn in rows:
            m = c.execute(
                "SELECT realtor_id, total_listings FROM realtor_match WHERE sys_regno=? LIMIT 1",
                (rg,)).fetchone()
            br = c.execute(
                "SELECT sgg_cd, registered_ymd FROM vworld_brokers WHERE sys_regno=? LIMIT 1",
                (rg,)).fetchone()
            sgg = br[0] if br else None
            items.append({
                "realtor_id": (m[0] if m else None),
                "realtor_name": bn,
                "count": (m[1] if m else None),
                "sido": (cities.get((sgg or "")[:2]) if sgg else None),
                "staff_count": emp, "licensed_count": lic, "assistant_count": asst,
                "licensed_ratio": (round(lic / emp, 2) if emp else None),
                "established_year": (br[1][:4] if (br and br[1] and len(br[1]) >= 4) else None),
            })
    out = {"limit": limit, "by": by, "items": items}
    _cache_put(ck, out)
    return out


@app.get("/stats/realtors/by-tenure")
def realtors_by_tenure(limit: int = 20, region: str = ""):
    """업력(개업일 빠른 순) 상위 N개 중개사. vworld_brokers.registered_ymd 기준(V-World 전체,
    네이버 매칭 여부 무관). region: sgg_cd 접두(2/4/5자리). 주면 그 지역 안에서 순위."""
    if limit < 1 or limit > 100:
        raise HTTPException(400, "limit out of range")
    region = _sgg_prefix(region)
    ck = f"realtor_tenure:{limit}:{region}"
    cached = _cache_get(ck)
    if cached is not None:
        return cached
    with _open_db() as c:
        where = ["registered_ymd IS NOT NULL", "length(registered_ymd) >= 8",
                 "registered_ymd > '1900'", "(status IS NULL OR status NOT LIKE '%폐업%')"]
        params: list = []
        if region:
            where.insert(0, "substr(sgg_cd, 1, ?) = ?")
            params += [len(region), region]
        params.append(limit)
        rows = c.execute(
            f"""
            SELECT sys_regno, registered_ymd, business_name, sgg_cd
            FROM vworld_brokers
            WHERE {' AND '.join(where)}
            ORDER BY registered_ymd ASC
            LIMIT ?
            """, params,
        ).fetchall()
        cities = {r[0][:2]: r[1] for r in c.execute(
            "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'")}
        items = []
        for rg, reg, bn, sgg in rows:
            m = c.execute(
                "SELECT realtor_id, total_listings FROM realtor_match WHERE sys_regno=? LIMIT 1",
                (rg,)).fetchone()
            emp = c.execute(
                "SELECT COUNT(*) FROM vworld_employees WHERE sys_regno=?", (rg,)).fetchone()
            items.append({
                "realtor_id": (m[0] if m else None),   # 매칭된 곳만 상세링크
                "realtor_name": bn,
                "count": (m[1] if m else None),
                "sido": (cities.get((sgg or "")[:2]) if sgg else None),
                "staff_count": (emp[0] if emp else None),
                # registered_ymd 는 'YYYY.MM.DD' 형식 → 연도만으론 순서가 모호해 월·일까지 표기.
                "established_year": reg[:4] if reg and len(reg) >= 4 else None,
                "established_date": reg if reg and len(reg) >= 8 else None,
            })
    out = {"limit": limit, "items": items}
    _cache_put(ck, out)
    return out


_NONRESI_DB = {"sangga": "listings_sangga.sqlite", "office": "listings_office.sqlite",
               "villa": "listings_villa.sqlite", "house": "listings_house.sqlite",
               "land": "listings_land.sqlite", "factory": "listings_factory.sqlite",
               "building": "listings_building.sqlite",
               "knowledge": "listings_knowledge.sqlite", "redev": "listings_redev.sqlite",
               "oneroom": "listings_oneroom.sqlite"}
_NONRESI_LABEL = {"sangga": "상가", "office": "사무실", "villa": "빌라·연립", "house": "단독·다가구",
                  "land": "토지", "factory": "공장·창고", "building": "건물",
                  "knowledge": "지식산업센터", "redev": "재개발", "oneroom": "원룸"}


@app.get("/stats/nonresi")
def nonresi_stats(cat: str, cortar: str = "", trade: str = ""):
    """비단지(상가·사무실·빌라·단독) 호가 통계 — 지역×거래유형별 건수·평균 보증/월세/매매·평당·면적.
    cat: sangga|office|villa|house. cortar: 동(10)/구(5) 접두. trade: A1/B1/B2. (호가 기준, 실거래 아님)"""
    if cat not in _NONRESI_DB:
        raise HTTPException(400, "cat must be sangga|office|villa|house")
    path = DB_PATH.parent / _NONRESI_DB[cat]
    if not path.exists():
        return {"cat": cat, "available": False, "by_trade": [], "total": 0}
    region_name = None
    if cortar:
        with _open_db() as mc:
            r = mc.execute("SELECT cortar_name FROM regions WHERE cortar_no=? OR "
                           "(cortar_type='dvsn' AND substr(cortar_no,1,5)=?) ORDER BY length(cortar_no) DESC LIMIT 1",
                           (cortar, cortar)).fetchone()
            region_name = r[0] if r else None
    where, params = [], []
    if cortar:
        where.append("substr(cortar_no,1,?)=?"); params += [len(cortar), cortar]
    if trade in ("A1", "B1", "B2"):
        where.append("trade_type=?"); params.append(trade)
    wsql = ("WHERE " + " AND ".join(where)) if where else ""
    tt = {"A1": "매매", "B1": "전세", "B2": "월세"}
    M = 10000  # 만원→원
    with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as c:
        # 가격 평균은 자릿수 오타 제외(거래유형별 중위값의 0.4~2.5배 밖 컷 — 아파트 agg와 동일 원칙).
        # 월세(rent)는 만원 단위 3~1,000(3만~1천만원/월) sane band. 건수(n)는 전체 그대로.
        rows = c.execute(
            f"""WITH base AS (SELECT trade_type, deal_or_warrant_price pr, rent_price rp, area1_m2 ar
                              FROM listings {wsql}),
                med AS (SELECT tt, AVG(pr) m FROM (
                          SELECT trade_type tt, pr,
                                 ROW_NUMBER() OVER (PARTITION BY trade_type ORDER BY pr) rn,
                                 COUNT(*) OVER (PARTITION BY trade_type) n
                          FROM base WHERE pr > 0)
                        WHERE rn IN ((n+1)/2, n/2+1) GROUP BY tt)
                SELECT b.trade_type, COUNT(*),
                       AVG(CASE WHEN b.pr > 0 AND (m.m IS NULL OR b.pr BETWEEN m.m*0.4 AND m.m*2.5)
                                THEN b.pr END),
                       AVG(CASE WHEN b.rp BETWEEN 3 AND 1000 THEN b.rp END),
                       AVG(b.ar),
                       AVG(CASE WHEN b.pr > 0 AND (m.m IS NULL OR b.pr BETWEEN m.m*0.4 AND m.m*2.5)
                                THEN b.pr / NULLIF(b.ar, 0) END)
                FROM base b LEFT JOIN med m ON m.tt = b.trade_type
                GROUP BY b.trade_type""", params).fetchall()
        by_trade = []
        for t, n, dp, rp, ar, ppm in rows:
            d = {"trade": tt.get(t, t), "n": n,
                 "avg_price": int((dp or 0) * M) or None,
                 "avg_area_m2": round(ar) if ar else None}
            if t == "B2":
                d["avg_rent"] = int((rp or 0) * M) or None
            if t == "A1" and ppm:           # 매매 평당가(㎡당×3.3058)
                d["avg_pyeong"] = int(ppm * 3.3058 * M)
            by_trade.append(d)
        total = sum(x["n"] for x in by_trade)
        # 건물(상가·빌라)·지역 top — 매물 많은 곳
        tops = c.execute(
            f"SELECT COALESCE(NULLIF(building_name,''),'(기타)'), COUNT(*) n FROM listings {wsql} "
            f"GROUP BY building_name ORDER BY n DESC LIMIT 8", params).fetchall()
    order = {"매매": 0, "전세": 1, "월세": 2}
    by_trade.sort(key=lambda x: order.get(x["trade"], 9))
    return {"cat": cat, "label": _NONRESI_LABEL[cat], "cortar": cortar,
            "region_name": region_name, "total": total, "by_trade": by_trade,
            "top_buildings": [{"name": b, "n": n} for b, n in tops],
            "source": "호가", "realprice": _nonresi_realprice(cat, cortar)}


_SIDO_STD = {"11": "서울", "26": "부산", "27": "대구", "28": "인천", "29": "광주",
             "30": "대전", "31": "울산", "36": "세종", "41": "경기", "51": "강원",
             "43": "충북", "44": "충남", "52": "전북", "46": "전남", "47": "경북",
             "48": "경남", "50": "제주"}
_TT_KO = {"A1": "매매", "B1": "전세", "B2": "월세"}


def _villa_agg_db(cat: str = "villa"):
    if cat not in _NONRESI_DB:
        raise HTTPException(400, f"cat must be one of {sorted(_NONRESI_DB)}")
    path = DB_PATH.parent / _NONRESI_DB[cat]
    if not path.exists():
        raise HTTPException(503, f"{cat} DB 없음")
    return sqlite3.connect(f"file:{path}?mode=ro", uri=True)


@app.get("/stats/nonresi/trend")
def nonresi_trend(cat: str = "villa", region: str = "00", trade: str = ""):
    """비단지 일별 매물 추이 — 카테고리 DB region_daily 축적분(전 10종, 2026-07-11~).
    region: '00'(전국)|시도 2자리(광주29·전남46 표준)|시군구 5자리(네이버 코드).
    trade 생략=전 유형. 가격 단위 만원: med/avg/p25/p75=매매·전세가(월세는 보증금),
    ppm2=매매 ㎡당 중위(전용, 없으면 area1), rent_med/rent_avg=월세.
    units=중복 광고 제거 실매물."""
    where, params = ["region=?"], [region]
    if trade in ("A1", "B1", "B2"):
        where.append("trade_type=?"); params.append(trade)
    with _villa_agg_db(cat) as c:
        rows = c.execute(
            f"""SELECT snapshot_date, trade_type, ads, units, px_med, px_avg, px_p25,
                       px_p75, ppm2_med, rent_med, rent_avg
                FROM region_daily WHERE {' AND '.join(where)}
                ORDER BY snapshot_date, trade_type""", params).fetchall()
    name = "전국" if region == "00" else _SIDO_STD.get(region)
    if name is None and len(region) == 5:
        with _open_db() as mc:
            r = mc.execute("SELECT cortar_name FROM regions WHERE cortar_type='dvsn' "
                           "AND substr(cortar_no,1,5)=? LIMIT 1", (region,)).fetchone()
            name = r[0] if r else None
        if name is None:  # 광주·전남 네이버 12* — villa_region_map 이름 폴백
            with _villa_agg_db() as c:
                r = c.execute("SELECT sido_std, name FROM villa_region_map WHERE sgg5=?",
                              (region,)).fetchone()
                name = f"{_SIDO_STD.get(r[0], '')} {r[1]}".strip() if r else None
    return {"cat": cat, "region": region, "region_name": name, "unit": "만원",
            "rows": [{"d": d, "t": _TT_KO.get(t, t), "ads": a, "units": u,
                      "med": m, "avg": av, "p25": p25, "p75": p75,
                      "ppm2": pp, "rent_med": rm, "rent_avg": ra}
                     for d, t, a, u, m, av, p25, p75, pp, rm, ra in rows]}


@app.get("/stats/nonresi/regions")
def nonresi_regions(cat: str = "villa", level: str = "sido", sido: str = "", date: str = ""):
    """비단지 지역별 매물표(매매·전세·월세 광고/실매물/중위가) — region_daily 최신일(전 10종).
    level: sido(전국+17시도) | sigungu(시군구, sido=2자리로 좁히기 가능). date 생략=최신."""
    with _villa_agg_db(cat) as c:
        d = date or c.execute("SELECT MAX(snapshot_date) FROM region_daily").fetchone()[0]
        if level == "sido":
            cond, params = "length(region)=2 OR region='00'", [d]
        else:
            cond, params = "length(region)=5", [d]
            if sido:
                # 광주29·전남46은 네이버 12* 시군구를 포함(매핑은 villa DB에만 있음)
                with _villa_agg_db() as vc:
                    extra = [r[0] for r in vc.execute(
                        "SELECT sgg5 FROM villa_region_map WHERE sido_std=?", (sido,))]
                ph = ",".join("?" * len(extra)) or "''"
                cond += f" AND (substr(region,1,2)=? OR region IN ({ph}))"
                params += [sido] + extra
        rows = c.execute(
            f"""SELECT region, trade_type, ads, units, px_med, ppm2_med, rent_med
                FROM region_daily WHERE snapshot_date=? AND ({cond})""",
            params).fetchall()
    names = dict(_SIDO_STD, **{"00": "전국"})
    if level != "sido":
        with _open_db() as mc:
            names = {r[0][:5]: r[1] for r in mc.execute(
                "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='dvsn'")}
        with _villa_agg_db() as c:  # 광주·전남 네이버 12* 이름 폴백
            for sgg5, nm, std in c.execute("SELECT sgg5, name, sido_std FROM villa_region_map"):
                names.setdefault(sgg5, f"{_SIDO_STD.get(std, '')} {nm}".strip())
    out = {}
    for reg, t, a, u, m, pp, rm in rows:
        e = out.setdefault(reg, {"code": reg, "name": names.get(reg), "trades": {}})
        e["trades"][_TT_KO.get(t, t)] = {"ads": a, "units": u, "med": m,
                                         **({"ppm2": pp} if t == "A1" else {}),
                                         **({"rent_med": rm} if t == "B2" else {})}
    ordered = sorted(out.values(),
                     key=lambda e: (-1 if e["code"] == "00" else sido_rank(e["code"]), e["code"]))
    return {"cat": cat, "date": d, "level": level, "unit": "만원", "rows": ordered}


# 비단지 실거래 테이블 매핑. sangga/office는 같은 nrg_transactions를 building_use로 분기.
_NONRESI_TX = {
    "villa":  {"sale": "rh_transactions", "rent": "rh_rentals", "bld": "mhouse_nm", "area": "excl_use_ar"},
    "house":  {"sale": "sh_transactions", "rent": "sh_rentals", "bld": None, "area": "total_floor_ar"},
    "sangga": {"sale": "nrg_transactions", "rent": None, "bld": "jibun", "area": "building_ar", "use": "sangga"},
    "office": {"sale": "nrg_transactions", "rent": None, "bld": "jibun", "area": "building_ar", "use": "office"},
}


def _nrg_use_clause(cat: str) -> tuple[str, list]:
    """nrg_transactions를 상가/사무실로 분기 — 업무용=사무실, 그 외(판매·근린생활)=상가."""
    if cat == "office":
        return "building_use LIKE '%업무%'", []
    if cat == "sangga":
        return "(building_use IS NULL OR building_use NOT LIKE '%업무%')", []
    return "", []


@app.get("/stats/nonresi/deals")
def nonresi_deals(cat: str, cortar: str = "", trade: str = "sale", area_min: float = 0,
                  area_max: float = 0, q: str = "", sort: str = "recent", limit: int = 50):
    """비단지 개별 실거래 사례 — 집계 아닌 실제 거래 리스트. 지역·면적·검색·정렬 필터."""
    if cat not in _NONRESI_TX:
        raise HTTPException(400, "bad cat")
    conf = _NONRESI_TX[cat]
    table = conf["sale"] if trade == "sale" else conf["rent"]
    if not table:
        return {"cat": cat, "trade": trade, "deals": [], "note": "이 유형은 실거래(임대) 공개가 없습니다."}
    area_col, bld_col = conf["area"], conf["bld"]
    where, params = ["deal_ymd>=?"], ["2024-01-01"]
    rc, rp = _rh_region_clause(cortar)
    if rc:
        where.append(rc); params += rp
    if trade == "sale":
        where.append("is_cancelled=0")
    if cat in ("sangga", "office"):
        uc, _ = _nrg_use_clause(cat)
        if uc:
            where.append(uc)
    if area_min:
        where.append(f"{area_col}>=?"); params.append(area_min)
    if area_max:
        where.append(f"{area_col}<=?"); params.append(area_max)
    if q:
        like = f"%{q}%"
        cols = [c for c in ("umd_nm", bld_col, "building_use") if c]
        where.append("(" + " OR ".join(f"{c} LIKE ?" for c in cols) + ")")
        params += [like] * len(cols)
    order = {"recent": "deal_ymd DESC", "price_high": "deal_amount DESC",
             "price_low": "deal_amount ASC",
             "pyeong": f"deal_amount/NULLIF({area_col},0) DESC"}.get(sort, "deal_ymd DESC")
    if trade == "rent":
        order = {"recent": "deal_ymd DESC", "price_high": "deposit DESC",
                 "price_low": "deposit ASC"}.get(sort, "deal_ymd DESC")
    sel_amt = ("deal_amount" if trade == "sale" else "deposit, monthly_rent")
    extra = ", building_use, land_use, floor" if cat in ("sangga", "office") else \
            (", house_type" if cat == "house" else ", floor")
    bld_sel = f"{bld_col}" if bld_col else "house_type"
    limit = max(1, min(limit, 200))
    with _open_db() as c:
        rows = c.execute(
            f"SELECT deal_ymd, umd_nm, {bld_sel}, {area_col}, build_year, {sel_amt}{extra} "
            f"FROM {table} WHERE {' AND '.join(where)} ORDER BY {order} LIMIT ?",
            params + [limit]).fetchall()
    deals = []
    for r in rows:
        d = {"date": r[0], "umd": r[1], "building": r[2], "area_m2": round(r[3]) if r[3] else None,
             "build_year": r[4]}
        if trade == "sale":
            d["amount"] = r[5]
            d["pyeong"] = int(r[5] / r[3] * 3.3058) if r[3] else None
            if cat in ("sangga", "office"):
                d["use"], d["land_use"], d["floor"] = r[6], r[7], r[8]
            elif cat == "house":
                d["house_type"] = r[6]
            else:
                d["floor"] = r[6]
        else:
            d["deposit"], d["monthly_rent"] = r[5], r[6]
            d["floor"] = r[7] if cat != "house" else None
        deals.append(d)
    return {"cat": cat, "trade": trade, "count": len(deals), "deals": deals}


@app.get("/stats/nonresi/jeonse-ratio")
def nonresi_jeonse_ratio(cortar: str = ""):
    """빌라 건물단위 전세가율(깡통전세 경고) — 같은 건물+면적(±3㎡) 매매·전세 매칭. 지역 요약+위험 건물."""
    rc, rp = _rh_region_clause(cortar)
    if not rc:
        raise HTTPException(400, "지역(구/동)을 선택하세요")
    with _open_db() as c:
        # 같은 건물+면적대(정수㎡)별 매매 평균 vs 전세 평균
        rows = c.execute(
            f"""WITH s AS (SELECT umd_nm, mhouse_nm, CAST(excl_use_ar AS INT) ar,
                   AVG(deal_amount) ma, COUNT(*) ns FROM rh_transactions
                   WHERE {rc} AND is_cancelled=0 AND deal_ymd>='2024-06-01' AND mhouse_nm NOT LIKE '(%'
                   GROUP BY umd_nm, mhouse_nm, ar),
                 j AS (SELECT umd_nm, mhouse_nm, CAST(excl_use_ar AS INT) ar,
                   AVG(deposit) mj, COUNT(*) nj FROM rh_rentals
                   WHERE {rc} AND monthly_rent=0 AND deal_ymd>='2024-06-01' AND mhouse_nm NOT LIKE '(%'
                   GROUP BY umd_nm, mhouse_nm, ar)
                SELECT s.umd_nm, s.mhouse_nm, s.ar, s.ma, j.mj, s.ns, j.nj,
                       j.mj*100.0/NULLIF(s.ma,0) ratio
                FROM s JOIN j ON s.umd_nm=j.umd_nm AND s.mhouse_nm=j.mhouse_nm AND s.ar=j.ar
                ORDER BY ratio DESC""",
            rp + rp).fetchall()
    if not rows:
        return {"cortar": cortar, "n_buildings": 0, "avg_ratio": None, "risky": [], "note": "매칭 거래 부족"}
    ratios = [r[7] for r in rows if r[7]]
    avg = round(sum(ratios) / len(ratios), 1) if ratios else None
    risky = [{"umd": r[0], "building": r[1], "area_m2": r[2], "sale": int(r[3]),
              "jeonse": int(r[4]), "ratio": round(r[7], 1)} for r in rows if r[7] and r[7] >= 80][:30]
    n_risky = sum(1 for r in ratios if r >= 80)
    return {"cortar": cortar, "n_buildings": len(ratios), "avg_ratio": avg,
            "risky_count": n_risky, "risky_pct": round(n_risky * 100 / len(ratios), 1) if ratios else 0,
            "risky": risky}


VWORLD_KEY = os.getenv("VWORLD_KEY", "")
VWORLD_DOMAIN = "koczip.com"
# 키 폴백 목록 — 1번(도메인 등록형)이 차단·오류일 때 2~5번으로 재시도.
# (VWorld 차단은 IP×키 쌍 단위라, 한 키가 막혀도 다른 키는 살아있는 경우가 많음)
_VW_KEYS = [k for k in [VWORLD_KEY] + [os.getenv(f"VWORLD_KEY{i}", "") for i in range(2, 6)] if k]


def _vworld_get(url: str, retries: int = 3) -> dict:
    """VWorld 호출 — 일시 오류(502/타임아웃/throttle)에 재시도+백오프. 마지막 실패만 raise."""
    import urllib.request, time
    last = None
    for i in range(retries):
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "koczip/1.0"})
            with urllib.request.urlopen(req, timeout=8) as r:
                return _json.loads(r.read().decode("utf-8"))
        except Exception as e:
            last = e
            time.sleep(0.4 * (i + 1))
    raise last if last else RuntimeError("vworld_get failed")


def _vw_geocode(addr: str) -> dict | None:
    import urllib.parse
    for key in _VW_KEYS:
        got_reply = False
        for typ in ("road", "parcel"):
            q = urllib.parse.urlencode({"service": "address", "request": "getcoord", "version": "2.0",
                                        "crs": "epsg:4326", "address": addr, "format": "json",
                                        "type": typ, "key": key})
            try:
                d = _vworld_get(f"https://api.vworld.kr/req/address?{q}")
                res = d.get("response", {})
                got_reply = True
                if res.get("status") == "OK":
                    pt = res["result"]["point"]
                    st = res.get("refined", {}).get("structure", {})
                    return {"x": float(pt["x"]), "y": float(pt["y"]),
                            "sgg": st.get("level2"), "umd": st.get("level4L") or st.get("level3"),
                            "text": res.get("refined", {}).get("text")}
            except Exception:
                continue
        if got_reply:       # 정상 응답(NOT_FOUND 포함)이면 키는 살아있음 — 다음 키 불필요
            return None
    return None


def _vw_pnu(x: float, y: float) -> dict | None:
    import urllib.parse
    for key in _VW_KEYS:
        q = urllib.parse.urlencode({"service": "data", "request": "GetFeature", "data": "LP_PA_CBND_BUBUN",
                                    "key": key, "domain": VWORLD_DOMAIN,
                                    "geomFilter": f"POINT({x} {y})", "size": "1", "format": "json"})
        try:
            d = _vworld_get(f"https://api.vworld.kr/req/data?{q}")
            feats = d["response"]["result"]["featureCollection"]["features"]
            if feats:
                p = feats[0]["properties"]
                return {"pnu": p["pnu"], "addr": p.get("addr"), "jiga": int(p.get("jiga") or 0)}
            return None       # 정상 응답에 결과 없음 — 키는 살아있음
        except Exception:
            continue          # 차단·오류 — 다음 키로
    return None


def _vw_ned(op: str, pnu: str) -> list:
    import urllib.parse
    for key in _VW_KEYS:
        q = urllib.parse.urlencode({"key": key, "domain": VWORLD_DOMAIN, "pnu": pnu,
                                    "format": "json", "numOfRows": "1000", "pageNo": "1"})
        try:
            d = _vworld_get(f"https://api.vworld.kr/ned/data/{op}?{q}")
            root = next(iter(d.values())) if d else {}
            f = root.get("field", []) if isinstance(root, dict) else []
            out = f if isinstance(f, list) else [f]
            if out:
                return out
        except Exception:
            continue
    return []


@app.get("/tools/jeonse-listings")
def jeonse_listings(cortar: str = "", limit: int = 50, offset: int = 0):
    """동 단위 빌라 전세 매물(좌표 포함) — 감별기에서 주소 없이 매물 선택용. 페이지네이션."""
    if not cortar:
        raise HTTPException(400, "지역(동)을 선택하세요")
    path = DB_PATH.parent / _NONRESI_DB["villa"]
    if not path.exists():
        return {"cortar": cortar, "total": 0, "listings": []}
    limit = max(1, min(limit, 60))
    with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as lc:
        total = lc.execute(
            "SELECT COUNT(*) FROM listings WHERE substr(cortar_no,1,?)=? AND trade_type='B1' "
            "AND deal_or_warrant_price>0 AND latitude>0", (len(cortar), cortar)).fetchone()[0]
        rows = lc.execute(
            "SELECT article_no, building_name, area2_m2, deal_or_warrant_price, latitude, longitude, floor_info "
            "FROM listings WHERE substr(cortar_no,1,?)=? AND trade_type='B1' "
            "AND deal_or_warrant_price>0 AND latitude>0 "
            "ORDER BY article_confirm_ymd DESC, deal_or_warrant_price DESC LIMIT ? OFFSET ?",
            (len(cortar), cortar, limit, max(0, offset))).fetchall()

    # 매물 좌표 역지오코딩 → 실제 지번 주소(건물명이 '빌라'로만 와서 구분 불가한 문제 해결). 병렬.
    from concurrent.futures import ThreadPoolExecutor

    def _short_addr(la, lo):
        p = _vw_pnu(lo, la)
        full = p.get("addr") if p else None
        if not full:
            return None
        toks = full.split()
        # 구/군 다음(동+지번)만 — "화곡동 102-119"
        for i, t in enumerate(toks):
            if t.endswith(("구", "군", "시")) and i + 1 < len(toks):
                return " ".join(toks[i + 1:])
        return full

    with ThreadPoolExecutor(max_workers=10) as ex:
        addrs = list(ex.map(lambda r: _short_addr(r[4], r[5]), rows))

    out = []
    for (a, b, ar, pr, la, lo, fl), addr in zip(rows, addrs):
        out.append({"article_no": a, "addr": addr, "building": b or "빌라",
                    "area_m2": round(ar) if ar else None, "floor": fl,
                    "deposit": int(pr * 10000), "lat": la, "lng": lo,
                    "naver_url": f"https://m.land.naver.com/article/info/{a}"})
    return {"cortar": cortar, "total": total, "listings": out}


@app.get("/tools/villa-cluster")
def villa_cluster(swlat: float, swlng: float, nelat: float, nelng: float,
                  cols: int = 8, rows: int = 8):
    """지도 축소 시 빌라 군집 — bbox를 격자로 나눠 셀별 빌라수+중심좌표(핀 폭주 방지)."""
    if not (swlat < nelat and swlng < nelng):
        raise HTTPException(400, "bad bounds")
    cols = max(2, min(cols, 16)); rows = max(2, min(rows, 16))
    dlat = (nelat - swlat) / rows or 1e-9
    dlng = (nelng - swlng) / cols or 1e-9
    with _open_db() as c:
        cells = c.execute(
            "SELECT CAST((lat-?)/? AS INT) gy, CAST((lng-?)/? AS INT) gx, "
            "COUNT(*) n, AVG(lat) clat, AVG(lng) clng FROM villa_master "
            "WHERE status='ok' AND lat BETWEEN ? AND ? AND lng BETWEEN ? AND ? GROUP BY gy, gx",
            (swlat, dlat, swlng, dlng, swlat, nelat, swlng, nelng)).fetchall()
    return {"cells": [{"lat": r[3], "lng": r[4], "count": r[2]} for r in cells if r[2]]}


@app.get("/tools/villa-bbox")
def villa_bbox(swlat: float, swlng: float, nelat: float, nelng: float, limit: int = 600):
    """지도 영역 내 '평가 가능한 모든 빌라'(villa_master, 실거래 이력+좌표) — 매물 아닌 것 포함."""
    if (nelat - swlat) > 0.08 or (nelng - swlng) > 0.1:
        return {"too_wide": True, "buildings": []}
    lim = max(1, min(limit, 1000))
    with _open_db() as c:
        rows = c.execute(
            "SELECT key, umd_nm, jibun, building, area_avg, tx_count, lat, lng FROM villa_master "
            "WHERE status='ok' AND lat BETWEEN ? AND ? AND lng BETWEEN ? AND ? LIMIT ?",
            (swlat, nelat, swlng, nelng, lim + 1)).fetchall()
    too_many = len(rows) > lim
    out = []
    for k, umd, jb, bld, ar, tx, la, lo in rows[:lim]:
        nm = bld if (bld and not bld.startswith("(")) else f"{umd} {jb}"
        out.append({"key": k, "name": nm, "umd": umd, "jibun": jb,
                    "area_m2": round(ar) if ar else None, "tx_count": tx, "lat": la, "lng": lo})
    return {"too_many": too_many, "count": len(out), "buildings": out}


@app.get("/tools/jeonse-markers-bbox")
def jeonse_markers_bbox(swlat: float, swlng: float, nelat: float, nelng: float, limit: int = 500):
    """지도 영역(bbox) 내 빌라 전세 매물 마커. 너무 넓으면 too_wide."""
    if (nelat - swlat) > 0.13 or (nelng - swlng) > 0.16:
        return {"too_wide": True, "markers": []}
    path = DB_PATH.parent / _NONRESI_DB["villa"]
    if not path.exists():
        return {"markers": []}
    lim = max(1, min(limit, 800))
    with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as lc:
        rows = lc.execute(
            "SELECT article_no, area2_m2, deal_or_warrant_price, latitude, longitude, floor_info, building_name "
            "FROM listings WHERE trade_type='B1' AND deal_or_warrant_price>0 "
            "AND latitude BETWEEN ? AND ? AND longitude BETWEEN ? AND ? "
            "ORDER BY article_confirm_ymd DESC LIMIT ?",
            (swlat, nelat, swlng, nelng, lim + 1)).fetchall()
    too_many = len(rows) > lim
    return {"too_many": too_many, "markers": [
        {"article_no": a, "area_m2": round(ar) if ar else None, "deposit": int(pr * 10000),
         "lat": la, "lng": lo, "floor": fl, "building": b or "빌라"}
        for a, ar, pr, la, lo, fl, b in rows[:lim]]}


