@app.get("/tools/jeonse-check")
def jeonse_check(addr: str = "", lat: float = 0, lng: float = 0, area: float = 0,
                 deposit: float = 0, cortar: str = ""):
    """깡통전세 감별기 — 주소 또는 좌표(매물 선택) + 전용면적·보증금 → 공시가격(HUG 140%) 위험판정
    + 주변 통계·매물. deposit 단위: 만원."""
    if not VWORLD_KEY:
        raise HTTPException(503, "공시가격 키 미설정")
    geo = None
    if lat and lng:
        pnu = _vw_pnu(lng, lat)          # 매물 좌표 직접 사용(주소 불필요)
    elif addr:
        geo = _vw_geocode(addr)
        if not geo:
            return {"ok": False, "error": "주소를 찾지 못했어요. 지번 주소로 다시 입력해 주세요."}
        pnu = _vw_pnu(geo["x"], geo["y"])
    else:
        return {"ok": False, "error": "주소를 입력하거나 매물을 선택해 주세요."}
    if not pnu:
        return {"ok": False, "error": "해당 위치의 공시가격 필지를 찾지 못했어요."}

    # 공시가격: 공동주택(빌라/아파트) 우선, 없으면 개별주택(단독)
    deposit_won = int(deposit * 10000)
    gongsi = None
    kind = None
    bld_name = None
    matched_area = None
    gongsi_year = None
    units_out: list = []   # 한 건물 안의 면적별 공시가격(공동주택)
    # DB 캐시(villa_price) 우선 — 공시가격은 연1회 공고라 캐시 재사용. 없으면 라이브 API 폴백.
    with _open_db() as _pc:
        vp = _pc.execute("SELECT area_m2, gongsi, aphus_nm, se_nm, year FROM villa_price WHERE pnu=?",
                         (pnu["pnu"],)).fetchall()
    if vp:
        grp: dict = {}
        for ar, g, _anm, _se, _yr in vp:
            a = round(ar or 0)
            if a > 0 and g:
                grp.setdefault(a, []).append(g)
        units_out = [{"area_m2": a, "gongsi": round(sum(v) / len(v)),
                      "hug_limit": round(sum(v) / len(v) * 1.26), "n": len(v)}
                     for a, v in sorted(grp.items())]
        bld_name = vp[0][2]; kind = vp[0][3] or "공동주택"; gongsi_year = vp[0][4]
    else:
        units = _vw_ned("getApartHousingPriceAttr", pnu["pnu"])
        if units:
            yrs = [u.get("stdrYear", "") for u in units if u.get("stdrYear")]
            maxyr = max(yrs) if yrs else None
            latest = [u for u in units if u.get("stdrYear") == maxyr and u.get("pblntfPc")]
            grp = {}
            for u in latest:
                ar = round(float(u.get("prvuseAr") or 0))
                if ar > 0:
                    grp.setdefault(ar, []).append(int(u["pblntfPc"]))
            units_out = [{"area_m2": ar, "gongsi": round(sum(v) / len(v)),
                          "hug_limit": round(sum(v) / len(v) * 1.26), "n": len(v)}
                         for ar, v in sorted(grp.items())]
            if latest:
                bld_name = latest[0].get("aphusNm")
                kind = latest[0].get("aphusSeCodeNm") or "공동주택"
                gongsi_year = maxyr
    if area and units_out:                   # 입력 면적에 가장 가까운 그룹으로 판정
        best = min(units_out, key=lambda x: abs((x["area_m2"] or 0) - area))
        gongsi, matched_area = best["gongsi"], best["area_m2"]
    if gongsi is None and not units_out:      # 공동주택 아님 → 단독주택가격
        ind = _vw_ned("getIndvdHousingPriceAttr", pnu["pnu"])
        if ind:
            yrs = [u.get("stdrYear", "") for u in ind if u.get("stdrYear")]
            maxyr = max(yrs) if yrs else None
            cur = [u for u in ind if u.get("stdrYear") == maxyr and u.get("housePc")]
            if cur:
                gongsi = int(cur[0]["housePc"]); kind = "단독·다가구"; gongsi_year = maxyr
                bld_name = cur[0].get("ldCodeNm") or None
                # 건물 전체 1개 값(호별 아님) → 단일 unit. whole=True 로 프런트가 경고 표시.
                units_out = [{"area_m2": None, "gongsi": gongsi,
                              "hug_limit": round(gongsi * 1.26), "n": 1, "whole": True}]

    # 판정 (HUG 전세보증 기준 = 공시가격 × 140%)
    verdict = None
    if gongsi and deposit_won:
        ratio = deposit_won / gongsi
        hug = round(gongsi * 1.4)
        if ratio <= 1.0:
            grade, msg = "안전", "공시가격 이하입니다."
        elif ratio <= 1.2:
            grade, msg = "양호", "공시가격을 넘지만 HUG 한도 안입니다."
        elif ratio <= 1.4:
            grade, msg = "주의", "HUG 보증한도(공시가격 140%)에 근접합니다."
        else:
            grade, msg = "위험", "공시가격 140%를 초과 — HUG 전세보증도 거부되는 깡통전세 위험 수준입니다."
        verdict = {"grade": grade, "ratio": round(ratio * 100), "hug_limit": hug,
                   "gongsi": gongsi, "gongsi_year": gongsi_year, "deposit": deposit_won, "message": msg}
    elif gongsi:
        verdict = {"grade": None, "gongsi": gongsi, "gongsi_year": gongsi_year, "hug_limit": round(gongsi * 1.4),
                   "deposit": None, "message": "보증금을 입력하면 위험도를 판정해요."}

    # 주변 통계·매물 (동 단위). cortar(선택한 동) 우선 → 없으면 geo/pnu에서 해석.
    sgg = pnu["pnu"][:5]
    umd = None
    sgg_name = geo.get("sgg") if geo else None
    if cortar:
        with _open_db() as c:
            r = c.execute("SELECT cortar_name FROM regions WHERE cortar_no=?", (cortar,)).fetchone()
            umd = r[0] if r else None
            sgg = cortar[:5]
    if not umd and geo:
        umd = geo.get("umd")
    if not umd and pnu.get("addr"):     # pnu 주소에서 동/읍/면 토큰 추출
        for tok in pnu["addr"].split():
            if tok.endswith(("동", "읍", "면")):
                umd = tok; break
    nearby = _jeonse_nearby(sgg, umd)

    # 이 건물의 실거래(매매/전세 최근) + 현재 매물(좌표 근접) — 지번/좌표로 매칭
    bjibun = None
    if pnu.get("addr"):
        toks = pnu["addr"].split()
        if toks and ("-" in toks[-1] or toks[-1].rstrip("0123456789") == ""):
            bjibun = toks[-1]
    bld_deals = {"sales": [], "rents": []}
    if umd and bjibun:
        with _open_db() as c:
            for r in c.execute(
                "SELECT deal_ymd, deal_amount, excl_use_ar, floor FROM rh_transactions "
                "WHERE sgg_cd=? AND umd_nm=? AND jibun=? AND is_cancelled=0 ORDER BY deal_ymd DESC LIMIT 5",
                    (sgg, umd, bjibun)):
                bld_deals["sales"].append({"date": r[0], "amount": r[1], "area_m2": round(r[2]) if r[2] else None, "floor": r[3]})
            for r in c.execute(
                "SELECT deal_ymd, deposit, monthly_rent, excl_use_ar, floor FROM rh_rentals "
                "WHERE sgg_cd=? AND umd_nm=? AND jibun=? ORDER BY deal_ymd DESC LIMIT 5",
                    (sgg, umd, bjibun)):
                bld_deals["rents"].append({"date": r[0], "deposit": r[1], "monthly": r[2],
                                           "area_m2": round(r[3]) if r[3] else None, "floor": r[4]})
    bld_listings = []
    if lat and lng:
        path = DB_PATH.parent / _NONRESI_DB["villa"]
        if path.exists():
            d = 0.00045   # 약 45m
            seen: dict = {}   # (거래·면적·가격·월세·층) 동일 → 중복 매물 합치기
            with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as lc:
                for r in lc.execute(
                    "SELECT article_no, building_name, area2_m2, trade_type, deal_or_warrant_price, "
                    "rent_price, floor_info FROM listings WHERE latitude BETWEEN ? AND ? "
                    "AND longitude BETWEEN ? AND ? AND deal_or_warrant_price>0 LIMIT 120",
                        (lat - d, lat + d, lng - d, lng + d)):
                    key = (r[3], round(r[2] or 0), r[4], r[5] or 0)   # 거래·면적·가격·월세 (층 무시)
                    if key in seen:
                        seen[key]["dup"] += 1
                        continue
                    tt = {"A1": "매매", "B1": "전세", "B2": "월세"}.get(r[3], r[3])
                    item = {"article_no": r[0], "trade": tt,
                            "area_m2": round(r[2]) if r[2] else None,
                            "price": int(r[4] * 10000), "rent": int((r[5] or 0) * 10000),
                            "floor": r[6], "dup": 1,
                            "naver_url": f"https://m.land.naver.com/article/info/{r[0]}"}
                    seen[key] = item
                    bld_listings.append(item)
    # 옵션 A: 이 건물 공시가격 등록 면적과 ±3㎡ 맞는 매물만(옆 건물 매물 제외). + 전세 안전도 등급.
    area_units = [u for u in units_out if u.get("area_m2")]
    if area_units:
        uareas = [u["area_m2"] for u in area_units]
        bld_listings = [it for it in bld_listings
                        if it.get("area_m2") and min(abs(a - it["area_m2"]) for a in uareas) <= 3]
        for it in bld_listings:
            if it["trade"] == "전세":
                best = min(area_units, key=lambda u: abs(u["area_m2"] - it["area_m2"]))
                if best["gongsi"]:
                    rr = it["price"] / best["gongsi"]
                    it["ratio"] = round(rr * 100)
                    it["grade"] = ("양호" if rr <= 1.15 else "보증한도 확인" if rr <= 1.26
                                   else "HUG 초과 가능" if rr <= 1.40 else "고위험")
    bld_listings = bld_listings[:12]
    return {"ok": True, "input": {"addr": addr, "area": area, "deposit": deposit_won},
            "building_deals": bld_deals, "building_listings": bld_listings,
            "resolved": {"text": pnu.get("addr") or (geo.get("text") if geo else None), "pnu": pnu["pnu"],
                         "building": bld_name, "kind": kind, "matched_area": matched_area,
                         "sgg": sgg_name, "umd": umd, "land_price": pnu.get("jiga")},
            "units": units_out, "verdict": verdict, "nearby": nearby}


def _jeonse_nearby(sgg: str, umd: str | None) -> dict:
    """동(또는 구) 빌라 실거래 시세·건물단위 위험비율 + 현재 전세 매물."""
    w = ["sgg_cd=?"]; p = [sgg]
    if umd:
        w.append("umd_nm=?"); p.append(umd)
    ws = " AND ".join(w)
    out = {"scope": (umd or "") + " 빌라", "sale_median": None, "jeonse_median": None,
           "risky_pct": None, "n_buildings": None, "listings": []}
    with _open_db() as c:
        out["sale_median"] = _med(c, "rh_transactions", "deal_amount",
                                  f"{ws} AND is_cancelled=0 AND deal_ymd>='2024-06-01'", list(p))
        out["jeonse_median"] = _med(c, "rh_rentals", "deposit",
                                    f"monthly_rent=0 AND {ws} AND deal_ymd>='2024-06-01'", list(p))
        # 건물단위 위험비율(전세가율≥80%)
        rows = c.execute(
            f"""WITH s AS (SELECT mhouse_nm, CAST(excl_use_ar AS INT) ar, AVG(deal_amount) ma
                   FROM rh_transactions WHERE {ws} AND is_cancelled=0 AND deal_ymd>='2024-06-01'
                   AND mhouse_nm NOT LIKE '(%' GROUP BY mhouse_nm, ar),
                 j AS (SELECT mhouse_nm, CAST(excl_use_ar AS INT) ar, AVG(deposit) mj
                   FROM rh_rentals WHERE {ws} AND monthly_rent=0 AND deal_ymd>='2024-06-01'
                   AND mhouse_nm NOT LIKE '(%' GROUP BY mhouse_nm, ar)
                SELECT COUNT(*), SUM(CASE WHEN j.mj*100.0/NULLIF(s.ma,0)>=80 THEN 1 ELSE 0 END)
                FROM s JOIN j ON s.mhouse_nm=j.mhouse_nm AND s.ar=j.ar""", p + p).fetchone()
        if rows and rows[0]:
            out["n_buildings"] = rows[0]
            out["risky_pct"] = round((rows[1] or 0) * 100 / rows[0], 1)
    # 현재 전세 매물 (동 cortar 매핑 → listings_villa B1)
    cortar = None
    with _open_db() as c:
        if umd:
            r = c.execute("SELECT cortar_no FROM regions WHERE cortar_type='sec' AND cortar_name=? "
                          "AND substr(cortar_no,1,5)=? LIMIT 1", (umd, sgg)).fetchone()
            cortar = r[0] if r else None
    path = DB_PATH.parent / _NONRESI_DB["villa"]
    if path.exists():
        pref = cortar or sgg
        with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as lc:
            lr = lc.execute("SELECT article_no, building_name, area2_m2, deal_or_warrant_price "
                            "FROM listings WHERE substr(cortar_no,1,?)=? AND trade_type='B1' "
                            "AND deal_or_warrant_price>0 ORDER BY deal_or_warrant_price LIMIT 8",
                            (len(pref), pref)).fetchall()
        out["listings"] = [{"building": b or "-", "area_m2": round(a) if a else None,
                            "deposit": int(pr * 10000),
                            "naver_url": f"https://m.land.naver.com/article/info/{art}"}
                           for art, b, a, pr in lr]
    return out


def _nonresi_real_table(cat: str) -> tuple[str, str, str]:
    """실거래 테이블·전용면적컬럼·용도절 — 급매/환금성 비교용."""
    if cat == "villa":
        return "rh_transactions", "excl_use_ar", ""
    if cat in ("sangga", "office"):
        uc, _ = _nrg_use_clause(cat)
        return "nrg_transactions", "building_ar", uc
    return "", "", ""   # house는 대지·건물 복합이라 ㎡당 비교 제외


@app.get("/stats/nonresi/bargains")
def nonresi_bargains(cat: str, cortar: str = "", limit: int = 40):
    """③ 급매 — 호가 매물(전용면적 기준)을 같은 지역·면적대 실거래 중위 ₩/㎡와 비교해 저평가 매물 추출."""
    if cat not in _NONRESI_DB:
        raise HTTPException(400, "bad cat")
    rtable, rarea, ruse = _nonresi_real_table(cat)
    if not rtable or not cortar:
        return {"cat": cat, "available": False, "note": "단독은 ㎡당 비교 부적합, 또는 지역 미선택", "bargains": []}
    sgg = cortar[:5]
    import datetime as _dt
    cutoff = (_dt.date.today().replace(day=1) - _dt.timedelta(days=365)).strftime("%Y-%m-%d")
    rwhere = [f"sgg_cd=?", "is_cancelled=0", "deal_ymd>=?", f"{rarea}>0"]
    rparams = [sgg, cutoff]
    if ruse:
        rwhere.append(ruse)
    with _open_db() as c:
        rows = c.execute(f"SELECT {rarea}, deal_amount FROM {rtable} WHERE {' AND '.join(rwhere)}",
                         rparams).fetchall()
    # 면적대(10㎡) 버킷별 실거래 중위 ₩/㎡(전용)
    from statistics import median
    band: dict[int, list] = {}
    for ar, amt in rows:
        if ar and amt:
            band.setdefault(int(ar // 10), []).append(amt / ar)
    band_med = {b: median(v) for b, v in band.items() if len(v) >= 5}
    if not band_med:
        return {"cat": cat, "available": False, "note": "실거래 표본 부족", "bargains": []}
    # 호가 매물(매매 A1, 전용=area2) 비교
    path = DB_PATH.parent / _NONRESI_DB[cat]
    out = []
    with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as lc:
        lrows = lc.execute(
            "SELECT article_no, building_name, cortar_no, area2_m2, deal_or_warrant_price, floor_info "
            "FROM listings WHERE substr(cortar_no,1,5)=? AND trade_type='A1' "
            "AND area2_m2>0 AND deal_or_warrant_price>0", [sgg]).fetchall()
    for art, bn, ct, ar2, price, fl in lrows:
        b = int(ar2 // 10)
        med = band_med.get(b)
        if not med:
            continue
        ppm = price * 10000.0 / ar2
        disc = 1 - ppm / med
        if disc >= 0.15:
            out.append({"article_no": art, "building": bn or "-", "cortar": ct,
                        "area_m2": round(ar2), "price": int(price * 10000),
                        "floor": fl, "market_pyeong": int(med * 3.3058),
                        "discount": round(disc * 100), "needs_check": disc >= 0.4,
                        "naver_url": f"https://m.land.naver.com/article/info/{art}"})
    out.sort(key=lambda x: -x["discount"])
    return {"cat": cat, "available": True, "n_listings": len(lrows),
            "n_bargains": len(out), "bargains": out[:max(1, min(limit, 100))]}


@app.get("/stats/nonresi/liquidity")
def nonresi_liquidity(cat: str, cortar: str = ""):
    """② 환금성 — 현재 매물수(호가) vs 월평균 실거래(최근12개월) → 소진 개월수(매물 적체도)."""
    if cat not in _NONRESI_DB:
        raise HTTPException(400, "bad cat")
    rtable, _, ruse = _nonresi_real_table(cat)
    sgg = cortar[:5] if cortar else ""
    import datetime as _dt
    cutoff = (_dt.date.today().replace(day=1) - _dt.timedelta(days=365)).strftime("%Y-%m-%d")
    monthly = None
    if rtable and sgg:
        rwhere = ["sgg_cd=?", "is_cancelled=0", "deal_ymd>=?"]
        rparams = [sgg, cutoff]
        if ruse:
            rwhere.append(ruse)
        with _open_db() as c:
            n = c.execute(f"SELECT COUNT(*) FROM {rtable} WHERE {' AND '.join(rwhere)}", rparams).fetchone()[0]
        monthly = round(n / 12, 1)
    path = DB_PATH.parent / _NONRESI_DB[cat]
    listings_n = None
    if path.exists() and sgg:
        with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as lc:
            listings_n = lc.execute("SELECT COUNT(*) FROM listings WHERE substr(cortar_no,1,5)=? "
                                    "AND trade_type='A1'", [sgg]).fetchone()[0]
    months = round(listings_n / monthly, 1) if (listings_n and monthly) else None
    return {"cat": cat, "cortar": cortar, "listings": listings_n,
            "monthly_deals": monthly, "months_to_clear": months}


@app.get("/stats/nonresi/jeonse-listings")
def nonresi_jeonse_listings(cortar: str = "", limit: int = 40):
    """① 깡통전세 × 전세매물 — 동별 위험도(건물단위 전세가율≥80% 비율)를 현재 전세 매물에 부착."""
    if not cortar:
        raise HTTPException(400, "지역을 선택하세요")
    rc, rp = _rh_region_clause(cortar)
    with _open_db() as c:
        # 동별 건물단위 전세가율 → 위험건물 비율
        drows = c.execute(
            f"""WITH s AS (SELECT umd_nm, mhouse_nm, CAST(excl_use_ar AS INT) ar, AVG(deal_amount) ma
                   FROM rh_transactions WHERE {rc} AND is_cancelled=0 AND deal_ymd>='2024-06-01'
                   AND mhouse_nm NOT LIKE '(%' GROUP BY umd_nm,mhouse_nm,ar),
                 j AS (SELECT umd_nm, mhouse_nm, CAST(excl_use_ar AS INT) ar, AVG(deposit) mj
                   FROM rh_rentals WHERE {rc} AND monthly_rent=0 AND deal_ymd>='2024-06-01'
                   AND mhouse_nm NOT LIKE '(%' GROUP BY umd_nm,mhouse_nm,ar)
                SELECT s.umd_nm, COUNT(*), SUM(CASE WHEN j.mj*100.0/NULLIF(s.ma,0)>=80 THEN 1 ELSE 0 END)
                FROM s JOIN j ON s.umd_nm=j.umd_nm AND s.mhouse_nm=j.mhouse_nm AND s.ar=j.ar
                GROUP BY s.umd_nm""", rp + rp).fetchall()
    dong_risk = {r[0]: {"n": r[1], "risky": r[2], "pct": round(r[2] * 100 / r[1], 1) if r[1] else 0}
                 for r in drows}
    # 현재 전세 매물(listings_villa B1)
    path = DB_PATH.parent / _NONRESI_DB["villa"]
    items = []
    with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as lc:
        lrows = lc.execute(
            "SELECT article_no, building_name, cortar_no, area2_m2, deal_or_warrant_price "
            "FROM listings WHERE substr(cortar_no,1,?)=? AND trade_type='B1' AND deal_or_warrant_price>0 "
            "LIMIT 400", [len(cortar), cortar]).fetchall()
    # cortar(동코드) → 동명
    with _open_db() as c:
        cmap = {r[0]: r[1] for r in c.execute(
            "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='sec'").fetchall()}
    for art, bn, ct, ar2, price in lrows:
        umd = cmap.get(ct)
        risk = dong_risk.get(umd)
        items.append({"article_no": art, "building": bn or "-", "umd": umd,
                      "area_m2": round(ar2) if ar2 else None, "deposit": int(price * 10000),
                      "dong_risk_pct": risk["pct"] if risk else None,
                      "naver_url": f"https://m.land.naver.com/article/info/{art}"})
    items.sort(key=lambda x: -(x["dong_risk_pct"] or -1))
    risky_items = [x for x in items if (x["dong_risk_pct"] or 0) >= 30]
    return {"cortar": cortar, "n_listings": len(lrows), "n_risky_dong_listings": len(risky_items),
            "dong_risk": dong_risk, "listings": (risky_items or items)[:max(1, min(limit, 100))]}


def _rh_region_clause(cortar: str) -> tuple[str, list]:
    """rh_transactions/rh_rentals 는 sgg_cd(5자리)+umd_nm(동명) 키. 구=sgg_cd, 동=sgg_cd+umd_nm."""
    if not cortar:
        return "", []
    if len(cortar) <= 5:
        return "sgg_cd=?", [cortar]
    with _open_db() as mc:
        r = mc.execute("SELECT cortar_name FROM regions WHERE cortar_no=?", (cortar,)).fetchone()
    if r:
        return "sgg_cd=? AND umd_nm=?", [cortar[:5], r[0]]
    return "sgg_cd=?", [cortar[:5]]


def _med(c, table: str, col: str, where: str, params: list):
    n = c.execute(f"SELECT COUNT(*) FROM {table} WHERE {where} AND {col}>0", params).fetchone()[0]
    if not n:
        return None
    r = c.execute(f"SELECT {col} FROM {table} WHERE {where} AND {col}>0 ORDER BY {col} "
                  f"LIMIT 1 OFFSET ?", params + [n // 2]).fetchone()
    return r[0] if r else None


def _nonresi_realprice(cat: str, cortar: str) -> dict | None:
    """비단지 실거래 집계(최근 12개월·해제 제외). 카테고리별 핵심지표:
    빌라=매매/전세/월세, 단독=매매+대지평당가, 상가/사무실=매매+평당(+임대수익률 참고추정)."""
    import datetime as _dt
    cutoff = (_dt.date.today().replace(day=1) - _dt.timedelta(days=365)).strftime("%Y-%m-%d")
    rc, rp = _rh_region_clause(cortar)
    rcc = [rc] if rc else []

    if cat == "villa":
        w_tx = ["is_cancelled=0", "deal_ymd>=?"] + rcc
        w_rt = ["deal_ymd>=?"] + rcc
        with _open_db() as c:
            tx = c.execute(f"SELECT COUNT(*), CAST(AVG(deal_amount) AS INT), "
                           f"CAST(AVG(NULLIF(deal_amount,0)/NULLIF(excl_use_ar,0))*3.3058 AS INT) "
                           f"FROM rh_transactions WHERE {' AND '.join(w_tx)}", [cutoff] + rp).fetchone()
            med = _med(c, "rh_transactions", "deal_amount", ' AND '.join(w_tx), [cutoff] + rp)
            js = c.execute(f"SELECT COUNT(*), CAST(AVG(deposit) AS INT) FROM rh_rentals "
                           f"WHERE monthly_rent=0 AND {' AND '.join(w_rt)}", [cutoff] + rp).fetchone()
            ws = c.execute(f"SELECT COUNT(*), CAST(AVG(deposit) AS INT), CAST(AVG(monthly_rent) AS INT) "
                           f"FROM rh_rentals WHERE monthly_rent>0 AND {' AND '.join(w_rt)}", [cutoff] + rp).fetchone()
        if not (tx[0] or js[0] or ws[0]):
            return None
        return {"window": "최근 12개월",
                "sale": {"n": tx[0], "avg": tx[1], "median": med, "avg_pyeong": tx[2]},
                "jeonse": {"n": js[0], "avg_deposit": js[1]},
                "wolse": {"n": ws[0], "avg_deposit": ws[1], "avg_rent": ws[2]}}

    if cat == "house":
        w_tx = ["is_cancelled=0", "deal_ymd>=?"] + rcc
        w_rt = ["deal_ymd>=?"] + rcc
        with _open_db() as c:
            tx = c.execute(f"SELECT COUNT(*), CAST(AVG(deal_amount) AS INT), "
                           f"CAST(AVG(NULLIF(deal_amount,0)/NULLIF(plottage_ar,0))*3.3058 AS INT) "
                           f"FROM sh_transactions WHERE {' AND '.join(w_tx)}", [cutoff] + rp).fetchone()
            med = _med(c, "sh_transactions", "deal_amount", ' AND '.join(w_tx), [cutoff] + rp)
            ws = c.execute(f"SELECT COUNT(*), CAST(AVG(deposit) AS INT), CAST(AVG(monthly_rent) AS INT) "
                           f"FROM sh_rentals WHERE monthly_rent>0 AND {' AND '.join(w_rt)}", [cutoff] + rp).fetchone()
            js = c.execute(f"SELECT COUNT(*), CAST(AVG(deposit) AS INT) FROM sh_rentals "
                           f"WHERE monthly_rent=0 AND {' AND '.join(w_rt)}", [cutoff] + rp).fetchone()
        if not (tx[0] or ws[0] or js[0]):
            return None
        return {"window": "최근 12개월",
                "sale": {"n": tx[0], "avg": tx[1], "median": med, "avg_pyeong_land": tx[2],
                         "pyeong_label": "대지 평당"},
                "jeonse": {"n": js[0], "avg_deposit": js[1]},
                "wolse": {"n": ws[0], "avg_deposit": ws[1], "avg_rent": ws[2]}}

    if cat in ("sangga", "office"):
        uc, _ = _nrg_use_clause(cat)
        w_tx = ["is_cancelled=0", "deal_ymd>=?"] + rcc + ([uc] if uc else [])
        with _open_db() as c:
            tx = c.execute(f"SELECT COUNT(*), CAST(AVG(deal_amount) AS INT), "
                           f"CAST(AVG(NULLIF(deal_amount,0)/NULLIF(building_ar,0))*3.3058 AS INT) "
                           f"FROM nrg_transactions WHERE {' AND '.join(w_tx)}", [cutoff] + rp).fetchone()
            med = _med(c, "nrg_transactions", "deal_amount", ' AND '.join(w_tx), [cutoff] + rp)
            # 매매 ㎡당가(전유면적 기준)
            ppm = c.execute(f"SELECT AVG(NULLIF(deal_amount,0)/NULLIF(building_ar,0)) "
                            f"FROM nrg_transactions WHERE {' AND '.join(w_tx)}", [cutoff] + rp).fetchone()[0]
        # 임대 호가 ㎡당 월세(같은 카테고리 DB)
        rent_ppm = None
        path = DB_PATH.parent / _NONRESI_DB[cat]
        if path.exists() and cortar:
            with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as lc:
                rr = lc.execute("SELECT AVG(rent_price/NULLIF(area1_m2,0)) FROM listings "
                                "WHERE substr(cortar_no,1,?)=? AND trade_type='B2' AND area1_m2>10",
                                [len(cortar), cortar]).fetchone()
                rent_ppm = rr[0] if rr and rr[0] else None
        if not tx[0]:
            return None
        out = {"window": "최근 12개월",
               "sale": {"n": tx[0], "avg": tx[1], "median": med, "avg_pyeong": tx[2]}}
        if ppm and rent_ppm:   # 참고용 수익률(면적기준 상이 → 추정치)
            out["yield_est"] = round(rent_ppm * 12 / ppm * 1e4 * 100, 1)
        return out
    return None


@app.get("/stats/nearest-dong")
def nearest_dong(lat: float, lng: float):
    """접속 위치(위경도) → 가장 가까운 동(cortar_no). 우리동네 기본값용. 가장 가까운 단지의 동."""
    if not (33 < lat < 39 and 124 < lng < 132):   # 대한민국 대략 범위 밖이면 미해결
        return {"found": False}
    with _open_db() as c:
        # 중개사가 실제로 있는(realtor_dong) 가장 가까운 동 — 빈 동에 떨어져 허전해지는 것 방지.
        row = c.execute(
            "SELECT cx.cortar_no, cx.dong_name, "
            "(cx.latitude-?)*(cx.latitude-?)+(cx.longitude-?)*(cx.longitude-?) AS d2 "
            "FROM complexes cx WHERE cx.latitude IS NOT NULL AND cx.cortar_no IS NOT NULL "
            "AND cx.latitude BETWEEN ?-0.2 AND ?+0.2 AND cx.longitude BETWEEN ?-0.2 AND ?+0.2 "
            "AND EXISTS (SELECT 1 FROM realtor_dong rd WHERE rd.cortar_no=cx.cortar_no) "
            "ORDER BY d2 LIMIT 1",
            (lat, lat, lng, lng, lat, lat, lng, lng)).fetchone()
        if not row:
            return {"found": False}
        cortar = row[0]
        sgg = c.execute("SELECT cortar_name FROM regions WHERE cortar_type='dvsn' "
                        "AND substr(cortar_no,1,5)=? LIMIT 1", (cortar[:5],)).fetchone()
        sido = c.execute("SELECT cortar_name FROM regions WHERE cortar_type='city' "
                         "AND substr(cortar_no,1,2)=? LIMIT 1", (cortar[:2],)).fetchone()
    region_name = " ".join([x[0] for x in (sido, sgg) if x] + [row[1] or ""]).strip()
    return {"found": True, "cortar_no": cortar, "dong_name": row[1], "region_name": region_name}


@app.get("/stats/realtors/by-dong")
def realtors_by_dong(cortar: str, sort: str = "listings", scope: str = "complex", limit: int = 1000):
    """우리동네(동) 중개사 랭킹 — 사무소가 그 동에 소재한 등록 중개사(realtor_dong 기준).
    매물수·직원수·업력을 한눈에. scope=매물 범위: complex(단지형 아파트·오피)/resi(주거전체=단지+빌라+단독)/
    comm(상가·사무실)/all(전체)."""
    if not cortar:
        raise HTTPException(400, "cortar required")
    if limit < 1 or limit > 2000:
        limit = 1000
    ck = f"realtor_dong:{cortar}:{sort}:{scope}:{limit}"
    cached = _cache_get(ck)
    if cached is not None:
        return cached
    # 매물수 범위 — realtor_match(단지형 total_listings) + realtor_region_counts(비단지) 합산.
    _rall = ("COALESCE(rc.villa_n,0)+COALESCE(rc.house_n,0)+COALESCE(rc.sangga_n,0)+COALESCE(rc.office_n,0)"
             "+COALESCE(rc.land_n,0)+COALESCE(rc.factory_n,0)+COALESCE(rc.building_n,0)"
             "+COALESCE(rc.knowledge_n,0)+COALESCE(rc.redev_n,0)")
    scope_sql = {
        "complex": "SUM(m.total_listings)",
        "house": "SUM(COALESCE(rc.villa_n,0)+COALESCE(rc.house_n,0))",
        "comm": "SUM(COALESCE(rc.sangga_n,0)+COALESCE(rc.office_n,0))",
        "building": "SUM(COALESCE(rc.building_n,0))",
        "land": "SUM(COALESCE(rc.land_n,0)+COALESCE(rc.factory_n,0))",
        "all": f"SUM(COALESCE(m.total_listings,0) + {_rall})",
    }.get(scope, "SUM(m.total_listings)")
    import datetime as _dt
    cur_year = _dt.date.today().year
    with _open_db() as c:
        dn = c.execute("SELECT cortar_name FROM regions WHERE cortar_no=? LIMIT 1", (cortar,)).fetchone()
        # vworld 등록 중개사 전체(사무소 소재 동). 사무소(sys_regno)당 1행 — realtor_match를
        # 직접 JOIN하면 한 사무소가 여러 naver_id에 매칭돼 행이 복제됨(둥지 버그) → 서브쿼리로 집계.
        rows = c.execute(
            f"""
            SELECT rd.realtor_id, rd.sys_regno, v.business_name AS name,
                   COALESCE((SELECT {scope_sql} FROM realtor_match m
                             LEFT JOIN realtor_region_counts rc ON rc.realtor_id=m.realtor_id
                             WHERE m.sys_regno=rd.sys_regno), 0) AS listings,
                   COALESCE((SELECT SUM(COALESCE(m.total_listings,0) + {_rall})
                             FROM realtor_match m LEFT JOIN realtor_region_counts rc ON rc.realtor_id=m.realtor_id
                             WHERE m.sys_regno=rd.sys_regno), 0) AS total_n,
                   (SELECT COUNT(*) FROM vworld_employees e WHERE e.sys_regno=rd.sys_regno) AS staff,
                   substr(v.registered_ymd,1,4) AS est_yr,
                   v.phone
            FROM realtor_dong rd
            JOIN vworld_brokers v ON v.sys_regno = rd.sys_regno
            WHERE rd.cortar_no = ?
            GROUP BY rd.sys_regno
            """, (cortar,)).fetchall()
    items = []
    for r in rows:
        est = int(r[6]) if (r[6] and r[6].isdigit()) else None
        items.append({
            "realtor_id": r[0], "sys_regno": r[1], "realtor_name": r[2] or "공인중개사",
            "listings": r[3] or 0, "total_listings": r[4] or 0, "staff_count": r[5] or None,
            "established_year": est, "tenure_years": (cur_year - est) if est else None,
            "phone": r[7], "naver_linked": r[0] is not None,
        })
    key = {"staff": lambda x: x["staff_count"] or 0,
           "tenure": lambda x: x["tenure_years"] or 0}.get(sort, lambda x: x["listings"])
    items.sort(key=key, reverse=True)
    items = items[:limit]
    out = {"cortar_no": cortar, "dong_name": (dn[0] if dn else None),
           "sort": sort, "scope": scope, "count": len(items),
           "top": (items[0] if items else None), "items": items}
    _cache_put(ck, out)
    return out


@app.get("/stats/realtors/by-sido")
def realtors_by_sido(limit: int = 10, scope: str = "complex"):
    """시도별 상위 N개 중개사. scope=complex/resi/comm/all(매물 범위). 단지=cortar 앞2자리, 비단지=realtor_region_sido."""
    if limit < 1 or limit > 50:
        raise HTTPException(400, "limit out of range")
    ck = f"sido:{scope}:{limit}"
    cached = _cache_get(ck)
    if cached is not None:
        return cached
    with _open_db() as c:
        sido_names = {r[0][:2]: r[1] for r in c.execute(
            "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'")}
        parts = []
        if scope in ("complex", "all"):
            parts.append("SELECT sido, realtor_id rid, n FROM realtor_complex_sido")
        if scope in ("house", "all"):
            parts.append("SELECT sido, realtor_id rid, (villa_n+house_n) n FROM realtor_region_sido WHERE villa_n+house_n>0")
        if scope in ("comm", "all"):
            parts.append("SELECT sido, realtor_id rid, (sangga_n+office_n) n FROM realtor_region_sido WHERE sangga_n+office_n>0")
        if scope in ("building", "all"):
            parts.append("SELECT sido, realtor_id rid, building_n n FROM realtor_region_sido WHERE building_n>0")
        if scope in ("land", "all"):
            parts.append("SELECT sido, realtor_id rid, (land_n+factory_n) n FROM realtor_region_sido WHERE land_n+factory_n>0")
        if not parts:
            parts.append("SELECT substr(c.cortar_no,1,2) sido, l.realtor_id rid, COUNT(*) n "
                         "FROM listings_current l JOIN complexes c ON c.complex_no=l.complex_no "
                         "WHERE l.realtor_id IS NOT NULL AND c.cortar_no IS NOT NULL "
                         "GROUP BY substr(c.cortar_no,1,2), l.realtor_id")
        union = " UNION ALL ".join(parts)
        rows = c.execute(
            f"""
            WITH per_sido AS (SELECT sido, rid, SUM(n) n FROM ({union}) WHERE rid IS NOT NULL AND rid!='' GROUP BY sido, rid),
                 ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY sido ORDER BY n DESC) rk FROM per_sido)
            SELECT sido, rid, n FROM ranked WHERE rk <= ? ORDER BY sido, n DESC
            """, (limit,)).fetchall()
        ids = list({r[1] for r in rows})
        names = {}; totals: dict = {}
        if ids:
            ph = ",".join("?" * len(ids))
            names = {x[0]: x[1] for x in c.execute(
                f"SELECT realtor_id, realtor_name FROM realtor_names WHERE realtor_id IN ({ph})", ids)}
            for x in c.execute(f"SELECT realtor_id, COUNT(*) FROM listings_current "
                               f"WHERE realtor_id IN ({ph}) GROUP BY realtor_id", ids):
                totals[x[0]] = x[1]
            for x in c.execute(f"SELECT realtor_id, COALESCE(villa_n,0)+COALESCE(house_n,0)+"
                               f"COALESCE(sangga_n,0)+COALESCE(office_n,0)+COALESCE(land_n,0)+"
                               f"COALESCE(factory_n,0)+COALESCE(building_n,0)+COALESCE(knowledge_n,0)+COALESCE(redev_n,0)+COALESCE(oneroom_n,0) "
                               f"FROM realtor_region_counts WHERE realtor_id IN ({ph})", ids):
                totals[x[0]] = totals.get(x[0], 0) + (x[1] or 0)
    grouped: dict[str, list[dict]] = {}
    for sido, rid, n in rows:
        name = sido_names.get(sido, sido)
        grouped.setdefault(name, []).append(
            {"realtor_id": rid, "realtor_name": names.get(rid) or "공인중개사", "count": n,
             "total_count": totals.get(rid, n)})
    out = {"limit": limit, "scope": scope, "groups": grouped}
    _cache_put(ck, out)
    return out


_OFFICE_FILLER_RE = None


def _office_core(s: str | None) -> str:
    """중개사무소명에서 흔한 접미·일반어(부동산·공인중개사사무소 등)를 제거한 '핵심어'.
    '동대구푸르지오부동산' / '동대구푸르지오공인중개사사무소' → 둘 다 '동대구푸르지오'로 매칭."""
    global _OFFICE_FILLER_RE
    if _OFFICE_FILLER_RE is None:
        import re
        _OFFICE_FILLER_RE = re.compile(
            r"공인중개사사무소|부동산중개사무소|부동산공인중개사|공인중개사|중개사무소|"
            r"중개법인|부동산중개|중개사|사무소|부동산|공인|중개|랜드|에이전시")
    if not s:
        return ""
    return _OFFICE_FILLER_RE.sub("", s).replace(" ", "").lower()


def _office_name_hit(q_low: str, q_core: str, name: str | None) -> bool:
    if not name:
        return False
    if q_low in name.lower():
        return True
    return bool(q_core) and q_core in _office_core(name)


@app.get("/stats/realtors/search")
def realtors_search(q: str = "", sido: str = "", limit: int = 30):
    """중개사 검색 — 이름 부분일치 + 선택적 시도 필터. 매물 보유 내림차순.
    sido는 cortar_no 앞 2자리 (예: '11'=서울).
    캐시된 rank 테이블(51k row)에서 in-memory 필터 — listings_current 풀스캔 회피.
    """
    if limit < 1 or limit > 100:
        raise HTTPException(400, "limit out of range")
    q = q.strip()
    sido = sido.strip()
    if len(q) < 1 and not sido:
        return {"items": []}
    if sido and (len(sido) != 2 or not sido.isdigit()):
        raise HTTPException(400, "sido must be 2-digit")
    ranks = _rank_tables()
    q_low = q.lower()
    q_core = _office_core(q)
    items: list[tuple[str, str | None, int]] = []  # (rid, name, count)
    # 다중 토큰("명가 군포", "명가 이선혜") — 각 토큰이 상호·주소·대표자 중 하나에 걸리면 매칭.
    # 흔한 상호가 매물수 정렬에 밀려 못 찾는 문제 해소(지역·대표자로 좁히기).
    toks = [t for t in q.split() if t]
    if len(toks) >= 2:
        conds, params = [], []
        for t in toks:
            conds.append("(realtor_name LIKE ? OR address LIKE ? OR representative_name LIKE ?)")
            params += [f"%{t}%"] * 3
        if sido:
            conds.append("substr(cortar_no,1,2)=?"); params.append(sido)
        with _open_db() as c:
            for rid, name in c.execute(
                    f"SELECT realtor_id, realtor_name FROM naver_realtors "
                    f"WHERE {' AND '.join(conds)} LIMIT 80", params):
                nat = ranks["national"].get(rid)
                items.append((rid, name, nat[1] if nat else 0))
        return _realtors_search_finish(q, sido, items, limit)
    if sido:
        for (s, rid), (_rk, n, name) in ranks["sido_rank"].items():
            if s != sido:
                continue
            if q and not _office_name_hit(q_low, q_core, name):
                continue
            items.append((rid, name, n))
    else:
        for rid, (_rk, n, name) in ranks["national"].items():
            if q and not _office_name_hit(q_low, q_core, name):
                continue
            items.append((rid, name, n))
    # 매물이 없어 랭킹 인덱스에 없는 사무소(신규/합성 등)도 이름으로 찾게 보강.
    if q:
        seen = {rid for rid, _n, _c in items}
        with _open_db() as c:
            # 필러어 제거한 핵심어로 LIKE (없으면 원문). '동대구푸르지오부동산'→'%동대구푸르지오%'
            like_term = q_core if q_core else q
            cond, params = "(nr.realtor_name LIKE ? OR nr.representative_name = ?)", [f"%{like_term}%", q]
            if sido:
                cond += " AND substr(nr.cortar_no,1,2)=?"; params.append(sido)
            # 핵심어가 짧으면(예 '참공인'→'참') 매칭이 수백 건 → 무정렬 LIMIT은 실매물 보유 사무소를
            # 임의로 탈락시킴(금천 참공인 69건 누락). 비단지 매물수 내림차순으로 의미있는 곳부터.
            for rid, name in c.execute(
                    f"SELECT nr.realtor_id, nr.realtor_name FROM naver_realtors nr "
                    f"LEFT JOIN realtor_region_counts rc ON rc.realtor_id=nr.realtor_id "
                    f"WHERE {cond} ORDER BY (COALESCE(rc.villa_n,0)+COALESCE(rc.house_n,0)"
                    f"+COALESCE(rc.sangga_n,0)+COALESCE(rc.office_n,0)+COALESCE(rc.land_n,0)"
                    f"+COALESCE(rc.factory_n,0)+COALESCE(rc.building_n,0)+COALESCE(rc.knowledge_n,0)"
                    f"+COALESCE(rc.redev_n,0)+COALESCE(rc.oneroom_n,0)) DESC LIMIT 80", params):
                if rid not in seen:
                    nat = ranks["national"].get(rid)
                    seen.add(rid); items.append((rid, name, nat[1] if nat else 0))
        items += _vworld_search_fallback(q, sido, seen)
    return _realtors_search_finish(q, sido, items, limit)


def _vworld_search_fallback(q: str, sido: str, seen: set) -> list:
    """네이버 프로필이 없는 사무소도 공부(vworld) 상호·대표로 검색되게 하는 폴백.
    브라운홈즈(동대문, 네이버 ID 숨김) 사례 — 매물에 중개사 정보가 있는데 검색 실종 방지.
    이미 네이버 ID로 매칭(realtor_match)됐거나 프로비저닝된 사무소는 naver 경로가 커버."""
    core = _office_core(q) or q
    out = []
    with _open_db() as c:
        cond = ("vb.status='영업' AND (vb.business_name LIKE ? OR vb.representative = ?) "
                "AND NOT EXISTS (SELECT 1 FROM realtor_match rm WHERE rm.sys_regno=vb.sys_regno "
                "                AND rm.realtor_id IS NOT NULL)")
        params: list = [f"%{core}%", q]
        if sido:
            # sgg_cd 5자리의 앞 2자리 = 시도
            cond += " AND substr(vb.sgg_cd,1,2)=?"; params.append(sido)
        for sregno, name in c.execute(
                f"SELECT vb.sys_regno, vb.business_name FROM vworld_brokers vb "
                f"WHERE {cond} LIMIT 40", params):
            rid = f"vw{sregno}"
            if rid in seen:
                continue
            seen.add(rid)
            out.append((rid, name, 0))
    return out


def _live_realtor_counts(rids: list[str]) -> dict[str, int]:
    """검색 결과용 실시간 보유매물 카운트(전 매물 DB). 랭킹 pkl에 없는 신규·vw귀속
    사무소가 '매물 0'으로 보이던 문제 — idx_l_rid_snap 복합 인덱스로 건당 0.1ms 실측(2026-07-07)."""
    import glob as _g
    out = {r: 0 for r in rids}
    if not rids:
        return out
    try:
        with _open_db() as c:
            qm = ",".join("?" * len(rids))
            for rid, n in c.execute(
                    f"SELECT realtor_id, COUNT(*) FROM listings_current "
                    f"WHERE realtor_id IN ({qm}) GROUP BY realtor_id", rids):
                out[rid] += n
        for f in sorted(_g.glob(str(DB_PATH.parent / "listings_*.sqlite"))):
            d = sqlite3.connect(f"file:{f}?mode=ro", uri=True)
            try:
                snap = d.execute("SELECT MAX(snapshot_date) FROM listings").fetchone()[0]
                if snap:
                    qm = ",".join("?" * len(rids))
                    for rid, n in d.execute(
                            f"SELECT realtor_id, COUNT(*) FROM listings "
                            f"WHERE snapshot_date=? AND realtor_id IN ({qm}) GROUP BY realtor_id",
                            [snap] + rids):
                        out[rid] += n
            except sqlite3.Error:
                pass
            finally:
                d.close()
    except sqlite3.Error:
        pass
    # vworld-only 사무소(vw{sys_regno})는 매물에 realtor_id가 없어(위 카운트=0) — CP 제휴
    # 매물을 등록번호로 귀속한 office_region_counts로 보정([[naverreal-region-office-attribution]]).
    vw_ids = [r for r in rids if r and r.startswith("vw")]
    if vw_ids:
        attr = DB_PATH.parent / "office_attribution.sqlite"
        if attr.exists():
            try:
                with sqlite3.connect(f"file:{attr}?mode=ro", uri=True) as ac:
                    qm = ",".join("?" * len(vw_ids))
                    for sregno, total in ac.execute(
                            f"SELECT sys_regno, total FROM office_region_counts WHERE sys_regno IN ({qm})",
                            [r[2:] for r in vw_ids]):
                        out[f"vw{sregno}"] = out.get(f"vw{sregno}", 0) + total
            except sqlite3.Error:
                pass
    return out


def _realtors_search_finish(q: str, sido: str, items: list, limit: int) -> dict:
    # 비단지 전용 사무소 보정: 랭킹 count는 단지형(listings_current) 기반이라 상가·사무실·지산만
    # 취급하는 사무소는 count=0 → 동명 사무소에 밀려 limit에서 잘림(금천 참공인 69건 사례).
    # realtor_region_counts(비단지 10종)로 채워 정상 랭크되게 한다.
    zero = [r[0] for r in items if not r[2]]
    if zero:
        reg: dict = {}
        with _open_db() as c:
            for i in range(0, len(zero), 400):
                chunk = zero[i:i + 400]
                ph = ",".join("?" * len(chunk))
                for rid, n in c.execute(
                        f"SELECT realtor_id, (COALESCE(villa_n,0)+COALESCE(house_n,0)+COALESCE(sangga_n,0)"
                        f"+COALESCE(office_n,0)+COALESCE(land_n,0)+COALESCE(factory_n,0)+COALESCE(building_n,0)"
                        f"+COALESCE(knowledge_n,0)+COALESCE(redev_n,0)+COALESCE(oneroom_n,0)) "
                        f"FROM realtor_region_counts WHERE realtor_id IN ({ph})", chunk):
                    if n:
                        reg[rid] = n
        if reg:
            items = [(rid, nm, (c0 or reg.get(rid, 0))) for rid, nm, c0 in items]
    # 정확 상호 우선: '명가' 검색 시 상호 핵심어가 정확히 '명가'인 사무소(전국 군포 명가공인 등)를
    # '푸르지오명가' 같은 파생 상호(매물 많음)보다 위로 — 흔한 상호가 묻히지 않게.
    qc = _office_core(q) or q
    def _score(name):
        nc = _office_core(name or "") or (name or "")
        if nc == qc:
            return 0            # 정확 일치
        if nc.startswith(qc):
            return 1            # 접두 일치
        return 2                # 부분 포함
    items.sort(key=lambda r: (_score(r[1]), -r[2]))
    items = items[:limit]
    # 동명 중개사무소가 많아 이름만으론 구분 불가 → 소재지(주소)·대표자명을 함께 준다.
    info: dict = {}
    meta: dict = {}   # rid -> (staff_count, established_year) — 우리동네와 같은 톤으로 직원·업력 보강
    ids = [rid for rid, _n, _c in items]
    region_of: dict[str, str] = {}   # rid -> "서울특별시 중구 신당동" (cortar 기반, 동 수준)
    if ids:
        with _open_db() as c:
            qm = ",".join("?" * len(ids))
            for rid, rep, addr in c.execute(
                f"SELECT realtor_id, representative_name, address "
                f"FROM naver_realtors WHERE realtor_id IN ({qm})", ids):
                info[rid] = (rep, addr)
            # 지역: 주소 앞 3토큰은 도로명("중구 퇴계로")이 섞임 → cortar_no로 법정동까지 정확히
            for rid, rsi, rsg, rdo in c.execute(
                f"SELECT nr.realtor_id, si.cortar_name, sg.cortar_name, do_.cortar_name "
                f"FROM naver_realtors nr "
                f"LEFT JOIN regions si ON si.cortar_no=substr(nr.cortar_no,1,2)||'00000000' "
                f"LEFT JOIN regions sg ON sg.cortar_no=substr(nr.cortar_no,1,5)||'00000' "
                f"LEFT JOIN regions do_ ON do_.cortar_no=nr.cortar_no AND substr(nr.cortar_no,6,5)!='00000' "
                f"WHERE nr.realtor_id IN ({qm}) AND nr.cortar_no IS NOT NULL", ids):
                parts = [x for x in (rsi, rsg, rdo) if x]
                if parts:
                    region_of[rid] = " ".join(parts)
            for rid, staff, est in c.execute(
                f"SELECT m.realtor_id, "
                f"(SELECT COUNT(*) FROM vworld_employees e WHERE e.sys_regno=m.sys_regno), "
                f"substr(vb.registered_ymd,1,4) "
                f"FROM realtor_match m LEFT JOIN vworld_brokers vb ON vb.sys_regno=m.sys_regno "
                f"WHERE m.realtor_id IN ({qm})", ids):
                meta[rid] = (staff or None, int(est) if (est and est.isdigit()) else None)
            # vworld 폴백(vw{sys_regno}) — 프로비저닝 전이거나 cortar가 시군구 레벨이라
            # 동이 빠지는 사무소는 vworld의 dong_name(주소 파싱)으로 동 수준까지 보강
            vw_all = [rid for rid in ids if rid.startswith("vw")]
            if vw_all:
                qm2 = ",".join("?" * len(vw_all))
                for sregno, rep, addr, est, dong_nm in c.execute(
                        f"SELECT sys_regno, representative, address, substr(registered_ymd,1,4), dong_name "
                        f"FROM vworld_brokers WHERE sys_regno IN ({qm2})",
                        [r[2:] for r in vw_all]):
                    rid = f"vw{sregno}"
                    if rid not in info:
                        info[rid] = (rep, addr)
                        staff = c.execute("SELECT COUNT(*) FROM vworld_employees WHERE sys_regno=?",
                                          (sregno,)).fetchone()[0]
                        meta[rid] = (staff or None, int(est) if (est and est.isdigit()) else None)
                    if dong_nm:
                        base = region_of.get(rid)
                        if base and dong_nm not in base:
                            region_of[rid] = f"{base} {dong_nm}"
                        elif not base and addr:
                            region_of[rid] = " ".join(addr.split()[:2] + [dong_nm])

    def _loc(rid: str, addr: str | None) -> str | None:
        if region_of.get(rid):
            return region_of[rid]                     # cortar 기반 "시도 시군구 동"
        if not addr:
            return None
        toks = addr.split()
        return " ".join(toks[:3]) if toks else None   # 폴백: 주소 앞 3토큰

    # 랭킹 인덱스에 없어 매물 0으로 보이는 사무소(vw 귀속·신규)는 라이브 카운트로 보정
    zero_ids = [rid for rid, _n, c_ in items if rid and c_ == 0]
    live = _live_realtor_counts(zero_ids) if zero_ids else {}

    return {
        "q": q, "sido": sido,
        "items": [
            {"realtor_id": rid, "realtor_name": name,
             "count": (live.get(rid) or n) if n == 0 else n,
             "representative": (info.get(rid) or (None, None))[0],
             "location": _loc(rid, (info.get(rid) or (None, None))[1]),
             "address": (info.get(rid) or (None, None))[1],
             "staff_count": (meta.get(rid) or (None, None))[0],
             "established_year": (meta.get(rid) or (None, None))[1]}
            for rid, name, n in items
        ],
    }


# 랭킹 영속 파일. listings 는 하루 1회(수집)만 바뀌므로, 매 요청·재시작마다 414만
# 행을 GROUP BY 하지 않고 파일에서 즉시 로드한다. daily_run(build_api_cache)이 매일
# persist_ranks() 로 새로 빌드해 갱신.
_RANK_FILE = DB_PATH.parent / "realtor_ranks.pkl"
# 시작 시 현재 mtime으로 초기화 — 재시작만으로는 '변경됨'으로 오판해 디스크캐시를 비우지
# 않도록(영속 캐시 보존). 데이터 실제 갱신(daily가 파일 재작성) 시엔 mtime이 바뀌어 무효화.
try:
    _rank_loaded_mtime: float | None = _RANK_FILE.stat().st_mtime
except OSError:
    _rank_loaded_mtime = None


def _rank_tables() -> dict:
    """랭킹 테이블. 메모리캐시 → 영속파일 → (없으면) 라이브 빌드 순.
    national: id->(rank,count,name), sido_rank: (sido,id)->(rank,count,name),
    sido_totals, sido_names, national_total."""
    global _rank_loaded_mtime
    # 매일 아침 daily_run 이 랭킹 파일을 새로 쓰면 mtime 이 바뀐다 → 모든 realtor
    # 캐시를 비워 새 데이터를 즉시 반영('보존기간'을 아침 파이프라인 완료 기준으로).
    try:
        mtime = _RANK_FILE.stat().st_mtime
    except OSError:
        mtime = None
    if mtime is not None and mtime != _rank_loaded_mtime:
        _realtor_cache.clear()
        _rc_clear()               # 디스크 캐시도 비움(daily 갱신 반영)
        _rank_loaded_mtime = mtime
    cached = _cache_get("ranks")
    if cached is not None:
        return cached
    out = None
    if _RANK_FILE.exists():
        try:
            with open(_RANK_FILE, "rb") as f:
                out = pickle.load(f)
        except Exception:
            out = None
    if out is None:
        out = _build_ranks()            # 파일 없으면 라이브 빌드(느림) 후 저장
        try:
            with open(_RANK_FILE, "wb") as f:
                pickle.dump(out, f)
        except OSError:
            pass
    _cache_put("ranks", out)
    return out


def persist_ranks() -> None:
    """랭킹을 새로 빌드해 영속 파일에 저장. daily_run(build_api_cache)에서 호출 —
    서버는 이 파일을 즉시 로드하므로 realtor 페이지가 항상 빠르다."""
    out = _build_ranks()
    with open(_RANK_FILE, "wb") as f:
        pickle.dump(out, f)


def _build_ranks() -> dict:
    """listings_current 를 GROUP BY 해 랭킹을 라이브 계산(35~112s). 직접 호출 금지 —
    _rank_tables()/persist_ranks() 를 통해서만."""
    with _open_db() as c:
        nat_rows = c.execute(
            """
            SELECT realtor_id, MAX(realtor_name) AS realtor_name, COUNT(*) AS n
            FROM listings_current WHERE realtor_id IS NOT NULL
            GROUP BY realtor_id
            """
        ).fetchall()
        sido_rows = c.execute(
            """
            SELECT substr(c.cortar_no,1,2) AS sido,
                   l.realtor_id, MAX(l.realtor_name) AS realtor_name, COUNT(*) AS n
            FROM listings_current l
            JOIN complexes c ON c.complex_no = l.complex_no
            WHERE l.realtor_id IS NOT NULL AND c.cortar_no IS NOT NULL
            GROUP BY sido, l.realtor_id
            """
        ).fetchall()
        sido_names = {
            r[0][:2]: r[1]
            for r in c.execute(
                "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'"
            )
        }
        # 동률 타이브레이크용 비단지 매물수(전체매물 = 단지 n + 비단지). national
        # 리스트(/stats/realtors/national)와 순위가 어긋나지 않도록 같은 기준 적용.
        reg_total: dict[str, int] = {}
        try:
            for rid, x in c.execute(
                "SELECT realtor_id, COALESCE(villa_n,0)+COALESCE(house_n,0)+"
                "COALESCE(sangga_n,0)+COALESCE(office_n,0)+COALESCE(land_n,0)+"
                "COALESCE(factory_n,0)+COALESCE(building_n,0)+COALESCE(knowledge_n,0)+"
                "COALESCE(redev_n,0) FROM realtor_region_counts"
            ):
                if rid:
                    reg_total[rid] = x or 0
        except sqlite3.Error:
            reg_total = {}     # 비단지 테이블 없으면 단지 매물수만으로 정렬
    # 1순위=단지 매물수(n), 동률 시 2순위=전체매물(n+비단지) DESC, 그 다음 id 안정정렬.
    nat_sorted = sorted(nat_rows, key=lambda r: (-r[2], -(r[2] + reg_total.get(r[0], 0)), r[0]))
    national: dict[str, tuple[int, int, str]] = {
        rid: (i + 1, n, name) for i, (rid, name, n) in enumerate(nat_sorted)
    }
    by_sido: dict[str, list[tuple[str, str, int]]] = {}
    for sido, rid, name, n in sido_rows:
        by_sido.setdefault(sido, []).append((rid, name, n))
    sido_rank: dict[tuple[str, str], tuple[int, int, str]] = {}
    sido_totals: dict[str, int] = {}
    for sido, items in by_sido.items():
        items.sort(key=lambda r: -r[2])
        sido_totals[sido] = len(items)
        for i, (rid, name, n) in enumerate(items):
            sido_rank[(sido, rid)] = (i + 1, n, name)
    out = {
        "national": national,
        "sido_rank": sido_rank,
        "sido_totals": sido_totals,
        "sido_names": sido_names,
        "national_total": len(nat_sorted),
    }
    return out


@app.get("/realtor/{realtor_id}/staff")
def realtor_staff(realtor_id: str):
    """소속 직원 명단 — 국가공간정보(V-World) 부동산중개업 공시 그대로.
    이름·구분(공인중개사/중개보조원 등)·직위(대표/소속…)·상태 전부 반환.
    vworld는 공부상 공개 정보라 실명 노출 가능(사이트 회원 별명정책과 무관)."""
    with _open_db() as c:
        row = c.execute("SELECT sys_regno FROM realtor_match WHERE realtor_id=?",
                        (realtor_id,)).fetchone()
        sys_regno = row[0] if row and row[0] else None
        if not sys_regno and realtor_id.startswith("vw"):
            sys_regno = realtor_id[2:]           # vw프로비저닝 사무소(vw+sys_regno)
        if not sys_regno:
            raise HTTPException(404, "V-World 매칭 정보가 없는 사무소입니다")
        rows = c.execute(
            "SELECT employee_name, role, position, status, business_name, fetched_at "
            "FROM vworld_employees WHERE sys_regno=?", (sys_regno,)).fetchall()
    # 대표 → 공인중개사(소속) → 중개보조원 → 기타, 같은 그룹 안은 이름순
    def _ord(r):
        pos, role = r[2] or "", r[1] or ""
        if pos == "대표":
            g = 0
        elif role in ("공인중개사", "중개인", "법인"):
            g = 1
        elif role == "중개보조원":
            g = 2
        else:
            g = 3
        return (g, r[0] or "")
    rows = sorted(rows, key=_ord)
    return {
        "realtor_id": realtor_id,
        "sys_regno": sys_regno,
        "business_name": rows[0][4] if rows else None,
        "as_of": max((r[5] or "" for r in rows), default=None),
        "count": len(rows),
        "items": [{"name": r[0], "role": r[1], "position": r[2], "status": r[3]}
                  for r in rows],
    }


def _office_region_sys_regno(realtor_id: str) -> str | None:
    """중개사 realtor_id → 사무소 sys_regno. vw{sys_regno}는 직접, 네이버는 realtor_match 경유."""
    if realtor_id.startswith("vw") and realtor_id[2:].isdigit():
        return realtor_id[2:]
    with _open_db() as c:
        r = c.execute("SELECT sys_regno FROM realtor_match WHERE realtor_id=? AND sys_regno IS NOT NULL",
                      (realtor_id,)).fetchone()
        return r[0] if r else None


def _office_region_cats(realtor_id: str) -> dict:
    """이 사무소의 비단지 CP매물 귀속 카테고리별 수(office_region_counts.by_cat).
    등록번호 기반 귀속([[naverreal-region-office-attribution]])."""
    attr = DB_PATH.parent / "office_attribution.sqlite"
    if not attr.exists():
        return {}
    sys_regno = _office_region_sys_regno(realtor_id)
    if not sys_regno:
        return {}
    try:
        with sqlite3.connect(f"file:{attr}?mode=ro", uri=True) as ac:
            r = ac.execute("SELECT by_cat FROM office_region_counts WHERE sys_regno=?", (sys_regno,)).fetchone()
            return _json.loads(r[0]) if r and r[0] else {}
    except (sqlite3.Error, ValueError):
        return {}


@app.get("/realtor/{realtor_id}")
def realtor_detail(realtor_id: str):
    """중개사 상세: 전국 등수, 시도별 등수, 단지별 매물 집계."""
    # vw{sys_regno}(vworld-only 사무소)는 상세 접근 시 naver_realtors에 자동등록(멱등) →
    # 검색엔 뜨는데 상세는 404나던 문제 해결(2026-07-14). CP제휴 매물은 아래 region_listings로.
    if realtor_id.startswith("vw") and realtor_id[2:].isdigit():
        _provision_vworld_office(realtor_id)
    ranks = _rank_tables()
    nat = ranks["national"].get(realtor_id)
    if nat:
        nat_rank, total_count, realtor_name = nat
    else:
        # 비단지 전용 중개사 — 단지(national) 랭킹엔 없지만 매칭/비단지 매물이 있으면 표시.
        with _open_db() as c:
            exists = c.execute(
                "SELECT 1 FROM realtor_match WHERE realtor_id=? UNION ALL "
                "SELECT 1 FROM realtor_region_counts WHERE realtor_id=? UNION ALL "
                # vworld 수동등록(vw…)·신규개업 등 매물 없는 사무소도 기본정보 표시
                "SELECT 1 FROM naver_realtors WHERE realtor_id=? LIMIT 1",
                (realtor_id, realtor_id, realtor_id)).fetchone()
            if not exists:
                raise HTTPException(404, "realtor not found")
            nm = c.execute("SELECT realtor_name FROM realtor_names WHERE realtor_id=?", (realtor_id,)).fetchone()
            if not nm:
                nm = c.execute("SELECT realtor_name FROM naver_realtors WHERE realtor_id=?", (realtor_id,)).fetchone()
        nat_rank, total_count, realtor_name = None, 0, (nm[0] if nm else realtor_id)
    by_sido_out = []
    for (sido, rid), (rk, n, _name) in ranks["sido_rank"].items():
        if rid == realtor_id:
            by_sido_out.append({
                "sido_code": sido,
                "sido_name": ranks["sido_names"].get(sido, sido),
                "count": n,
                "rank": rk,
                "total_in_sido": ranks["sido_totals"].get(sido, 0),
            })
    by_sido_out.sort(key=lambda r: -r["count"])

    with _open_db() as c:
        cx_rows = c.execute(
            """
            SELECT l.complex_no, c.complex_name, l.trade_type, COUNT(*) AS n
            FROM listings_current l
            LEFT JOIN complexes c ON c.complex_no = l.complex_no
            WHERE l.realtor_id = ?
            GROUP BY l.complex_no, l.trade_type
            """,
            (realtor_id,),
        ).fetchall()
    by_complex_map: dict[str, dict] = {}
    for cno, cname, t, n in cx_rows:
        key = cno or "__none__"
        e = by_complex_map.setdefault(key, {
            "complex_no": cno, "complex_name": cname,
            "A1": 0, "B1": 0, "B2": 0, "total": 0,
        })
        if t in ("A1", "B1", "B2"):
            e[t] += n
        e["total"] += n
    by_complex = sorted(by_complex_map.values(), key=lambda r: -r["total"])

    # Naver 중개사 정보 (naver_realtors)
    naver_info = None
    with _open_db() as c:
        nr = c.execute(
            """
            SELECT realtor_name, representative_name, address,
                   representative_tel_no, cell_phone_no, home_page_url,
                   latitude, longitude, deal_count, lease_count, rent_count
            FROM naver_realtors WHERE realtor_id = ?
            """,
            (realtor_id,),
        ).fetchone()
        if nr:
            naver_info = {
                "name": nr[0], "representative": nr[1], "address": nr[2],
                "tel": nr[3], "cell": nr[4], "homepage": nr[5],
                "latitude": nr[6], "longitude": nr[7],
                "deal_count": nr[8], "lease_count": nr[9], "rent_count": nr[10],
            }

    # vworld 매칭 정보 (realtor_match 테이블) + 직원 카운트
    vworld_match = None
    with _open_db() as c:
        row = c.execute(
            """
            SELECT m.match_type, m.sys_regno, m.vworld_name, m.vworld_rep,
                   m.candidates_json, b.address, b.phone, b.status,
                   b.registered_ymd, b.ra_regno
            FROM realtor_match m
            LEFT JOIN vworld_brokers b ON b.sys_regno = m.sys_regno
            WHERE m.realtor_id = ?
            """,
            (realtor_id,),
        ).fetchone()
        if row:
            import json as _json
            cands = _json.loads(row[4]) if row[4] else []
            sys_regno = row[1]
            # 직원 카운트 (개인 이름 노출 안 함)
            licensed = assistant = 0
            if sys_regno:
                emp_rows = c.execute(
                    "SELECT role, COUNT(*) FROM vworld_employees "
                    "WHERE sys_regno=? GROUP BY role",
                    (sys_regno,),
                ).fetchall()
                for role, n in emp_rows:
                    if role in ("공인중개사", "중개인", "법인"):
                        licensed += n
                    elif role == "중개보조원":
                        assistant += n
            vworld_match = {
                "match_type": row[0],
                "sys_regno": sys_regno,
                "name": row[2],
                "representative": row[3],
                "address": row[5],
                "phone": row[6],
                "status": row[7],
                "registered_ymd": row[8],
                "ra_regno": row[9],
                "candidates": cands,
                "employees": {
                    "licensed": licensed,
                    "assistant": assistant,
                    "total": licensed + assistant,
                },
            }

    # 매물 통계 — 단지형(기본) + 비단지 유형별 + 전체(부수). 사이트 일관 규칙.
    with _open_db() as c:
        rc = c.execute("SELECT villa_n,house_n,sangga_n,office_n,land_n,factory_n,building_n,knowledge_n,redev_n,COALESCE(oneroom_n,0) "
                       "FROM realtor_region_counts WHERE realtor_id=?", (realtor_id,)).fetchone()
    vals = [x or 0 for x in (rc or (0,) * 10)]
    while len(vals) < 10:   # 구버전 테이블(oneroom_n 없음) 호환
        vals.append(0)
    _v, _h, _s, _o, _l, _f, _b, _k, _r, _or = vals[:10]
    # CP 제휴 등 비단지 매물의 등록번호 귀속 수(office_region_counts)와 realtor_region_counts를 합치되
    # **카테고리별 max**로 중복 제거 — 귀속배치가 realtor_id를 세팅하면 같은 매물이 양쪽에 잡혀
    # 이중집계(예: 틸트 6건→12)되던 버그 수정. 둘은 같은 등록번호 귀속의 두 표현이라 max가 정확.
    _rcat = _office_region_cats(realtor_id)
    if _rcat:
        _v = max(_v, _rcat.get("villa", 0)); _h = max(_h, _rcat.get("house", 0)); _s = max(_s, _rcat.get("sangga", 0))
        _o = max(_o, _rcat.get("office", 0)); _l = max(_l, _rcat.get("land", 0)); _f = max(_f, _rcat.get("factory", 0))
        _b = max(_b, _rcat.get("building", 0)); _k = max(_k, _rcat.get("knowledge", 0)); _r = max(_r, _rcat.get("redev", 0))
        _or = max(_or, _rcat.get("oneroom", 0))
    listing_breakdown = {
        "complex": total_count, "villa": _v, "house": _h, "sangga": _s, "office": _o,
        "land": _l, "factory": _f, "building": _b, "knowledge": _k, "redev": _r, "oneroom": _or,
        "total": total_count + _v + _h + _s + _o + _l + _f + _b + _k + _r + _or,
    }

    # 대표 분야(최다 유형) 순위 + 전체 매물 순위. 단지형만으로 줄세우던 한계 보완.
    _TLABEL = {"complex": "단지형", "villa": "빌라", "house": "단독", "sangga": "상가",
               "office": "사무실", "building": "빌딩", "land": "토지", "factory": "공장",
               "knowledge": "지식산업센터", "redev": "재개발", "oneroom": "원룸"}
    _tkeys = ["complex", "villa", "house", "sangga", "office", "building", "land", "factory", "knowledge", "redev", "oneroom"]
    top_key = max(_tkeys, key=lambda k: listing_breakdown.get(k, 0))
    top_n = listing_breakdown.get(top_key, 0)
    rep_rank = total_rank_out = None
    if top_n > 0:
        with _open_db() as c:
            if top_key == "complex":
                nrk = c.execute("SELECT COUNT(*)+1 FROM realtor_match WHERE total_listings>?", (top_n,)).fetchone()[0]
                ntot = c.execute("SELECT COUNT(*) FROM realtor_match WHERE total_listings>0").fetchone()[0]
                ps = c.execute("SELECT sido,n FROM realtor_complex_sido WHERE realtor_id=? ORDER BY n DESC LIMIT 1",
                               (realtor_id,)).fetchone()
                sname = srk = None
                if ps:
                    sname = ranks["sido_names"].get(ps[0], ps[0])
                    srk = c.execute("SELECT COUNT(*)+1 FROM realtor_complex_sido WHERE sido=? AND n>?",
                                    (ps[0], ps[1])).fetchone()[0]
            else:
                col = top_key + "_n"
                nrk = c.execute(f"SELECT COUNT(*)+1 FROM realtor_region_counts WHERE {col}>?", (top_n,)).fetchone()[0]
                ntot = c.execute(f"SELECT COUNT(*) FROM realtor_region_counts WHERE {col}>0").fetchone()[0]
                ps = c.execute(f"SELECT sido,{col} FROM realtor_region_sido WHERE realtor_id=? ORDER BY {col} DESC LIMIT 1",
                               (realtor_id,)).fetchone()
                sname = srk = None
                if ps and ps[1]:
                    sname = ranks["sido_names"].get(ps[0], ps[0])
                    srk = c.execute(f"SELECT COUNT(*)+1 FROM realtor_region_sido WHERE sido=? AND {col}>?",
                                    (ps[0], ps[1])).fetchone()[0]
            rep_rank = {"type": _TLABEL[top_key], "type_key": top_key, "count": top_n,
                        "national_rank": nrk, "national_total": ntot, "sido_name": sname, "sido_rank": srk}
            tn = listing_breakdown["total"]
            trk = c.execute("SELECT COUNT(*)+1 FROM realtor_total WHERE total_n>?", (tn,)).fetchone()[0]
            ttot = c.execute("SELECT COUNT(*) FROM realtor_total WHERE total_n>0").fetchone()[0]
            total_rank_out = {"count": tn, "national_rank": trk, "national_total": ttot}

    # 거래유형 분포 — 전 유형(단지형+비단지) 기준. 통계 막대가 단지형(by_complex)만 세서
    # 보유매물(전 유형) 매매수와 안 맞던 문제 보완. 보유매물과 동일 소스(_collect)라 숫자 일치.
    _tt = {"매매": 0, "전세": 0, "월세": 0, "단기임대": 0}
    for it in _collect_realtor_listings(realtor_id, None, ""):
        k = it.get("trade_type")
        if k in _tt:
            _tt[k] += 1
    trade_totals = {"A1": _tt["매매"], "B1": _tt["전세"], "B2": _tt["월세"] + _tt["단기임대"]}

    return {
        "realtor_id": realtor_id,
        "realtor_name": realtor_name,
        "total_count": total_count,
        "listing_breakdown": listing_breakdown,
        "trade_totals": trade_totals,
        "rep_rank": rep_rank,
        "total_rank": total_rank_out,
        "national_rank": nat_rank,
        "national_total": ranks["national_total"],
        "by_sido": by_sido_out,
        "by_complex": by_complex,
        "vworld": vworld_match,
        "naver": naver_info,
    }


@app.get("/complex/{complex_no}/summary")
def complex_summary(complex_no: str):
    """단지 종합 대시보드 — 역대최고가·최근실거래(최고가표시)·평형별 호가(최저/최고)·매물수."""
    with _open_db() as d:
        cx = d.execute(
            "SELECT complex_name, total_household_count, use_approve_ymd, construction_company, "
            "dong_name, real_estate_type_name, total_building_count, parking_per_household, "
            "latitude, longitude FROM complexes WHERE complex_no=?", (complex_no,)).fetchone()
        if not cx:
            raise HTTPException(404, "complex not found")
        reg = d.execute(
            "SELECT rsi.cortar_name, rsg.cortar_name, rdo.cortar_name FROM complexes cx "
            "LEFT JOIN regions rsi ON rsi.cortar_no=substr(cx.cortar_no,1,2)||'00000000' "
            "LEFT JOIN regions rsg ON rsg.cortar_no=substr(cx.cortar_no,1,5)||'00000' "
            "LEFT JOIN regions rdo ON rdo.cortar_no=cx.cortar_no WHERE cx.complex_no=?", (complex_no,)).fetchone()
        region = " ".join(x for x in [
            (_SIDO_SHORT.get(reg[0], reg[0]) if reg else None), (reg[1] if reg else None), (reg[2] if reg else None)] if x)
        # 역대 최고가 = 매매계열(매매+분양권)만. 전세/월세 record 혼입 방지.
        rec = d.execute("SELECT area_key, record_price, record_date, prev_high FROM tx_record_rollup "
                        "WHERE complex_no=? AND kind IN ('sale','silv','offi_sale') ORDER BY record_price DESC LIMIT 1",
                        (complex_no,)).fetchone()
        record_high = {"area_key": rec[0], "price": rec[1], "date": rec[2], "prev_high": rec[3]} if rec else None
        # 최근 실거래 = 매매 + 분양권 + 오피매매 통합(신축 분양권 단지·오피스텔 단지가
        # 비어 보이던 문제 수정 — 오피 실거래는 offi_transactions에 별도 적재).
        rtx = d.execute(
            "SELECT deal_ymd, deal_amount, excl_use_ar, floor, 0 AS is_silv FROM transactions "
            "WHERE matched_complex_no=? AND is_cancelled=0 "
            "UNION ALL "
            "SELECT deal_ymd, deal_amount, excl_use_ar, floor, 1 AS is_silv FROM silv_transactions "
            "WHERE matched_complex_no=? AND is_cancelled=0 "
            "UNION ALL "
            "SELECT deal_ymd, deal_amount, excl_use_ar, floor, 0 AS is_silv FROM offi_transactions "
            "WHERE matched_complex_no=? AND is_cancelled=0 "
            "ORDER BY deal_ymd DESC LIMIT 8", (complex_no, complex_no, complex_no)).fetchall()
        recent_tx = [{"date": r[0], "price": r[1], "area": r[2], "floor": r[3], "is_silv": bool(r[4])} for r in rtx]
        # 최근 거래 통합 피드(매매+전세+월세, 종합탭 시인성 개선 2026-07-04) — 뱃지에 필요한
        # 신고가·직거래·등기·재계약·갱신권·종전금액까지 포함. 신고가=같은 평형그룹의 이전 최고가 경신.
        ra = d.execute(
            "SELECT 'sale' kind, t.deal_ymd, t.deal_amount price, 0 rent, t.excl_use_ar, t.floor, "
            "  json_extract(t.raw,'$.aptDong') dong, t.dealing_gbn, "
            "  (json_extract(t.raw,'$.rgstDate') IS NOT NULL AND json_extract(t.raw,'$.rgstDate')!='') registered, "
            "  NULL contract_type, NULL use_rr, NULL pre_dep, NULL pre_rent, NULL silv_kind, 'apt' src "
            "FROM transactions t WHERE t.matched_complex_no=? AND t.is_cancelled=0 "
            "UNION ALL "
            "SELECT 'sale', deal_ymd, deal_amount, 0, excl_use_ar, floor, NULL, dealing_gbn, 0, "
            "  NULL, NULL, NULL, NULL, ownership_gbn, 'silv' FROM silv_transactions "
            "WHERE matched_complex_no=? AND is_cancelled=0 "
            "UNION ALL "
            "SELECT 'sale', t.deal_ymd, t.deal_amount, 0, t.excl_use_ar, t.floor, NULL, t.dealing_gbn, "
            "  (json_extract(t.raw,'$.rgstDate') IS NOT NULL AND json_extract(t.raw,'$.rgstDate')!=''), "
            "  NULL, NULL, NULL, NULL, NULL, 'offi' FROM offi_transactions t "
            "WHERE t.matched_complex_no=? AND t.is_cancelled=0 "
            "UNION ALL "
            "SELECT CASE WHEN monthly_rent>0 THEN 'wolse' ELSE 'jeonse' END, deal_ymd, deposit, "
            "  monthly_rent, excl_use_ar, floor, NULL, NULL, 0, "
            "  contract_type, use_rr_right, pre_deposit, pre_monthly_rent, NULL, 'apt' "
            "FROM rentals WHERE matched_complex_no=? "
            "UNION ALL "
            "SELECT CASE WHEN monthly_rent>0 THEN 'wolse' ELSE 'jeonse' END, deal_ymd, deposit, "
            "  monthly_rent, excl_use_ar, floor, NULL, NULL, 0, "
            "  contract_type, use_rr_right, pre_deposit, pre_monthly_rent, NULL, 'offi' "
            "FROM offi_rentals WHERE matched_complex_no=? "
            "ORDER BY deal_ymd DESC LIMIT 10",
            (complex_no, complex_no, complex_no, complex_no, complex_no)).fetchall()
        recent_all = []
        for r in ra:
            kind, ymd_, price, rent, ar, fl, dong, gbn, regi, ctype, urr, pdep, prent, silv, src = r
            row = {"kind": kind, "date": ymd_, "price": price, "rent": rent or 0,
                   "area": ar, "floor": fl, "dong": dong, "silv_kind": silv,
                   "direct": gbn == "직거래", "registered": bool(regi),
                   "renew": bool(ctype and "갱신" in str(ctype)), "rr": urr == "사용",
                   "pre_deposit": pdep, "pre_rent": prent,
                   "record_high": False, "complex_record_high": False}
            if kind == "sale" and not silv and ar is not None and price:
                tbl = "offi_transactions" if src == "offi" else "transactions"
                # 타입신고가: 같은 평형그룹(전용 10㎡ 버킷) 내 이전 최고가 경신
                prev = d.execute(
                    f"SELECT MAX(deal_amount) FROM {tbl} WHERE matched_complex_no=? "
                    "AND is_cancelled=0 AND deal_ymd<? AND CAST(excl_use_ar/10 AS INT)=CAST(?/10 AS INT)",
                    (complex_no, ymd_, ar)).fetchone()[0]
                row["record_high"] = bool(prev is None or price > prev)
                # 단지신고가: 단지 전체(아파트+오피, 분양권 제외) 이전 최고가 경신 ⟹ 타입신고가도 참
                prevc = d.execute(
                    "SELECT MAX(mx) FROM ("
                    "  SELECT MAX(deal_amount) mx FROM transactions WHERE matched_complex_no=? AND is_cancelled=0 AND deal_ymd<?"
                    "  UNION ALL SELECT MAX(deal_amount) FROM offi_transactions WHERE matched_complex_no=? AND is_cancelled=0 AND deal_ymd<?)",
                    (complex_no, ymd_, complex_no, ymd_)).fetchone()[0]
                row["complex_record_high"] = bool(prevc is None or price > prevc)
            recent_all.append(row)
        cnt = {"A1": 0, "B1": 0, "B2": 0}
        units = {"A1": 0, "B1": 0, "B2": 0}   # 실매물(중복 광고 합침)
        for t, n, u in d.execute(
                "SELECT trade_type, COUNT(*), SUM(1.0/MAX(COALESCE(same_addr_cnt,1),1)) "
                "FROM listings_current WHERE complex_no=? GROUP BY trade_type", (complex_no,)):
            if t in cnt:
                cnt[t] = n
                units[t] = int(round(u or 0))
        cnt["total"] = cnt["A1"] + cnt["B1"] + cnt["B2"]
        units["total"] = units["A1"] + units["B1"] + units["B2"]
        # 평형별 min~max — 자릿수 오타(예: 5.9억→61.8억) 제외: 셀 중위값의 0.4~2.5배 밖 컷
        rows = d.execute(
            """WITH p AS (
                 SELECT area_name, trade_type, deal_or_warrant_price pr,
                        ROW_NUMBER() OVER (PARTITION BY area_name, trade_type ORDER BY deal_or_warrant_price) rn,
                        COUNT(*) OVER (PARTITION BY area_name, trade_type) n
                 FROM listings_current
                 WHERE complex_no=? AND deal_or_warrant_price>0 AND deal_or_warrant_price<1000000000000),
               md AS (SELECT area_name, trade_type, AVG(pr) m FROM p
                      WHERE rn IN ((n+1)/2, n/2+1) GROUP BY area_name, trade_type)
               SELECT p.area_name, p.trade_type, COUNT(*),
                      MIN(CASE WHEN p.pr BETWEEN md.m*0.4 AND md.m*2.5 THEN p.pr END),
                      MAX(CASE WHEN p.pr BETWEEN md.m*0.4 AND md.m*2.5 THEN p.pr END)
               FROM p JOIN md ON md.area_name=p.area_name AND md.trade_type=p.trade_type
               GROUP BY p.area_name, p.trade_type""", (complex_no,)).fetchall()
        # 타입명(area_name) → 전용/공급 면적·세대수 (complex_areas: pyeong_name == listings.area_name)
        areas_map = {pn: (sup, exc, hh) for pn, sup, exc, hh in d.execute(
            "SELECT pyeong_name, supply_area, exclusive_area, household_count FROM complex_areas WHERE complex_no=?",
            (complex_no,)).fetchall()}
    types: dict = {}
    for area, t, n, mn, mx in rows:
        e = types.setdefault(area, {"area_name": area, "sale_count": 0, "sale_min": None, "sale_max": None,
                                    "jeonse_count": 0, "jeonse_min": None, "jeonse_max": None, "rent_count": 0,
                                    "supply_area": None, "exclusive_area": None, "type_households": None})
        am = areas_map.get(area)
        if am:
            e["supply_area"], e["exclusive_area"], e["type_households"] = am[0], am[1], am[2]
        if t == "A1":
            e["sale_count"], e["sale_min"], e["sale_max"] = n, mn, mx
        elif t == "B1":
            e["jeonse_count"], e["jeonse_min"], e["jeonse_max"] = n, mn, mx
        elif t == "B2":
            e["rent_count"] = n
    by_type = sorted(types.values(), key=lambda x: -(x["sale_max"] or x["jeonse_max"] or 0))
    subway = _complex_subway(d, complex_no)
    school = _complex_school(d, complex_no)
    return {
        "complex_no": complex_no, "complex_name": cx[0], "region": region, "households": cx[1],
        "use_approve_ymd": cx[2], "builder": cx[3], "dong_name": cx[4], "asset_type": cx[5],
        "building_count": cx[6], "parking_per_household": cx[7],
        "latitude": cx[8], "longitude": cx[9],
        "record_high": record_high,
        "recent_tx": recent_tx, "recent_high": max((x["price"] for x in recent_tx), default=None),
        "recent_all": recent_all,
        "listing_counts": cnt, "listing_units": units, "by_type": by_type,
        "subway": subway, "school": school,
    }


def _complex_subway(d, complex_no: str):
    """단지 최근접 지하철역(사전계산 complex_subway). 없으면 None.
    거리=직선거리, 도보분=직선×1.25 우회계수÷80m/분 (build_subway.py 배치 산출)."""
    try:
        r = d.execute("SELECT station_name, lines, distance_m, walk_min FROM complex_subway "
                      "WHERE complex_no=?", (complex_no,)).fetchone()
    except Exception:
        return None
    if not r:
        return None
    st = r[0] if str(r[0]).endswith("역") else f"{r[0]}역"   # 원본에 '역' 유무 혼재(도농역/송파)
    return {"station": st, "lines": r[1], "distance_m": r[2], "walk_min": r[3]}


@app.get("/complex/{complex_no}/subway-nearby")
def complex_subway_nearby(complex_no: str, radius_km: float = 2.0, limit: int = 8):
    """단지 주변 지하철역 — 반경 내 역을 거리순으로(주변역 팝업·지도용).
    도보분 = 직선거리 ×1.25(도로 우회계수) ÷ 80m/분."""
    radius_km = max(0.5, min(radius_km, 5.0))
    limit = max(1, min(limit, 15))
    with _open_db() as d:
        cx = d.execute("SELECT complex_name, latitude, longitude FROM complexes "
                       "WHERE complex_no=?", (complex_no,)).fetchone()
        if not cx or not cx[1] or not cx[2]:
            raise HTTPException(404, "단지 좌표가 없어요")
        lat0, lng0 = float(cx[1]), float(cx[2])
        import math
        dlat = radius_km / 111.0
        dlng = radius_km / (111.0 * max(math.cos(math.radians(lat0)), 0.01))
        rows = d.execute(
            "SELECT station_name, lat, lng, lines FROM subway_stations "
            "WHERE lat BETWEEN ? AND ? AND lng BETWEEN ? AND ?",
            (lat0 - dlat, lat0 + dlat, lng0 - dlng, lng0 + dlng)).fetchall()
        items = []
        for nm, la, ln, lines in rows:
            dm = _haversine_km(lat0, lng0, la, ln) * 1000
            if dm > radius_km * 1000:
                continue
            st = nm if str(nm).endswith("역") else f"{nm}역"
            items.append({"station": st, "lines": lines, "lat": la, "lng": ln,
                          "distance_m": round(dm), "walk_min": max(1, round(dm * 1.25 / 80))})
        items.sort(key=lambda x: x["distance_m"])
        # 같은 역명 병합(승강장 분리로 두 번 잡히는 수서역 3호선/분당선 등) — 가까운 쪽 좌표 + 노선 합침
        merged: dict = {}
        for x in items:
            if x["station"] in merged:
                m = merged[x["station"]]
                m["lines"] = "·".join(sorted(set(m["lines"].split("·")) | set(x["lines"].split("·"))))
            else:
                merged[x["station"]] = x
        items = list(merged.values())
    return {"complex_no": complex_no, "complex_name": cx[0],
            "lat": lat0, "lng": lng0, "radius_km": radius_km, "items": items[:limit]}


@app.get("/complex/{complex_no}/school-map")
def complex_school_map(complex_no: str, radius_km: float = 1.5):
    """배정 초등학교 팝업 — 배정교(공동학구 포함)·학구 경계 GeoJSON·인근 초등학교.
    경계는 학구도(통학구역) 15m 간소화본, WGS84 외곽 링 목록."""
    import json as _json
    with _open_db() as d:
        cx = d.execute("SELECT complex_name, latitude, longitude FROM complexes "
                       "WHERE complex_no=?", (complex_no,)).fetchone()
        if not cx or not cx[1] or not cx[2]:
            raise HTTPException(404, "단지 좌표가 없어요")
        lat0, lng0 = float(cx[1]), float(cx[2])
        row = d.execute("SELECT school_id, names_all, src, zone_ids FROM complex_school "
                        "WHERE complex_no=?", (complex_no,)).fetchone()
        assigned, zones = [], []
        if row:
            names = (row[1] or "").split("·")
            ids = [r[0] for r in d.execute(
                f"SELECT school_id FROM elementary_schools WHERE name IN "
                f"({','.join('?' * len(names))})", names)] if names and names[0] else []
            if row[0] and row[0] not in ids:
                ids.insert(0, row[0])
            for sid, nm, la, ln in d.execute(
                    f"SELECT school_id, name, lat, lng FROM elementary_schools "
                    f"WHERE school_id IN ({','.join('?' * len(ids))})", ids) if ids else []:
                dm = _haversine_km(lat0, lng0, la, ln) * 1000
                assigned.append({"school_id": sid, "name": nm, "lat": la, "lng": ln,
                                 "distance_m": round(dm),
                                 "walk_min": max(1, round(dm * 1.25 / 80))})
            assigned.sort(key=lambda x: x["distance_m"])
            for zid in (row[3] or "").split("·"):
                if not zid:
                    continue
                zr = d.execute("SELECT geojson FROM school_zones WHERE zone_id=?", (zid,)).fetchone()
                if zr:
                    zones.append(_json.loads(zr[0]))
        # 인근 초등학교(참고용, 배정 제외)
        import math
        dlat = radius_km / 111.0
        dlng = radius_km / (111.0 * max(math.cos(math.radians(lat0)), 0.01))
        aset = {a["school_id"] for a in assigned}
        nearby = []
        for sid, nm, la, ln in d.execute(
                "SELECT school_id, name, lat, lng FROM elementary_schools "
                "WHERE lat BETWEEN ? AND ? AND lng BETWEEN ? AND ?",
                (lat0 - dlat, lat0 + dlat, lng0 - dlng, lng0 + dlng)):
            if sid in aset:
                continue
            dm = _haversine_km(lat0, lng0, la, ln) * 1000
            if dm > radius_km * 1000:
                continue
            nearby.append({"school_id": sid, "name": nm, "lat": la, "lng": ln,
                           "distance_m": round(dm), "walk_min": max(1, round(dm * 1.25 / 80))})
        nearby.sort(key=lambda x: x["distance_m"])
    return {"complex_no": complex_no, "complex_name": cx[0], "lat": lat0, "lng": lng0,
            "src": (row[2] if row else None), "assigned": assigned,
            "zones": zones, "nearby": nearby[:6]}


def _pearson(xs: list, ys: list):
    n = len(xs)
    if n < 3:
        return None
    mx, my = sum(xs) / n, sum(ys) / n
    sxy = sum((a - mx) * (b - my) for a, b in zip(xs, ys))
    sxx = sum((a - mx) ** 2 for a in xs)
    syy = sum((b - my) ** 2 for b in ys)
    if sxx <= 0 or syy <= 0:
        return None
    return sxy / (sxx * syy) ** 0.5


def _px_buckets(excl: float) -> list:
    """전용면적 ±3.5㎡ 밴드가 걸치는 5㎡ 버킷들(중간 버킷 포함 — 밴드폭 6.8㎡는
    버킷 경계 2개를 걸칠 수 있어 lo·hi만 취하면 가운데가 빠진다)."""
    lo, hi = int((excl - 3.4) // 5) * 5, int((excl + 3.4) // 5) * 5
    return [b for b in range(max(0, lo), hi + 1, 5)]


def _px_series(d, complex_no: str, buckets: list, start_ym: str) -> dict:
    """complex_month_px에서 밴드 월별 가중평균 시계열 {ym: (avg, n)}."""
    ph = ",".join("?" * len(buckets))
    out = {}
    for ym, a, n in d.execute(
            f"SELECT ym, SUM(avg_amt*n)/SUM(n), SUM(n) FROM complex_month_px "
            f"WHERE complex_no=? AND b IN ({ph}) AND ym >= ? GROUP BY ym",
            (complex_no, *buckets, start_ym)).fetchall():
        out[ym] = (a, n)
    return out


def _px_recent(series: dict, last_ym: str):
    """최근 6개월 내 관측치 가중평균(현재가 근사)."""
    from datetime import date
    y, m = int(last_ym[:4]), int(last_ym[5:7])
    keep = set()
    for i in range(6):
        mm = m - i
        yy = y
        while mm <= 0:
            mm += 12
            yy -= 1
        keep.add(f"{yy:04d}-{mm:02d}")
    num = den = 0.0
    for ym, (a, n) in series.items():
        if ym in keep:
            num += a * n
            den += n
    return (num / den) if den else None


@app.get("/stats/similar-complexes")
def similar_complexes(complex_no: str, area_name: str = "", years: int = 3,
                      scope: str = "sido", limit: int = 30):
    """유사 단지 — 기준 단지·평형의 월별 실거래가 흐름과 상관도가 높은 단지 랭킹.
    유사도 = 선택 기간 월평균 거래가 시계열의 피어슨 상관(같은 달 관측치만, 최소 6개월).
    scope: sigungu(같은 시군구) | sido(같은 시도) | national(전국)."""
    from datetime import date
    years = years if years in (1, 3, 5) else 3
    limit = max(5, min(limit, 50))
    today = date.today()
    start_ym = f"{today.year - years:04d}-{today.month:02d}"
    last_ym = f"{today.year:04d}-{today.month:02d}"

    with _open_db() as d:
        base = d.execute("SELECT complex_name, cortar_no, total_household_count, use_approve_ymd "
                         "FROM complexes WHERE complex_no=?", (complex_no,)).fetchone()
        if not base:
            raise HTTPException(404, "단지를 찾을 수 없어요")
        # 기준 전용면적: area_name 지정 시 그 타입, 아니면 거래 최다 버킷
        excl = None
        if area_name:
            row = d.execute("SELECT exclusive_area FROM complex_areas WHERE complex_no=? "
                            "AND pyeong_name=? AND exclusive_area IS NOT NULL", (complex_no, area_name)).fetchone()
            excl = row[0] if row else None
        if excl is None:
            row = d.execute("SELECT b FROM complex_month_px WHERE complex_no=? AND b>=0 AND ym>=? "
                            "GROUP BY b ORDER BY SUM(n) DESC LIMIT 1", (complex_no, start_ym)).fetchone()
            if not row:
                return {"reference": None, "items": [], "note": "기준 단지의 기간 내 실거래가 부족해요"}
            excl = row[0] + 2.5
        buckets = _px_buckets(float(excl))

        ref_series = _px_series(d, complex_no, buckets, start_ym)
        min_common = max(6, int(years * 12 * 0.35))
        if len(ref_series) < min_common:
            return {"reference": None, "items": [],
                    "note": f"기준 단지의 해당 평형 실거래 관측월이 {len(ref_series)}개뿐이라 흐름 비교가 어려워요 (최소 {min_common}개월)"}

        ct = str(base[1] or "")
        prefix = {"sigungu": ct[:5], "sido": ct[:2], "national": ""}.get(scope, ct[:2])
        ph = ",".join("?" * len(buckets))
        rows = d.execute(
            f"""SELECT p.complex_no, p.ym, SUM(p.avg_amt*p.n)/SUM(p.n), SUM(p.n)
                FROM complex_month_px p JOIN complexes c ON c.complex_no = p.complex_no
                WHERE p.b IN ({ph}) AND p.ym >= ? AND p.complex_no <> ?
                  {"AND c.cortar_no LIKE ?" if prefix else ""}
                GROUP BY p.complex_no, p.ym""",
            (*buckets, start_ym, complex_no, *((prefix + "%",) if prefix else ()))).fetchall()

        cand: dict = {}
        for cno, ym, a, n in rows:
            cand.setdefault(cno, {})[ym] = (a, n)

        ref_recent = _px_recent(ref_series, last_ym)
        scored = []
        for cno, series in cand.items():
            common = sorted(set(series) & set(ref_series))
            if len(common) < min_common:
                continue
            corr = _pearson([ref_series[k][0] for k in common], [series[k][0] for k in common])
            if corr is None or corr < 0.3:
                continue
            scored.append((corr, len(common), cno, series))
        scored.sort(key=lambda x: -x[0])
        scored = scored[:limit]

        # 상위 후보 enrich
        items = []
        sido_names = {r[0]: r[1] for r in d.execute(
            "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'")}
        for corr, n_common, cno, series in scored:
            cx = d.execute("SELECT complex_name, cortar_no, dong_name, total_household_count, "
                           "use_approve_ymd FROM complexes WHERE complex_no=?", (cno,)).fetchone()
            if not cx:
                continue
            cct = str(cx[1] or "")
            sgg = d.execute("SELECT cortar_name FROM regions WHERE cortar_no=?",
                            (cct[:5] + "0" * 5,)).fetchone()
            region = " ".join(x for x in [
                _SIDO_SHORT.get(sido_names.get(cct[:2] + "0" * 8), sido_names.get(cct[:2] + "0" * 8)),
                sgg[0] if sgg else None, cx[2]] if x)
            recent = _px_recent(series, last_ym)
            # 해당 밴드 타입의 현재 매매 매물
            names = [r[0] for r in d.execute(
                "SELECT pyeong_name FROM complex_areas WHERE complex_no=? "
                "AND exclusive_area IS NOT NULL AND ABS(exclusive_area - ?) <= 3.5", (cno, excl))]
            ask = {"n": 0, "min": None}
            if names:
                ph2 = ",".join("?" * len(names))
                row = d.execute(
                    f"SELECT COUNT(*), MIN(CASE WHEN deal_or_warrant_price>0 THEN deal_or_warrant_price END) "
                    f"FROM listings_current WHERE complex_no=? AND trade_type='A1' AND area_name IN ({ph2})",
                    (cno, *names)).fetchone()
                ask = {"n": row[0], "min": row[1]}
            rec = d.execute("SELECT record_price FROM tx_record_rollup WHERE complex_no=? "
                            "AND area_key BETWEEN ? AND ? ORDER BY record_price DESC LIMIT 1",
                            (cno, excl - 3.5, excl + 3.5)).fetchone()
            items.append({
                "complex_no": cno, "complex_name": cx[0], "region": region,
                "households": cx[3], "approve_year": (str(cx[4])[:4] if cx[4] else None),
                "similarity": round(corr * 100, 1), "months": n_common,
                "recent_avg": round(recent) if recent else None,
                "diff_pct": (round((recent - ref_recent) / ref_recent * 100, 1)
                             if recent and ref_recent else None),
                "ask": ask,
                "record_high": rec[0] if rec else None,
                "vs_peak_pct": (round((recent / rec[0] - 1) * 100, 1) if recent and rec and rec[0] else None),
                "series": [[ym, round(series[ym][0])] for ym in sorted(series)],
            })

        return {
            "reference": {
                "complex_no": complex_no, "complex_name": base[0],
                "excl": round(float(excl), 1), "buckets": buckets,
                "recent_avg": round(ref_recent) if ref_recent else None,
                "series": [[ym, round(ref_series[ym][0])] for ym in sorted(ref_series)],
            },
            "years": years, "scope": scope, "min_common_months": min_common,
            "items": items,
        }


@app.get("/stats/px-series")
def px_series(nos: str, years: int = 3, area_name: str = "", mode: str = "sqm"):
    """단지 월별 실거래 시계열 — 비교 차트용.
    mode=sqm: 전평형 ㎡당가(원/㎡, 평형 구성이 달라도 비교 가능) / band: 첫 단지의
    area_name 전용면적 ±3.5㎡ 밴드 평균 거래가."""
    from datetime import date
    ids = [x.strip() for x in (nos or "").split(",") if x.strip()][:6]
    if not ids:
        raise HTTPException(400, "nos required")
    years = years if years in (1, 3, 5) else 3
    today = date.today()
    start_ym = f"{today.year - years:04d}-{today.month:02d}"
    out = []
    with _open_db() as d:
        buckets = [-1]
        if mode == "band" and area_name:
            row = d.execute("SELECT exclusive_area FROM complex_areas WHERE complex_no=? "
                            "AND pyeong_name=? AND exclusive_area IS NOT NULL", (ids[0], area_name)).fetchone()
            if row:
                buckets = _px_buckets(float(row[0]))
        for cno in ids:
            nm = d.execute("SELECT complex_name FROM complexes WHERE complex_no=?", (cno,)).fetchone()
            series = _px_series(d, cno, buckets, start_ym)
            out.append({"complex_no": cno, "complex_name": nm[0] if nm else cno,
                        "series": [[ym, round(series[ym][0])] for ym in sorted(series)]})
    return {"mode": ("band" if buckets != [-1] else "sqm"), "years": years, "items": out}


def _complex_school(d, complex_no: str):
    """단지 배정 초등학교(사전계산 complex_school, 학구도 폴리곤 기준).
    src='zone'=학구도 배정 / 'near'=학구도 미포함 지역의 인근 학교(배정 아님)."""
    try:
        r = d.execute("SELECT school_name, names_all, n_schools, distance_m, walk_min, src "
                      "FROM complex_school WHERE complex_no=?", (complex_no,)).fetchone()
    except Exception:
        return None
    if not r:
        return None
    return {"name": r[0], "names_all": r[1], "n": r[2],
            "distance_m": r[3], "walk_min": r[4], "src": r[5]}


def _haversine_km(lat1, lon1, lat2, lon2) -> float:
    import math
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp, dl = math.radians(lat2 - lat1), math.radians(lon2 - lon1)
    a = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * 6371.0 * math.asin(math.sqrt(a))


@app.get("/complex/{complex_no}/nearby-transactions")
def complex_nearby_transactions(complex_no: str, area: float = 0.0, months: int = 12,
                                radius_km: float = 1.5, limit: int = 12,
                                include_listings: int = 0):
    """인근 단지 실거래가 — 대상단지 좌표 기준 반경 내 같은유형(아파트/오피) 단지들의 최근
    매매 실거래. area>0이면 전용면적±3.5㎡(같은 평형)만, area=0이면 전체평형. 거리순.
    include_listings=1이면 단지별 현재 매물(매매 건수·최저호가)도 함께 반환(관심단지 팝업용)."""
    import math
    months = max(1, min(months, 60))
    radius_km = max(0.2, min(radius_km, 5.0))
    limit = max(1, min(limit, 30))
    with _open_db() as c:
        tgt = c.execute(
            "SELECT complex_name, latitude, longitude, real_estate_type "
            "FROM complexes WHERE complex_no=?", (complex_no,)).fetchone()
        if not tgt or not tgt["latitude"] or not tgt["longitude"]:
            return {"complex_no": complex_no, "target_name": None, "nearby": [], "areas": []}
        lat0, lon0 = float(tgt["latitude"]), float(tgt["longitude"])
        asset_apt = (tgt["real_estate_type"] or "") != "OPST"
        tbl = "transactions" if asset_apt else "offi_transactions"
        areas = [{"pyeong_name": r["pyeong_name"], "exclusive_area": r["exclusive_area"],
                  "household_count": r["household_count"]}
                 for r in c.execute(
                     "SELECT pyeong_name, exclusive_area, household_count FROM complex_areas "
                     "WHERE complex_no=? AND exclusive_area IS NOT NULL ORDER BY exclusive_area",
                     (complex_no,))]
        dlat = radius_km / 111.0
        dlon = radius_km / (111.0 * max(math.cos(math.radians(lat0)), 0.01))
        cands = c.execute(
            "SELECT complex_no, complex_name, latitude, longitude, real_estate_type, dong_name, "
            "total_household_count, use_approve_ymd "
            "FROM complexes WHERE complex_no<>? AND latitude BETWEEN ? AND ? "
            "AND longitude BETWEEN ? AND ?",
            (complex_no, lat0 - dlat, lat0 + dlat, lon0 - dlon, lon0 + dlon)).fetchall()
        near = []
        for r in cands:
            if not r["latitude"] or (((r["real_estate_type"] or "") != "OPST") != asset_apt):
                continue
            d = _haversine_km(lat0, lon0, float(r["latitude"]), float(r["longitude"]))
            if d <= radius_km:
                near.append((d, r))
        near.sort(key=lambda x: x[0])
        near = near[:limit]
        result = []
        if near:
            ids = [r["complex_no"] for _, r in near]
            ph = ",".join("?" * len(ids))
            params: list = [*ids, f"-{months} months"]
            area_cl = ""
            if area and area > 0:
                area_cl = " AND excl_use_ar BETWEEN ? AND ?"
                params += [area - 3.5, area + 3.5]
            by: dict = {}
            for r in c.execute(
                f"SELECT matched_complex_no AS cno, deal_ymd, deal_amount, excl_use_ar, floor "
                f"FROM {tbl} WHERE matched_complex_no IN ({ph}) AND deal_ymd >= date('now','+9 hours', ?)"
                f"{area_cl} AND is_cancelled=0 ORDER BY deal_ymd DESC", params):
                by.setdefault(r["cno"], []).append(
                    {"deal_ymd": r["deal_ymd"], "deal_amount": r["deal_amount"],
                     "excl_use_ar": r["excl_use_ar"], "floor": r["floor"]})
            # 역대 최고가(전체 기간, 같은 area band) — 신고가 판정용
            am_params: list = [*ids]
            am_area = ""
            if area and area > 0:
                am_area = " AND excl_use_ar BETWEEN ? AND ?"
                am_params += [area - 3.5, area + 3.5]
            allmax: dict = {}
            for r in c.execute(
                f"SELECT matched_complex_no AS cno, MAX(deal_amount) AS mx FROM {tbl} "
                f"WHERE matched_complex_no IN ({ph}){am_area} AND is_cancelled=0 "
                f"GROUP BY matched_complex_no", am_params):
                allmax[r["cno"]] = r["mx"]
            # 현재 매물(매매) — 건수·최저호가 (관심단지 주변단지 팝업용)
            lst: dict = {}
            sub_by: dict = {}
            if include_listings:
                for r in c.execute(
                    f"SELECT complex_no AS cno, COUNT(*) AS n, "
                    f"MIN(CASE WHEN deal_or_warrant_price > 0 THEN deal_or_warrant_price END) AS mn "
                    f"FROM listings_current WHERE complex_no IN ({ph}) AND trade_type='A1' "
                    f"GROUP BY complex_no", ids):
                    lst[r["cno"]] = {"n": r["n"], "ask_min": r["mn"]}
                try:
                    for r in c.execute(
                        f"SELECT complex_no, station_name, walk_min FROM complex_subway "
                        f"WHERE complex_no IN ({ph})", ids):
                        st = r[1] if str(r[1]).endswith("역") else f"{r[1]}역"
                        sub_by[r[0]] = {"station": st, "walk_min": r[2]}
                except Exception:
                    pass
            for d, r in near:
                deals = by.get(r["complex_no"], [])
                amts = [x["deal_amount"] for x in deals if x["deal_amount"]]
                result.append({
                    "complex_no": r["complex_no"], "complex_name": r["complex_name"],
                    "dong_name": r["dong_name"], "distance_m": round(d * 1000),
                    "lat": float(r["latitude"]), "lng": float(r["longitude"]),
                    "households": r["total_household_count"],
                    "use_approve_ymd": r["use_approve_ymd"],
                    "deal_count": len(deals),
                    "avg_amount": round(sum(amts) / len(amts)) if amts else None,
                    "max_amount": max(amts) if amts else None,   # 최근 12개월 최고
                    "all_time_max": allmax.get(r["complex_no"]),  # 역대 최고(거래내역 표시용)
                    "recent": deals[:5],
                    **({"listings": lst.get(r["complex_no"]) or {"n": 0, "ask_min": None},
                        "subway": sub_by.get(r["complex_no"])}
                       if include_listings else {}),
                })
        # 기준단지 자신도 같은 잣대(기간·평형)로 집계 — 지도에서 주변과 나란히 비교
        me_params: list = [complex_no, f"-{months} months"]
        me_area = ""
        if area and area > 0:
            me_area = " AND excl_use_ar BETWEEN ? AND ?"
            me_params += [area - 3.5, area + 3.5]
        me_amts = [r["deal_amount"] for r in c.execute(
            f"SELECT deal_amount FROM {tbl} WHERE matched_complex_no=? "
            f"AND deal_ymd >= date('now','+9 hours', ?){me_area} AND is_cancelled=0", me_params)
            if r["deal_amount"]]
        me = {"deal_count": len(me_amts),
              "avg_amount": round(sum(me_amts) / len(me_amts)) if me_amts else None}
        if include_listings:
            r = c.execute(
                "SELECT COUNT(*) AS n, "
                "MIN(CASE WHEN deal_or_warrant_price > 0 THEN deal_or_warrant_price END) AS mn "
                "FROM listings_current WHERE complex_no=? AND trade_type='A1'",
                (complex_no,)).fetchone()
            me["listings"] = {"n": r["n"], "ask_min": r["mn"]}
    return {"complex_no": complex_no, "target_name": tgt["complex_name"],
            "lat": lat0, "lng": lon0,
            "asset": "apt" if asset_apt else "offi", "area": area, "months": months,
            "radius_km": radius_km, "areas": areas, "self": me, "nearby": result}


@app.get("/complex/{complex_no}/areas")
def complex_areas_endpoint(complex_no: str):
    """단지 면적타입별 구성 (Naver 단지 detail 기반): 면적타입/공급/전용/세대수."""
    with _open_db() as c:
        rows = c.execute(
            """
            SELECT pyeong_name, supply_area, exclusive_area, household_count
            FROM complex_areas WHERE complex_no = ?
            ORDER BY supply_area
            """,
            (complex_no,),
        ).fetchall()
    return {
        "complex_no": complex_no,
        "items": [
            {"pyeong_name": r[0], "supply_area": r[1],
             "exclusive_area": r[2], "household_count": r[3]}
            for r in rows
        ],
    }


@app.get("/complex/{complex_no}/listing-daily")
def complex_listing_daily(complex_no: str, days: int = 31):
    """단지매물분석: 일자별 매물수·실매물수·호가(면적타입×거래유형별 원자료).
    complex_daily_agg 그대로 내려주고 집계(전체/면적선택)는 프론트에서.
    """
    if days < 1 or days > 92:
        raise HTTPException(400, "days out of range")
    _ck = f"cxlistdaily:{complex_no}:{days}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    with _open_db() as c:
        rows = c.execute(
            """
            SELECT snapshot_date, area_name, trade_type,
                   listing_count, unit_count, price_avg, price_min, price_max, rent_avg
            FROM complex_daily_agg
            WHERE complex_no = ? AND snapshot_date >= date('now','+9 hours', ?)
            ORDER BY snapshot_date ASC
            """,
            (complex_no, f"-{days} days"),
        ).fetchall()
    out = {
        "complex_no": complex_no,
        "days": days,
        "rows": [
            {"d": r[0], "area": r[1], "t": r[2], "n": r[3],
             "u": (int(round(r[4])) if r[4] is not None else None),
             "avg": r[5], "min": r[6], "max": r[7], "ravg": r[8]}
            for r in rows
        ],
    }
    _cache_put(_ck, out)
    return out


@app.get("/complex/{complex_no}/realtors")
def complex_realtors(complex_no: str, limit: int = 10):
    """단지별 매물 보유 상위 N개 중개사 + 거래종류 분포 / 사무소 정보 / 전화번호."""
    if limit < 1 or limit > 50:
        raise HTTPException(400, "limit out of range")
    with _open_db() as c:
        rows = c.execute(
            """
            SELECT realtor_id,
                   MAX(realtor_name) AS realtor_name,
                   COUNT(*) AS n,
                   SUM(CASE WHEN trade_type='A1' THEN 1 ELSE 0 END) AS n_sale,
                   SUM(CASE WHEN trade_type='B1' THEN 1 ELSE 0 END) AS n_jeonse,
                   SUM(CASE WHEN trade_type='B2' THEN 1 ELSE 0 END) AS n_wolse,
                   AVG(CASE WHEN trade_type='A1' AND deal_or_warrant_price>0
                            THEN deal_or_warrant_price END) AS avg_sale_price
            FROM listings_current
            WHERE complex_no = ? AND realtor_id IS NOT NULL
            GROUP BY realtor_id
            ORDER BY n DESC
            LIMIT ?
            """,
            (complex_no, limit),
        ).fetchall()

        # 사무소 정보 (national 엔드포인트와 같은 enrichment).
        info: dict[str, dict] = {}
        ids = [r[0] for r in rows]
        if ids:
            ph = ",".join("?" * len(ids))
            sido_names = {
                r[0][:2]: r[1]
                for r in c.execute(
                    "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'"
                )
            }
            for er in c.execute(
                f"""
                SELECT nr.realtor_id, nr.realtor_name, nr.cortar_no,
                       vb.registered_ymd,
                       (SELECT COUNT(*) FROM vworld_employees ve
                        WHERE ve.sys_regno = rm.sys_regno) AS emp,
                       nr.representative_tel_no, nr.cell_phone_no
                FROM naver_realtors nr
                LEFT JOIN realtor_match rm ON rm.realtor_id = nr.realtor_id
                LEFT JOIN vworld_brokers vb ON vb.sys_regno = rm.sys_regno
                WHERE nr.realtor_id IN ({ph})
                """,
                ids,
            ):
                cortar = er[2] or ""
                reg = er[3] or ""
                info[er[0]] = {
                    "office_name": er[1],
                    "sido": sido_names.get(cortar[:2]) if cortar else None,
                    "established_year": reg[:4] if len(reg) >= 4 else None,
                    "staff_count": er[4] or None,
                    "tel": er[5] or er[6] or None,
                }

        # 각 중개사의 전국 총 매물 수
        total_by_id: dict[str, int] = {}
        if ids:
            ph = ",".join("?" * len(ids))
            for tid, n in c.execute(
                f"""
                SELECT realtor_id, COUNT(*)
                FROM listings_current
                WHERE realtor_id IN ({ph})
                GROUP BY realtor_id
                """,
                ids,
            ):
                total_by_id[tid] = n

    items = []
    for r in rows:
        e = info.get(r[0], {})
        items.append({
            "realtor_id": r[0],
            "realtor_name": e.get("office_name") or r[1],
            "count": r[2],
            "n_sale": r[3],
            "n_jeonse": r[4],
            "n_wolse": r[5],
            "avg_sale_price": r[6],
            "sido": e.get("sido"),
            "established_year": e.get("established_year"),
            "staff_count": e.get("staff_count"),
            "tel": e.get("tel"),
            "total_listings": total_by_id.get(r[0]),
        })
    return {"complex_no": complex_no, "items": items}


@app.get("/complex/{complex_no}/quick-deals")
def complex_quick_deals(
    complex_no: str,
    days: int = 90,
    trade_type: str = "A1",       # A1=매매 | B1=전세
    min_discount: float = 0.05,   # 최근 실거래 평균 대비 N% 이상 저렴
    max_discount: float = 0.5,    # 극단치 컷
    min_samples: int = 3,         # 평형별 실거래 N건 이상이어야 기준 인정
    limit: int = 50,
):
    """단지 내 급매 매물 + 보유 중개사 연락처.
    평형(area_name)별 최근 N일 실거래 평균을 기준으로, 호가가 그 평균보다
    min_discount 이상 싼 개별 매물을 골라 중개사 전화번호와 함께 반환."""
    if trade_type not in ("A1", "B1"):
        raise HTTPException(400, "trade_type must be A1|B1")
    if trade_type == "A1":
        tx_tbl, amount_col = "transactions", "tx.deal_amount"
        extra = "AND COALESCE(tx.dealing_gbn,'') <> '직거래' AND tx.is_cancelled = 0"
    else:
        tx_tbl, amount_col = "rentals", "tx.deposit"
        extra = "AND COALESCE(tx.monthly_rent,0) = 0"
    cutoff = f"-{days} days"
    area_tol = 5.0

    with _open_db() as c:
        # 평형(area_name)별 실거래 평균 — 단지 1개라 가볍다
        real = c.execute(
            f"""
            SELECT pyeong, AVG(amount) AS avg_real, COUNT(*) AS n_real FROM (
              SELECT ca.pyeong_name AS pyeong, {amount_col} AS amount,
                     ROW_NUMBER() OVER (PARTITION BY tx.rowid
                       ORDER BY ABS(ca.exclusive_area - tx.excl_use_ar)) AS rn
              FROM {tx_tbl} tx
              JOIN complex_areas ca ON ca.complex_no = tx.matched_complex_no
                AND ca.exclusive_area IS NOT NULL
                AND ABS(ca.exclusive_area - tx.excl_use_ar) <= {area_tol}
              WHERE tx.matched_complex_no = ?
                AND tx.deal_ymd >= date('now','+9 hours', ?)
                AND tx.excl_use_ar IS NOT NULL {extra}
                AND tx.matched_score >= 0.85
            ) WHERE rn = 1 AND pyeong IS NOT NULL
            GROUP BY pyeong HAVING COUNT(*) >= ?
            """,
            (complex_no, cutoff, min_samples),
        ).fetchall()
        avg_by_area = {r[0]: (r[1], r[2]) for r in real}
        if not avg_by_area:
            return {"complex_no": complex_no, "count": 0, "items": []}

        listings = c.execute(
            """
            SELECT article_no, area_name, floor_info, direction,
                   deal_or_warrant_price, deal_or_warrant_price_text,
                   realtor_id, realtor_name, article_confirm_ymd, cp_pc_article_url,
                   json_extract(raw,'$.aptDong') AS dong
            FROM listings_current
            WHERE complex_no = ? AND trade_type = ? AND deal_or_warrant_price > 0
              AND area_name IS NOT NULL
            """,
            (complex_no, trade_type),
        ).fetchall()

        ids = list({r[6] for r in listings if r[6]})
        contact: dict[str, dict] = {}
        if ids:
            ph = ",".join("?" * len(ids))
            for er in c.execute(
                f"""SELECT realtor_id, realtor_name, representative_tel_no,
                          cell_phone_no, address
                   FROM naver_realtors WHERE realtor_id IN ({ph})""",
                ids,
            ):
                contact[er[0]] = {"office": er[1], "tel": er[2] or er[3], "addr": er[4]}

        # realtor_id 가 NULL 인 매물(전국 매매의 ~5.6%) → 이름+지역으로 안전 역매칭.
        # 같은 시군구 단일 매칭이거나 전국에서 이름이 고유할 때만 연결(동명 다수는 미연결).
        null_names = list({r[7] for r in listings if not r[6] and r[7]})
        name_fallback: dict[str, dict] = {}
        if null_names:
            crow = c.execute("SELECT cortar_no FROM complexes WHERE complex_no=?",
                             (complex_no,)).fetchone()
            sgg = ((crow[0] or "")[:5]) if crow else ""
            ph2 = ",".join("?" * len(null_names))
            cand: dict[str, list] = {}
            for er in c.execute(
                f"""SELECT realtor_name, realtor_id, representative_tel_no, cell_phone_no, cortar_no
                    FROM naver_realtors WHERE realtor_name IN ({ph2})""", null_names):
                cand.setdefault(er[0], []).append((er[1], er[2] or er[3], er[4] or ""))
            for nm, lst in cand.items():
                same = [x for x in lst if x[2][:5] == sgg]
                pick = same[0] if len(same) == 1 else (lst[0] if len(lst) == 1 else None)
                if pick:
                    name_fallback[nm] = {"realtor_id": pick[0], "tel": pick[1]}

    items = []
    for r in listings:
        ar = avg_by_area.get(r[1])
        if not ar:
            continue
        avg_real, n_real = ar
        disc = (r[4] - avg_real) / avg_real
        if disc > -abs(min_discount) or disc < -abs(max_discount):
            continue
        ct = contact.get(r[6], {})
        rid, tel = r[6], ct.get("tel")
        office, addr = ct.get("office") or r[7], ct.get("addr")
        if not rid and r[7] in name_fallback:        # realtor_id 없으면 이름 역매칭 결과 사용
            rid, tel = name_fallback[r[7]]["realtor_id"], name_fallback[r[7]]["tel"]
        items.append({
            "article_no": r[0], "area_name": r[1], "floor_info": r[2],
            "direction": r[3], "price": r[4], "price_text": r[5],
            "discount": disc, "avg_real": avg_real, "n_real": n_real,
            "realtor_id": rid, "realtor_name": office,
            "tel": tel, "addr": addr, "dong": r[10],
            "confirm_ymd": r[8], "article_url": r[9],
            # 네이버 정식 매물 딥링크 (article_no 로 구성). CP(매경 등) 리다이렉트 대신 네이버로.
            "naver_url": f"https://new.land.naver.com/complexes/{complex_no}?articleNo={r[0]}",
        })
    items.sort(key=lambda x: x["discount"])
    # 동일매물 묶기 — 같은 동·층표기·평형·방향·가격이면 같은 매물(여러 중개사 중복게시) → 1건
    # (할인 큰 순 정렬 후 dedup이라 대표는 가장 싼 게시물). realtor_count=게시 중개사 수.
    seen: dict = {}
    deduped: list = []
    for it in items:
        key = (it.get("dong") or "", it["floor_info"], it["area_name"],
               it["direction"], it["price"])
        g = seen.get(key)
        if g is None:
            it["dup_count"] = 1
            it["_rids"] = {it.get("realtor_id")} if it.get("realtor_id") else set()
            seen[key] = it
            deduped.append(it)
        else:
            g["dup_count"] += 1
            if it.get("realtor_id"):
                g["_rids"].add(it["realtor_id"])
    for g in deduped:
        g["realtor_count"] = len(g.pop("_rids")) or 1
    return {"complex_no": complex_no, "count": len(deduped), "items": deduped[:limit]}


# 공급면적 평형 bucket (㎡ 단위로 환산)
# 공급면적 = 전용면적 × 1.33 (일반 아파트 전용율 ~0.77)
# 10평 = 33㎡, 20평 = 66㎡, 30평 = 99㎡, 40평 = 132㎡, 50평 = 165㎡
_AREA_BUCKETS_SUPPLY = {
    "under10": (None, 33),
    "10s": (33, 66),
    "20s": (66, 99),
    "30s": (99, 132),
    "40s": (132, 165),
    "over50": (165, None),
}


def _area_cond(col_excl: str, area_class: str | None, col_supply: str | None = "supply_area") -> tuple[str, list]:
    """col_excl = 전용면적, col_supply = listings 매핑으로 채워진 공급면적.
    정확도 위해 supply_area NULL인 행은 평형 필터 시 제외 (특히 오피스텔 전용율 가변).
    """
    if not area_class or area_class == "all":
        return "", []
    rng = _AREA_BUCKETS_SUPPLY.get(area_class)
    if not rng:
        return "", []
    lo, hi = rng
    if col_supply:
        # supply_area 있는 행만 필터 적용
        conds = [f"{col_supply} IS NOT NULL"]
        expr = col_supply
    else:
        conds = []
        expr = f"{col_excl} * 1.33"
    params: list = []
    if lo is not None:
        conds.append(f"{expr} >= ?")
        params.append(lo)
    if hi is not None:
        conds.append(f"{expr} < ?")
        params.append(hi)
    if not conds:
        return "", []
    return " AND " + " AND ".join(conds), params


# tx_area_rollup(area_key=ROUND(전용면적 m2)) 평형 버킷. 공급면적 버킷을 전용율 ~0.76 로
# 환산해 전용 m2 경계로. (랭킹 엔드포인트가 area_key 기준이라 전용 기준이 자연스럽다.)
_AREA_BUCKETS_KEY = {
    "under10": (None, 25), "10s": (25, 50), "20s": (50, 75),
    "30s": (75, 100), "40s": (100, 125), "over50": (125, None),
}


def _area_cond_key(area_class: str | None) -> tuple[str, list]:
    """tx_area_rollup.area_key(전용 m2) 평형 필터. (' AND area_key ...', params)."""
    if not area_class or area_class == "all":
        return "", []
    rng = _AREA_BUCKETS_KEY.get(area_class)
    if not rng:
        return "", []
    lo, hi = rng
    conds, params = [], []
    if lo is not None:
        conds.append("area_key >= ?"); params.append(lo)
    if hi is not None:
        conds.append("area_key < ?"); params.append(hi)
    return (" AND " + " AND ".join(conds), params) if conds else ("", [])


_area_rollup_ok: bool | None = None


def _area_rollup_ready() -> bool:
    """tx_area_rollup 존재+비어있지 않음(메모이즈)."""
    global _area_rollup_ok
    if _area_rollup_ok:
        return True
    try:
        with _open_db() as c:
            r = c.execute("SELECT EXISTS(SELECT 1 FROM tx_area_rollup LIMIT 1)").fetchone()
        _area_rollup_ok = bool(r and r[0])
    except Exception:  # noqa: BLE001
        _area_rollup_ok = False
    return _area_rollup_ok


_ASSET_TYPES = {
    "apt": ("APT", "JGC", "ABYG"),       # 아파트(재건축·분양권 포함)
    "offi": ("OPST", "OBYG"),            # 오피스텔(분양권 포함)
}


def _asset_type_clause(asset: str | None, alias: str = "cx") -> str:
    """asset(apt/offi) → complexes.real_estate_type 필터 SQL(' AND cx.real_estate_type IN (...)').
    타입값은 하드코딩 상수라 인젝션 안전. all/None 이면 빈 문자열."""
    t = _ASSET_TYPES.get(asset or "")
    if not t:
        return ""
    return f" AND {alias}.real_estate_type IN (" + ",".join(f"'{x}'" for x in t) + ")"


def _roll_region_clause(sido: str | None, sigungu: str | None,
                        dong: str | None = None) -> tuple[str, list]:
    """area 롤업용 지역 필터 — complex_no IN (해당 지역 단지)."""
    if dong:
        return (" AND complex_no IN (SELECT complex_no FROM complexes "
                "WHERE cortar_no = ?)", [dong])
    if sigungu:
        return (" AND complex_no IN (SELECT complex_no FROM complexes "
                "WHERE substr(cortar_no,1,5)=substr(?,1,5))", [sigungu])
    if sido:
        return (" AND complex_no IN (SELECT complex_no FROM complexes "
                "WHERE substr(cortar_no,1,2)=substr(?,1,2))", [sido])
    return "", []


def _mcn_region_clause(sido: str | None, sigungu: str | None,
                       dong: str | None = None) -> tuple[str, list]:
    """transactions/rentals 의 matched_complex_no 컬럼용 지역필터."""
    cond, params = _roll_region_clause(sido, sigungu, dong)
    return (cond.replace("complex_no IN", "matched_complex_no IN", 1), params)


def _cx_region_clause(sido: str | None, sigungu: str | None,
                      dong: str | None = None) -> tuple[str, list]:
    """complexes 별칭 cx 가 JOIN 된 쿼리용 지역필터 (cx.cortar_no 직접 비교)."""
    if dong:
        return (" AND cx.cortar_no = ?", [dong])
    if sigungu:
        return (" AND substr(cx.cortar_no,1,5)=substr(?,1,5)", [sigungu])
    if sido:
        return (" AND substr(cx.cortar_no,1,2)=substr(?,1,2)", [sido])
    return "", []


# 단지(cx) → 시도/시군구/동 3단계 지역명. SQL에 complexes 별칭 cx가 이미 JOIN돼 있어야 함.
_REGION_JOINS = (
    " LEFT JOIN regions rs ON rs.cortar_no = substr(cx.cortar_no,1,2)||'00000000'"
    " LEFT JOIN regions rg ON rg.cortar_no = substr(cx.cortar_no,1,5)||'00000'"
    " LEFT JOIN regions rd ON rd.cortar_no = cx.cortar_no"
)
_REGION_NAME_COL = (
    "TRIM(COALESCE(rs.cortar_name,'')||' '||COALESCE(rg.cortar_name,'')"
    "||' '||COALESCE(rd.cortar_name,'')) AS region_name"
)


@app.get("/stats/tx-top-price")
def tx_top_price(days: int = 30, trade: str = "A1", asset: str = "all",
                 dealing: str = "all", area_class: str = "all", sido: str | None = None,
                 sigungu: str | None = None, dong: str | None = None, limit: int = 100,
                 ar_min: float = 0, ar_max: float = 0):
    """실거래 최고가 top N.
    trade: A1(매매)/B1(전세)/B2(월세)  asset: apt/offi/all  days: 1=하루, 365=1년, 0=전체
    ar_min/ar_max: 전용면적(㎡) 정확 밴드(둘 중 하나라도 >0이면 area_class 대신 이 밴드 사용).
                   예: 59㎡=58~61, 84㎡=83~86."""
    if limit < 1 or limit > 500:
        raise HTTPException(400, "limit out of range")
    if days < 0 or days > 3650:
        raise HTTPException(400, "days out of range")
    # 런타임 캐시(24h·데이터버전 무효) — 홈 위젯(limit=7)은 프리빌드 키와 어긋나 라이브였음
    _ck = (f"txtopP:{days}:{trade}:{asset}:{dealing}:{area_class}:"
           f"{sido or ''}:{sigungu or ''}:{dong or ''}:{limit}:{ar_min}:{ar_max}")
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    cutoff = f"-{days} days"
    # dealing 필터 (매매만): all / broker(중개거래) / direct(직거래)
    dg_filter = ""
    if dealing == "broker":
        dg_filter = " AND dealing_gbn='중개거래'"
    elif dealing == "direct":
        dg_filter = " AND dealing_gbn='직거래'"
    # 전용면적 정확 밴드(ar_min/ar_max) 우선, 없으면 area_class 공급면적 평형 필터
    if ar_min > 0 or ar_max > 0:
        _acs, _acp = [], []
        if ar_min > 0: _acs.append("excl_use_ar >= ?"); _acp.append(ar_min)
        if ar_max > 0: _acs.append("excl_use_ar < ?"); _acp.append(ar_max)
        ac_filter, ac_params = " AND " + " AND ".join(_acs), _acp
    else:
        ac_filter, ac_params = _area_cond("excl_use_ar", area_class, col_supply=None)  # silv union 호환

    with _open_db() as c:
        existing = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        unions = []
        params: list = []
        # 거래 유형별 source 결정
        if trade == "A1":
            # 매매: deal_amount + dealing_gbn
            if asset in ("apt", "all") and "transactions" in existing:
                unions.append(
                    "SELECT deal_ymd, deal_amount AS price, NULL AS monthly_rent, "
                    "excl_use_ar, floor, build_year, matched_complex_no, dealing_gbn, 'apt' AS asset "
                    "FROM transactions WHERE matched_complex_no IS NOT NULL AND is_cancelled=0" + dg_filter + ac_filter
                    + (f" AND deal_ymd >= date('now','+9 hours', ?)" if days > 0 else "")
                )
                params.extend(ac_params)
                if days > 0: params.append(cutoff)
            # 분양권(silv): 매매 최고가와 통합(거래총액=실거래총액). 거래방식 필터 시 제외.
            if asset in ("apt", "all") and dealing == "all" and "silv_transactions" in existing:
                unions.append(
                    "SELECT deal_ymd, deal_amount AS price, NULL AS monthly_rent, "
                    "excl_use_ar, floor, NULL AS build_year, matched_complex_no, dealing_gbn, 'silv' AS asset "
                    "FROM silv_transactions WHERE matched_complex_no IS NOT NULL AND is_cancelled=0" + ac_filter
                    + (f" AND deal_ymd >= date('now','+9 hours', ?)" if days > 0 else "")
                )
                params.extend(ac_params)
                if days > 0: params.append(cutoff)
            if asset in ("offi", "all") and "offi_transactions" in existing:
                unions.append(
                    "SELECT deal_ymd, deal_amount AS price, NULL AS monthly_rent, "
                    "excl_use_ar, floor, build_year, matched_complex_no, dealing_gbn, 'offi' AS asset "
                    "FROM offi_transactions WHERE matched_complex_no IS NOT NULL AND is_cancelled=0" + dg_filter + ac_filter
                    + (f" AND deal_ymd >= date('now','+9 hours', ?)" if days > 0 else "")
                )
                params.extend(ac_params)
                if days > 0: params.append(cutoff)
        elif trade == "B1":
            # 전세: deposit (monthly_rent=0) — 전월세는 dealing_gbn 없음
            if asset in ("apt", "all") and "rentals" in existing:
                unions.append(
                    "SELECT deal_ymd, deposit AS price, monthly_rent, "
                    "excl_use_ar, floor, build_year, matched_complex_no, NULL AS dealing_gbn, 'apt' AS asset "
                    "FROM rentals WHERE matched_complex_no IS NOT NULL AND monthly_rent=0" + ac_filter
                    + (f" AND deal_ymd >= date('now','+9 hours', ?)" if days > 0 else "")
                )
                params.extend(ac_params)
                if days > 0: params.append(cutoff)
            if asset in ("offi", "all") and "offi_rentals" in existing:
                unions.append(
                    "SELECT deal_ymd, deposit AS price, monthly_rent, "
                    "excl_use_ar, floor, build_year, matched_complex_no, NULL AS dealing_gbn, 'offi' AS asset "
                    "FROM offi_rentals WHERE matched_complex_no IS NOT NULL AND monthly_rent=0" + ac_filter
                    + (f" AND deal_ymd >= date('now','+9 hours', ?)" if days > 0 else "")
                )
                params.extend(ac_params)
                if days > 0: params.append(cutoff)
        elif trade == "B2":
            # 월세: monthly_rent 우선
            if asset in ("apt", "all") and "rentals" in existing:
                unions.append(
                    "SELECT deal_ymd, deposit AS price, monthly_rent, "
                    "excl_use_ar, floor, build_year, matched_complex_no, NULL AS dealing_gbn, 'apt' AS asset "
                    "FROM rentals WHERE matched_complex_no IS NOT NULL AND monthly_rent>0" + ac_filter
                    + (f" AND deal_ymd >= date('now','+9 hours', ?)" if days > 0 else "")
                )
                params.extend(ac_params)
                if days > 0: params.append(cutoff)
            if asset in ("offi", "all") and "offi_rentals" in existing:
                unions.append(
                    "SELECT deal_ymd, deposit AS price, monthly_rent, "
                    "excl_use_ar, floor, build_year, matched_complex_no, NULL AS dealing_gbn, 'offi' AS asset "
                    "FROM offi_rentals WHERE matched_complex_no IS NOT NULL AND monthly_rent>0" + ac_filter
                    + (f" AND deal_ymd >= date('now','+9 hours', ?)" if days > 0 else "")
                )
                params.extend(ac_params)
                if days > 0: params.append(cutoff)
        else:
            raise HTTPException(400, "trade must be A1/B1/B2")
        if not unions:
            return {"items": []}

        order_col = "monthly_rent" if trade == "B2" else "price"
        reg_cond, reg_params = _cx_region_clause(sido, sigungu, dong)
        sql = (
            "SELECT t.*, cx.complex_name, " + _REGION_NAME_COL + " FROM ("
            + " UNION ALL ".join(unions) + ") t "
            "LEFT JOIN complexes cx ON cx.complex_no = t.matched_complex_no"
            + _REGION_JOINS +
            " WHERE 1=1" + reg_cond +
            f" ORDER BY t.{order_col} DESC LIMIT ?"
        )
        rows = c.execute(sql, [*params, *reg_params, limit]).fetchall()
    # 카드 스파크라인용 월별 추이 (단지×ROUND(전용)) — 매매/전세만
    tmap = _price_trend_map([r["matched_complex_no"] for r in rows], trade)
    items = []
    for r in rows:
        ar = r["excl_use_ar"]
        items.append({
            "deal_ymd": r["deal_ymd"],
            "price": r["price"], "monthly_rent": r["monthly_rent"],
            "excl_use_ar": ar, "floor": r["floor"],
            "build_year": r["build_year"],
            "complex_no": r["matched_complex_no"],
            "complex_name": r["complex_name"],
            "region_name": r["region_name"],
            "dealing_gbn": r["dealing_gbn"],
            "asset": r["asset"],
            "trend": tmap.get((r["matched_complex_no"], round(ar)), []) if ar is not None else [],
        })
    _res = {"trade": trade, "asset": asset, "days": days, "dealing": dealing, "items": items}
    _cache_put(_ck, _res)
    return _res


def _price_trend_map(complex_nos: list, trade: str | None, months: int = 18) -> dict:
    """단지들의 (complex_no, ROUND(전용면적))별 월별 실거래 평균 추이 — 카드 스파크라인용.
    tx_record_high 의 area_key(=CAST(ROUND(excl_use_ar))) 그룹핑과 동일하게 묶어 매칭.
    소수 단지로 스코핑돼 빠르다. trade 미지원이면 빈 dict."""
    nos = list({n for n in complex_nos if n})
    table, amt, extra = ({"A1": ("transactions", "deal_amount", " AND is_cancelled=0"),
                          "B1": ("rentals", "deposit", " AND monthly_rent=0"),
                          "B2": ("rentals", "monthly_rent", " AND monthly_rent>0")}
                         ).get(trade or "", (None, None, None))
    if not nos or not table:
        return {}
    out: dict = {}
    ph = ",".join("?" * len(nos))
    with _open_db() as c:
        rows = c.execute(
            f"SELECT matched_complex_no, CAST(ROUND(excl_use_ar) AS INTEGER) ak, "
            f"  substr(deal_ymd,1,7) ym, ROUND(AVG({amt})) avg "
            f"FROM {table} WHERE matched_complex_no IN ({ph}) "
            f"  AND excl_use_ar IS NOT NULL AND matched_score>=0.85 "
            f"  AND deal_ymd>=date('now','+9 hours', ?){extra} "
            f"GROUP BY 1, 2, ym ORDER BY ym",
            (*nos, f"-{months} months")).fetchall()
    for r in rows:
        out.setdefault((r[0], r[1]), []).append({"ym": r[2], "avg": r[3]})
    return out


@app.get("/stats/tx-record-high")
def tx_record_high(days: int = 90, trade: str = "A1", asset: str = "all",
                   area_class: str = "all", min_prior: int = 1,
                   sido: str | None = None, sigungu: str | None = None, dong: str | None = None,
                   max_gap_months: float = 0, order: str = "premium", limit: int = 200):
    """단지×타입(전용면적)별 신고가 경신.
    - 그룹(단지×전용면적)의 역대 최고가(record)가 최근 days일 내에 나왔고, 직전
      최고가(prev_high)를 초과한 = '신고가 경신' 케이스만 반환.
    - months_since: 직전 고가 거래일 → 신고가 거래일까지 걸린 개월 수.
    - trade A1(매매)/B1(전세)/B2(월세), asset apt/offi/all.
    - order: premium(상승률 큰 순, default) / recent(경신일 최신 순) / price(거래가격 높은 순)."""
    if limit < 1 or limit > 1000:
        raise HTTPException(400, "limit out of range")
    if days < 1 or days > 3650:
        raise HTTPException(400, "days out of range")
    if not _area_rollup_ready():
        raise HTTPException(503, "tx_area_rollup 미빌드 — build_tx_rollups.py 실행 필요")
    ackey_cond, ackey_params = _area_cond_key(area_class)
    reg_cond, reg_params = _cx_region_clause(sido, sigungu, dong)

    # trade → 롤업 kind(매매/전세/월세) + floor 룩업용 라이브 소스(테이블·가격컬럼·조건).
    if trade == "A1":
        cand = [("transactions", "deal_amount", "is_cancelled=0", "apt", "sale"),
                ("silv_transactions", "deal_amount", "is_cancelled=0", "apt", "silv"),
                ("offi_transactions", "deal_amount", "is_cancelled=0", "offi", "offi_sale")]
    elif trade == "B1":
        cand = [("rentals", "deposit", "monthly_rent=0", "apt", "jeonse"),
                ("offi_rentals", "deposit", "monthly_rent=0", "offi", "offi_jeonse")]
    elif trade == "B2":
        cand = [("rentals", "monthly_rent", "monthly_rent>0", "apt", "wolse"),
                ("offi_rentals", "monthly_rent", "monthly_rent>0", "offi", "offi_wolse")]
    else:
        raise HTTPException(400, "trade must be A1/B1/B2")

    with _open_db() as c:
        existing = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        sources = [(t, px, ex) for (t, px, ex, ag, _k) in cand
                   if asset in (ag, "all") and t in existing]
        kinds = [k for (t, px, ex, ag, k) in cand if asset in (ag, "all") and t in existing]
        if not sources:
            return {"items": []}

        # 신고가 거래의 층수: 최종 결과(rec) 행에 대해서만 라이브 인덱스로 조회. 결과 행 수만.
        def _floor_lookup(date_col: str, price_col: str) -> str:
            subqs = [
                f"(SELECT floor FROM {tbl} WHERE matched_complex_no = base.cno "
                f"AND CAST(ROUND(excl_use_ar) AS INTEGER) = base.area_key "
                f"AND deal_ymd = base.{date_col} AND {price_expr} = base.{price_col}"
                f"{(' AND ' + extra) if extra else ''} LIMIT 1)"
                for tbl, price_expr, extra in sources
            ]
            if not subqs:
                return "NULL"
            if len(subqs) == 1:
                return subqs[0]  # COALESCE는 인자 2개 미만이면 SQL 에러
            return "COALESCE(" + ", ".join(subqs) + ")"

        floor_expr = _floor_lookup("record_date", "record_price")       # 신고가 거래 층
        prev_floor_expr = _floor_lookup("prev_date", "prev_high")        # 직전고가 거래 층

        order_sql = ({"recent": "record_date DESC", "price": "record_price DESC",
                      "premium": "premium DESC"}).get(order, "premium DESC")
        # 경신 간격(직전 신고가 최초 수립일 → 새 신고가) 상한 필터. 0/음수면 제한 없음.
        gap_cond, gap_params = "", []
        if max_gap_months and max_gap_months > 0:
            gap_cond = " AND (julianday(rr.record_date) - julianday(rr.prev_date)) <= ?"
            gap_params = [max_gap_months * 30.44]
        # 단지×평형당 1행짜리 record 사전집계(tx_record_rollup)에서 바로 필터·정렬.
        # floor(층)만 결과 행에 대해 라이브 인덱스로 룩업(정렬·LIMIT 후 base 바깥).
        kph = ",".join("?" * len(kinds))
        sql = f"""
        SELECT base.*, {floor_expr} AS floor, {prev_floor_expr} AS prev_floor FROM (
          SELECT rr.complex_no AS cno, rr.area_key, rr.record_price, rr.record_date, rr.n_total,
                 rr.prev_high, rr.n_prior, rr.prev_date, rr.kind AS rec_kind,
                 (rr.record_price - rr.prev_high) * 1.0 / rr.prev_high AS premium,
                 (julianday(rr.record_date) - julianday(rr.prev_date)) AS days_since,
                 cx.complex_name, cx.cortar_no, cx.total_household_count,
                 TRIM(COALESCE(rs.cortar_name,'')||' '||COALESCE(rg.cortar_name,'')
                      ||' '||COALESCE(rd.cortar_name,'')) AS region_name
          FROM tx_record_rollup rr
          LEFT JOIN complexes cx ON cx.complex_no = rr.complex_no
          LEFT JOIN regions rs ON rs.cortar_no = substr(cx.cortar_no,1,2)||'00000000'
          LEFT JOIN regions rg ON rg.cortar_no = substr(cx.cortar_no,1,5)||'00000'
          LEFT JOIN regions rd ON rd.cortar_no = cx.cortar_no
          WHERE rr.kind IN ({kph}){ackey_cond}{reg_cond}
            AND rr.record_date >= date('now','+9 hours', ?)
            AND rr.n_prior >= ?
            AND rr.prev_high > 0
            AND rr.record_price > rr.prev_high{gap_cond}
          ORDER BY {order_sql} LIMIT ?
        ) base
        """
        params = [*kinds, *ackey_params, *reg_params, f"-{days} days", min_prior, *gap_params, limit]
        rows = c.execute(sql, params).fetchall()

    # 카드 스파크라인용 월별 실거래 추이 (단지×ROUND(전용면적))
    tmap = _price_trend_map([r["cno"] for r in rows], trade)

    items = []
    for r in rows:
        ds = r["days_since"]
        items.append({
            "complex_no": r["cno"],
            "complex_name": r["complex_name"],
            "cortar_no": r["cortar_no"],
            "region_name": r["region_name"],
            "households": r["total_household_count"],
            "area_key": r["area_key"],
            "asset": "silv" if r["rec_kind"] == "silv" else ("offi" if str(r["rec_kind"]).startswith("offi") else "apt"),
            "floor": r["floor"],
            "prev_floor": r["prev_floor"],
            "record_price": r["record_price"],
            "record_date": r["record_date"],
            "prev_high": r["prev_high"],
            "prev_date": r["prev_date"],
            "premium": r["premium"],
            "months_since": round(ds / 30.44, 1) if ds is not None else None,
            "n_total": r["n_total"],
            "n_prior": r["n_prior"],
            "trend": tmap.get((r["cno"], r["area_key"]), []),
        })
    return {"trade": trade, "asset": asset, "days": days, "order": order, "items": items}


_DIGEST_KINDS = {
    "A1": {"apt": ["sale", "silv"], "offi": ["offi_sale"], "all": ["sale", "silv", "offi_sale"]},
    "B1": {"apt": ["jeonse"], "offi": ["offi_jeonse"], "all": ["jeonse", "offi_jeonse"]},
    "B2": {"apt": ["wolse"], "offi": ["offi_wolse"], "all": ["wolse", "offi_wolse"]},
}
_DIGEST_TX = {
    "A1": [("transactions", "is_cancelled=0", "apt", "deal_amount"),
           ("silv_transactions", "is_cancelled=0", "apt", "deal_amount"),
           ("offi_transactions", "is_cancelled=0", "offi", "deal_amount")],
    "B1": [("rentals", "monthly_rent=0", "apt", "deposit"),
           ("offi_rentals", "monthly_rent=0", "offi", "deposit")],
    "B2": [("rentals", "monthly_rent>0", "apt", "monthly_rent"),
           ("offi_rentals", "monthly_rent>0", "offi", "monthly_rent")],
}


@app.get("/stats/region-digest")
def region_digest(sido: str, sigungu: str, dong: str | None = None, days: int = 90,
                  asset: str = "apt", trade: str = "A1", high_n: int = 20):
    """랜딩 실거래 요약: ① 신고가 주요거래(단지/타입 신고가 구분) ② 타입별 주요거래
    ③ 지역별 거래현황(선택 시=구별/동별) + 인접 지역.
    dong(10자리) 주면 그 동으로, 아니면 sigungu가 속한 '시'(앞4자리) 전체로 스코프."""
    import re as _re_d
    days = min(max(int(days), 1), 3650)
    sido2, sgg5, city4 = sido[:2], sigungu[:5], sigungu[:4]
    dong10 = dong[:10] if dong and len(dong) >= 10 else None
    is_dong = bool(dong10)
    hkinds = _DIGEST_KINDS.get(trade, {}).get(asset, ["sale", "silv"])

    with _open_db() as c:
        sgg_rows = c.execute(
            "SELECT substr(cortar_no,1,5), cortar_name FROM regions "
            "WHERE cortar_type='dvsn' AND substr(cortar_no,1,4)=? AND substr(cortar_no,1,2)=?",
            (city4, sido2)).fetchall()
        sido_nm = (c.execute("SELECT cortar_name FROM regions WHERE cortar_no=?",
                             (sido2 + "00000000",)).fetchone() or [""])[0]
        dong_nm = ""
        if is_dong:
            dr = c.execute("SELECT cortar_name FROM regions WHERE cortar_no=?", (dong10,)).fetchone()
            dong_nm = (dr[0].split(" ")[-1] if dr else "")
    if not sgg_rows:
        sgg_rows = [(sgg5, "")]
    sggs = [r[0] for r in sgg_rows]
    city_full = next((" ".join(r[1].split(" ")[:-1]) or r[1] for r in sgg_rows if r[1]), "")

    def _short(nm):
        return _re_d.sub(r"(특별자치도|특별자치시|특별시|광역시|자치도|도|시)$", "", nm or "")

    def _split_rn(rn):
        parts = (rn or "").split(" ")
        if len(parts) >= 3: return " ".join(parts[1:-1]), parts[-1]
        if len(parts) == 2: return parts[1], ""
        return (parts[0] if parts else ""), ""

    def _pyeong(a):
        return round(a / 0.74 / 3.3058) if a else None

    # 신고가/타입별 스코프: 동 선택 시 그 동, 아니면 시의 각 구
    region_calls = ([{"sido": sido, "sigungu": sgg5, "dong": dong10}] if is_dong
                    else [{"sido": sido, "sigungu": s} for s in sggs])

    # ① 신고가 주요거래
    highs = []
    for rc in region_calls:
        try:
            highs.extend(tx_record_high(days=days, trade=trade, asset=asset, order="price",
                                        limit=100, **rc).get("items", []))
        except HTTPException:
            pass
    highs.sort(key=lambda x: x.get("record_price") or 0, reverse=True)
    top = highs[:high_n]
    # 단지신고가 판정: 단지 전 타입 통틀어 최고가와 같으면 단지신고가, 아니면 타입신고가
    cmax = {}
    cnos = list({it.get("complex_no") for it in top if it.get("complex_no")})
    if cnos:
        kph = ",".join("?" * len(hkinds)); ph = ",".join("?" * len(cnos))
        with _open_db() as c:
            for cno, mx in c.execute(
                    f"SELECT complex_no, MAX(record_price) FROM tx_record_rollup "
                    f"WHERE kind IN ({kph}) AND complex_no IN ({ph}) GROUP BY complex_no",
                    [*hkinds, *cnos]):
                cmax[cno] = mx
    record_highs = []
    for it in top:
        sgg, dn = _split_rn(it.get("region_name"))
        ak = it.get("area_key") or 0
        rp = it.get("record_price") or 0
        record_highs.append({
            "name": it.get("complex_name"), "price": rp,
            "up": rp - (it.get("prev_high") or 0),
            "sgg": sgg, "dong": dn, "area": round(ak) if ak else None, "pyeong": _pyeong(ak),
            "floor": it.get("floor"), "bunyang": it.get("asset") == "silv",
            "complex_high": bool(cmax.get(it.get("complex_no")) == rp and rp),
        })

    # ② 타입별 주요거래(전용 정확 밴드)
    def _size_block(ar_min, ar_max, top_n):
        merged = []
        for rc in region_calls:
            try:
                merged.extend(tx_top_price(days=days, trade=trade, asset=asset,
                                           ar_min=ar_min, ar_max=ar_max, limit=20, **rc).get("items", []))
            except HTTPException:
                pass
        merged.sort(key=lambda x: x.get("price") or 0, reverse=True)
        out = []
        for it in merged[:top_n]:
            sgg, dn = _split_rn(it.get("region_name"))
            ar = it.get("excl_use_ar") or 0
            out.append({"name": it.get("complex_name"), "price": it.get("price"),
                        "sgg": sgg, "dong": dn, "area": round(ar) if ar else None, "pyeong": _pyeong(ar),
                        "floor": it.get("floor"), "bunyang": it.get("asset") == "silv"})
        return out
    sizes = []
    for _n, _lo, _hi in [(39, 36, 41), (49, 46, 52), (59, 58, 62), (74, 72, 78), (84, 83, 87), (114, 110, 118)]:
        _its = _size_block(_lo, _hi, 8)
        if len(_its) >= 3:
            sizes.append({"label": f"{_n}㎡", "items": _its})

    # ③ 지역별 현황(구별/동별) + 인접 — regions 중심좌표로 최근접 산출
    sub_len = 10 if is_dong else 5
    with _open_db() as c:
        if is_dong:
            own_rows = c.execute(
                "SELECT cortar_no, cortar_name, center_lat, center_lon FROM regions "
                "WHERE cortar_type='sec' AND substr(cortar_no,1,5)=?", (sgg5,)).fetchall()
            all_rows = c.execute(
                "SELECT cortar_no, cortar_name, center_lat, center_lon FROM regions "
                "WHERE cortar_type='sec' AND center_lat IS NOT NULL").fetchall()
            cr = c.execute("SELECT center_lat, center_lon FROM regions WHERE cortar_no=?", (dong10,)).fetchone()
            clat, clon = (cr or (None, None)); own_pref, own_len = sgg5, 5
        else:
            own_rows = c.execute(
                "SELECT cortar_no, cortar_name, center_lat, center_lon FROM regions "
                "WHERE cortar_type='dvsn' AND substr(cortar_no,1,4)=? AND substr(cortar_no,1,2)=?",
                (city4, sido2)).fetchall()
            all_rows = c.execute(
                "SELECT cortar_no, cortar_name, center_lat, center_lon FROM regions "
                "WHERE cortar_type='dvsn' AND center_lat IS NOT NULL").fetchall()
            _oc = [(r[2], r[3]) for r in own_rows if r[2] is not None]
            clat = sum(x[0] for x in _oc) / len(_oc) if _oc else None
            clon = sum(x[1] for x in _oc) / len(_oc) if _oc else None
            own_pref, own_len = city4, 4

    def _lastname(nm):   # '성남시 분당구'→'분당구'(sec은 이미 '성내동')
        return (nm or "").split(" ")[-1]
    own_full = {r[0][:sub_len]: r[1] for r in own_rows}   # code → cortar_name
    own_codes = list(own_full.keys())
    nearby = []
    if clat is not None:
        cand = [(r[0][:sub_len], r[1], (r[2] - clat) ** 2 + (r[3] - clon) ** 2)
                for r in all_rows if r[0][:own_len] != own_pref and r[2] is not None]
        cand.sort(key=lambda x: x[2])
        nearby = cand[:20]              # 넉넉히 뽑아 거래0 제외 후 상위
    nearby_codes = [x[0] for x in nearby]
    nearby_order = {x[0]: i for i, x in enumerate(nearby)}   # 근접 순서 보존
    full_of = {**own_full, **{x[0]: x[1] for x in nearby}}

    # own+인접 지역의 거래건수·신고가건수 (complexes 조인, 2쿼리)
    allcodes = list(dict.fromkeys(own_codes + nearby_codes))
    vcnt, vavg, rcnt = {}, {}, {}
    if allcodes:
        ph = ",".join("?" * len(allcodes))
        srcs = [(t, cond, pcol) for (t, cond, ag, pcol) in _DIGEST_TX.get(trade, _DIGEST_TX["A1"])
                if asset in (ag, "all")]
        with _open_db() as c:
            existing = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            vparts, vpar = [], []
            for t, cond, pcol in srcs:
                if t not in existing:
                    continue
                vparts.append(f"SELECT substr(cx.cortar_no,1,{sub_len}) g, tx.{pcol} p FROM {t} tx "
                              f"JOIN complexes cx ON cx.complex_no=tx.matched_complex_no "
                              f"WHERE {cond} AND tx.deal_ymd>=date('now','+9 hours',?) "
                              f"AND substr(cx.cortar_no,1,{sub_len}) IN ({ph})")
                vpar += [f"-{days} days", *allcodes]
            if vparts:
                for g, n, av in c.execute(
                        "SELECT g, COUNT(*), AVG(p) FROM (" + " UNION ALL ".join(vparts)
                        + ") GROUP BY g", vpar):
                    vcnt[g] = n; vavg[g] = av
            kph = ",".join("?" * len(hkinds))
            rcnt = {r[0]: r[1] for r in c.execute(
                f"SELECT substr(cx.cortar_no,1,{sub_len}) g, COUNT(*) FROM tx_record_rollup rr "
                f"JOIN complexes cx ON cx.complex_no=rr.complex_no "
                f"WHERE rr.kind IN ({kph}) AND rr.record_date>=date('now','+9 hours',?) "
                f"AND rr.n_prior>=1 AND rr.prev_high>0 AND rr.record_price>rr.prev_high "
                f"AND substr(cx.cortar_no,1,{sub_len}) IN ({ph}) GROUP BY g",
                [*hkinds, f"-{days} days", *allcodes])}

    # 행정구역(시/구) — 동 스코프: 각 동의 부모 구; 구 스코프: 소속 시(구 이름에 있으면)
    region_of = {}
    if is_dong:
        sgg5s = list({cd[:5] for cd in allcodes})
        if sgg5s:
            with _open_db() as c:
                ph2 = ",".join("?" * len(sgg5s))
                snm = {r[0][:5]: r[1] for r in c.execute(
                    f"SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='dvsn' "
                    f"AND substr(cortar_no,1,5) IN ({ph2})", sgg5s)}
            region_of = {cd: snm.get(cd[:5], "") for cd in allcodes}
    else:
        region_of = {cd: " ".join((full_of.get(cd, "") or "").split(" ")[:-1]) for cd in allcodes}

    def _mk(cd):
        return {"name": _lastname(full_of.get(cd, cd)), "region": region_of.get(cd, ""),
                "code": cd,   # 클릭 시 그 동/구 실거래 페이지로(프런트에서 10자리 패딩)
                "count": vcnt.get(cd, 0), "record": rcnt.get(cd, 0),
                "avg": round(vavg[cd]) if vavg.get(cd) else None}
    by_own = sorted([_mk(cd) for cd in own_codes], key=lambda x: x["count"], reverse=True)[:12]
    # 인접: 거래 있는 곳만, 근접 순서로 상위 8
    by_near = [_mk(cd) for cd in sorted(nearby_codes, key=lambda cd: nearby_order.get(cd, 99))
               if vcnt.get(cd, 0) > 0][:8]

    return {"sido_name": _short(sido_nm), "city_name": _short(city_full),
            "dong_name": dong_nm if is_dong else None,
            "region_level": "동" if is_dong else "구",
            "days": days, "record_highs": record_highs, "sizes": sizes,
            "by_sigungu": by_own, "nearby": by_near}


@app.get("/stats/tx-top-volume")
def tx_top_volume(days: int = 30, trade: str = "A1", asset: str = "all",
                  dealing: str = "all", area_class: str = "all",
                  sido: str | None = None, sigungu: str | None = None, dong: str | None = None, limit: int = 100):
    """단지별 거래량 top N."""
    if limit < 1 or limit > 500:
        raise HTTPException(400, "limit out of range")
    if days < 0 or days > 3650:
        raise HTTPException(400, "days out of range")
    _ck = (f"txtopV:{days}:{trade}:{asset}:{dealing}:{area_class}:"
           f"{sido or ''}:{sigungu or ''}:{dong or ''}:{limit}")
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    cutoff = f"-{days} days"
    reg_cond, reg_params = _cx_region_clause(sido, sigungu, dong)
    dg_extra = ""
    if dealing == "broker":
        dg_extra = "dealing_gbn='중개거래'"
    elif dealing == "direct":
        dg_extra = "dealing_gbn='직거래'"
    ac_cond, ac_params = _area_cond("excl_use_ar", area_class, col_supply=None)  # silv union 호환(전용*1.33로 평형필터)

    with _open_db() as c:
        existing = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        unions = []
        params: list = []
        def _src(tbl, asset_tag, extra=""):
            cond = "matched_complex_no IS NOT NULL"
            if extra: cond += f" AND {extra}"
            cond += ac_cond  # ' AND excl_use_ar * 1.33 >= ?' 형식, 이미 leading AND 포함
            extra_params = list(ac_params)
            if days > 0:
                cond += " AND deal_ymd >= date('now','+9 hours', ?)"
                extra_params.append(cutoff)
            return (
                f"SELECT matched_complex_no, '{asset_tag}' AS asset FROM {tbl} WHERE {cond}",
                extra_params,
            )

        if trade == "A1":
            # 매매: 해제거래 제외 + (선택) 거래방식 필터
            sale_extra = "is_cancelled=0" + (f" AND {dg_extra}" if dg_extra else "")
            if asset in ("apt", "all") and "transactions" in existing:
                s, p = _src("transactions", "apt", sale_extra); unions.append(s); params.extend(p)
            # 분양권(silv): 매매 실거래와 통합 집계(사용자 멘탈모델). 거래방식 필터 시엔 제외(분양권엔 무의미).
            if asset in ("apt", "all") and dealing == "all" and "silv_transactions" in existing:
                s, p = _src("silv_transactions", "silv", "is_cancelled=0"); unions.append(s); params.extend(p)
            if asset in ("offi", "all") and "offi_transactions" in existing:
                s, p = _src("offi_transactions", "offi", sale_extra); unions.append(s); params.extend(p)
        elif trade == "B1":
            if asset in ("apt", "all") and "rentals" in existing:
                s, p = _src("rentals", "apt", "monthly_rent=0"); unions.append(s); params.extend(p)
            if asset in ("offi", "all") and "offi_rentals" in existing:
                s, p = _src("offi_rentals", "offi", "monthly_rent=0"); unions.append(s); params.extend(p)
        elif trade == "B2":
            if asset in ("apt", "all") and "rentals" in existing:
                s, p = _src("rentals", "apt", "monthly_rent>0"); unions.append(s); params.extend(p)
            if asset in ("offi", "all") and "offi_rentals" in existing:
                s, p = _src("offi_rentals", "offi", "monthly_rent>0"); unions.append(s); params.extend(p)
        else:
            raise HTTPException(400, "trade must be A1/B1/B2")
        if not unions:
            return {"items": []}

        sql = (
            "WITH agg AS (SELECT matched_complex_no AS cno, COUNT(*) AS n, "
            "SUM(CASE WHEN asset='silv' THEN 1 ELSE 0 END) AS silv_n "
            "FROM (" + " UNION ALL ".join(unions) + ") "
            "GROUP BY matched_complex_no) "
            "SELECT agg.cno, agg.n, agg.silv_n, cx.complex_name, cx.cortar_no, cx.total_household_count, "
            + _REGION_NAME_COL +
            " FROM agg LEFT JOIN complexes cx ON cx.complex_no = agg.cno"
            + _REGION_JOINS +
            " WHERE 1=1" + reg_cond +
            " ORDER BY agg.n DESC LIMIT ?"
        )
        rows = c.execute(sql, [*params, *reg_params, limit]).fetchall()
    _res = {
        "trade": trade, "asset": asset, "days": days, "dealing": dealing,
        "items": [
            {
                "complex_no": r["cno"],
                "complex_name": r["complex_name"],
                "cortar_no": r["cortar_no"],
                "region_name": r["region_name"],
                "households": r["total_household_count"],
                "count": r["n"],
                "silv_count": r["silv_n"] or 0,   # 이 중 분양권 건수(투명 표기용)
            }
            for r in rows
        ],
    }
    _cache_put(_ck, _res)
    return _res


@app.get("/stats/tx-region-volume")
def tx_region_volume(level: str = "sido", parent: str = "", days: int = 30,
                     trade: str = "A1", limit: int = 30):
    """지역(시도/시군구/동) 실거래 '거래량 순위' — parent 하위 지역을 기간(days) 내 거래수로 랭킹.
    level=sido(전국→17시도) / sigungu(parent=시도2자리 → 시군구) / dong(parent=시군구5자리 → 동).
    trade A1(매매)/B1(전세)/B2(월세). 카드뉴스 '지역별 거래량 순위'용."""
    days = min(max(int(days), 1), 3650)
    limit = min(max(int(limit), 1), 100)
    if trade == "A1":
        srcs = [("transactions", "is_cancelled=0"), ("offi_transactions", "is_cancelled=0")]
    elif trade == "B1":
        srcs = [("rentals", "+monthly_rent=0"), ("offi_rentals", "+monthly_rent=0")]
    else:
        srcs = [("rentals", "+monthly_rent>0"), ("offi_rentals", "+monthly_rent>0")]
    if level == "dong":
        grp = "umd_nm"; where = "substr(sgg_cd,1,5)=?"; wp = [parent[:5]]
    elif level == "sigungu":
        grp = "substr(sgg_cd,1,5)"; where = "substr(sgg_cd,1,2)=?"; wp = [parent[:2]]
    else:
        grp = "substr(sgg_cd,1,2)"; where = "1=1"; wp = []
    _ck = f"txregvol:{level}:{parent}:{days}:{trade}:{limit}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    with _open_db() as c:
        existing = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        parts, params = [], []
        for tbl, cond in srcs:
            if tbl not in existing:
                continue
            parts.append(f"SELECT {grp} g, COUNT(*) n FROM {tbl} "
                         f"WHERE {cond} AND deal_ymd>=date('now','+9 hours',?) AND {where} GROUP BY g")
            params += [f"-{days} days"] + wp
        if not parts:
            return {"items": []}
        union = " UNION ALL ".join(parts)
        rows = c.execute(f"SELECT g, SUM(n) n FROM ({union}) WHERE g IS NOT NULL AND g!='' "
                         f"GROUP BY g ORDER BY n DESC LIMIT ?", params + [limit]).fetchall()
        # 지역명 붙이기
        names: dict = {}
        if level == "sido":
            names = {g: _SIDO_STD.get(g, g) for g, _ in rows}
        elif level == "sigungu":
            codes = [g for g, _ in rows]
            if codes:
                ph = ",".join("?" * len(codes))
                names = {r[0][:5]: r[1] for r in c.execute(
                    f"SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='dvsn' "
                    f"AND substr(cortar_no,1,5) IN ({ph})", codes)}
        else:  # dong — g가 이미 동명
            names = {g: g for g, _ in rows}
    items = [{"region_code": g, "region_name": names.get(g, g), "count": n} for g, n in rows]
    _res = {"level": level, "parent": parent, "days": days, "trade": trade, "items": items}
    _cache_put(_ck, _res)
    return _res


@app.get("/stats/tx-low-price")
def tx_low_price(days: int = 180, discount: float = 0.20, min_samples: int = 3,
                 asset: str = "all", area_class: str = "all", sido: str | None = None,
                 sigungu: str | None = None, dong: str | None = None, limit: int = 200):
    """단지×평형 평균보다 N% 이상 저렴한 매매 거래 (증여 의심 등 시세차이).
    - days: 최근 N일 기간 (default 180일 = 6개월)
    - discount: 평균 대비 할인율 (default 0.20 = 20%)
    - min_samples: (단지×평형) 그룹 평균 신뢰도용 최소 거래 건수
    """
    if not (0.0 <= discount <= 0.9):
        raise HTTPException(400, "discount must be 0.0~0.9")
    if days < 30 or days > 3650:
        raise HTTPException(400, "days out of range")
    if min_samples < 1 or min_samples > 100:
        raise HTTPException(400, "min_samples out of range")
    if limit < 1 or limit > 1000:
        raise HTTPException(400, "limit out of range")
    cutoff = f"-{days} days"
    ac_cond, ac_params = _area_cond("excl_use_ar", area_class, col_supply=None)  # silv union 호환(전용*1.33로 평형필터)
    reg_cond, reg_params = _mcn_region_clause(sido, sigungu, dong)   # 지역 좁힘(동필터 시 빠름)

    with _open_db() as c:
        existing = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        unions = []
        params: list = []
        if asset in ("apt", "all") and "transactions" in existing:
            unions.append("SELECT deal_ymd, deal_amount, excl_use_ar, floor, dealing_gbn, "
                          "matched_complex_no, 'apt' AS asset FROM transactions "
                          "WHERE matched_complex_no IS NOT NULL AND is_cancelled=0 AND deal_ymd >= date('now','+9 hours', ?)" + ac_cond + reg_cond)
            params.append(cutoff); params.extend(ac_params); params.extend(reg_params)
        if asset in ("apt", "all") and "silv_transactions" in existing:
            unions.append("SELECT deal_ymd, deal_amount, excl_use_ar, floor, dealing_gbn, "
                          "matched_complex_no, 'silv' AS asset FROM silv_transactions "
                          "WHERE matched_complex_no IS NOT NULL AND is_cancelled=0 AND deal_ymd >= date('now','+9 hours', ?)" + ac_cond + reg_cond)
            params.append(cutoff); params.extend(ac_params); params.extend(reg_params)
        if asset in ("offi", "all") and "offi_transactions" in existing:
            unions.append("SELECT deal_ymd, deal_amount, excl_use_ar, floor, dealing_gbn, "
                          "matched_complex_no, 'offi' AS asset FROM offi_transactions "
                          "WHERE matched_complex_no IS NOT NULL AND is_cancelled=0 AND deal_ymd >= date('now','+9 hours', ?)" + ac_cond + reg_cond)
            params.append(cutoff); params.extend(ac_params); params.extend(reg_params)
        if not unions:
            return {"items": []}
        src = " UNION ALL ".join(unions)

        # (단지, 면적_정수) 그룹별 평균 + 각 거래 할인율
        sql = f"""
        WITH tx AS ({src}),
        grp AS (
            SELECT matched_complex_no AS cno,
                   CAST(ROUND(excl_use_ar) AS INTEGER) AS area_key,
                   AVG(deal_amount) AS avg_price,
                   COUNT(*) AS n
            FROM tx
            WHERE excl_use_ar IS NOT NULL
            GROUP BY cno, area_key
            HAVING COUNT(*) >= ?
        )
        SELECT t.deal_ymd, t.deal_amount, t.excl_use_ar, t.floor, t.dealing_gbn,
               t.matched_complex_no AS cno, t.asset,
               g.avg_price, g.n AS group_size,
               (g.avg_price - t.deal_amount) * 1.0 / g.avg_price AS discount_rate,
               cx.complex_name, {_REGION_NAME_COL}
        FROM tx t
        JOIN grp g ON g.cno = t.matched_complex_no
                  AND g.area_key = CAST(ROUND(t.excl_use_ar) AS INTEGER)
        LEFT JOIN complexes cx ON cx.complex_no = t.matched_complex_no{_REGION_JOINS}
        WHERE g.avg_price > 0
          AND (g.avg_price - t.deal_amount) * 1.0 / g.avg_price >= ?
        ORDER BY discount_rate DESC
        LIMIT ?
        """
        rows = c.execute(sql, [*params, min_samples, discount, limit]).fetchall()
    return {
        "days": days, "discount": discount, "min_samples": min_samples, "asset": asset,
        "items": [
            {
                "deal_ymd": r["deal_ymd"],
                "deal_amount": r["deal_amount"],
                "avg_price": r["avg_price"],
                "discount_rate": r["discount_rate"],
                "excl_use_ar": r["excl_use_ar"],
                "floor": r["floor"],
                "dealing_gbn": r["dealing_gbn"],
                "complex_no": r["cno"],
                "complex_name": r["complex_name"],
                "region_name": r["region_name"],
                "group_size": r["group_size"],
                "asset": r["asset"],
            }
            for r in rows
        ],
    }


@app.get("/stats/tx-inventory-pressure")
def tx_inventory_pressure(trade: str = "A1", min_listings: int = 10,
                          min_households: int = 50, area_class: str = "all", limit: int = 100):
    """매물 적체 단지: (현재 매물수 / 세대수) 비율 높은 순.
    매도 압력 지표 — 거래 안 되는 단지 식별."""
    if limit < 1 or limit > 500:
        raise HTTPException(400, "limit out of range")
    if trade not in ("A1", "B1", "B2", "all"):
        raise HTTPException(400, "trade must be A1/B1/B2/all")
    with _open_db() as c:
        trade_cond = "" if trade == "all" else "AND l.trade_type=?"
        params: list = []
        if trade != "all":
            params.append(trade)
        # area_class for listings_current 의 area1_m2는 공급면적이므로 ×1.33 환산 불필요
        ac_cond = ""
        if area_class != "all":
            rng = _AREA_BUCKETS_SUPPLY.get(area_class)
            if rng:
                lo, hi = rng
                if lo is not None:
                    ac_cond += " AND l.area1_m2 >= ?"
                    params.append(lo)
                if hi is not None:
                    ac_cond += " AND l.area1_m2 < ?"
                    params.append(hi)
        # 성능: ①매물수를 먼저 단지별 집계(lc) ②세대수·비율로 top N 컷(ranked) ③region join은
        # 최종 N행에만 적용. (기존엔 전체 단지에 region join을 걸고 정렬 → 전국 17s)
        sql = (
            "WITH lc AS ("
            "  SELECT l.complex_no AS cno, COUNT(l.article_no) AS n "
            "  FROM listings_current l "
            f"  WHERE 1=1 {trade_cond} {ac_cond} "
            "  GROUP BY l.complex_no HAVING COUNT(l.article_no) >= ? "
            "), ranked AS ("
            "  SELECT c.complex_no, c.complex_name, c.cortar_no, "
            "         c.total_household_count AS households, lc.n AS listings, "
            "         lc.n * 1.0 / c.total_household_count AS ratio "
            "  FROM lc JOIN complexes c ON c.complex_no = lc.cno "
            "  WHERE c.total_household_count >= ? "
            "  ORDER BY ratio DESC LIMIT ? "
            ") "
            "SELECT ranked.complex_no, ranked.complex_name, ranked.households, ranked.listings, ranked.ratio, "
            "TRIM(COALESCE(rs.cortar_name,'')||' '||COALESCE(rg.cortar_name,'')"
            "||' '||COALESCE(rd.cortar_name,'')) AS region_name "
            "FROM ranked "
            "LEFT JOIN regions rs ON rs.cortar_no = substr(ranked.cortar_no,1,2)||'00000000' "
            "LEFT JOIN regions rg ON rg.cortar_no = substr(ranked.cortar_no,1,5)||'00000' "
            "LEFT JOIN regions rd ON rd.cortar_no = ranked.cortar_no "
            "ORDER BY ranked.ratio DESC"
        )
        rows = c.execute(sql, [*params, min_listings, min_households, limit]).fetchall()
    return {
        "trade": trade,
        "items": [
            {"complex_no": r[0], "complex_name": r[1], "households": r[2],
             "listings": r[3], "ratio": r[4], "region_name": r[5]}
            for r in rows
        ],
    }


@app.get("/stats/tx-gap-rank")
def tx_gap_rank(days: int = 365, asset: str = "apt", min_samples: int = 3,
                area_class: str = "all", sido: str | None = None,
                sigungu: str | None = None, dong: str | None = None, limit: int = 100, order: str = "asc"):
    """갭투자 순위: 같은 단지·평형 평균 매매가 - 평균 전세가.
    order='asc' = 갭 작은 순 (적은 자본 투자), 'desc' = 갭 큰 순.
    """
    _ck = (f"txgap:{days}:{asset}:{min_samples}:{area_class}:"
           f"{sido or ''}:{sigungu or ''}:{dong or ''}:{limit}:{order}")
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    if not days or days < 30 or days > 3650:
        raise HTTPException(400, "days out of range")
    if limit < 1 or limit > 500:
        raise HTTPException(400, "limit out of range")
    if not _area_rollup_ready():
        raise HTTPException(503, "tx_area_rollup 미빌드 — build_tx_rollups.py 실행 필요")
    cutoff = f"-{days} days"
    sk = "offi_sale" if asset == "offi" else "sale"
    jk = "offi_jeonse" if asset == "offi" else "jeonse"
    direction = "ASC" if order == "asc" else "DESC"
    ac_cond, ac_params = _area_cond_key(area_class)
    reg_cond, reg_params = _roll_region_clause(sido, sigungu, dong)
    cte_filter = reg_cond + ac_cond
    fp = reg_params + ac_params  # per-CTE filter params (reg, ac 순)
    with _open_db() as c:
        rows = c.execute(
            f"""
            WITH sale AS (
              SELECT complex_no AS cno, area_key,
                     SUM(sum_amt)*1.0/SUM(n) AS avg_sale, SUM(n) AS n_sale
              FROM tx_area_rollup
              WHERE kind=? AND deal_ymd >= date('now','+9 hours', ?){cte_filter}
              GROUP BY cno, area_key HAVING SUM(n) >= ?
            ),
            jeonse AS (
              SELECT complex_no AS cno, area_key,
                     SUM(sum_amt)*1.0/SUM(n) AS avg_jeonse, SUM(n) AS n_jeonse
              FROM tx_area_rollup
              WHERE kind=? AND deal_ymd >= date('now','+9 hours', ?){cte_filter}
              GROUP BY cno, area_key HAVING SUM(n) >= ?
            )
            SELECT s.cno, s.area_key, s.avg_sale, j.avg_jeonse,
                   s.avg_sale - j.avg_jeonse AS gap,
                   j.avg_jeonse * 1.0 / s.avg_sale AS jeonse_rate,
                   s.n_sale, j.n_jeonse, cx.complex_name, {_REGION_NAME_COL}
            FROM sale s
            JOIN jeonse j ON j.cno = s.cno AND j.area_key = s.area_key
            LEFT JOIN complexes cx ON cx.complex_no = s.cno{_REGION_JOINS}
            WHERE s.avg_sale > j.avg_jeonse
            ORDER BY gap {direction} LIMIT ?
            """,
            (sk, cutoff, *fp, min_samples, jk, cutoff, *fp, min_samples, limit),
        ).fetchall()
    _res = {
        "days": days, "asset": asset, "order": order,
        "items": [
            {"complex_no": r[0], "area_key": r[1], "avg_sale": r[2],
             "avg_jeonse": r[3], "gap": r[4], "jeonse_rate": r[5],
             "n_sale": r[6], "n_jeonse": r[7], "complex_name": r[8], "region_name": r[9]}
            for r in rows
        ],
    }
    _cache_put(_ck, _res)
    return _res


@app.get("/stats/tx-jeonse-rate")
def tx_jeonse_rate(days: int = 365, asset: str = "apt", min_samples: int = 3,
                   area_class: str = "all", sido: str | None = None,
                   sigungu: str | None = None, dong: str | None = None,
                   limit: int = 100, order: str = "desc"):
    """전세율 (전세가/매매가) 순위. desc = 전세가 비중 높은 단지(갭투자 매력)."""
    _ck = (f"txjr:{days}:{asset}:{min_samples}:{area_class}:"
           f"{sido or ''}:{sigungu or ''}:{dong or ''}:{limit}:{order}")
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    if not _area_rollup_ready():
        raise HTTPException(503, "tx_area_rollup 미빌드 — build_tx_rollups.py 실행 필요")
    cutoff = f"-{days} days"
    sk = "offi_sale" if asset == "offi" else "sale"
    jk = "offi_jeonse" if asset == "offi" else "jeonse"
    direction = "ASC" if order == "asc" else "DESC"
    ac_cond, ac_params = _area_cond_key(area_class)
    reg_cond, reg_params = _roll_region_clause(sido, sigungu, dong)   # CTE 안에서 지역 좁힘 → 빠름
    cte = ac_cond + reg_cond
    cte_p = [*ac_params, *reg_params]
    with _open_db() as c:
        rows = c.execute(
            f"""
            WITH sale AS (
              SELECT complex_no AS cno, area_key,
                     SUM(sum_amt)*1.0/SUM(n) AS avg_sale, SUM(n) AS n_sale
              FROM tx_area_rollup
              WHERE kind=? AND deal_ymd >= date('now','+9 hours', ?){cte}
              GROUP BY cno, area_key HAVING SUM(n) >= ?
            ),
            jeonse AS (
              SELECT complex_no AS cno, area_key,
                     SUM(sum_amt)*1.0/SUM(n) AS avg_jeonse, SUM(n) AS n_jeonse
              FROM tx_area_rollup
              WHERE kind=? AND deal_ymd >= date('now','+9 hours', ?){cte}
              GROUP BY cno, area_key HAVING SUM(n) >= ?
            )
            SELECT s.cno, s.area_key, s.avg_sale, j.avg_jeonse,
                   j.avg_jeonse * 1.0 / s.avg_sale AS jeonse_rate,
                   s.n_sale, j.n_jeonse, cx.complex_name, {_REGION_NAME_COL}
            FROM sale s
            JOIN jeonse j ON j.cno = s.cno AND j.area_key = s.area_key
            LEFT JOIN complexes cx ON cx.complex_no = s.cno{_REGION_JOINS}
            WHERE s.avg_sale > 0
            ORDER BY jeonse_rate {direction} LIMIT ?
            """,
            (sk, cutoff, *cte_p, min_samples, jk, cutoff, *cte_p, min_samples, limit),
        ).fetchall()
    _res = {
        "days": days, "asset": asset, "order": order,
        "items": [
            {"complex_no": r[0], "area_key": r[1], "avg_sale": r[2],
             "avg_jeonse": r[3], "jeonse_rate": r[4],
             "n_sale": r[5], "n_jeonse": r[6], "complex_name": r[7], "region_name": r[8]}
            for r in rows
        ],
    }
    _cache_put(_ck, _res)
    return _res


@app.get("/stats/tx-price-change")
def tx_price_change(window_days: int = 90, asset: str = "apt", min_samples: int = 3,
                    area_class: str = "all", sido: str | None = None,
                    sigungu: str | None = None, dong: str | None = None,
                    limit: int = 100, order: str = "desc"):
    """가격 변동률 — 최근 window_days 평균 vs 이전 window_days 평균.
    order='desc' = 상승률 높은 순, 'asc' = 하락률 큰 순."""
    if window_days < 30 or window_days > 365:
        raise HTTPException(400, "window_days out of range")
    if not _area_rollup_ready():
        raise HTTPException(503, "tx_area_rollup 미빌드 — build_tx_rollups.py 실행 필요")
    _ck = (f"txchg:{window_days}:{asset}:{min_samples}:{area_class}:"
           f"{sido or ''}:{sigungu or ''}:{dong or ''}:{limit}:{order}")
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    sks = _sale_kinds(asset)
    kph = ",".join("?" * len(sks))
    direction = "ASC" if order == "asc" else "DESC"
    recent_cutoff = f"-{window_days} days"
    prev_cutoff = f"-{window_days * 2} days"
    ac_cond, ac_params = _area_cond_key(area_class)
    reg_cond, reg_params = _roll_region_clause(sido, sigungu, dong)
    cte = ac_cond + reg_cond
    cte_p = [*ac_params, *reg_params]
    with _open_db() as c:
        rows = c.execute(
            f"""
            WITH recent AS (
              SELECT complex_no AS cno, area_key,
                     SUM(sum_amt)*1.0/SUM(n) AS recent_avg, SUM(n) AS n_recent
              FROM tx_area_rollup
              WHERE kind IN ({kph}) AND deal_ymd >= date('now','+9 hours', ?){cte}
              GROUP BY cno, area_key HAVING SUM(n) >= ?
            ),
            prev AS (
              SELECT complex_no AS cno, area_key,
                     SUM(sum_amt)*1.0/SUM(n) AS prev_avg, SUM(n) AS n_prev
              FROM tx_area_rollup
              WHERE kind IN ({kph}) AND deal_ymd >= date('now','+9 hours', ?) AND deal_ymd < date('now','+9 hours', ?){cte}
              GROUP BY cno, area_key HAVING SUM(n) >= ?
            )
            SELECT r.cno, r.area_key, r.recent_avg, p.prev_avg,
                   (r.recent_avg - p.prev_avg) * 1.0 / p.prev_avg AS change_rate,
                   r.n_recent, p.n_prev, cx.complex_name, {_REGION_NAME_COL}
            FROM recent r
            JOIN prev p ON p.cno = r.cno AND p.area_key = r.area_key
            LEFT JOIN complexes cx ON cx.complex_no = r.cno{_REGION_JOINS}
            WHERE p.prev_avg > 0
            ORDER BY change_rate {direction} LIMIT ?
            """,
            (*sks, recent_cutoff, *cte_p, min_samples, *sks, prev_cutoff, recent_cutoff, *cte_p, min_samples, limit),
        ).fetchall()
    _res = {
        "window_days": window_days, "asset": asset, "order": order,
        "items": [
            {"complex_no": r[0], "area_key": r[1], "recent_avg": r[2],
             "prev_avg": r[3], "change_rate": r[4],
             "n_recent": r[5], "n_prev": r[6], "complex_name": r[7], "region_name": r[8]}
            for r in rows
        ],
    }
    _cache_put(_ck, _res)
    return _res


@app.get("/stats/tx-asking-vs-real")
def tx_asking_vs_real(days: int = 90, min_samples: int = 3, area_class: str = "all",
                      limit: int = 100, order: str = "desc", sido: str | None = None,
                      sigungu: str | None = None, dong: str | None = None):
    """호가(매물) vs 실거래가 갭. asking/real ratio 큰 순 (호가가 더 비쌈).
    order='desc'=호가 프리미엄(매도강세) / 'asc'=호가 역전(실거래보다 낮은 저평가·매수기회)."""
    cutoff = f"-{days} days"
    direction = "ASC" if order == "asc" else "DESC"
    reg_cond, reg_params = _cx_region_clause(sido, sigungu, dong)
    # 호가는 공급면적(area1_m2), 실거래는 전용면적(supply_area 매핑) 기준으로 각각 필터
    ac_ask, ac_ask_p = _area_cond("area1_m2", area_class, col_supply="area1_m2")
    ac_real, ac_real_p = _area_cond("excl_use_ar", area_class)
    with _open_db() as c:
        rows = c.execute(
            f"""
            WITH asking AS (
              SELECT complex_no,
                     CAST(ROUND(area1_m2) AS INTEGER) AS area_key,
                     AVG(deal_or_warrant_price) AS avg_asking,
                     COUNT(*) AS n_asking
              FROM listings_current
              WHERE trade_type='A1' AND deal_or_warrant_price > 0
                AND complex_no IS NOT NULL AND area1_m2 IS NOT NULL{ac_ask}
              GROUP BY complex_no, area_key HAVING COUNT(*) >= ?
            ),
            real_tx AS (
              SELECT matched_complex_no AS cno,
                     CAST(ROUND(excl_use_ar) AS INTEGER) AS area_key,
                     AVG(deal_amount) AS avg_real, COUNT(*) AS n_real
              FROM transactions
              WHERE matched_complex_no IS NOT NULL AND is_cancelled = 0
                AND deal_ymd >= date('now','+9 hours', ?) AND excl_use_ar IS NOT NULL{ac_real}
              GROUP BY cno, area_key HAVING COUNT(*) >= ?
            )
            SELECT a.complex_no, a.area_key, a.avg_asking, t.avg_real,
                   (a.avg_asking - t.avg_real) * 1.0 / t.avg_real AS gap_rate,
                   a.n_asking, t.n_real, cx.complex_name, {_REGION_NAME_COL}
            FROM asking a
            JOIN real_tx t ON t.cno = a.complex_no AND t.area_key = a.area_key
            LEFT JOIN complexes cx ON cx.complex_no = a.complex_no{_REGION_JOINS}
            WHERE t.avg_real > 0{reg_cond}
            ORDER BY gap_rate {direction} LIMIT ?
            """,
            (*ac_ask_p, min_samples, cutoff, *ac_real_p, min_samples, *reg_params, limit),
        ).fetchall()
    return {
        "days": days, "order": order,
        "items": [
            {"complex_no": r[0], "area_key": r[1], "avg_asking": r[2],
             "avg_real": r[3], "gap_rate": r[4],
             "n_asking": r[5], "n_real": r[6], "complex_name": r[7], "region_name": r[8]}
            for r in rows
        ],
    }


def _sale_kinds(asset: str) -> list[str]:
    """매매 통계 = 일반매매(sale) + 분양권(silv) 통합(사용자 멘탈모델). 분양권 거래금액은
    실거래 총액이라 매매와 같은 scale. 오피스텔은 분양권 분리 데이터 없어 offi_sale만."""
    return ["offi_sale"] if asset == "offi" else ["sale", "silv"]


@app.get("/stats/tx-pyeong-price")
def tx_pyeong_price(days: int = 365, asset: str = "apt", min_samples: int = 3,
                    area_class: str = "all", sido: str | None = None,
                    sigungu: str | None = None, dong: str | None = None, limit: int = 100, order: str = "desc"):
    """평당가 순위 — 거래가 ÷ 면적(평). 단지×평형 그룹 평균.
    order='desc' = 비싼 순, 'asc' = 싼 순."""
    _ck = (f"txpy:{days}:{asset}:{min_samples}:{area_class}:"
           f"{sido or ''}:{sigungu or ''}:{dong or ''}:{limit}:{order}")
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    if not _area_rollup_ready():
        raise HTTPException(503, "tx_area_rollup 미빌드 — build_tx_rollups.py 실행 필요")
    cutoff = f"-{days} days"
    sks = _sale_kinds(asset)
    kph = ",".join("?" * len(sks))
    direction = "ASC" if order == "asc" else "DESC"
    ac_cond, ac_params = _area_cond_key(area_class)
    reg_cond, reg_params = _roll_region_clause(sido, sigungu, dong)
    cte_filter = reg_cond + ac_cond
    with _open_db() as c:
        # 평당가 = 가중평균(Σ금액 / Σ전용평). area_key 그룹 내 전용면적이 거의 일정해
        # 원본 AVG(금액/평) 과 사실상 동일(롤업쪽이 면적가중이라 더 견고).
        rows = c.execute(
            f"""
            SELECT cno, area_key, avg_price, pyeong_price, n,
                   cx.complex_name, {_REGION_NAME_COL}
            FROM (
              SELECT complex_no AS cno, area_key,
                     SUM(sum_amt)*1.0/SUM(n) AS avg_price,
                     SUM(sum_amt) * 3.3058 / SUM(sum_excl) AS pyeong_price,
                     SUM(n) AS n
              FROM tx_area_rollup
              WHERE kind IN ({kph}) AND deal_ymd >= date('now','+9 hours', ?){cte_filter}
              GROUP BY complex_no, area_key HAVING SUM(n) >= ?
            ) t
            LEFT JOIN complexes cx ON cx.complex_no = t.cno{_REGION_JOINS}
            ORDER BY pyeong_price {direction}
            LIMIT ?
            """,
            (*sks, cutoff, *reg_params, *ac_params, min_samples, limit),
        ).fetchall()
    _res = {
        "days": days, "asset": asset, "order": order,
        "items": [
            {"complex_no": r[0], "area_key": r[1], "avg_price": r[2],
             "pyeong_price": r[3], "n": r[4], "complex_name": r[5], "region_name": r[6]}
            for r in rows
        ],
    }
    _cache_put(_ck, _res)
    return _res


@app.get("/stats/tx-turnover")
def tx_turnover(days: int = 365, trade: str = "A1", asset: str = "apt",
                min_households: int = 50, area_class: str = "all",
                sido: str | None = None, sigungu: str | None = None, dong: str | None = None, limit: int = 100):
    """거래회전율 — 거래량 / 세대수. trade=A1 매매, B1 전세."""
    _ck = (f"txto:{days}:{trade}:{asset}:{min_households}:{area_class}:"
           f"{sido or ''}:{sigungu or ''}:{dong or ''}:{limit}")
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    if not _area_rollup_ready():
        raise HTTPException(503, "tx_area_rollup 미빌드 — build_tx_rollups.py 실행 필요")
    cutoff = f"-{days} days"
    if trade == "A1":
        kinds = _sale_kinds(asset)   # 매매+분양권 통합
    elif trade == "B1":
        kinds = ["offi_jeonse" if asset == "offi" else "jeonse"]
    else:
        raise HTTPException(400, "trade must be A1 or B1")
    kph = ",".join("?" * len(kinds))
    ac_cond, ac_params = _area_cond_key(area_class)
    reg_cond, reg_params = _roll_region_clause(sido, sigungu, dong)
    src = (f"SELECT complex_no AS cno, SUM(n) AS n FROM tx_area_rollup "
           f"WHERE kind IN ({kph}) AND deal_ymd >= date('now','+9 hours', ?){reg_cond}{ac_cond} GROUP BY complex_no")
    with _open_db() as c:
        rows = c.execute(
            f"""
            WITH agg AS ({src})
            SELECT cx.complex_no, cx.complex_name, cx.total_household_count AS households,
                   agg.n AS tx_count,
                   agg.n * 1.0 / cx.total_household_count AS turnover_rate,
                   {_REGION_NAME_COL}
            FROM complexes cx
            JOIN agg ON agg.cno = cx.complex_no{_REGION_JOINS}
            WHERE cx.total_household_count >= ?
            ORDER BY turnover_rate DESC LIMIT ?
            """,
            (*kinds, cutoff, *reg_params, *ac_params, min_households, limit),
        ).fetchall()
    _res = {
        "days": days, "trade": trade, "asset": asset,
        "items": [
            {"complex_no": r[0], "complex_name": r[1], "households": r[2],
             "tx_count": r[3], "turnover_rate": r[4], "region_name": r[5]}
            for r in rows
        ],
    }
    _cache_put(_ck, _res)
    return _res


@app.get("/stats/tx-yield")
def tx_yield(days: int = 365, asset: str = "apt", area_class: str = "all",
             sido: str | None = None, sigungu: str | None = None,
             dong: str | None = None, min_samples: int = 3, limit: int = 100):
    """월세수익률 — 연 월세 / 매매가 × 100. 단지×평형 그룹.
    월세 거래의 (deposit + monthly_rent×100) ÷ 매매가 (보증금 환산은 ×100 approx).
    area_class: 평형(공급면적) 버킷, sido: 시도(시군구코드 앞 2자리)로 거른다."""
    if not _area_rollup_ready():
        raise HTTPException(503, "tx_area_rollup 미빌드 — build_tx_rollups.py 실행 필요")
    cutoff = f"-{days} days"
    sk = "offi_sale" if asset == "offi" else "sale"
    wk = "offi_wolse" if asset == "offi" else "wolse"
    # 평형·지역 필터 — sale/wolse 두 CTE 에 동일 적용 (롤업: area_key + complex_no IN 지역).
    reg_cond, reg_params = _roll_region_clause(sido, sigungu, dong)
    ac_cond, ac_params = _area_cond_key(area_class)
    cte_filter = reg_cond + ac_cond
    fp = reg_params + ac_params  # per-CTE filter params

    with _open_db() as c:
        rows = c.execute(
            f"""
            WITH sale AS (
              SELECT complex_no AS cno, area_key,
                     SUM(sum_amt)*1.0/SUM(n) AS avg_sale, SUM(n) AS n_sale
              FROM tx_area_rollup
              WHERE kind=? AND deal_ymd >= date('now','+9 hours', ?){cte_filter}
              GROUP BY cno, area_key HAVING SUM(n) >= ?
            ),
            wolse AS (
              SELECT complex_no AS cno, area_key,
                     SUM(sum_amt2)*1.0/SUM(n) AS avg_deposit,
                     SUM(sum_amt)*1.0/SUM(n) AS avg_monthly,
                     SUM(n) AS n_wolse
              FROM tx_area_rollup
              WHERE kind=? AND deal_ymd >= date('now','+9 hours', ?){cte_filter}
              GROUP BY cno, area_key HAVING SUM(n) >= ?
            )
            SELECT s.cno, s.area_key, s.avg_sale, w.avg_deposit, w.avg_monthly,
                   (w.avg_monthly * 12) * 1.0 / s.avg_sale AS yield_rate,
                   s.n_sale, w.n_wolse, cx.complex_name,
                   cx.total_household_count,
                   TRIM(COALESCE(rg.cortar_name,'')||' '||COALESCE(rd.cortar_name,'')) AS region_name
            FROM sale s
            JOIN wolse w ON w.cno = s.cno AND w.area_key = s.area_key
            LEFT JOIN complexes cx ON cx.complex_no = s.cno
            LEFT JOIN regions rg ON rg.cortar_no = substr(cx.cortar_no,1,5)||'00000'
            LEFT JOIN regions rd ON rd.cortar_no = cx.cortar_no
            WHERE s.avg_sale > 0
            ORDER BY yield_rate DESC LIMIT ?
            """,
            (sk, cutoff, *fp, min_samples, wk, cutoff, *fp, min_samples, limit),
        ).fetchall()
    return {
        "days": days, "asset": asset, "area_class": area_class, "sido": sido,
        "items": [
            {"complex_no": r[0], "area_key": r[1], "avg_sale": r[2],
             "avg_deposit": r[3], "avg_monthly": r[4], "yield_rate": r[5],
             "n_sale": r[6], "n_wolse": r[7], "complex_name": r[8],
             "households": r[9], "region_name": r[10]}
            for r in rows
        ],
    }


@app.get("/admin/suspicious-realtors")
def suspicious_realtors(_admin: dict = Depends(admin_user), limit: int = 200):
    """vworld 영업 등록이 안 된 채 Naver에 광고 올리는 의심 사무소.
    match_type='none'이고 현재 매물이 있는 realtor 목록.
    """
    if limit < 1 or limit > 2000:
        raise HTTPException(400, "limit out of range")
    import re as _re
    _STD_RE = _re.compile(r"^\d{4,5}-\d{4}-\d{4,6}(?:-\d{3})?$")

    def _categorize(regno: str | None) -> str:
        if not regno:
            return "B"  # 등록번호 없음
        # normalize 시도
        import sys as _sys
        from pathlib import Path as _P
        _sys.path.insert(0, str(_P(__file__).resolve().parent.parent))
        from collector.realtor_matching import normalize_regno
        nr = normalize_regno(regno)
        if not nr or not _STD_RE.match(nr):
            return "C"  # 옛/이상 포맷
        return "D"  # 표준이지만 vworld 미등록 = 폐업/이전 의심

    with _open_db() as c:
        # 매칭 안 됐거나 vworld_status가 있는 (정지/휴업) 케이스 모두
        rows = c.execute(
            """
            SELECT m.realtor_id, m.naver_name, m.primary_sgg_cd, m.total_listings,
                   m.vworld_status, m.match_type,
                   nr.representative_name, nr.address,
                   nr.representative_tel_no, nr.cell_phone_no,
                   nr.establish_registration_no
            FROM realtor_match m
            LEFT JOIN naver_realtors nr ON nr.realtor_id = m.realtor_id
            WHERE (m.match_type='none' OR m.vworld_status IS NOT NULL)
              AND COALESCE(m.total_listings, 0) > 0
            ORDER BY m.total_listings DESC
            LIMIT ?
            """,
            (limit,),
        ).fetchall()

    out: list[dict] = []
    for r in rows:
        regno = r["establish_registration_no"]
        vws = r["vworld_status"]
        if vws:
            cat = "E"  # vworld 정지/휴업 — 직원 검색으로 확인됨
        elif r["representative_name"] is None and r["address"] is None:
            cat = "A"
        else:
            cat = _categorize(regno)
        out.append({
            "realtor_id": r["realtor_id"],
            "naver_name": r["naver_name"],
            "sgg_cd": r["primary_sgg_cd"],
            "listings": r["total_listings"],
            "representative": r["representative_name"],
            "address": r["address"],
            "phone": r["representative_tel_no"],
            "cell": r["cell_phone_no"],
            "registration_no": regno,
            "category": cat,
            "vworld_status": vws,
        })
    return {"items": out, "total": len(out)}


# ===========================================================================
# 가격 변동 대시보드 (전국 매물 가격 변동을 집계 관점에서 본다)
#
# complex_daily_agg.price_avg 는 오타 호가(예: 8억을 800억으로 입력)에 오염될 수
# 있어 — 실제로 max 가 1.7조원까지 찍힌다 — 모든 집계에 sane bound 를 건다.
# 지역(시도/시군구)은 complexes.cortar_no 의 앞자리로 도출한다:
#   시도   = substr(cortar_no,1,2) || '00000000'   (예: 11→서울시)
#   시군구 = substr(cortar_no,1,5) || '00000'        (예: 11680→강남구)
# ===========================================================================

# 매물 호가 sane 범위 (원). 거래유형별 하한, 공통 상한.
_PRICE_LO = {"A1": 20_000_000, "B1": 5_000_000, "B2": 1_000_000}
_PRICE_HI = 500_000_000_000  # 5천억 — 이 이상은 입력 오류로 본다
# 월세료(B2 rent_avg) sane 범위 (원/월). 상한은 시군구별 실거래 기준(rent_ref_sgg)을
# 우선 쓰고, 기준이 없는 시군구만 _RENT_HI(1천만/월) fallback. 하한은 공통 3만원.
_RENT_LO = 30_000
_RENT_HI = 10_000_000


def _consecutive_days(prev: str | None, latest: str | None) -> bool:
    """prev 가 latest 의 정확히 하루 전(연속일)이면 True. 수집 누락으로 며칠
    건너뛰면 False → '전일 대비' 라벨을 실제 날짜로 바꾸기 위함."""
    from datetime import date as _date
    try:
        return bool(prev and latest) and (
            _date.fromisoformat(latest) - _date.fromisoformat(prev)).days == 1
    except Exception:
        return False


@app.get("/stats/changes/summary")
def changes_summary(sido: str | None = None, sigungu: str | None = None, dong: str | None = None, asset: str | None = None):
    """지역별 요약: 최신 스냅샷의 거래유형별 매물 수 + 전일 대비 증감, 단지 수,
    그리고 최신 일자 가격 변동 이벤트(상승/하락) 건수.

    sido/sigungu 미지정 시 전국. asset(apt/offi)로 아파트/오피스텔 구분.
    필터는 complexes.cortar_no/real_estate_type 로 적용 (complex_daily_agg ⨝ complexes).
    """
    # 버전연동 캐시 — 데이터 재빌드 시 자동 무효(정확성), 그 전엔 즉시응답(전국 콜드 ~2s).
    _ck = f"chsummary:{sido or ''}:{sigungu or ''}:{dong or ''}:{asset or ''}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    # 지역 필터 SQL fragment. complexes 를 join 해서 cortar_no prefix 로 거름.
    region_join = ""
    region_clause = ""
    region_params: list[Any] = []
    if sigungu:
        region_join = " JOIN complexes cx ON cx.complex_no = a.complex_no"
        region_clause = " AND substr(cx.cortar_no,1,5) = substr(?,1,5)"
        region_params.append(sigungu)
    elif sido:
        region_join = " JOIN complexes cx ON cx.complex_no = a.complex_no"
        region_clause = " AND substr(cx.cortar_no,1,2) = substr(?,1,2)"
        region_params.append(sido)
    # 자산(아파트/오피스텔) 필터 — complexes join 필요시 추가.
    asset_clause = _asset_type_clause(asset)
    if asset_clause and not region_join:
        region_join = " JOIN complexes cx ON cx.complex_no = a.complex_no"
    region_clause += asset_clause

    with _open_db() as c:
        dates = [
            r[0]
            for r in c.execute(
                "SELECT DISTINCT snapshot_date FROM complex_daily_agg "
                "ORDER BY snapshot_date DESC LIMIT 2"
            )
        ]
        latest = dates[0] if dates else None
        prev = dates[1] if len(dates) > 1 else None

        def totals(d):
            if not d:
                return {}, 0
            by = {
                t: n
                for t, n in c.execute(
                    f"SELECT a.trade_type, SUM(a.listing_count) FROM complex_daily_agg a"
                    f"{region_join} WHERE a.snapshot_date=?{region_clause}"
                    f" GROUP BY a.trade_type",
                    (d, *region_params),
                )
            }
            cplx = c.execute(
                f"SELECT COUNT(DISTINCT a.complex_no) FROM complex_daily_agg a"
                f"{region_join} WHERE a.snapshot_date=?{region_clause}",
                (d, *region_params),
            ).fetchone()[0]
            return by, cplx

        cur, cur_cplx = totals(latest)
        old, _ = totals(prev)

        # 실매물(중복 광고 합침) — 같은 집을 여러 중개업소가 올린 광고를 1건으로.
        # 광고 수와 동일 테이블(complex_daily_agg.unit_count, daily가 같은 쿼리에서 동시
        # 계산)에서 읽어 두 수치가 항상 같은 행에서 나온다(정합 보장 + 원장 풀스캔 회피).
        units_by: dict[str, int] = {}
        try:
            if latest:
                units_by = {
                    t: int(round(u))
                    for t, u in c.execute(
                        f"SELECT a.trade_type, SUM(a.unit_count) FROM complex_daily_agg a"
                        f"{region_join} WHERE a.snapshot_date=?{region_clause}"
                        f" GROUP BY a.trade_type",
                        (latest, *region_params),
                    )
                    if u is not None
                }
        except Exception:  # noqa: BLE001 — 실매물 계산 실패해도 기존 응답은 유지
            units_by = {}

        def avg_price(d, t):
            """거래유형별 가중 평균 호가 (지역 필터 적용 + sane bound)."""
            if not d:
                return None
            lo = _PRICE_LO.get(t, 1_000_000)
            row = c.execute(
                f"SELECT SUM(a.price_avg*a.listing_count)*1.0/SUM(a.listing_count) "
                f"FROM complex_daily_agg a{region_join} "
                f"WHERE a.snapshot_date=? AND a.trade_type=? "
                f"  AND a.price_avg BETWEEN ? AND ?{region_clause}",
                (d, t, lo, _PRICE_HI, *region_params),
            ).fetchone()
            return row[0] if row and row[0] is not None else None

        def avg_monthly_rent(d):
            """B2 (월세) 행의 rent_avg 가중평균 — 월세 평균."""
            if not d:
                return None
            row = c.execute(
                f"SELECT SUM(a.rent_avg*a.listing_count)*1.0/SUM(a.listing_count) "
                f"FROM complex_daily_agg a "
                f"JOIN complexes cr ON cr.complex_no = a.complex_no "
                f"LEFT JOIN rent_ref_sgg rr ON rr.sgg5 = substr(cr.cortar_no,1,5)"
                f"{region_join} "
                f"WHERE a.snapshot_date=? AND a.trade_type='B2' "
                f"  AND a.rent_avg BETWEEN ? AND COALESCE(rr.rent_cap, ?)"
                f"{region_clause}",
                (d, _RENT_LO, _RENT_HI, *region_params),
            ).fetchone()
            return row[0] if row and row[0] is not None else None

        avg_cur = {t: avg_price(latest, t) for t in ("A1", "B1", "B2")}
        avg_old = {t: avg_price(prev, t) for t in ("A1", "B1", "B2")}
        rent_cur = avg_monthly_rent(latest)
        rent_old = avg_monthly_rent(prev)

        # 가격 변동 이벤트도 지역 필터. article_events 에는 complex_no 가 있으면
        # complexes join 으로 지역 거름 (없으면 전국 기본).
        ev_region_join = ""
        if region_join:
            # article_events 의 complex_no 와 직접 join
            ev_region_join = " JOIN complexes cx ON cx.complex_no = ae.complex_no"
        ev_date = c.execute(
            f"SELECT MAX(ae.event_date) FROM article_events ae{ev_region_join} "
            f"WHERE ae.event_type='PRICE_CHANGE'"
            f"{region_clause}",
            tuple(region_params),
        ).fetchone()[0]
        up = down = 0
        if ev_date:
            for dr, n in c.execute(
                f"SELECT CASE WHEN ae.new_price>ae.old_price THEN 'up' ELSE 'down' END, COUNT(*) "
                f"FROM article_events ae{ev_region_join} "
                f"WHERE ae.event_type='PRICE_CHANGE' AND ae.event_date=? "
                f"  AND ae.old_price BETWEEN 1000000 AND 500000000000 "
                f"  AND ae.new_price BETWEEN 1000000 AND 500000000000 "
                f"  AND ae.old_price<>ae.new_price{region_clause} "
                f"GROUP BY 1",
                (ev_date, *region_params),
            ):
                if dr == "up":
                    up = n
                else:
                    down = n

    def _change(now, was):
        if now is None or was is None or was == 0:
            return None
        return (now - was) / was

    trades = {
        t: {
            "count": cur.get(t, 0),
            "prev": old.get(t, 0),
            "delta": cur.get(t, 0) - old.get(t, 0),
            "avg_price": avg_cur[t],
            "avg_prev": avg_old[t],
            "avg_change": _change(avg_cur[t], avg_old[t]),
            # 실매물(중복 광고 합침) — 광고 대비 배수는 프런트에서 count/units
            "units": units_by.get(t),
        }
        for t in ("A1", "B1", "B2")
    }
    # B2(월세) 행의 월세 평균 — 보증금(avg_price)과 따로.
    trades["B2"]["rent_avg"] = rent_cur
    trades["B2"]["rent_prev"] = rent_old
    trades["B2"]["rent_change"] = _change(rent_cur, rent_old)
    out = {
        "latest_date": latest,
        "prev_date": prev,
        # prev 가 latest 의 바로 전날(연속일)인지 — 수집 누락으로 며칠 건너뛴 경우
        # 프런트가 "전일 대비" 대신 실제 날짜를 표기하도록(거짓 전일 비교 방지).
        "prev_is_yesterday": _consecutive_days(prev, latest),
        "complex_count": cur_cplx,
        "total": sum(cur.values()),
        "total_units": (sum(units_by.values()) if units_by else None),
        "trades": trades,
        "event_date": ev_date,
        "events_up": up,
        "events_down": down,
        "sido": sido,
        "sigungu": sigungu,
    }
    _cache_put(_ck, out)
    return out


@app.get("/stats/changes/sido-list")
def changes_sido_list():
    """시도 드롭다운용 목록 (regions.cortar_type='city') — 표준 배열 순서."""
    with _open_db() as c:
        rows = c.execute(
            "SELECT cortar_no, cortar_name FROM regions WHERE cortar_type='city'"
        ).fetchall()
    rows = sorted(rows, key=lambda r: sido_rank(r[0]))
    return {"items": [{"code": r[0], "name": r[1]} for r in rows]}


@app.get("/stats/changes/region-rank")
def changes_region_rank(
    level: str = "sido",
    trade: str = "A1",
    order: str = "desc",
    sido: str | None = None,
    sigungu: str | None = None, dong: str | None = None,
    asset: str | None = None,
    min_listings: int = 10,
    area_class: str = "all",
    limit: int = 100,
):
    """지역별 평균 매물가 순위 (최신 스냅샷). level=sido|sigungu|dong. asset=apt/offi.
    평균은 단지·평형별 price_avg 를 listing_count 로 가중 평균한 값.
    area_class: 평형 필터 — complex_areas.supply_area(공급면적) 기준 버킷.
    complexes.cortar_no 는 동(sec) 레벨 코드라, dong 은 코드 전체로 그룹화한다."""
    if level not in ("sido", "sigungu", "dong"):
        raise HTTPException(400, "level must be sido|sigungu|dong")
    if trade not in ("A1", "B1", "B2"):
        raise HTTPException(400, "bad trade")
    if limit < 1 or limit > 1000:
        raise HTTPException(400, "limit out of range")
    direction = "ASC" if order == "asc" else "DESC"
    cut, pad = {"sido": (2, "00000000"), "sigungu": (5, "00000"), "dong": (10, "")}[level]
    lo = _PRICE_LO.get(trade, 1_000_000)

    # 평형 필터 — complex_areas 를 (complex_no, pyeong_name=area_name) 로 조인해
    # 공급면적 버킷으로 거른다. area_name↔pyeong_name 커버리지는 사실상 100%.
    ac_cond, ac_params = _area_cond("ca.exclusive_area", area_class, col_supply="ca.supply_area")
    area_join = (
        " JOIN complex_areas ca ON ca.complex_no=a.complex_no AND ca.pyeong_name=a.area_name"
        if ac_cond else ""
    )

    params: list[Any] = [trade, lo, _PRICE_HI]
    sido_clause = ""
    if sigungu:
        sido_clause = " AND substr(cx.cortar_no,1,5)=substr(?,1,5)"
        params.append(sigungu)
    elif sido:
        sido_clause = " AND substr(cx.cortar_no,1,2)=substr(?,1,2)"
        params.append(sido)
    params += ac_params
    params += [min_listings, limit]
    asset_clause = _asset_type_clause(asset)  # cx 항상 조인됨

    # 지역명은 "동구·강서구"처럼 시군구 단독이면 어느 시·도인지 모호하다. 레벨에 따라
    # 시도(+시군구)를 접두로 붙여 명확하게 만든다. r 은 그룹 레벨 지역, rs=시도, rg=시군구.
    if level == "sido":
        label_joins = ""
        label_expr = "MAX(r.cortar_name)"
    elif level == "sigungu":
        label_joins = " LEFT JOIN regions rs ON rs.cortar_no=substr(cx.cortar_no,1,2)||'00000000'"
        label_expr = "TRIM(COALESCE(MAX(rs.cortar_name),'')||' '||COALESCE(MAX(r.cortar_name),''))"
    else:  # dong
        label_joins = (
            " LEFT JOIN regions rs ON rs.cortar_no=substr(cx.cortar_no,1,2)||'00000000'"
            " LEFT JOIN regions rg ON rg.cortar_no=substr(cx.cortar_no,1,5)||'00000'"
        )
        label_expr = (
            "TRIM(COALESCE(MAX(rs.cortar_name),'')||' '||COALESCE(MAX(rg.cortar_name),'')"
            "||' '||COALESCE(MAX(r.cortar_name),''))"
        )

    # 최신·직전 두 스냅샷을 한 번에 스캔해 지역별 가중 평균과 전일 대비 변동을 함께 낸다.
    # 필터(거래·가격범위·시도·평형)는 양일에 동일 적용되므로 CASE 피벗으로 파라미터를
    # 늘리지 않는다.
    sql = f"""
        WITH dts AS (
          SELECT MAX(snapshot_date) AS hi,
                 (SELECT MAX(snapshot_date) FROM complex_daily_agg
                  WHERE snapshot_date < (SELECT MAX(snapshot_date) FROM complex_daily_agg)) AS lo
          FROM complex_daily_agg
        )
        SELECT substr(cx.cortar_no,1,{cut})||'{pad}' AS rc, {label_expr} AS cortar_name,
               SUM(CASE WHEN a.snapshot_date=d.hi THEN a.price_avg*a.listing_count ELSE 0 END)*1.0
                 / NULLIF(SUM(CASE WHEN a.snapshot_date=d.hi THEN a.listing_count ELSE 0 END),0) AS avg_price,
               SUM(CASE WHEN a.snapshot_date=d.lo THEN a.price_avg*a.listing_count ELSE 0 END)*1.0
                 / NULLIF(SUM(CASE WHEN a.snapshot_date=d.lo THEN a.listing_count ELSE 0 END),0) AS prev_avg,
               SUM(CASE WHEN a.snapshot_date=d.hi THEN a.listing_count ELSE 0 END) AS listings,
               COUNT(DISTINCT CASE WHEN a.snapshot_date=d.hi THEN a.complex_no END) AS complexes,
               SUM(CASE WHEN a.snapshot_date=d.hi THEN COALESCE(a.unit_count,0) ELSE 0 END) AS units
        FROM complex_daily_agg a
        JOIN complexes cx ON cx.complex_no=a.complex_no
        JOIN dts d ON a.snapshot_date IN (d.hi, d.lo){area_join}
        LEFT JOIN regions r ON r.cortar_no=substr(cx.cortar_no,1,{cut})||'{pad}'{label_joins}
        WHERE a.trade_type=? AND a.price_avg BETWEEN ? AND ?
          AND cx.cortar_no IS NOT NULL{sido_clause}{asset_clause}{ac_cond}
        GROUP BY rc HAVING listings>=?
        ORDER BY avg_price {direction} LIMIT ?
    """
    with _open_db() as c:
        rows = c.execute(sql, params).fetchall()
        dpair = c.execute(
            "SELECT MAX(snapshot_date), (SELECT MAX(snapshot_date) FROM complex_daily_agg "
            "WHERE snapshot_date < (SELECT MAX(snapshot_date) FROM complex_daily_agg)) "
            "FROM complex_daily_agg"
        ).fetchone()
    latest_d, prev_d = (dpair[0], dpair[1]) if dpair else (None, None)

    def _change(now, was):
        if now is None or was is None or was == 0:
            return None
        return (now - was) / was

    return {
        "level": level,
        "trade": trade,
        "order": order,
        "latest_date": latest_d,
        "prev_date": prev_d,
        "prev_is_yesterday": _consecutive_days(prev_d, latest_d),
        "items": [
            {
                "region_code": r[0],
                "region_name": r[1],
                "avg_price": r[2],
                "prev_avg": r[3],
                "change": _change(r[2], r[3]),
                "listings": r[4],
                "complexes": r[5],
                # 실매물(중복 광고 합침) — 미백필/미집계면 0 → None 처리
                "units": (int(round(r[6])) if r[6] else None),
            }
            for r in rows
        ],
    }


@app.get("/stats/changes/movers")
def changes_movers(
    trade: str = "A1",
    sido: str | None = None,
    sigungu: str | None = None, dong: str | None = None,
    asset: str | None = None,
    days: int = 7,
    min_listings: int = 5,
    min_complex_listings: int = 50,
    limit: int = 5,
):
    """상승 / 하락 top — 단지·평형별 최신 스냅샷 vs 비교 기준일 price_avg 비교.
    days: 비교 기간(일). 기준일 = 최신일-days 이후 첫 스냅샷. 0=전체 기간.
    (전체 기간 비교는 매물 구성 변화가 누적돼 변동률이 과장될 수 있음 — 기본 7일.)
    rate 는 ±급변(오타·구성변화) 컷을 위해 -80%~+100% 로 클램프.
    min_listings: 단지×평형 매물이 양일 모두 이 값 이상 — 소표본 평균 변동 노이즈 억제.
    min_complex_listings: 최신 스냅샷에서 단지 전체 매물(전 거래유형 합)이 이 값 이상인
    단지만 — 소형/유령 단지의 노이즈를 거른다."""
    if trade not in ("A1", "B1", "B2"):
        raise HTTPException(400, "bad trade")
    if limit < 1 or limit > 50:
        raise HTTPException(400, "limit out of range")
    if days < 0 or days > 365:
        raise HTTPException(400, "days out of range")
    lo = _PRICE_LO.get(trade, 1_000_000)
    if sigungu:
        sido_clause = " AND substr(cx.cortar_no,1,5)=substr(?,1,5)"
    elif sido:
        sido_clause = " AND substr(cx.cortar_no,1,2)=substr(?,1,2)"
    else:
        sido_clause = ""
    asset_clause = _asset_type_clause(asset)  # cx LEFT JOIN 됨

    # 비교 기준일: days=0 이면 전체 기간(단, 부분수집일 5/18 제외), 아니면 최신-days 이후 첫 스냅샷
    if days == 0:
        lo_expr = "(SELECT MIN(snapshot_date) FROM complex_daily_agg WHERE snapshot_date > '2026-05-18')"
    else:
        lo_expr = ("(SELECT MIN(snapshot_date) FROM complex_daily_agg "
                   f"WHERE snapshot_date >= date((SELECT MAX(snapshot_date) FROM complex_daily_agg), '-{int(days)} days') "
                   "AND snapshot_date > '2026-05-18')")

    def _sql(direction: str) -> str:
        return f"""
            WITH d AS (
              SELECT {lo_expr} lo, MAX(snapshot_date) hi FROM complex_daily_agg
            ),
            ct AS (
              SELECT complex_no, SUM(listing_count) AS total
              FROM complex_daily_agg
              WHERE snapshot_date = (SELECT hi FROM d)
              GROUP BY complex_no
            )
            SELECT a.complex_no, cx.complex_name, a.area_name,
                   TRIM(COALESCE(rs.cortar_name,'')||' '||COALESCE(r.cortar_name,'')) AS region_name,
                   p.price_avg AS old_p, a.price_avg AS new_p,
                   (a.price_avg-p.price_avg)*1.0/p.price_avg AS rate,
                   a.listing_count, ct.total
            FROM complex_daily_agg a
            JOIN d ON a.snapshot_date=d.hi
            JOIN complex_daily_agg p ON p.complex_no=a.complex_no
                 AND p.area_name=a.area_name AND p.trade_type=a.trade_type
                 AND p.snapshot_date=d.lo
            JOIN ct ON ct.complex_no=a.complex_no
            LEFT JOIN complexes cx ON cx.complex_no=a.complex_no
            LEFT JOIN regions rs ON rs.cortar_no=substr(cx.cortar_no,1,2)||'00000000'
            LEFT JOIN regions r ON r.cortar_no=substr(cx.cortar_no,1,5)||'00000'
            WHERE a.trade_type=? AND a.price_avg BETWEEN ? AND ?
              AND p.price_avg BETWEEN ? AND ?
              AND a.listing_count>=? AND p.listing_count>=?
              AND ct.total>=?
              AND (a.price_avg-p.price_avg)*1.0/p.price_avg BETWEEN -0.8 AND 1.0
              AND a.price_avg<>p.price_avg{sido_clause}{asset_clause}
            ORDER BY rate {direction} LIMIT ?
        """

    def _params() -> list[Any]:
        p: list[Any] = [
            trade, lo, _PRICE_HI, lo, _PRICE_HI,
            min_listings, min_listings, min_complex_listings,
        ]
        if sigungu:
            p.append(sigungu)
        elif sido:
            p.append(sido)
        p.append(limit)
        return p

    def _fmt(rows):
        return [
            {
                "complex_no": r[0],
                "complex_name": r[1],
                "area_name": r[2],
                "region_name": r[3],
                "old_avg": r[4],
                "new_avg": r[5],
                "rate": r[6],
                "listing_count": r[7],
                "complex_listings": r[8],
            }
            for r in rows
        ]

    with _open_db() as c:
        up = c.execute(_sql("DESC"), _params()).fetchall()
        down = c.execute(_sql("ASC"), _params()).fetchall()
        dts = c.execute(
            f"SELECT {lo_expr}, MAX(snapshot_date) FROM complex_daily_agg").fetchone()
    return {"trade": trade, "days": days,
            "from_date": (dts[0] if dts else None), "to_date": (dts[1] if dts else None),
            "up": _fmt(up), "down": _fmt(down)}


@app.get("/stats/changes/events")
def changes_events(trade: str = "A1", limit: int = 40):
    """최근 가격 변동 이벤트 피드 (article_events PRICE_CHANGE). 오타 정정 노이즈를
    줄이기 위해 변동률 ±50% 이내, sane price 범위만."""
    if trade not in ("A1", "B1", "B2", "all"):
        raise HTTPException(400, "bad trade")
    if limit < 1 or limit > 200:
        raise HTTPException(400, "limit out of range")
    where_trade = "" if trade == "all" else " AND e.trade_type=?"
    params: list[Any] = [1_000_000, _PRICE_HI, 1_000_000, _PRICE_HI]
    if trade != "all":
        params.append(trade)
    params.append(limit)
    sql = f"""
        SELECT e.event_date, e.complex_no, cx.complex_name, e.trade_type,
               e.old_price, e.new_price,
               TRIM(COALESCE(rs.cortar_name,'')||' '||COALESCE(r.cortar_name,'')) AS region_name,
               (e.new_price-e.old_price)*1.0/e.old_price AS rate
        FROM article_events e
        LEFT JOIN complexes cx ON cx.complex_no=e.complex_no
        LEFT JOIN regions rs ON rs.cortar_no=substr(cx.cortar_no,1,2)||'00000000'
        LEFT JOIN regions r ON r.cortar_no=substr(cx.cortar_no,1,5)||'00000'
        WHERE e.event_type='PRICE_CHANGE'
          AND e.old_price BETWEEN ? AND ? AND e.new_price BETWEEN ? AND ?
          AND (e.new_price-e.old_price)*1.0/e.old_price BETWEEN -0.5 AND 0.5
          AND e.old_price<>e.new_price{where_trade}
        ORDER BY e.event_date DESC, abs(e.new_price-e.old_price) DESC LIMIT ?
    """
    with _open_db() as c:
        rows = c.execute(sql, params).fetchall()
    return {
        "trade": trade,
        "items": [
            {
                "event_date": r[0],
                "complex_no": r[1],
                "complex_name": r[2],
                "trade_type": r[3],
                "old_price": r[4],
                "new_price": r[5],
                "region_name": r[6],
                "rate": r[7],
            }
            for r in rows
        ],
    }


