def _kr_region_from_geo(region_name: str, city: str):
    """ip-api 영어 regionName/city → 한글 지역 문자열. (서울은 구 단위까지)"""
    rn = (region_name or "").lower().replace("-do", "").replace(" province", "").strip()
    sido = _SIDO_EN.get(rn)
    if not sido:
        return None
    if sido == "서울":
        cy = (city or "").lower().replace("-gu", "").replace("-si", "").strip()
        gu = _SEOUL_GU_EN.get(cy)
        return f"서울 {gu}" if gu else "서울"
    return sido


@app.get("/ai/region")
def ai_region(request: Request):
    """접속 IP로 대략 지역(시/구)을 추정해 AI 추천질문을 지역화한다.
    - Cloudflare/프록시 뒤에서는 CF-Connecting-IP 등 헤더의 실제 IP 사용.
    - 사설/로컬 IP면 ip-api에 IP 미지정으로 호출 → 서버 공인 IP 지역(=로컬 개발자 위치) 추정.
    - geo-IP(ip-api, 무료)만 사용하고 LLM 호출 없음(비용 0)."""
    ip = None
    for h in ("cf-connecting-ip", "x-real-ip"):
        v = request.headers.get(h)
        if v:
            ip = v.strip(); break
    if not ip:
        xff = request.headers.get("x-forwarded-for")
        if xff:
            ip = xff.split(",")[0].strip()
    if not ip and request.client:
        ip = request.client.host
    private = (not ip) or ip in ("::1", "localhost") or ip.startswith(
        ("127.", "10.", "192.168.", "172.16.", "172.17.", "172.18.", "172.19.", "172.2", "172.30.", "172.31."))

    geo = {}
    try:
        import urllib.request as _u
        target = "" if private else ip
        url = (f"http://ip-api.com/json/{target}"
               "?fields=status,countryCode,regionName,city,query&lang=ko")
        with _u.urlopen(url, timeout=4) as resp:
            geo = _json.load(resp)
    except Exception:
        geo = {}

    region, examples = None, None
    if geo.get("status") == "success" and geo.get("countryCode") == "KR":
        region = _kr_region_from_geo(geo.get("regionName"), geo.get("city"))
        if region:
            examples = [
                f"{region} 급매 찾아줘",
                f"{region} 최근 신고가 단지 보여줘",
                f"{region} 요즘 거래 활발해?",
                f"{region} 직거래 취소거래 알려줘",
            ]
    return {"region": region, "examples": examples,
            "city": geo.get("city"), "region_name": geo.get("regionName")}


class AiAskBody(BaseModel):
    q: str
    history: list[dict] = []   # [{"role":"user"|"model","text":"..."}] 멀티턴 맥락


# 접속 IP → 지역 캐시(질문마다 ip-api 왕복 방지). {ip: (ts, region|None)}
_IP_REGION_CACHE: dict = {}


def _ask_user_region(request: Request) -> str | None:
    """ask용 접속 지역 추정 — /ai/region 로직 재사용 + IP별 1시간 캐시.
    실패/해외/사설IP면 None(→ AI는 전국 기본). 지역이 틀릴 수 있으므로
    프롬프트에서 '접속 위치 기준' 명시와 정정 안내를 강제한다."""
    try:
        ip = None
        for h in ("cf-connecting-ip", "x-real-ip"):
            v = request.headers.get(h)
            if v:
                ip = v.strip(); break
        if not ip:
            xff = request.headers.get("x-forwarded-for")
            if xff:
                ip = xff.split(",")[0].strip()
        if not ip and request.client:
            ip = request.client.host
        if not ip:
            return None
        hit = _IP_REGION_CACHE.get(ip)
        if hit and _time.time() - hit[0] < 3600:
            return hit[1]
        private = ip in ("::1", "localhost") or ip.startswith(
            ("127.", "10.", "192.168.", "172.16.", "172.17.", "172.18.", "172.19.", "172.2", "172.30.", "172.31."))
        import urllib.request as _u
        target = "" if private else ip
        url = (f"http://ip-api.com/json/{target}"
               "?fields=status,countryCode,regionName,city,query&lang=ko")
        with _u.urlopen(url, timeout=2) as resp:
            geo = _json.load(resp)
        region = None
        if geo.get("status") == "success" and geo.get("countryCode") == "KR":
            region = _kr_region_from_geo(geo.get("regionName"), geo.get("city"))
        if len(_IP_REGION_CACHE) > 5000:   # 무한 성장 방지
            _IP_REGION_CACHE.clear()
        _IP_REGION_CACHE[ip] = (_time.time(), region)
        return region
    except Exception:  # noqa: BLE001 — 지역 추정 실패는 조용히 전국 기본
        return None


# ─── AI 이용 제한 (비회원 개방 · 포인트 차감 없음) ────────────────────────
# 하루 50건은 '한 사람' 기준이라 방문자 식별이 먼저다. 쿠키는 koczip.com→api.koczip.com
# 이 교차 사이트라 credentials 를 켜야 하고(CORS allow_origins="*" 와 충돌) 전 엔드포인트에
# 영향이 가므로, 프런트가 localStorage 로 만든 방문자 ID 를 헤더로 보낸다.
# 그건 지우면 초기화되니 **IP 상한을 함께** 둬서 폭주를 막는다(둘 다 통과해야 함).
AI_DAILY_PER_VISITOR = 50     # 한 사람 하루 질문 수
AI_DAILY_PER_IP = 200         # 같은 IP 합계 — 통신사 NAT·사무실 공용을 감안해 넉넉히
AI_BURST_PER_MIN = 10         # 1분 연타 상한(사람이 읽고 묻는 속도를 넘는 구간)
AI_MAX_INFLIGHT = 2           # 한 사람이 동시에 돌릴 수 있는 질문 수
AI_MAX_INFLIGHT_ALL = 12      # 서버 전체 동시 처리 상한(박스 2코어 보호)

_AI_INFLIGHT: dict = {}       # {키: 진행 중 건수}
_AI_BURST: dict = {}          # {키: [최근 요청 시각…]}
_AI_LOCK = _threading.Lock()


def _ai_day() -> str:
    """한국 날짜. 리셋은 KST 자정 — 프로젝트 전역이 date('now','+9 hours') 관례다."""
    import datetime as _d
    return (_d.datetime.now(_d.timezone.utc) + _d.timedelta(hours=9)).strftime("%Y-%m-%d")


_AI_SWEPT: list = []          # 마지막으로 옛 행을 지운 날짜(하루 한 번만 돈다)


def _ai_quota_db() -> sqlite3.Connection:
    """일일 카운터는 재시작(배포)에도 살아 있어야 한다 — 메모리에 두면 배포가 곧 초기화다."""
    c = sqlite3.connect(REVIEWS_DB, timeout=5)
    c.execute("CREATE TABLE IF NOT EXISTS ai_usage("
              "scope TEXT NOT NULL, key TEXT NOT NULL, day TEXT NOT NULL, "
              "n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(scope, key, day))")
    today = _ai_day()
    if _AI_SWEPT[:1] != [today]:   # 방문자 수만큼 행이 쌓이므로 지난 것은 버린다
        _AI_SWEPT[:] = [today]
        try:
            c.execute("DELETE FROM ai_usage WHERE day < date(?, '-3 day')", (today,))
            c.commit()
        except Exception:  # noqa: BLE001 — 청소 실패가 이용을 막지는 않는다
            pass
    return c


def _ai_visitor(request: Request, user: dict | None) -> tuple[str, str]:
    """(방문자키, IP키). 로그인 사용자는 계정이 기준 — 기기를 옮겨도 같은 사람이다."""
    ip = _client_ip(request) or "-"
    if user and user.get("id"):
        return f"u:{user['id']}", f"ip:{ip}"
    vid = (request.headers.get("x-visitor-id") or "").strip()[:64]
    # 헤더가 없으면(구버전 프런트·직접 호출) IP 를 방문자로 본다
    return (f"v:{vid}" if vid else f"ip:{ip}"), f"ip:{ip}"


def _ai_quota_check(request: Request, user: dict | None) -> dict:
    """제한을 넘으면 429. 통과하면 {남은건수} 반환하고 카운터를 올린다.

    올려놓고 실패 시 되돌린다(_ai_quota_release) — 먼저 올려야 동시 요청이 새지 않는다.
    """
    vkey, ipkey = _ai_visitor(request, user)
    now = _time.time()
    with _AI_LOCK:
        # ① 서버 전체 동시 처리 — 이게 뚫리면 박스가 통째로 느려진다
        if sum(_AI_INFLIGHT.values()) >= AI_MAX_INFLIGHT_ALL:
            raise HTTPException(429, detail={
                "code": "ai_busy",
                "message": "지금 AI 이용이 몰리고 있어요. 잠시 후 다시 시도해 주세요."})
        # ② 개인 동시 처리
        if _AI_INFLIGHT.get(vkey, 0) >= AI_MAX_INFLIGHT:
            raise HTTPException(429, detail={
                "code": "ai_inflight",
                "message": "앞의 질문에 답하는 중이에요. 잠시만 기다려 주세요."})
        # ③ 1분 연타
        hits = [t for t in _AI_BURST.get(vkey, []) if now - t < 60]
        if len(hits) >= AI_BURST_PER_MIN:
            raise HTTPException(429, detail={
                "code": "ai_too_fast", "retry_after": 60,
                "message": "질문이 너무 빨라요. 1분 뒤에 다시 시도해 주세요."})
        hits.append(now)
        _AI_BURST[vkey] = hits
        if len(_AI_BURST) > 20000:      # 무한 성장 방지 — 오래된 것부터 버린다
            _AI_BURST.clear()
        # ★ 검사와 증가는 같은 락 안에서 끝내야 한다. 나눠 두면 동시에 들어온 요청이
        #   전부 검사를 통과한 뒤 다 같이 증가해 동시 상한이 통째로 무력화된다.
        _AI_INFLIGHT[vkey] = _AI_INFLIGHT.get(vkey, 0) + 1

    day = _ai_day()
    try:
        return _ai_quota_day(vkey, ipkey, day)
    except Exception:
        with _AI_LOCK:                  # 일일 상한에 걸렸으면 방금 올린 동시 카운터를 내린다
            n = _AI_INFLIGHT.get(vkey, 0) - 1
            _AI_INFLIGHT[vkey] = n if n > 0 else 0
            if not _AI_INFLIGHT.get(vkey):
                _AI_INFLIGHT.pop(vkey, None)
        raise


def _ai_quota_day(vkey: str, ipkey: str, day: str) -> dict:
    """일일 카운터 확인 후 1 증가. 상한이면 429."""
    with _ai_quota_db() as c:
        rows = dict(c.execute(
            "SELECT scope||':'||key, n FROM ai_usage WHERE day=? AND "
            "((scope='v' AND key=?) OR (scope='i' AND key=?))",
            (day, vkey, ipkey)).fetchall())
        used_v = rows.get(f"v:{vkey}", 0)
        used_ip = rows.get(f"i:{ipkey}", 0)
        if used_v >= AI_DAILY_PER_VISITOR:
            raise HTTPException(429, detail={
                "code": "ai_daily_limit", "limit": AI_DAILY_PER_VISITOR, "used": used_v,
                "message": f"오늘 AI 질문 {AI_DAILY_PER_VISITOR}건을 모두 쓰셨어요. "
                           "내일 0시에 다시 채워집니다."})
        if used_ip >= AI_DAILY_PER_IP:
            raise HTTPException(429, detail={
                "code": "ai_ip_limit", "limit": AI_DAILY_PER_IP,
                "message": "같은 네트워크에서 오늘 질문이 너무 많았어요. 내일 다시 이용해 주세요."})
        for scope, key in (("v", vkey), ("i", ipkey)):
            c.execute("INSERT INTO ai_usage(scope,key,day,n) VALUES(?,?,?,1) "
                      "ON CONFLICT(scope,key,day) DO UPDATE SET n=n+1", (scope, key, day))
        c.commit()
    return {"key": vkey, "ip_key": ipkey, "remaining": AI_DAILY_PER_VISITOR - used_v - 1}


def _ai_quota_release(st: dict | None, *, refund: bool = False) -> None:
    """진행 중 카운터를 내린다. refund=True 면 실패한 질문이라 일일 사용분도 돌려준다."""
    if not st:
        return
    with _AI_LOCK:
        n = _AI_INFLIGHT.get(st["key"], 0) - 1
        if n > 0:
            _AI_INFLIGHT[st["key"]] = n
        else:
            _AI_INFLIGHT.pop(st["key"], None)
    if not refund:
        return
    try:
        day = _ai_day()
        with _ai_quota_db() as c:
            for scope, key in (("v", st["key"]), ("i", st["ip_key"])):
                c.execute("UPDATE ai_usage SET n=MAX(0,n-1) WHERE scope=? AND key=? AND day=?",
                          (scope, key, day))
            c.commit()
    except Exception:  # noqa: BLE001 — 환불 실패로 답변까지 막지는 않는다
        pass


@app.get("/ai/quota")
def ai_quota(request: Request, user: dict | None = Depends(current_user_optional)):
    """오늘 남은 AI 질문 수. 카운터를 올리지 않는 조회 전용(화면 표시용)."""
    vkey, _ = _ai_visitor(request, user)
    with _ai_quota_db() as c:
        row = c.execute("SELECT n FROM ai_usage WHERE scope='v' AND key=? AND day=?",
                        (vkey, _ai_day())).fetchone()
    used = (row[0] if row else 0)
    return {"limit": AI_DAILY_PER_VISITOR, "used": used,
            "remaining": max(0, AI_DAILY_PER_VISITOR - used), "login": bool(user)}


def _log_ai(user: dict | None, question: str, *, answer=None, tools=None, usage=None,
            status: int = 200, error=None, duration_ms=None, request=None) -> None:
    """AI 질문-답변을 상세 로그로 남긴다(질문/답변/사용도구/토큰/소요시간).
    비회원도 질문할 수 있으므로 user 는 None 일 수 있다 — 그때는 IP·UA 만 남는다."""
    user = user or {}
    detail: dict = {"question": question}
    if answer is not None:
        detail["answer"] = answer[:8000]
    if tools is not None:
        detail["tools"] = tools
    if usage is not None:
        detail["usage"] = usage
    if error is not None:
        detail["error"] = str(error)[:500]
    _log_event(
        "ai_ask", user_id=user.get("id"), email=user.get("email"),
        provider=user.get("provider"), member_no=_member_no(user.get("id")),
        path="/ai/ask", method="POST", status=status, duration_ms=duration_ms,
        ip=(_client_ip(request) if request else None),
        user_agent=(request.headers.get("user-agent") if request else None),
        detail=detail)


@app.post("/ai/ask")
def ai_ask_post(body: AiAskBody, request: Request,
                user: dict | None = Depends(current_user_optional)):
    """부동산 AI 질의(멀티턴). history 로 이전 대화를 넘기면 '거기서 30평대만' 같은 후속 질문 가능.
    로그인 없이도 쓸 수 있고 포인트도 들지 않는다 — 대신 한 사람 하루 50건."""
    q = (body.q or "").strip()
    if not q:
        raise HTTPException(400, "질문(q)이 비어있습니다")
    if len(q) > 500:
        raise HTTPException(400, "질문이 너무 깁니다 (최대 500자)")
    quota = _ai_quota_check(request, user)
    nick = None
    if user and user.get("id"):
        with _reviews_db() as c:
            nick = _nickname(c, user["id"])
    t0 = _time.perf_counter()
    try:
        from scripts.ai_agent import run_agent
        res = run_agent(q, history=body.history, nickname=nick,
                        user_region=_ask_user_region(request))
        _log_ai(user, q, answer=(res or {}).get("answer"),
                tools=(res or {}).get("tools_used") or (res or {}).get("tools"),
                usage=(res or {}).get("usage"),
                duration_ms=int((_time.perf_counter() - t0) * 1000), request=request)
        _ai_quota_release(quota)
        return {**(res or {}), "remaining": quota["remaining"]}
    except Exception as e:
        _log_ai(user, q, status=500, error=e,
                duration_ms=int((_time.perf_counter() - t0) * 1000), request=request)
        # 답을 못 줬으면 오늘 사용분에서 빼 준다 — 서버 잘못으로 50건이 깎이면 안 된다
        _ai_quota_release(quota, refund=True)
        msg = str(e)
        transient = "503" in msg or "UNAVAILABLE" in msg or "overloaded" in msg or "429" in msg or "RESOURCE_EXHAUSTED" in msg
        if transient:   # 일시 과부하 → 친절 안내(200)
            return {"answer": "지금 AI 이용이 잠시 몰려서 답변을 못 드렸어요. 잠시 후 다시 시도해 주세요.",
                    "tools_used": [], "usage": {}, "model": "", "retry": True}
        raise HTTPException(500, f"AI 처리 실패: {e}")


@app.post("/ai/ask-stream")
def ai_ask_stream(body: AiAskBody, request: Request,
                  user: dict | None = Depends(current_user_optional)):
    """부동산 AI 질의(SSE 스트리밍). 진행 단계를 실시간 전송:
    질문분석중 → (도구별)조회중 → 데이터정리중 → 답변작성중 → done(최종답변).
    로그인 없이도 쓸 수 있고 포인트도 들지 않는다 — 대신 한 사람 하루 50건."""
    from fastapi.responses import StreamingResponse
    q = (body.q or "").strip()
    if not q:
        raise HTTPException(400, "질문(q)이 비어있습니다")
    if len(q) > 500:
        raise HTTPException(400, "질문이 너무 깁니다 (최대 500자)")
    # 쿼터는 스트리밍 시작 전에 잡는다 — 본문이 흐르기 시작하면 429 를 줄 수 없다
    quota = _ai_quota_check(request, user)
    nick = None
    if user and user.get("id"):
        with _reviews_db() as c:
            nick = _nickname(c, user["id"])

    def gen():
        t0 = _time.perf_counter()
        fin = {"answer": None, "tools": None, "usage": None}
        err = None
        try:
            from scripts.ai_agent import run_agent_stream
            for ev in run_agent_stream(q, history=body.history, nickname=nick,
                                       user_region=_ask_user_region(request)):
                if ev.get("type") == "done":
                    fin["answer"] = ev.get("answer")
                    fin["tools"] = ev.get("tools_used")
                    fin["usage"] = ev.get("usage")
                    ev["remaining"] = quota["remaining"]   # 남은 질문 수 → 프런트 표시
                elif ev.get("type") == "error":
                    err = ev.get("error")
                yield f"data: {_json.dumps(ev, ensure_ascii=False)}\n\n"
        except Exception as e:
            err = str(e)
            transient = any(x in err for x in ("503", "UNAVAILABLE", "overloaded", "429", "RESOURCE_EXHAUSTED"))
            emsg = ("지금 AI 이용이 잠시 몰려서 답변을 못 드렸어요. 잠시 후 다시 시도해 주세요."
                    if transient else "AI 처리 중 오류가 발생했어요. 잠시 후 다시 시도해 주세요.")
            yield f"data: {_json.dumps({'type': 'error', 'error': emsg, 'retry': transient}, ensure_ascii=False)}\n\n"
        finally:
            _ai_quota_release(quota, refund=bool(err))
            _log_ai(user, q, answer=fin["answer"], tools=fin["tools"], usage=fin["usage"],
                    status=(500 if err else 200), error=err,
                    duration_ms=int((_time.perf_counter() - t0) * 1000), request=request)

    return StreamingResponse(gen(), media_type="text/event-stream",
                             headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


@app.get("/ai/history")
def ai_history(request: Request, user: dict = Depends(current_user), limit: int = 30):
    """로그인 사용자의 과거 AI 질문-답변 이력(최신순으로 가져와 오래된→최신으로 반환).
    event_log(ai_ask)를 재사용 — 재로그인·다른 기기에서도 과거 답변을 복원한다."""
    if limit < 1 or limit > 100:
        limit = 30
    uid = user.get("id")
    if not uid:
        return {"items": []}
    items: list[dict] = []
    try:
        with _logs_db() as c:
            rows = c.execute(
                "SELECT detail FROM event_log WHERE kind='ai_ask' AND user_id=? "
                "AND status=200 ORDER BY id DESC LIMIT ?",
                (uid, limit),
            ).fetchall()
        for r in rows:
            try:
                j = _json.loads(r[0] or "{}")
            except Exception:  # noqa: BLE001
                continue
            ans = j.get("answer")
            q = j.get("question")
            if not ans or not q:
                continue   # 답이 없는(실패) 기록은 제외
            items.append({"q": q, "answer": ans, "tools": j.get("tools"), "usage": j.get("usage")})
        items.reverse()   # 오래된 → 최신(화면 표시 순서)
    except sqlite3.Error:
        return {"items": []}
    return {"items": items}


# ===========================================================================
# 관리자: naver 중개사 ↔ vworld 등록정보 수작업 매칭
# ===========================================================================
_VW_SEL = ("sys_regno, business_name, representative, address, status, "
           "registered_ymd, phone, sgg_cd")


def _vw_row(r):
    return {"sys_regno": r[0], "business_name": r[1], "representative": r[2],
            "address": r[3], "status": r[4], "registered_ymd": r[5],
            "phone": r[6], "sgg_cd": r[7]}


def _name_core(name: str) -> str:
    s = name or ""
    for w in ("공인중개사사무소", "공인중개사무소", "공인중개사", "중개사사무소", "부동산중개", "부동산", "중개사무소"):
        s = s.replace(w, "")
    return s.strip()


@app.get("/admin/realtor-match/unmatched")
def admin_match_unmatched(_admin: dict = Depends(admin_user), limit: int = 300):
    """vworld 미매칭 중개사 큐 (수작업 매칭용). match_type='none' 인 naver 중개사, 매물수 많은 순. 관리자 전용."""
    if limit < 1 or limit > 2000:
        raise HTTPException(400, "limit out of range")
    with _open_db() as c:
        rows = c.execute(
            """
            SELECT m.realtor_id, m.naver_name, m.primary_sgg_cd, m.total_listings,
                   n.address, n.representative_name, n.establish_registration_no,
                   COALESCE(n.representative_tel_no, n.cell_phone_no)
            FROM realtor_match m
            LEFT JOIN naver_realtors n ON n.realtor_id = m.realtor_id
            WHERE m.match_type = 'none'
            ORDER BY m.total_listings DESC
            LIMIT ?
            """, (limit,)).fetchall()
    items = [{
        "realtor_id": r[0], "naver_name": r[1], "sgg_cd": r[2],
        "sido": SIDO_NAMES.get((r[2] or "")[:2]),
        "total_listings": r[3], "address": r[4], "rep": r[5],
        "regno": (r[6] or "").strip() or None, "tel": r[7],
    } for r in rows]
    return {"count": len(items), "items": items}


@app.get("/admin/realtor-match/candidates")
def admin_match_candidates(realtor_id: str, _admin: dict = Depends(admin_user)):
    """해당 naver 중개사의 vworld 후보 자동 제안 (등록번호 / 지역+이름 / 지역+대표). 관리자 전용."""
    with _open_db() as c:
        nr = c.execute(
            "SELECT realtor_name, representative_name, establish_registration_no, cortar_no "
            "FROM naver_realtors WHERE realtor_id=?", (realtor_id,)).fetchone()
        mr = c.execute("SELECT naver_name, primary_sgg_cd FROM realtor_match WHERE realtor_id=?",
                       (realtor_id,)).fetchone()
        if not mr:
            raise HTTPException(404, "realtor not found")
        name = (nr[0] if nr else None) or mr[0] or ""
        rep = nr[1] if nr else None
        regno = (nr[2] or "").strip() if nr else ""
        sgg = mr[1] or ((nr[3] or "")[:5] if nr else "")
        cands: dict[str, dict] = {}

        def add(rs, reason):
            for r in rs:
                d = cands.setdefault(r[0], {**_vw_row(r), "reasons": []})
                if reason not in d["reasons"]:
                    d["reasons"].append(reason)

        if regno:
            add(c.execute(f"SELECT {_VW_SEL} FROM vworld_brokers WHERE ra_regno=? LIMIT 10", (regno,)), "등록번호")
        core = _name_core(name)[:6]
        if sgg and core:
            add(c.execute(f"SELECT {_VW_SEL} FROM vworld_brokers WHERE sgg_cd=? AND business_name LIKE ? LIMIT 25",
                          (sgg, "%" + core + "%")), "지역+이름")
        if sgg and rep:
            add(c.execute(f"SELECT {_VW_SEL} FROM vworld_brokers WHERE sgg_cd=? AND representative=? LIMIT 25",
                          (sgg, rep)), "지역+대표")
    return {"realtor_id": realtor_id,
            "naver": {"name": name, "rep": rep, "regno": regno or None, "sgg_cd": sgg},
            "count": len(cands), "candidates": list(cands.values())}


@app.get("/admin/vworld/search")
def admin_vworld_search(q: str = "", sgg: str = "", limit: int = 30,
                        _admin: dict = Depends(admin_user)):
    """vworld 중개사 자유 검색 (이름/대표/주소 부분일치 + 선택적 시군구). 관리자 전용."""
    q = q.strip()
    if len(q) < 2 and not sgg:
        return {"items": []}
    where, params = [], []
    if q:
        where.append("(business_name LIKE ? OR representative LIKE ? OR address LIKE ?)")
        params += ["%" + q + "%"] * 3
    if sgg:
        where.append("sgg_cd = ?"); params.append(sgg)
    params.append(min(max(limit, 1), 100))
    with _open_db() as c:
        rows = c.execute(
            f"SELECT {_VW_SEL} FROM vworld_brokers WHERE {' AND '.join(where)} LIMIT ?",
            params).fetchall()
    return {"items": [_vw_row(r) for r in rows]}


class MatchBody(BaseModel):
    sys_regno: str | None = None   # None/빈값이면 '매칭 없음'으로 확정


@app.post("/admin/realtor-match/{realtor_id}")
def admin_apply_match(realtor_id: str, body: MatchBody, _admin: dict = Depends(admin_user)):
    """수작업 매칭 적용. sys_regno 주면 그 vworld 사무소로 연결(match_type='manual'),
    없으면 '매칭 없음 확정'(match_type='manual_none')으로 큐에서 제외."""
    with _open_db() as c:
        if not c.execute("SELECT 1 FROM realtor_match WHERE realtor_id=?", (realtor_id,)).fetchone():
            raise HTTPException(404, "realtor not found")
        sr = (body.sys_regno or "").strip()
        if sr:
            v = c.execute("SELECT business_name, representative, status FROM vworld_brokers WHERE sys_regno=?",
                          (sr,)).fetchone()
            if not v:
                raise HTTPException(400, "sys_regno not found in vworld")
            c.execute(
                "UPDATE realtor_match SET sys_regno=?, vworld_name=?, vworld_rep=?, vworld_status=?, "
                "match_type='manual', matched_at=datetime('now') WHERE realtor_id=?",
                (sr, v[0], v[1], v[2], realtor_id))
            c.commit()
            return {"ok": True, "realtor_id": realtor_id, "sys_regno": sr, "vworld_name": v[0]}
        c.execute("UPDATE realtor_match SET match_type='manual_none', matched_at=datetime('now') "
                  "WHERE realtor_id=?", (realtor_id,))
        c.commit()
        return {"ok": True, "realtor_id": realtor_id, "sys_regno": None}


@app.get("/admin/users")
def admin_users(_admin: dict = Depends(admin_user), page: int = 1, per_page: int = 200):
    """가입 사용자 목록 (Supabase Admin API). SUPABASE_SECRET_KEY(service_role) 필요. 관리자 전용."""
    if not settings.supabase_url or not settings.supabase_secret_key:
        raise HTTPException(503, "SUPABASE_SECRET_KEY 미설정 — 사용자 목록 조회 불가")
    per_page = min(max(int(per_page), 1), 1000)
    url = (f"{settings.supabase_url}/auth/v1/admin/users"
           f"?page={int(page)}&per_page={per_page}")
    req = _urlreq.Request(url, headers={
        "apikey": settings.supabase_secret_key,
        "Authorization": f"Bearer {settings.supabase_secret_key}",
    })
    try:
        with _urlreq.urlopen(req, timeout=10) as resp:
            data = _authjson.loads(resp.read().decode("utf-8"))
    except _urlerr.HTTPError as e:
        raise HTTPException(502, f"Supabase Admin API 오류({e.code}) — service_role 키 확인")
    except _urlerr.URLError:
        raise HTTPException(502, "Supabase에 연결할 수 없습니다")
    # 자체 인증한 휴대폰 번호·회원번호(user_profiles)를 병합 — Supabase 메타데이터보다 우선.
    # + 중개사 홈페이지 개설자(realtor_homepages)의 slug·공개여부를 함께 노출.
    with _reviews_db() as c:
        prof = {r[0]: (r[1], r[2]) for r in c.execute(
            "SELECT user_id, phone, member_no FROM user_profiles WHERE phone_verified=1").fetchall()}
        hp = {r[0]: (r[1], r[2], r[3]) for r in c.execute(
            "SELECT user_id, slug, published, realtor_id FROM realtor_homepages "
            "WHERE user_id IS NOT NULL AND slug IS NOT NULL").fetchall()}
        # 연결된 중개사무소(라운지 멤버) — 역할·상태 포함
        mem = {r[0]: (r[1], r[2], r[3]) for r in c.execute(
            "SELECT user_id, realtor_id, role, status FROM realtor_members").fetchall()}
    # 사무소 이름 배치 조회(메인 DB)
    office_names: dict = {}
    rids = {v[0] for v in mem.values()}
    if rids:
        with _open_db() as dc:
            qm = ",".join("?" * len(rids))
            office_names = {r[0]: r[1] for r in dc.execute(
                f"SELECT realtor_id, realtor_name FROM naver_realtors WHERE realtor_id IN ({qm})",
                list(rids)).fetchall()}
    out = []
    for u in data.get("users", []):
        m = u.get("user_metadata") or {}
        am = u.get("app_metadata") or {}
        uid = u.get("id")
        vphone, member_no = prof.get(uid, (None, None))
        hp_slug, hp_pub, hp_rid = hp.get(uid, (None, None, None))
        out.append({
            "id": uid,
            "member_no": member_no,
            "email": u.get("email"),
            "phone": vphone or u.get("phone") or m.get("phone_number"),
            "phone_verified": bool(vphone),
            "name": m.get("name") or m.get("nickname") or m.get("full_name"),
            "avatar": m.get("avatar_url") or m.get("picture"),
            "provider": am.get("provider"),
            "created_at": u.get("created_at"),
            "last_sign_in_at": u.get("last_sign_in_at"),
            "homepage_slug": hp_slug,
            "homepage_published": bool(hp_pub),
            "homepage_realtor_id": hp_rid,
            "realtor_id": mem.get(uid, (None,))[0],
            "realtor_name": office_names.get(mem.get(uid, (None,))[0]),
            "realtor_role": mem.get(uid, (None, None))[1] if uid in mem else None,
            "realtor_status": mem.get(uid, (None, None, None))[2] if uid in mem else None,
        })
    return {"count": len(out), "users": out}


# ===========================================================================
# 관리자: 직원 업무관리 워크플로우 (직원 · 할일/진행중/완료 · 비용지출)
# ===========================================================================
_OPS_SCHEMA = """
CREATE TABLE IF NOT EXISTS ops_staff(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, title TEXT,
  created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS ops_tasks(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, detail TEXT,
  assignee_id INTEGER, status TEXT DEFAULT 'todo', due_date TEXT,
  created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS ops_expenses(id INTEGER PRIMARY KEY AUTOINCREMENT, item TEXT, amount INTEGER,
  spender_id INTEGER, memo TEXT, spent_at TEXT, kind TEXT DEFAULT 'adhoc', category TEXT,
  created_at TEXT DEFAULT (datetime('now')));
"""


def _ensure_ops(c):
    c.executescript(_OPS_SCHEMA)
    # 기존 테이블에 신규 컬럼 보강(있으면 무시)
    for ddl in ("ALTER TABLE ops_expenses ADD COLUMN kind TEXT DEFAULT 'adhoc'",
                "ALTER TABLE ops_expenses ADD COLUMN category TEXT",
                "ALTER TABLE ops_tasks ADD COLUMN due_date TEXT"):
        try:
            c.execute(ddl)
        except Exception:
            pass


class OpsStaffBody(BaseModel):
    name: str
    title: str = ""


class OpsTaskBody(BaseModel):
    title: str
    detail: str = ""
    assignee_id: int | None = None
    status: str = "todo"
    due_date: str = ""


class OpsTaskPatch(BaseModel):
    title: str | None = None
    detail: str | None = None
    assignee_id: int | None = None
    status: str | None = None
    due_date: str | None = None


class OpsExpenseBody(BaseModel):
    item: str
    amount: int = 0
    spender_id: int | None = None
    memo: str = ""
    spent_at: str = ""
    kind: str = "adhoc"          # adhoc(수시) | fixed(월고정)
    category: str = ""           # 적요: 서버비용/홍보비/세금/기타


