# 관리자: 활동 로그 조회 (로그인/조회/AI질문 — 개선 분석용)
# ===========================================================================
def _member_map(user_ids) -> dict:
    """user_id 목록 → {user_id: (member_no, phone)} (reviews.sqlite)."""
    ids = [u for u in {*user_ids} if u]
    if not ids:
        return {}
    try:
        with _reviews_db() as c:
            ph = ",".join("?" * len(ids))
            return {r[0]: (r[1], r[2]) for r in c.execute(
                f"SELECT user_id, member_no, phone FROM user_profiles WHERE user_id IN ({ph})", ids)}
    except Exception:  # noqa: BLE001
        return {}


# ===========================================================================
# 관리자: KPI 목표 추적 (방문자·가입자·홈페이지 / 1·2·3차 목표)
# ===========================================================================
_KPI_DEFAULTS = [
    ("visitors", 1, 1000, "2026-12-31"), ("visitors", 2, 2000, "2027-06-30"), ("visitors", 3, 3000, "2027-12-31"),
    ("signups", 1, 1000, "2026-12-31"), ("signups", 2, 1500, "2027-06-30"), ("signups", 3, 2000, "2027-12-31"),
    ("homepages", 1, 100, "2026-12-31"), ("homepages", 2, 200, "2027-06-30"), ("homepages", 3, 300, "2027-12-31"),
]
_KPI_META = {
    "visitors": ("월평균 일간 순수방문자", "명"),
    "signups": ("누적 가입자", "명"),
    "homepages": ("중개사 홈페이지", "개"),
}


def _ensure_kpi(c):
    c.execute("CREATE TABLE IF NOT EXISTS kpi_targets("
              "metric TEXT, tier INTEGER, target INTEGER, deadline TEXT, PRIMARY KEY(metric,tier))")
    for m, t, tg, dl in _KPI_DEFAULTS:
        c.execute("INSERT OR IGNORE INTO kpi_targets(metric,tier,target,deadline) VALUES(?,?,?,?)", (m, t, tg, dl))
    c.commit()


@app.get("/admin/kpi")
def admin_kpi(_admin: dict = Depends(admin_user)):
    """KPI 현황 — 방문자(이달 월평균 일간 순방문)·가입자(누적)·홈페이지(개) vs 1·2·3차 목표."""
    with _logs_db() as lc:
        vis = lc.execute(
            "SELECT AVG(daily) FROM (SELECT date(ts,'+9 hours') d, COUNT(DISTINCT ip) daily "
            "FROM event_log WHERE date(ts,'+9 hours') >= date('now','+9 hours','start of month') GROUP BY d)"
        ).fetchone()[0]
    with _reviews_db() as rc:
        _ensure_kpi(rc)
        signups = rc.execute("SELECT COUNT(*) FROM user_profiles").fetchone()[0]
        homepages = rc.execute("SELECT COUNT(*) FROM realtor_homepages WHERE slug IS NOT NULL").fetchone()[0]
        trows = rc.execute("SELECT metric,tier,target,deadline FROM kpi_targets ORDER BY metric,tier").fetchall()
    cur = {"visitors": round(vis or 0), "signups": signups, "homepages": homepages}
    tmap: dict = {}
    for m, t, tg, dl in trows:
        tmap.setdefault(m, []).append({"tier": t, "target": tg, "deadline": dl})
    metrics = []
    for key in ("visitors", "signups", "homepages"):
        label, unit = _KPI_META[key]
        metrics.append({"key": key, "label": label, "unit": unit,
                        "current": cur[key], "tiers": tmap.get(key, [])})
    return {"metrics": metrics}


class KpiTargetBody(BaseModel):
    metric: str
    tier: int
    target: int
    deadline: str = ""


@app.post("/admin/kpi/target")
def admin_kpi_target(body: KpiTargetBody, _admin: dict = Depends(admin_user)):
    """KPI 목표값·기한 수정."""
    if body.metric not in _KPI_META or body.tier not in (1, 2, 3):
        raise HTTPException(400, "잘못된 지표/단계")
    with _reviews_db() as c:
        _ensure_kpi(c)
        c.execute("UPDATE kpi_targets SET target=?, deadline=? WHERE metric=? AND tier=?",
                  (int(body.target), body.deadline.strip(), body.metric, body.tier))
        c.commit()
    return {"ok": True}


# 프런트 라우트(정규화된 페이지 키) → 직관적 페이지명. 페이지뷰 분석·대시보드 공용.
# 더 구체적인 경로를 앞에 둔다(startswith 매칭). 신규 페이지는 여기만 추가하면 분석에 잡힘.
_PAGE_RULES = [
    ("/today/find", "TODAY·오늘의급매"), ("/today", "TODAY·우리동네"),
    ("/finder", "맞춤단지 찾기"), ("/similar", "유사단지"),
    ("/quick-deals", "급매찾기"), ("/quick", "급매찾기"),
    ("/buy-calculator", "아파트매수계산기"), ("/admin/buywizard", "아파트매수계산기(관리자)"),
    ("/jeonse-check", "깡통전세지수"),
    ("/changes/counts", "지역별 매물수"), ("/changes", "매물 호가"),
    ("/tx-stats", "실거래 통계"),
    ("/realtors", "중개사무소 랭킹"), ("/realtor/", "중개사 상세"),
    ("/nonresi/villa", "빌라·연립 통계"), ("/nonresi/sangga", "상가 통계"),
    ("/nonresi/office", "사무실 통계"), ("/nonresi/house", "단독·다가구 통계"),
    ("/nonresi", "비단지 통계"),
    ("/complex/", "단지 상세"), ("/complex", "단지 상세"),
    ("/deal-map", "실거래 지도"), ("/map", "지도"),
    ("/cancelled", "취소거래"), ("/suspicious", "이상매물"),
    ("/forum", "토론장"), ("/lounge", "중개사 라운지"),
    ("/my/favorites", "관심단지"), ("/ai", "AI 분석"), ("/overview", "전국현황"),
    ("/biz", "중개사앱"), ("/r/", "중개사 홈페이지"),
    ("/terms", "약관"), ("/privacy", "개인정보"), ("/delete-account", "회원탈퇴"),
    ("/me", "내 정보"), ("/account", "내 정보"),
    ("/admin/logs", "관리자·로그"), ("/admin/today", "관리자·오늘통계"),
    ("/admin/users", "관리자·회원"), ("/admin/kpi", "관리자·KPI"),
    ("/admin", "관리자"),
]


def _page_label(path: str | None) -> str:
    """경로 → 직관적 페이지명. 관리자 대시보드·페이지분석 표시용."""
    if not path:
        return "기타"
    p = path.split("?")[0]
    if p in ("/", ""):
        return "홈"
    for pre, lbl in _PAGE_RULES:
        if p.startswith(pre):
            return lbl
    return p


@app.get("/admin/trends")
def admin_trends(_admin: dict = Depends(admin_user), days: int = 30):
    """일별 추이 — 순방문자(distinct IP)·페이지뷰·신규가입. 최근 days일(KST)."""
    days = min(max(int(days), 7), 120)
    win = f"-{days} days"
    with _logs_db() as c:
        rows = c.execute(
            "SELECT date(ts,'+9 hours') d, COUNT(DISTINCT ip) vis, "
            "SUM(CASE WHEN kind IN ('view','view_complex','view_realtor') THEN 1 ELSE 0 END) pv "
            f"FROM event_log WHERE date(ts,'+9 hours') >= date('now','+9 hours', ?) AND {_HUMAN_SQL} GROUP BY d",
            (win,)).fetchall()
        # 90일 지난 행은 IP가 비식별화(NULL)돼 라이브 DISTINCT가 0이 됨 — 굳힌 실사람 집계로 보충.
        # (log_anonymize.py가 비식별화 전에 daily_stats.human_visitors에 적재. 미비식별 날짜는 라이브=집계라 max로 안전)
        try:
            agg_vis = dict(c.execute(
                "SELECT d, COALESCE(human_visitors, visitors) FROM daily_stats "
                "WHERE d >= date('now','+9 hours', ?)", (win,)))
        except sqlite3.OperationalError:
            agg_vis = {}
    daily = {r[0]: {"date": r[0], "visitors": (r[1] if r[1] else agg_vis.get(r[0], 0)),
                    "pageviews": r[2] or 0, "signups": 0} for r in rows}
    with _reviews_db() as rc:
        for d, n in rc.execute(
            "SELECT date(agreed_terms_at,'+9 hours') d, COUNT(*) FROM user_profiles "
            "WHERE agreed_terms_at IS NOT NULL AND date(agreed_terms_at,'+9 hours') >= date('now','+9 hours', ?) "
            "GROUP BY d", (win,)):
            daily.setdefault(d, {"date": d, "visitors": 0, "pageviews": 0, "signups": 0})["signups"] = n
    return {"days": sorted(daily.values(), key=lambda x: x["date"])}


@app.get("/admin/top-pages")
def admin_top_pages(_admin: dict = Depends(admin_user), days: int = 7, limit: int = 15):
    """페이지별 조회 — 직관적 이름으로 묶어 집계. 최근 days일."""
    days = min(max(int(days), 1), 90)
    with _logs_db() as c:
        rows = c.execute(
            "SELECT path, COUNT(*) n, COUNT(DISTINCT ip) v FROM event_log "
            "WHERE kind IN ('view','view_complex','view_realtor') AND path LIKE '/%' "
            "AND date(ts,'+9 hours') >= date('now','+9 hours', ?) GROUP BY path",
            (f"-{days} days",)).fetchall()
        # 비식별화 구간(90일 초과 날짜)의 방문자는 굳힌 집계에서 보충 — 라이브는 그 구간 v=0이라 중복 없음
        try:
            agg_pages = c.execute(
                "SELECT label, SUM(visitors) FROM daily_page_stats "
                "WHERE d >= date('now','+9 hours', ?) AND d < date('now','+9 hours','-90 days') "
                "GROUP BY label", (f"-{days} days",)).fetchall()
        except sqlite3.OperationalError:
            agg_pages = []
    agg: dict = {}
    for p, n, v in rows:
        lbl = _page_label(p)
        if lbl == p:        # 알려진 페이지명에 매칭 안 됨(=API·봇 경로) → 제외
            continue
        a = agg.setdefault(lbl, {"label": lbl, "views": 0, "visitors": 0})
        a["views"] += n; a["visitors"] += v
    for lbl, v in agg_pages:
        if lbl in agg:
            agg[lbl]["visitors"] += v or 0
    out = sorted(agg.values(), key=lambda x: -x["views"])[:limit]
    return {"days": days, "pages": out}


# 실사람 방문자 필터 — 봇/자동화/내부도구 제외(접속자 통계용).
# ① 우리 봇가드가 태그한 봇(detail.bot=goodbot:*/softbot) ② UA 패턴(검색봇·스크립트·헤드리스)
# ③ 빈 UA·내부도구(curl warm·testclient). 브라우저 UA 사칭 분산봇은 UA로는 못 거름(behavior 별도).
_HUMAN_SQL = (
    "json_extract(detail,'$.bot') IS NULL "
    "AND user_agent IS NOT NULL AND user_agent<>'' AND user_agent<>'testclient' "
    "AND user_agent NOT LIKE '%bot%' AND user_agent NOT LIKE '%Bot%' "
    "AND user_agent NOT LIKE '%spider%' AND user_agent NOT LIKE '%Spider%' "
    "AND user_agent NOT LIKE '%crawl%' AND user_agent NOT LIKE '%Crawl%' "
    "AND user_agent NOT LIKE '%slurp%' AND user_agent NOT LIKE '%Yeti%' "
    "AND user_agent NOT LIKE 'curl/%' AND user_agent NOT LIKE 'Wget%' "
    "AND user_agent NOT LIKE '%python-requests%' AND user_agent NOT LIKE '%python-urllib%' "
    "AND user_agent NOT LIKE '%Go-http%' AND user_agent NOT LIKE '%okhttp%' "
    "AND user_agent NOT LIKE '%Java/%' AND user_agent NOT LIKE '%libwww%' "
    "AND user_agent NOT LIKE '%libredtail%' AND user_agent NOT LIKE '%scrapy%' "
    "AND user_agent NOT LIKE '%HeadlessChrome%' AND user_agent NOT LIKE '%PhantomJS%' "
    "AND user_agent NOT LIKE '%Playwright%' AND user_agent NOT LIKE '%Puppeteer%' "
    "AND user_agent NOT LIKE '%axios%' AND user_agent NOT LIKE '%node-fetch%' "
    "AND user_agent NOT LIKE '%httpx%' AND user_agent NOT LIKE '%aiohttp%' "
    "AND user_agent NOT LIKE '%facebookexternalhit%' AND user_agent NOT LIKE '%masscan%' "
    "AND user_agent NOT LIKE '%zgrab%' AND user_agent NOT LIKE '%semrush%' "
    "AND user_agent NOT LIKE '%ahrefs%' AND user_agent NOT LIKE '%bytespider%'"
)


@app.get("/admin/bot-blocklist")
def admin_blocklist(_admin: dict = Depends(admin_user)):
    """스크레이퍼로 확정돼 차단된 IP 목록(자동 차단분 포함)."""
    rows = []
    try:
        if _BLOCK_FILE.exists():
            for ln in _BLOCK_FILE.read_text().splitlines():
                ip, _, note = ln.partition("#")
                if ip.strip():
                    rows.append({"ip": ip.strip(), "note": note.strip()})
    except Exception:  # noqa: BLE001
        pass
    return {"count": len(rows), "items": rows, "diversity_max_per_hour": _DIVERSITY_MAX}


@app.post("/admin/bot-blocklist")
def admin_blocklist_edit(body: dict, _admin: dict = Depends(admin_user)):
    """차단 추가/해제. {"ip": "1.2.3.4", "action": "add"|"remove", "note": "..."}"""
    ip = str(body.get("ip") or "").strip()
    if not ip:
        raise HTTPException(400, "ip 가 필요합니다")
    if body.get("action") == "remove":
        _blocked_ips.discard(ip)
        try:
            if _BLOCK_FILE.exists():
                keep = [ln for ln in _BLOCK_FILE.read_text().splitlines()
                        if ln.split("#")[0].strip() != ip]
                _BLOCK_FILE.write_text("\n".join(keep) + ("\n" if keep else ""))
        except Exception:  # noqa: BLE001
            pass
        return {"ok": True, "ip": ip, "blocked": False}
    _block_ip(ip, str(body.get("note") or "관리자 지정"))
    return {"ok": True, "ip": ip, "blocked": True}


@app.get("/admin/bot-stats")
def admin_bot_stats(_admin: dict = Depends(admin_user), days: int = 7):
    """봇 차단 현황 — 차단 사유별·일별 추이, 정상봇 유입, 상위 차단 IP/UA. bot_block 로그 집계."""
    days = min(max(int(days), 1), 90)
    win = f"-{days} days"
    with _logs_db() as c:
        # 사유별 차단 건수(+고유 IP)
        reasons = [{"reason": r[0] or "?", "count": r[1], "ips": r[2]} for r in c.execute(
            "SELECT query, COUNT(*), COUNT(DISTINCT ip) FROM event_log "
            "WHERE kind='bot_block' AND date(ts,'+9 hours') >= date('now','+9 hours', ?) "
            "GROUP BY query ORDER BY 2 DESC", (win,))]
        total = sum(r["count"] for r in reasons)
        # 일별 차단 추이
        daily = [{"date": r[0], "blocks": r[1]} for r in c.execute(
            "SELECT date(ts,'+9 hours') d, COUNT(*) FROM event_log "
            "WHERE kind='bot_block' AND date(ts,'+9 hours') >= date('now','+9 hours', ?) "
            "GROUP BY d ORDER BY d", (win,))]
        # 상위 차단 IP
        top_ips = [{"ip": r[0], "count": r[1], "reasons": r[2]} for r in c.execute(
            "SELECT ip, COUNT(*), COUNT(DISTINCT query) FROM event_log "
            "WHERE kind='bot_block' AND ip IS NOT NULL "
            "AND date(ts,'+9 hours') >= date('now','+9 hours', ?) "
            "GROUP BY ip ORDER BY 2 DESC LIMIT 15", (win,))]
        # 상위 차단 UA(빈 UA 제외 — 별도 사유로 집계됨)
        top_uas = [{"ua": (r[0] or "")[:80], "count": r[1]} for r in c.execute(
            "SELECT user_agent, COUNT(*) FROM event_log "
            "WHERE kind='bot_block' AND user_agent!='' AND user_agent IS NOT NULL "
            "AND date(ts,'+9 hours') >= date('now','+9 hours', ?) "
            "GROUP BY user_agent ORDER BY 2 DESC LIMIT 15", (win,))]
        # 최근 차단 50건
        recent = [{"ts": r[0], "reason": r[1], "status": r[2], "ip": r[3], "ua": (r[4] or "")[:80], "path": r[5]}
                  for r in c.execute(
            "SELECT ts, query, status, ip, user_agent, path FROM event_log "
            "WHERE kind='bot_block' ORDER BY ts DESC LIMIT 50")]
        # 정상봇 유입(검증 통과) — detail.bot 태그(goodbot:*/softbot)
        goodbots = [{"bot": r[0], "count": r[1]} for r in c.execute(
            "SELECT json_extract(detail,'$.bot'), COUNT(*) FROM event_log "
            "WHERE json_extract(detail,'$.bot') IS NOT NULL "
            "AND date(ts,'+9 hours') >= date('now','+9 hours', ?) "
            "GROUP BY 1 ORDER BY 2 DESC LIMIT 15", (win,))]
    _REASON_KR = {
        "ai_crawler": "AI 크롤러", "empty_ua": "빈 User-Agent", "scraper_ua": "스크레이퍼 도구",
        "velocity": "속도 초과", "fake_googlebot": "가짜 Googlebot", "fake_bingbot": "가짜 Bingbot",
        "fake_yandex": "가짜 Yandex", "fake_baiduspider": "가짜 Baidu", "fake_applebot": "가짜 Applebot",
        "fake_yeti": "가짜 네이버봇", "fake_naver": "가짜 네이버봇", "fake_daum": "가짜 다음봇",
        "fake_duckduckbot": "가짜 DuckDuckGo", "fake_petalbot": "가짜 PetalBot",
    }
    for r in reasons:
        r["label"] = _REASON_KR.get(r["reason"], r["reason"])
    return {"days": days, "total": total, "reasons": reasons, "daily": daily,
            "top_ips": top_ips, "top_uas": top_uas, "recent": recent, "goodbots": goodbots}


@app.get("/admin/today-stats")
def admin_today_stats(_admin: dict = Depends(admin_user)):
    """오늘(KST) 접속통계 — 방문자·로그인사용자·최대 동시작업자·신규가입·시간대별. ts는 UTC라 +9h 보정."""
    T = "date(ts,'+9 hours')=date('now','+9 hours')"   # KST 오늘
    TH = f"{T} AND {_HUMAN_SQL}"                        # 실사람만(봇·자동화·내부 제외)
    with _logs_db() as c:
        date_kst = c.execute("SELECT date('now','+9 hours')").fetchone()[0]
        # 방문자·페이지뷰·시간대는 실사람(TH) 기준. 총 이벤트(ev)만 전체.
        ev = c.execute(f"SELECT COUNT(*) FROM event_log WHERE {T}").fetchone()[0]
        lu, vi = c.execute(
            f"SELECT COUNT(DISTINCT user_id), COUNT(DISTINCT ip) FROM event_log WHERE {TH}").fetchone()
        # 봇으로 제외된 방문자 수(고유 IP) — 투명성 표기용
        bots_excluded = c.execute(
            f"SELECT COUNT(DISTINCT ip) FROM event_log WHERE {T} AND ip IS NOT NULL AND ip<>'' "
            f"AND ip NOT IN (SELECT ip FROM event_log WHERE {TH} AND ip IS NOT NULL AND ip<>'')").fetchone()[0]
        logins = c.execute(f"SELECT COUNT(*) FROM event_log WHERE {T} AND kind='login'").fetchone()[0]
        pageviews = c.execute(
            f"SELECT COUNT(*) FROM event_log WHERE {TH} AND kind IN ('view','view_complex','view_realtor')").fetchone()[0]
        ai = c.execute(f"SELECT COUNT(*) FROM event_log WHERE {T} AND kind LIKE 'ai%'").fetchone()[0]
        complex_views = c.execute(f"SELECT COUNT(*) FROM event_log WHERE {TH} AND kind='view_complex'").fetchone()[0]
        hourly = [{"hour": int(h), "visitors": v, "events": e} for h, v, e in c.execute(
            f"SELECT strftime('%H', ts,'+9 hours'), COUNT(DISTINCT ip), COUNT(*) "
            f"FROM event_log WHERE {TH} GROUP BY 1 ORDER BY 1")]
        # 최대 동시작업자 — 10분 버킷 distinct IP 최댓값(실사람 기준)
        pk = c.execute(
            f"SELECT MAX(c), bk FROM (SELECT strftime('%H:',ts,'+9 hours')||(CAST(strftime('%M',ts,'+9 hours') AS INT)/10*10) bk, "
            f"COUNT(DISTINCT ip) c FROM event_log WHERE {TH} GROUP BY bk)").fetchone()
        peak_concurrent, peak_window = (pk[0] or 0), (pk[1] or "")
        top_paths = [{"path": p, "label": _page_label(p), "n": n} for p, n in c.execute(
            f"SELECT path, COUNT(*) FROM event_log WHERE {T} AND path IS NOT NULL AND path<>'' "
            f"GROUP BY path ORDER BY 2 DESC LIMIT 8")]
        # 재접속자 비율 — 오늘 방문자(IP·로그인ID) 중 '최근 30일 내 이전에도 접속'한 비율
        _tod = "datetime('now','+9 hours','start of day','-9 hours')"          # KST 오늘 0시(UTC)
        _lb = "datetime('now','+9 hours','start of day','-30 days','-9 hours')"  # 30일 전 0시(UTC)
        ti, ri = c.execute(
            f"SELECT COUNT(DISTINCT ip), COUNT(DISTINCT CASE WHEN ip IN "
            f"(SELECT ip FROM event_log WHERE ts>={_lb} AND ts<{_tod} AND ip IS NOT NULL AND ip<>'') "
            f"THEN ip END) FROM event_log WHERE ts>={_tod} AND {_HUMAN_SQL} AND ip IS NOT NULL AND ip<>''").fetchone()
        tu, ru = c.execute(
            f"SELECT COUNT(DISTINCT user_id), COUNT(DISTINCT CASE WHEN user_id IN "
            f"(SELECT user_id FROM event_log WHERE ts>={_lb} AND ts<{_tod} AND user_id IS NOT NULL AND user_id<>'') "
            f"THEN user_id END) FROM event_log WHERE ts>={_tod} AND user_id IS NOT NULL AND user_id<>''").fetchone()
        # 디바이스(고유 IP 기준) — user_agent 로 모바일/PC 구분(둘 다에서 접속한 IP는 양쪽 집계)
        _MOB = "(user_agent LIKE '%Mobile%' OR user_agent LIKE '%Android%' OR user_agent LIKE '%iPhone%' OR user_agent LIKE '%iPad%')"
        dev = c.execute(
            f"SELECT COUNT(DISTINCT CASE WHEN {_MOB} THEN ip END), "
            f"       COUNT(DISTINCT CASE WHEN NOT {_MOB} THEN ip END) "
            f"FROM event_log WHERE {TH} AND ip IS NOT NULL AND ip<>''").fetchone()
        # 비로그인 방문자(고유 IP 중 로그인 이벤트 없는 IP)
        guest = c.execute(
            f"SELECT COUNT(DISTINCT ip) FROM event_log WHERE {TH} AND ip IS NOT NULL AND ip<>'' "
            f"AND ip NOT IN (SELECT ip FROM event_log WHERE {T} AND user_id IS NOT NULL AND user_id<>'')").fetchone()[0]
        # 활동 유형별 이벤트 수(오늘)
        by_kind = [{"kind": k, "n": n} for k, n in c.execute(
            f"SELECT kind, COUNT(*) FROM event_log WHERE {T} GROUP BY kind ORDER BY 2 DESC")]
        # 로그인 경로(오늘 로그인 이벤트의 provider별)
        by_provider = [{"provider": (p or "기타"), "n": n} for p, n in c.execute(
            f"SELECT provider, COUNT(*) FROM event_log WHERE {T} AND kind='login' GROUP BY provider ORDER BY 2 DESC")]
        # 오늘 인기 단지 조회 top (view_complex ref)
        top_complex_today = [{"ref": r, "n": n} for r, n in c.execute(
            f"SELECT ref, COUNT(*) FROM event_log WHERE {T} AND kind='view_complex' AND ref IS NOT NULL AND ref<>'' "
            f"GROUP BY ref ORDER BY 2 DESC LIMIT 8")]
    # 단지명 붙이기(있으면)
    if top_complex_today:
        try:
            with _open_db() as dc:
                nm = {str(r[0]): r[1] for r in dc.execute(
                    "SELECT complex_no, complex_name FROM complexes WHERE complex_no IN (%s)"
                    % ",".join("?" * len(top_complex_today)),
                    [x["ref"] for x in top_complex_today]).fetchall()}
            for x in top_complex_today:
                x["name"] = nm.get(str(x["ref"]), x["ref"])
        except Exception:  # noqa: BLE001
            for x in top_complex_today:
                x["name"] = x["ref"]
    with _reviews_db() as rc:
        new_signups = rc.execute(
            "SELECT COUNT(*) FROM user_profiles WHERE agreed_terms_at IS NOT NULL "
            "AND date(agreed_terms_at,'+9 hours')=date('now','+9 hours')").fetchone()[0]
        total_users = rc.execute("SELECT COUNT(*) FROM user_profiles").fetchone()[0]
    return {
        "date_kst": date_kst, "visitors": vi, "bots_excluded": bots_excluded, "logged_users": lu, "events": ev,
        "logins": logins, "pageviews": pageviews, "ai_questions": ai, "complex_views": complex_views,
        "peak_concurrent": peak_concurrent, "peak_window": peak_window,
        "new_signups": new_signups, "total_users": total_users,
        "hourly": hourly, "top_paths": top_paths,
        "devices": {"mobile": dev[0] or 0, "pc": dev[1] or 0},
        "guest_visitors": guest or 0,
        "by_kind": by_kind, "by_provider": by_provider,
        "top_complex_today": top_complex_today,
        "returning": {
            "ip_today": ti or 0, "ip_returning": ri or 0,
            "ip_rate": round((ri / ti) if ti else 0.0, 3),
            "user_today": tu or 0, "user_returning": ru or 0,
            "user_rate": round((ru / tu) if tu else 0.0, 3),
            "window_days": 30,
        },
    }


@app.get("/admin/logs")
def admin_logs(_admin: dict = Depends(admin_user), kind: str = "", user_id: str = "",
               ref: str = "", q: str = "", since_hours: int = 0, limit: int = 200):
    """활동 로그 최근 N건 (필터: kind/user_id/ref/질문검색/기간). 관리자 전용."""
    limit = min(max(int(limit), 1), 2000)
    where, params = ["1=1"], []
    if kind:
        where.append("kind=?"); params.append(kind)
    if user_id:
        where.append("user_id=?"); params.append(user_id)
    if ref:
        where.append("ref=?"); params.append(ref)
    if q:
        where.append("detail LIKE ?"); params.append(f"%{q}%")
    if since_hours and since_hours > 0:
        where.append("ts >= datetime('now', ?)"); params.append(f"-{int(since_hours)} hours")
    with _logs_db() as c:
        rows = c.execute(
            f"SELECT * FROM event_log WHERE {' AND '.join(where)} ORDER BY id DESC LIMIT ?",
            (*params, limit)).fetchall()
    mmap = _member_map([r["user_id"] for r in rows])
    out = []
    for r in rows:
        d = dict(r)
        mn, ph = mmap.get(r["user_id"], (r["member_no"], None))
        d["member_no"] = mn if mn is not None else r["member_no"]
        d["phone"] = ph
        if d.get("detail"):
            try:
                d["detail"] = _authjson.loads(d["detail"])
            except Exception:  # noqa: BLE001
                pass
        out.append(d)
    return {"count": len(out), "events": out}


