@app.get("/admin/server-disk")
def admin_server_disk(_admin: dict = Depends(admin_user)):
    """서버 저장공간 현황 — 본서버 디스크·백업 볼륨, 그리고 아카이브 서버(워커가 보고).
    디스크가 차면 수집·백업이 통째로 멈추므로 데이터 현황과 같은 화면에서 본다."""
    import shutil as _sh

    def _disk(path: str, name: str, role: str) -> dict | None:
        try:
            t, u, f = _sh.disk_usage(path)
        except Exception:                              # noqa: BLE001
            return None
        return {"name": name, "role": role, "mount": path, "total": t, "used": u,
                "free": f, "pct": round(u * 100 / t, 1) if t else 0}

    disks = [d for d in (_disk("/", "본서버", "수집·API·DB"),
                         _disk("/mnt/backup", "백업 볼륨", "일일 백업(본서버에 부착)")) if d]

    # 큰 파일·폴더(30분 캐시) — du 는 느려서 매번 돌리지 않는다
    top = _disk_top_cached()

    # 아카이브 서버는 원격이라 직접 못 읽는다 → 워커가 주기적으로 보고한 값을 쓴다
    remote = []
    try:
        with _reviews_db() as c:
            rows = c.execute("SELECT host,mount,total,used,free,note,at FROM host_disk "
                             "ORDER BY host,mount").fetchall()
        for r in rows:
            t, u = r[2] or 0, r[3] or 0
            remote.append({"name": r[0], "role": r[5] or "", "mount": r[1], "total": t,
                           "used": u, "free": r[4] or 0,
                           "pct": round(u * 100 / t, 1) if t else 0, "at": r[6]})
    except Exception:                                  # noqa: BLE001
        pass

    import datetime as _dtm
    return {"checked_at": _dtm.datetime.now().strftime("%Y-%m-%d %H:%M"),
            "disks": disks, "remote": remote, "top": top}


_DISK_TOP: dict = {"at": 0.0, "items": []}


def _disk_top_cached() -> list:
    """용량을 많이 쓰는 항목 상위 — 30분 캐시."""
    if _time.time() - _DISK_TOP["at"] < 1800 and _DISK_TOP["items"]:
        return _DISK_TOP["items"]
    import subprocess as _sp
    items = []
    data_dir = str(DB_PATH.parent)
    for base in (data_dir, "/mnt/backup"):
        try:
            out = _sp.run(["du", "-sb"] + sorted(Path(base).glob("*"))[:300],
                          capture_output=True, text=True, timeout=120).stdout
        except Exception:                              # noqa: BLE001
            continue
        for line in out.splitlines():
            try:
                sz, path = line.split("\t", 1)
                items.append({"path": path, "name": Path(path).name,
                              "where": "본서버 데이터" if base == data_dir else "백업 볼륨",
                              "size": int(sz)})
            except Exception:                          # noqa: BLE001
                continue
    items.sort(key=lambda x: -x["size"])
    _DISK_TOP.update({"at": _time.time(), "items": items[:10]})
    return _DISK_TOP["items"]


@app.post("/sns/host-disk")
def sns_host_disk(body: dict):
    """다른 박스(아카이브 서버)의 용량 보고 — 워커가 주기적으로 올린다."""
    _sns_require_worker(str(body.get("key") or ""))
    host = str(body.get("host") or "")[:40]
    if not host:
        return {"ok": False}
    with _reviews_db() as c:
        c.execute("""CREATE TABLE IF NOT EXISTS host_disk (
                       host TEXT, mount TEXT, total INTEGER, used INTEGER, free INTEGER,
                       note TEXT, at TEXT, PRIMARY KEY (host, mount))""")
        for d in (body.get("disks") or [])[:6]:
            c.execute("INSERT OR REPLACE INTO host_disk(host,mount,total,used,free,note,at) "
                      "VALUES(?,?,?,?,?,?,datetime('now','+9 hours'))",
                      (host, str(d.get("mount") or "/")[:40], int(d.get("total") or 0),
                       int(d.get("used") or 0), int(d.get("free") or 0),
                       str(d.get("note") or "")[:60]))
        c.commit()
    return {"ok": True}


@app.get("/admin/data-sources")
def admin_data_sources(_admin: dict = Depends(admin_user)):
    """수집 데이터 소스 현황 — 소스별 행수·최신 데이터·마지막 수집·신선도 상태. 관리자 전용.
    신선도 신호: 실거래=inserted_at(수집시각), 매물=snapshot_date, 중개사=fetched_at, vworld=list_fetched_at."""
    from datetime import datetime as _dt, timezone as _tz
    today = _dt.now(_tz.utc).date()

    def days_since(s):
        if not s:
            return None
        try:
            return (today - _dt.strptime(str(s)[:10], "%Y-%m-%d").date()).days
        except Exception:
            return None

    # (table, 친화이름, 분류, 출처, 수집주기, 정상주기일수, 마지막수집표현, 최신데이터표현)
    SRC = [
        ("transactions",      "아파트 매매 실거래",     "실거래 (국토부)", "국토교통부 실거래가",        "매일",            2,  "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("offi_transactions", "오피스텔 매매 실거래",   "실거래 (국토부)", "국토교통부 실거래가",        "매일",            2,  "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("rentals",           "아파트 전·월세 실거래",  "실거래 (국토부)", "국토교통부 실거래가",        "매일",            2,  "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("offi_rentals",      "오피스텔 전·월세 실거래", "실거래 (국토부)", "국토교통부 실거래가",        "매일",            2,  "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("silv_transactions", "분양권·입주권 전매 실거래", "실거래 (국토부)", "국토교통부 실거래가",      "매일",            2,  "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("rh_transactions",   "연립·다세대(빌라) 매매 실거래",   "실거래 (국토부)", "국토교통부 실거래가",  "매일", 2, "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("rh_rentals",        "연립·다세대(빌라) 전·월세 실거래", "실거래 (국토부)", "국토교통부 실거래가",  "매일", 2, "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("sh_transactions",   "단독·다가구 매매 실거래",         "실거래 (국토부)", "국토교통부 실거래가",  "매일", 2, "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("sh_rentals",        "단독·다가구 전·월세 실거래",      "실거래 (국토부)", "국토교통부 실거래가",  "매일", 2, "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("nrg_transactions",  "상업·업무용 매매 실거래",         "실거래 (국토부)", "국토교통부 실거래가",  "매일", 2, "MAX(date(inserted_at))", "MAX(deal_ymd)"),
        ("listings_current",  "아파트·오피 매물 (호가)",   "매물",           "부동산 매물 플랫폼",         "매일",            2,  "MAX(snapshot_date)",     "MAX(snapshot_date)"),
        ("complex_daily_agg", "단지별 일일 매물 집계",   "매물",           "내부 집계 (매물 보관)",       "매일",            2,  "MAX(snapshot_date)",     "MAX(snapshot_date)"),
        ("naver_realtors",    "중개사무소 정보",         "단지·중개사",    "부동산 매물 플랫폼",         "매일 (신규 보강)", 3,  "MAX(date(fetched_at))",  None),
        ("vworld_brokers",    "공인중개사 공식 등록",    "단지·중개사",    "브이월드 (국토교통부)",      "월 1회",          35, "MAX(date(list_fetched_at))", None),
        ("complexes",         "아파트·오피 단지 정보",   "단지·중개사",    "부동산 매물 플랫폼",         "매일 (매물과 함께)",  2, "_listings_snap",         None),
    ]
    out = []
    with _open_db() as c:
        existing = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        for table, name, cat, source, cycle, cyd, fexpr, dexpr in SRC:
            if table not in existing:
                continue
            n = c.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
            # complexes는 자체 타임스탬프가 없음 — 매물 수집(listings snapshot)과 함께 갱신되므로 이를 신선도 proxy로 사용.
            if fexpr == "_listings_snap":
                last = c.execute("SELECT MAX(snapshot_date) FROM listings_current").fetchone()[0]
            elif fexpr:
                last = c.execute(f"SELECT {fexpr} FROM {table}").fetchone()[0]
            else:
                last = None
            latest = c.execute(f"SELECT {dexpr} FROM {table}").fetchone()[0] if dexpr else None
            da = days_since(last)
            if da is None:
                status = "unknown"
            elif da <= cyd:
                status = "ok"
            elif da <= cyd * 2:
                status = "delay"
            else:
                status = "stale"
            out.append({"key": table, "name": name, "category": cat, "source": source,
                        "cycle": cycle, "rows": n, "last_collected": last, "days_ago": da,
                        "latest_data": latest, "status": status})

    # 비단지 호가 — 별도 DB(9종, listings_*.sqlite). snapshot_date 신선도.
    REGION_DBS = [
        ("listings_sangga", "상가 매물 (호가)"), ("listings_office", "사무실 매물 (호가)"),
        ("listings_villa", "빌라·연립 매물 (호가)"), ("listings_house", "단독·다가구 매물 (호가)"),
        ("listings_land", "토지 매물 (호가)"), ("listings_factory", "공장·창고 매물 (호가)"),
        ("listings_building", "건물 매물 (호가)"), ("listings_knowledge", "지식산업센터 매물 (호가)"),
        ("listings_redev", "재개발 매물 (호가)"),
    ]
    for fname, name in REGION_DBS:
        path = DB_PATH.parent / f"{fname}.sqlite"
        if not path.exists():
            continue
        try:
            with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as rc:
                n = rc.execute("SELECT COUNT(*) FROM listings").fetchone()[0]
                last = rc.execute("SELECT MAX(snapshot_date) FROM listings").fetchone()[0]
        except sqlite3.Error:
            continue
        da = days_since(last)
        status = ("unknown" if da is None else "ok" if da <= 2 else "delay" if da <= 4 else "stale")
        out.append({"key": fname, "name": name, "category": "매물 (비단지)",
                    "source": "부동산 매물 플랫폼", "cycle": "매일", "rows": n,
                    "last_collected": last, "days_ago": da, "latest_data": last, "status": status})

    return {"checked_at": _dt.now(_tz.utc).isoformat(), "sources": out}


@app.get("/admin/overview")
def admin_overview(_admin: dict = Depends(admin_user)):
    """관리자 대시보드 종합 지표 — 회원·활동·검수대기·콘텐츠·스냅샷을 한 번에.
    각 섹션은 독립 try/except 라 한 DB/테이블이 없어도 나머지는 채워진다."""
    def _one(conn, sql, params=()):
        try:
            r = conn.execute(sql, params).fetchone()
            return r[0] if r and r[0] is not None else 0
        except Exception:  # noqa: BLE001
            return 0

    members = {"total": 0, "verified": 0, "with_nickname": 0, "points_total": 0}
    moderation = {"reviews_pending": 0, "resident_pending": 0, "realtors_unmatched": 0}
    content = {"forum_posts": 0, "forum_comments": 0, "complex_reviews": 0, "realtor_reviews": 0}
    try:
        with _reviews_db() as c:
            members["total"] = _one(c, "SELECT COUNT(*) FROM user_profiles")
            members["verified"] = _one(c, "SELECT COUNT(*) FROM user_profiles WHERE phone_verified=1")
            members["with_nickname"] = _one(c, "SELECT COUNT(*) FROM user_profiles WHERE nickname IS NOT NULL")
            members["points_total"] = _one(c, "SELECT COALESCE(SUM(points),0) FROM user_profiles")
            moderation["reviews_pending"] = _one(c, "SELECT COUNT(*) FROM realtor_reviews WHERE status='pending'")
            moderation["resident_pending"] = _one(c, "SELECT COUNT(*) FROM resident_verifications WHERE status='pending'")
            content["forum_posts"] = _one(c, "SELECT COUNT(*) FROM forum_posts WHERE status='published'")
            content["forum_comments"] = _one(c, "SELECT COUNT(*) FROM forum_comments WHERE status='published'")
            content["complex_reviews"] = _one(c, "SELECT COUNT(*) FROM complex_reviews WHERE status='published'")
            content["realtor_reviews"] = _one(c, "SELECT COUNT(*) FROM realtor_reviews")
    except Exception:  # noqa: BLE001
        pass

    activity = {"logins_today": 0, "logins_7d": 0, "ai_today": 0, "ai_7d": 0,
                "active_7d": 0, "events_today": 0}
    try:
        with _logs_db() as c:
            activity["logins_today"] = _one(c, "SELECT COUNT(*) FROM event_log WHERE kind='login' AND ts>=date('now')")
            activity["logins_7d"] = _one(c, "SELECT COUNT(*) FROM event_log WHERE kind='login' AND ts>=datetime('now','-7 days')")
            activity["ai_today"] = _one(c, "SELECT COUNT(*) FROM event_log WHERE kind='ai_ask' AND ts>=date('now')")
            activity["ai_7d"] = _one(c, "SELECT COUNT(*) FROM event_log WHERE kind='ai_ask' AND ts>=datetime('now','-7 days')")
            activity["active_7d"] = _one(c, "SELECT COUNT(DISTINCT user_id) FROM event_log WHERE user_id IS NOT NULL AND ts>=datetime('now','-7 days')")
            activity["events_today"] = _one(c, "SELECT COUNT(*) FROM event_log WHERE ts>=date('now')")
    except Exception:  # noqa: BLE001
        pass

    snapshot = {"date": None, "listings": 0}
    try:
        with _open_db() as c:
            moderation["realtors_unmatched"] = _one(c, "SELECT COUNT(*) FROM realtor_match WHERE match_type='none'")
            row = c.execute(
                "SELECT snapshot_date, SUM(listing_count) FROM complex_daily_agg "
                "WHERE snapshot_date=(SELECT MAX(snapshot_date) FROM complex_daily_agg)"
            ).fetchone()
            if row and row[0]:
                snapshot = {"date": row[0], "listings": row[1] or 0}
    except Exception:  # noqa: BLE001
        pass

    return {"members": members, "activity": activity, "moderation": moderation,
            "content": content, "snapshot": snapshot}


class AdminPointsBody(BaseModel):
    delta: int
    reason: str = ""


@app.post("/admin/users/{user_id}/points")
def admin_grant_points(user_id: str, body: AdminPointsBody,
                       _admin: dict = Depends(admin_user)):
    """관리자 수동 포인트 지급/차감 (원장에 'admin' 사유로 기록). 새 잔액 반환."""
    if body.delta == 0 or abs(body.delta) > 1_000_000:
        raise HTTPException(400, "delta 는 0 이 아니고 ±1,000,000 이내여야 합니다")
    with _reviews_db() as c:
        new_bal = _award_points(c, user_id, "admin", delta=body.delta,
                                ref=(body.reason or "관리자 조정")[:100])
        c.commit()
    return {"ok": True, "user_id": user_id, "delta": body.delta, "balance": new_bal}


@app.post("/admin/users/{user_id}/unverify-phone")
def admin_unverify_phone(user_id: str, _admin: dict = Depends(admin_user)):
    """관리자: 사용자 전화번호 인증 해제. 번호를 비워 재인증·재사용 가능하게 한다.
    (회원번호·포인트는 유지. phone_bonus_awarded는 그대로 두어 재인증 시 중복지급 방지.)"""
    with _reviews_db() as c:
        row = c.execute("SELECT phone, phone_verified FROM user_profiles WHERE user_id=?", (user_id,)).fetchone()
        if not row:
            raise HTTPException(404, "사용자 프로필이 없습니다")
        c.execute("UPDATE user_profiles SET phone=NULL, phone_verified=0, updated_at=datetime('now') "
                  "WHERE user_id=?", (user_id,))
        c.commit()
    return {"ok": True, "user_id": user_id, "prev_phone": row[0], "phone_verified": False}


# ===========================================================================
# 시도 코드 → 이름 매핑 (2자리 prefix 기반)
# ===========================================================================
SIDO_NAMES = {
    "11": "서울시", "26": "부산시", "27": "대구시", "28": "인천시",
    "29": "전남광주통합특별시 (광주권)", "30": "대전시", "31": "울산시", "36": "세종시",
    "41": "경기도", "43": "충청북도", "44": "충청남도",
    "46": "전남광주통합특별시 (전남권)", "47": "경상북도", "48": "경상남도",
    "50": "제주도", "51": "강원특별자치도", "52": "전북특별자치도",
    # 행정개편 반영: 29(구 광주광역시)+46(구 전라남도)=전남광주통합특별시(2026-07-01),
    #   51=강원특별자치도(2023-06), 52=전북특별자치도(2024-01). 내부 코드(29·46·51·52)는
    #   데이터 연속성 위해 그대로 유지 — 표시 명칭만 현행화. 광주+전남은 권역 구분해 병기.
    # 45(구 전라북도)는 52로 대체된 죽은 코드 — 넣으면 0건 유령 row가 생긴다.
}

# 시도 표준 배열 순서 — 통계청·국토부·부동산원 발표 관례(행정표준코드 순).
# 강원(42→51)·전북(45→52) 특별자치도 개편으로 코드 숫자 정렬은 이 순서가
# 깨지므로(강원·전북이 제주 뒤로 밀림) 반드시 이 표로 정렬한다. 신·구 코드 병기.
# 46(전남권)을 29(광주권) 바로 뒤로 — 전남광주통합특별시 두 권역이 드롭다운에 붙어 보이게.
SIDO_ORDER = ["11", "26", "27", "28", "29", "46", "30", "31", "36",
              "41", "42", "51", "43", "44", "45", "52", "47", "48", "50"]


def sido_rank(code: str) -> int:
    """cortar/시군구 코드(앞 2자리) → 표준 배열 인덱스. 미지정 코드는 뒤로."""
    try:
        return SIDO_ORDER.index((code or "")[:2])
    except ValueError:
        return len(SIDO_ORDER)


# ── 지역별 실거래: 기간단위(일/주/월/분기/연) × 카테고리 시계열 ─────────────
# 카테고리 6종 테이블이 전부 동일 스키마(deal_ymd·deal_amount·sgg_cd·is_cancelled)라 단일 쿼리.
_SERIES_TBL = {
    "apt": "transactions", "offi": "offi_transactions", "silv": "silv_transactions",
    "villa": "rh_transactions", "house": "sh_transactions", "nrg": "nrg_transactions",
}
_SERIES_UNIT = {
    # (버킷 SQL, 기본 구간 수)
    "day":     ("substr(deal_ymd,1,10)", 60),
    "week":    ("strftime('%Y-W%W', deal_ymd)", 52),
    "month":   ("substr(deal_ymd,1,7)", 36),
    "quarter": ("substr(deal_ymd,1,4) || '-Q' || ((CAST(substr(deal_ymd,6,2) AS INTEGER)+2)/3)", 20),
    "year":    ("substr(deal_ymd,1,4)", 30),
}


@app.get("/stats/tx-region-series")
def tx_region_series(unit: str = "month", asset: str = "apt",
                     sido: str | None = None, sigungu: str | None = None,
                     limit: int = 0):
    """지역별 실거래 시계열 — unit=day|week|month|quarter|year, asset=apt|offi|silv|villa|house|nrg.
    건수 + 평균거래가. 해제거래 제외. 지역: 전국(기본)/시도/시군구."""
    if unit not in _SERIES_UNIT:
        raise HTTPException(400, "unit must be day|week|month|quarter|year")
    tbl = _SERIES_TBL.get(asset)
    if not tbl:
        raise HTTPException(400, f"asset must be one of {','.join(_SERIES_TBL)}")
    bucket, default_n = _SERIES_UNIT[unit]
    n = max(4, min(limit or default_n, 400))
    w, params = ["is_cancelled=0", "deal_ymd IS NOT NULL"], []
    if sigungu:
        w.append("substr(sgg_cd,1,5)=substr(?,1,5)"); params.append(sigungu)
    elif sido:
        w.append("substr(sgg_cd,1,2)=substr(?,1,2)"); params.append(sido)
    _ck = f"txseries:{unit}:{asset}:{sido or ''}:{sigungu or ''}:{n}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    with _open_db() as c:
        rows = c.execute(
            f"SELECT {bucket} p, COUNT(*) n, AVG(deal_amount) avg_amt "
            f"FROM {tbl} WHERE {' AND '.join(w)} GROUP BY p ORDER BY p DESC LIMIT ?",
            [*params, n]).fetchall()
    items = [{"period": r[0], "count": r[1],
              "avg_amt": round(r[2]) if r[2] else None} for r in reversed(rows)]
    out = {"unit": unit, "asset": asset, "items": items}
    _cache_put(_ck, out)
    return out


@app.get("/stats/tx-map")
def tx_map(asset: str = "apt", trade: str = "A1", sido: str = "", sigungu: str = "", dong: str = "",
           months: int = 6, limit: int = 1200):
    """실거래 지도 — 지역 내 실거래를 건물 단위로 좌표에 집계(핀별 건수·평균가·평당가·최근 거래).
    trade: A1(매매)/B1(전세)/B2(월세). 전월세 소스: apt=rentals(단지매칭 90%)·offi=offi_rentals(97%)·
    villa=rh_rentals(지번 100%). nrg는 임대 데이터 원천 없음(주택만 신고제), house는 임대 지번 없음 → A1만.
    apt/offi=단지 좌표, villa/nrg=coord_jibun(지번→좌표). 지도 과밀 방지로 시군구 이상 필수."""
    months = min(max(int(months), 1), 24)
    limit = min(max(int(limit), 50), 3000)
    if trade not in ("A1", "B1", "B2"):
        raise HTTPException(400, "trade must be A1|B1|B2")
    if trade != "A1" and asset in ("nrg", "house"):
        raise HTTPException(400, "상가는 임대 실거래 원천이 없고, 단독 임대는 지번이 없어 지도 미지원")
    sgg5 = (sigungu or "")[:5]
    cut = f"date('now','+9 hours','-{months} months')"
    _ck = f"txmap:{asset}:{trade}:{sido}:{sigungu}:{dong}:{months}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    # 전월세 공통 — 값 컬럼·필터(전월세 테이블엔 is_cancelled 없음: 해제신고는 매매만)
    rent_w = "AND t.monthly_rent=0" if trade == "B1" else ("AND t.monthly_rent>0" if trade == "B2" else "")
    val = "t.deal_amount" if trade == "A1" else ("t.deposit" if trade == "B1" else "t.monthly_rent")

    if asset in ("apt", "offi"):
        if trade == "A1":
            table, canc = ("transactions" if asset == "apt" else "offi_transactions"), "t.is_cancelled=0"
        else:
            table, canc = ("rentals" if asset == "apt" else "offi_rentals"), "1=1"
        # 지역 필터는 t.sgg_cd(인덱스 있음)로 거래를 먼저 좁힌다 — cx.cortar_no만 걸면
        # 전국 매칭거래를 다 스캔해 강남 등 대단지 지역이 콜드 20초+로 느려진다.
        # 매칭거래의 t.sgg_cd == 매칭단지 cortar_no[:5] 이므로 결과는 동일(검증), 인덱스만 태운다.
        if dong:
            reg, rp = "AND cx.cortar_no=? AND t.sgg_cd=?", [dong, str(dong)[:5]]
        elif sgg5:
            reg, rp = "AND t.sgg_cd=? AND substr(cx.cortar_no,1,5)=?", [sgg5, sgg5]
        elif sido:
            s2 = sido[:2]
            reg, rp = "AND t.sgg_cd>=? AND t.sgg_cd<=? AND substr(cx.cortar_no,1,2)=?", [s2 + "000", s2 + "999", s2]
        else:
            raise HTTPException(400, "시도 이상 지역을 선택하세요")
        dep = "t.deposit" if trade == "B2" else "NULL"   # 최근 거래의 보증금(월세핀)
        namecol = "apt_nm" if asset == "apt" else "offi_nm"
        with _open_db() as d:
            rows = d.execute(
                f"SELECT cx.latitude, cx.longitude, cx.complex_name, cx.complex_no, "
                f"  COUNT(*) n, {val} last, substr(MAX(t.deal_ymd||printf('%010d',t.rowid)),1,10) latest, "
                f"  CAST({val}/NULLIF(t.excl_use_ar,0)*3.3 AS INT) ppy, {dep} dep, "
                f"  CAST(AVG({val}) AS INT) avg, substr(cx.use_approve_ymd,1,4) built "
                f"FROM {table} t JOIN complexes cx ON cx.complex_no=t.matched_complex_no "
                f"WHERE {canc} AND t.matched_complex_no IS NOT NULL {rent_w} "
                f"  AND cx.latitude IS NOT NULL AND cx.latitude<>0 AND t.deal_ymd>={cut} {reg} "
                f"GROUP BY t.matched_complex_no ORDER BY n DESC LIMIT ?", rp + [limit]).fetchall()
            items = [{"lat": r[0], "lng": r[1], "name": r[2], "ref": str(r[3]),
                      "n": r[4], "last": r[5], "latest": r[6], "ppy": r[7], "deposit": r[8],
                      "avg": r[9], "built": r[10] or None, "kind": "complex"} for r in rows]
            # 단지 미매칭 매매(주로 시골 아파트·소형)를 지번 좌표로 개별핀 폴백 — 매매(A1)만.
            # 좌표: coord_jibun_fwd(정방향, 시군구 정합) 우선 → coord_jibun(역) 폴백. geocode_jibun.py가 채운다.
            if trade == "A1":
                d.execute("ATTACH DATABASE ? AS ca", (str(DB_PATH.parent / "coord_addr.sqlite"),))
                has_fwd = d.execute(
                    "SELECT COUNT(*) FROM ca.sqlite_master WHERE type='table' AND name='coord_jibun_fwd'").fetchone()[0]
                if dong:
                    _dn = d.execute("SELECT cortar_name FROM regions WHERE cortar_no=?", (dong,)).fetchone()
                    jreg, jrp = "AND substr(t.sgg_cd,1,5)=? AND t.umd_nm=?", [dong[:5], _dn[0] if _dn else "\x00"]
                elif sgg5:
                    jreg, jrp = "AND substr(t.sgg_cd,1,5)=?", [sgg5]
                else:
                    jreg, jrp = "AND substr(t.sgg_cd,1,2)=?", [sido[:2]]
                fj = ("LEFT JOIN ca.coord_jibun_fwd f ON f.sgg5=substr(t.sgg_cd,1,5) "
                      "AND f.dong=t.umd_nm AND f.jibun=t.jibun AND f.status='ok' " if has_fwd else "")
                jlat = "COALESCE(f.lat, cj.lat)" if has_fwd else "cj.lat"
                jlng = "COALESCE(f.lng, cj.lng)" if has_fwd else "cj.lng"
                jrows = d.execute(
                    f"SELECT {jlat}, {jlng}, t.{namecol}, t.umd_nm||'|'||t.jibun, "
                    f"  COUNT(*) n, t.deal_amount, substr(MAX(t.deal_ymd||printf('%010d',t.rowid)),1,10), "
                    f"  CAST(t.deal_amount/NULLIF(t.excl_use_ar,0)*3.3 AS INT), "
                    f"  CAST(AVG(t.deal_amount) AS INT), t.build_year "
                    f"FROM {table} t "
                    f"{fj}"
                    f"LEFT JOIN ca.coord_jibun cj ON cj.dong=t.umd_nm AND cj.jibun=t.jibun "
                    f"WHERE t.is_cancelled=0 AND t.matched_complex_no IS NULL "
                    f"  AND t.jibun IS NOT NULL AND t.jibun<>'' AND t.deal_ymd>={cut} "
                    f"  AND {jlat} IS NOT NULL {jreg} "
                    f"GROUP BY t.umd_nm, t.jibun ORDER BY n DESC LIMIT ?", jrp + [limit]).fetchall()
                items += [{"lat": r[0], "lng": r[1], "name": r[2] or r[3].replace("|", " "),
                           "ref": r[3], "n": r[4], "last": r[5], "latest": r[6], "ppy": r[7],
                           "deposit": None, "avg": r[8], "built": (str(r[9]) if r[9] else None),
                           "kind": "jibun"} for r in jrows]
        note = None
        if trade != "A1":
            note = "전월세는 갱신·신규 계약을 모두 포함합니다."
        res = {"asset": asset, "trade": trade, "items": items, "note": note}
        _cache_put(_ck, res)
        return res

    if asset in ("villa", "nrg"):
        if not sgg5:
            raise HTTPException(400, "빌라·상가 지도는 시군구를 선택하세요")
        if asset == "villa" and trade != "A1":
            rtable, acol, canc = "rh_rentals", "excl_use_ar", "1=1"
        else:
            rtable = "rh_transactions" if asset == "villa" else "nrg_transactions"
            acol = "excl_use_ar" if asset == "villa" else "building_ar"
            canc = "r.is_cancelled=0"
        rval = "r.deal_amount" if trade == "A1" else ("r.deposit" if trade == "B1" else "r.monthly_rent")
        rrent_w = rent_w.replace("t.", "r.")
        rdep = "r.deposit" if trade == "B2" else "NULL"   # 최근 거래의 보증금(월세핀)
        with _open_db() as d:
            d.execute("ATTACH DATABASE ? AS ca", (str(DB_PATH.parent / "coord_addr.sqlite"),))
            # 마스킹 지번('1**') 복원 — 건축물대장 표제부 역매칭 결과(ledger_recover.recovered).
            # 상가만 해당(빌라는 마스킹 0). 복원되면 실지번·건물명으로 지도에 찍힌다.
            rec_join = ""
            jib = "r.jibun"
            bld = "NULL"
            if asset == "nrg" and (DB_PATH.parent / "ledger_recover.sqlite").exists():
                try:
                    d.execute("ATTACH DATABASE ? AS lr", (str(DB_PATH.parent / "ledger_recover.sqlite"),))
                    rec_join = "LEFT JOIN lr.recovered rec ON rec.deal_id=r.deal_id AND rec.jibun IS NOT NULL "
                    jib = "COALESCE(rec.jibun, r.jibun)"
                    bld = "rec.bld_nm"   # bare — 쿼리 내 max는 deal_ymd 하나만(최근행 확정)
                except sqlite3.Error:
                    pass
            # 좌표 소스 2단: ① coord_jibun_fwd(정방향 지오코딩, 시군구까지 정합 — 동명이동 오매칭 없음)
            #               ② coord_jibun(역지오코딩 파생, dong+jibun) 폴백. geocode_jibun.py 가 ①을 채운다.
            has_fwd = d.execute(
                "SELECT COUNT(*) FROM ca.sqlite_master WHERE type='table' AND name='coord_jibun_fwd'").fetchone()[0]
            fwd_join = (f"LEFT JOIN ca.coord_jibun_fwd f ON f.sgg5=substr(r.sgg_cd,1,5) "
                        f"AND f.dong=r.umd_nm AND f.jibun={jib} AND f.status='ok' " if has_fwd else "")
            fwd_lat = "COALESCE(f.lat, cj.lat)" if has_fwd else "cj.lat"
            fwd_lng = "COALESCE(f.lng, cj.lng)" if has_fwd else "cj.lng"
            rows = d.execute(
                f"SELECT {fwd_lat}, {fwd_lng}, r.umd_nm||' '||{jib}, r.umd_nm||'|'||{jib}, "
                f"  COUNT(*) n, {rval} last, substr(MAX(r.deal_ymd||printf('%010d',r.rowid)),1,10) latest, "
                f"  CAST({rval}/NULLIF(r.{acol},0)*3.3 AS INT) ppy, {bld} bldnm, {rdep} dep, "
                f"  CAST(AVG({rval}) AS INT) avg, r.build_year built "
                f"FROM {rtable} r "
                f"{rec_join}"
                f"{fwd_join}"
                f"LEFT JOIN ca.coord_jibun cj ON cj.dong=r.umd_nm AND cj.jibun={jib} "
                f"WHERE {canc} AND r.deal_ymd>={cut} {rrent_w} AND substr(r.sgg_cd,1,5)=? "
                f"  AND {fwd_lat} IS NOT NULL "
                f"GROUP BY r.umd_nm, {jib} ORDER BY n DESC LIMIT ?", (sgg5, limit)).fetchall()
        items = [{"lat": r[0], "lng": r[1], "name": (r[8] or r[2]), "ref": r[3],
                  "n": r[4], "last": r[5], "latest": r[6], "ppy": r[7], "deposit": r[9],
                  "avg": r[10], "built": (str(r[11]) if r[11] else None), "kind": "jibun"} for r in rows]
        # 지도 아래 '몇 건 중 몇 건(%)' 안내는 두지 않는다 — 지도 위쪽에 이미
        # "지번 좌표가 확인된 실거래만 표시됩니다" 한 줄이 있어 중복이고,
        # 수치를 드러내면 데이터가 비어 보인다.
        res = {"asset": asset, "trade": trade, "items": items, "note": None}
        _cache_put(_ck, res)
        return res

    if asset == "house":
        # 단독·다가구 — 원본에 지번이 아예 없음. 건축물대장 표제부 역매칭(strict·유일해만)으로
        # 위치가 특정된 거래만 표시. ledger_jibun_recover.py 가 recovered(asset='sh')를 채운다.
        if not sgg5:
            raise HTTPException(400, "단독 지도는 시군구를 선택하세요")
        lrdb = DB_PATH.parent / "ledger_recover.sqlite"
        if not lrdb.exists():
            return {"asset": asset, "items": [], "note": "위치 복원 데이터 준비 중입니다."}
        with _open_db() as d:
            d.execute("ATTACH DATABASE ? AS ca", (str(DB_PATH.parent / "coord_addr.sqlite"),))
            d.execute("ATTACH DATABASE ? AS lr", (str(lrdb),))
            has_fwd = d.execute(
                "SELECT COUNT(*) FROM ca.sqlite_master WHERE type='table' AND name='coord_jibun_fwd'").fetchone()[0]
            fwd_join = ("LEFT JOIN ca.coord_jibun_fwd f ON f.sgg5=substr(r.sgg_cd,1,5) "
                        "AND f.dong=r.umd_nm AND f.jibun=rec.jibun AND f.status='ok' " if has_fwd else "")
            fwd_lat = "COALESCE(f.lat, cj.lat)" if has_fwd else "cj.lat"
            fwd_lng = "COALESCE(f.lng, cj.lng)" if has_fwd else "cj.lng"
            rows = d.execute(
                f"SELECT {fwd_lat}, {fwd_lng}, r.umd_nm||' '||rec.jibun, r.umd_nm||'|'||rec.jibun, "
                f"  COUNT(*) n, r.deal_amount last, substr(MAX(r.deal_ymd||printf('%010d',r.rowid)),1,10) latest, "
                f"  CAST(r.deal_amount/NULLIF(r.total_floor_ar,0)*3.3 AS INT) ppy, rec.bld_nm bldnm, "
                f"  CAST(AVG(r.deal_amount) AS INT) avg, r.build_year built "
                f"FROM sh_transactions r "
                f"JOIN lr.recovered rec ON rec.deal_id=r.deal_id AND rec.jibun IS NOT NULL "
                f"{fwd_join}"
                f"LEFT JOIN ca.coord_jibun cj ON cj.dong=r.umd_nm AND cj.jibun=rec.jibun "
                f"WHERE r.is_cancelled=0 AND r.deal_ymd>={cut} AND substr(r.sgg_cd,1,5)=? "
                f"  AND {fwd_lat} IS NOT NULL "
                f"GROUP BY r.umd_nm, rec.jibun ORDER BY n DESC LIMIT ?", (sgg5, limit)).fetchall()
        items = [{"lat": r[0], "lng": r[1], "name": r[8] or r[2], "ref": r[3],
                  "n": r[4], "last": r[5], "latest": r[6], "ppy": r[7],
                  "avg": r[9], "built": (str(r[10]) if r[10] else None), "kind": "jibun"} for r in rows]
        # 위쪽 설명과 중복이라 지도 아래 안내는 두지 않는다(건수·비율도 노출하지 않음).
        res = {"asset": asset, "items": items, "note": None}
        _cache_put(_ck, res)
        return res

    raise HTTPException(400, "asset must be apt|offi|villa|nrg|house")


def _txmap_ledger_full(cortar_no: str | None, addr: str | None) -> tuple:
    """실거래지도 상세용 건축물대장 표제부 상세 + 층별개요(온디맨드·영속캐시).
    단지핀=단지 지번(complexes.detail_address), 지번핀=클릭 지번. 키·쿼터 없으면 (None,None)."""
    if not cortar_no or not addr:
        return None, None
    try:
        _vw, dks = _audit_keys()
        if not dks:
            return None, None
        from collector.ondemand_ledger import ledger_full_for_jibun, flr_ouln_for_jibun
        full = ledger_full_for_jibun(cortar_no, addr, dks)
        full = full if isinstance(full, dict) else None
        floors = flr_ouln_for_jibun(cortar_no, addr, dks)
        # 층별개요는 용도가 섞인 건물(상가+주택 등)만 정보가치 있음. 아파트처럼 단일용도면 생략.
        if isinstance(floors, list) and floors:
            purps = {(f.get("purps") or "") for f in floors}
            purps.discard("")
            if len(purps) <= 1:
                floors = None
            else:
                seen, uniq = set(), []
                for f in sorted(floors, key=lambda x: (x.get("flr_gb") != "지상", -(x.get("flr_no") or 0))):
                    k = (f.get("flr_no_nm"), f.get("purps"))
                    if k in seen:
                        continue
                    seen.add(k)
                    uniq.append(f)
                floors = uniq[:60]
        else:
            floors = None
        return full, floors
    except Exception:  # noqa: BLE001 — 상세는 대장 없어도 거래내역만으로 유효
        return None, None


@app.get("/stats/tx-map/detail")
def tx_map_detail(asset: str = "apt", trade: str = "A1", ref: str = "",
                  sigungu: str = "", months: int = 6, limit: int = 60):
    """실거래 지도 핀 상세 — 개별 거래 내역 + 건물 정보.
    ref: 단지핀=complex_no, 지번핀='동|지번'. 건물정보는 단지=complexes, 지번=건축물대장 표제부 캐시.
    거래 내역: 매매=가격·층·면적·거래방식·(아파트)동·등기 / 전월세=보증금·월세·신규갱신·종전조건(인상률)."""
    months = min(max(int(months), 1), 24)
    limit = min(max(int(limit), 10), 200)
    if trade not in ("A1", "B1", "B2"):
        raise HTTPException(400, "trade must be A1|B1|B2")
    if not ref:
        raise HTTPException(400, "ref 필요")
    cut = f"date('now','+9 hours','-{months} months')"
    _ck = f"txmapdt:{asset}:{trade}:{ref}:{sigungu}:{months}"
    _hit = _cache_get(_ck)
    if _hit is not None:
        return _hit
    sgg5 = (sigungu or "")[:5]
    building: dict = {}
    deals: list = []
    ledger_full = None      # 건축물대장 표제부 상세(구조·층수·세대·건폐율·용적률 등)
    floors = None           # 층별개요(층별 용도·면적)

    def _num(v):
        try:
            return float(v)
        except Exception:
            return None

    with _open_db() as d:
        if "|" not in ref:                       # ── 단지 핀(아파트·오피스텔)
            cno = ref
            r = d.execute(
                "SELECT complex_name, total_household_count, use_approve_ymd, total_building_count, "
                "  parking_per_household, construction_company, real_estate_type_name, dong_name, "
                "  cortar_no, detail_address "
                "FROM complexes WHERE complex_no=?", (cno,)).fetchone()
            if r:
                building = {"kind": "complex", "complex_no": cno, "name": r[0],
                            "households": r[1], "built": (r[2] or "")[:4] or None,
                            "buildings": r[3], "parking": r[4],
                            "builder": (r[5] or "").split(",")[0] or None,
                            "type": r[6], "dong_name": r[7]}
                # 단지 지번으로 건축물대장 표제부 상세(건폐율·용적률·구조·높이·승강기 등) 보강
                ledger_full, floors = _txmap_ledger_full(r[8], r[9])
            if trade == "A1":
                table = "transactions" if asset == "apt" else "offi_transactions"
                rows = d.execute(
                    f"SELECT deal_ymd, deal_amount, excl_use_ar, floor, dealing_gbn, "
                    f"  json_extract(raw,'$.aptDong'), "
                    f"  (TRIM(COALESCE(json_extract(raw,'$.rgstDate'),''))<>''), "
                    f"  buyer_gbn, sler_gbn "
                    f"FROM {table} WHERE matched_complex_no=? AND is_cancelled=0 AND deal_ymd>={cut} "
                    f"ORDER BY deal_ymd DESC LIMIT ?", (cno, limit)).fetchall()
                deals = [{"date": r[0], "price": r[1], "area": r[2], "floor": r[3],
                          "dealing": r[4], "dong": r[5], "registered": bool(r[6]),
                          "buyer": r[7], "seller": r[8]} for r in rows]
            else:
                table = "rentals" if asset == "apt" else "offi_rentals"
                w = "monthly_rent=0" if trade == "B1" else "monthly_rent>0"
                rows = d.execute(
                    f"SELECT deal_ymd, deposit, monthly_rent, excl_use_ar, floor, contract_type, "
                    f"  contract_term, use_rr_right, pre_deposit, pre_monthly_rent "
                    f"FROM {table} WHERE matched_complex_no=? AND {w} AND deal_ymd>={cut} "
                    f"ORDER BY deal_ymd DESC LIMIT ?", (cno, limit)).fetchall()
                deals = [{"date": r[0], "deposit": r[1], "rent": r[2], "area": r[3], "floor": r[4],
                          "contract": r[5], "term": r[6], "rr_right": r[7],
                          "pre_deposit": r[8], "pre_rent": r[9]} for r in rows]
        else:                                    # ── 지번 핀(빌라·상가·단독·미매칭 아파트)
            dong, jib = ref.split("|", 1)
            # 지번 → 법정동코드 → 건축물대장 표제부 상세 + 층별개요(온디맨드·영속캐시)
            if sgg5:
                _cn = d.execute(
                    "SELECT cortar_no FROM regions WHERE substr(cortar_no,1,5)=? "
                    "AND cortar_name=? AND cortar_no NOT LIKE '%00000'", (sgg5, dong)).fetchone()
                _cortar = _cn[0] if _cn else None
                if not _cortar:      # 시골 리(里)는 regions에 없음 — ledger_recover.ri_bjd에서 법정동코드
                    _lrdb = DB_PATH.parent / "ledger_recover.sqlite"
                    if _lrdb.exists():
                        try:
                            with sqlite3.connect(f"file:{_lrdb}?mode=ro", uri=True) as _lc:
                                _rr = _lc.execute("SELECT sgg5||bjd5 FROM ri_bjd WHERE sgg5=? AND umd_nm=?",
                                                  (sgg5, dong)).fetchone()
                            _cortar = _rr[0] if _rr else None
                        except sqlite3.Error:
                            _cortar = None
                if _cortar:
                    ledger_full, floors = _txmap_ledger_full(_cortar, jib)
            # 건물정보 — 건축물대장 표제부 캐시(복원 데몬이 채움). 지번 '813-14' → bun/ji 매칭
            lrdb = DB_PATH.parent / "ledger_recover.sqlite"
            lr_ok = False
            if lrdb.exists():
                try:
                    d.execute("ATTACH DATABASE ? AS lr", (str(lrdb),))
                    lr_ok = True
                except sqlite3.Error:
                    pass
            if lr_ok and sgg5 and asset in ("villa", "nrg", "house"):
                try:
                    bjd = d.execute(
                        "SELECT substr(cortar_no,6,5) FROM regions "
                        "WHERE substr(cortar_no,1,5)=? AND cortar_name=? AND cortar_no NOT LIKE '%00000'",
                        (sgg5, dong)).fetchone()
                    row = d.execute("SELECT items FROM lr.title_cache WHERE sgg=? AND bjd=?",
                                    (sgg5, bjd[0] if bjd else "")).fetchone()
                    if row:
                        want_bun = jib.split("-")[0]
                        want_ji = jib.split("-")[1] if "-" in jib else "0"
                        for bun, ji, ta, pl, apr, nm, purps in _authjson.loads(row[0]):
                            try:
                                if str(int(bun)) == want_bun and int(ji or 0) == int(want_ji):
                                    building = {"kind": "ledger", "name": nm or None,
                                                "purpose": purps or None, "tot_area": _num(ta),
                                                "plat_area": _num(pl),
                                                "built": (apr or "")[:4] or None}
                                    break
                            except Exception:
                                continue
                except sqlite3.Error:
                    pass
            d.execute("ATTACH DATABASE ? AS ca2", (str(DB_PATH.parent / "coord_addr.sqlite"),))  # noqa — 미사용이어도 무해
            if asset in ("apt", "offi"):          # ── 단지 미매칭 아파트·오피 지번핀(매매)
                t2 = "transactions" if asset == "apt" else "offi_transactions"
                ncol = "apt_nm" if asset == "apt" else "offi_nm"
                rows = d.execute(
                    f"SELECT deal_ymd, deal_amount, excl_use_ar, floor, dealing_gbn, "
                    f"  json_extract(raw,'$.aptDong'), "
                    f"  (TRIM(COALESCE(json_extract(raw,'$.rgstDate'),''))<>''), "
                    f"  buyer_gbn, sler_gbn, {ncol} "
                    f"FROM {t2} WHERE umd_nm=? AND jibun=? AND substr(sgg_cd,1,5)=? "
                    f"  AND matched_complex_no IS NULL AND is_cancelled=0 AND deal_ymd>={cut} "
                    f"ORDER BY deal_ymd DESC LIMIT ?", (dong, jib, sgg5, limit)).fetchall()
                deals = [{"date": r[0], "price": r[1], "area": r[2], "floor": r[3],
                          "dealing": r[4], "dong": r[5], "registered": bool(r[6]),
                          "buyer": r[7], "seller": r[8]} for r in rows]
                if rows and not building:
                    building = {"kind": "tx", "name": rows[0][9],
                                "purpose": "아파트" if asset == "apt" else "오피스텔",
                                "built": None, "tot_area": None, "plat_area": None}
            elif asset == "villa":
                if trade == "A1":
                    rows = d.execute(
                        f"SELECT deal_ymd, deal_amount, excl_use_ar, land_ar, floor, house_type, "
                        f"  dealing_gbn, buyer_gbn, sler_gbn FROM rh_transactions "
                        f"WHERE umd_nm=? AND jibun=? AND substr(sgg_cd,1,5)=? AND is_cancelled=0 "
                        f"  AND deal_ymd>={cut} ORDER BY deal_ymd DESC LIMIT ?",
                        (dong, jib, sgg5, limit)).fetchall()
                    deals = [{"date": r[0], "price": r[1], "area": r[2], "land": r[3], "floor": r[4],
                              "htype": r[5], "dealing": r[6], "buyer": r[7], "seller": r[8]} for r in rows]
                else:
                    w = "monthly_rent=0" if trade == "B1" else "monthly_rent>0"
                    rows = d.execute(
                        f"SELECT deal_ymd, deposit, monthly_rent, excl_use_ar, floor, contract_type, "
                        f"  contract_term, use_rr_right, pre_deposit, pre_monthly_rent, house_type "
                        f"FROM rh_rentals WHERE umd_nm=? AND jibun=? AND substr(sgg_cd,1,5)=? AND {w} "
                        f"  AND deal_ymd>={cut} ORDER BY deal_ymd DESC LIMIT ?",
                        (dong, jib, sgg5, limit)).fetchall()
                    deals = [{"date": r[0], "deposit": r[1], "rent": r[2], "area": r[3], "floor": r[4],
                              "contract": r[5], "term": r[6], "rr_right": r[7],
                              "pre_deposit": r[8], "pre_rent": r[9], "htype": r[10]} for r in rows]
            elif asset == "nrg":
                rec_or = ""
                params = [dong, jib, sgg5]
                if lr_ok:
                    rec_or = ("OR r.deal_id IN (SELECT deal_id FROM lr.recovered "
                              "WHERE dong=? AND jibun=? AND sgg5=?) ")
                    params += [dong, jib, sgg5]
                rows = d.execute(
                    f"SELECT r.deal_ymd, r.deal_amount, r.building_ar, r.plottage_ar, r.floor, "
                    f"  r.building_use, r.building_type, r.land_use, r.dealing_gbn, r.buyer_gbn, r.sler_gbn "
                    f"FROM nrg_transactions r "
                    f"WHERE ((r.umd_nm=? AND r.jibun=? AND substr(r.sgg_cd,1,5)=?) {rec_or}) "
                    f"  AND r.is_cancelled=0 AND r.deal_ymd>={cut} "
                    f"ORDER BY r.deal_ymd DESC LIMIT ?", params + [limit]).fetchall()
                deals = [{"date": r[0], "price": r[1], "area": r[2], "land": r[3], "floor": r[4],
                          "use": r[5], "btype": r[6], "land_use": r[7], "dealing": r[8],
                          "buyer": r[9], "seller": r[10]} for r in rows]
            elif asset == "house":
                if not lr_ok:
                    deals = []
                else:
                    rows = d.execute(
                        f"SELECT r.deal_ymd, r.deal_amount, r.total_floor_ar, r.plottage_ar, "
                        f"  r.house_type, r.dealing_gbn, r.buyer_gbn, r.sler_gbn "
                        f"FROM sh_transactions r JOIN lr.recovered rec ON rec.deal_id=r.deal_id "
                        f"WHERE rec.dong=? AND rec.jibun=? AND rec.sgg5=? AND r.is_cancelled=0 "
                        f"  AND r.deal_ymd>={cut} ORDER BY r.deal_ymd DESC LIMIT ?",
                        (dong, jib, sgg5, limit)).fetchall()
                    deals = [{"date": r[0], "price": r[1], "area": r[2], "land": r[3],
                              "htype": r[4], "dealing": r[5], "buyer": r[6], "seller": r[7]} for r in rows]
            if not building and deals:           # 대장 미보유 동 — 거래 원본에서 최소 건물정보
                d0 = deals[0]
                building = {"kind": "tx", "name": None,
                            "purpose": d0.get("use") or d0.get("htype"),
                            "built": None, "tot_area": None, "plat_area": d0.get("land")}
    # 요약(최고·최저)
    stat = {}
    if deals:
        key = "price" if trade == "A1" else ("deposit" if trade == "B1" else "rent")
        vals = [x[key] for x in deals if x.get(key)]
        if vals:
            stat = {"max": max(vals), "min": min(vals), "n": len(deals)}
    res = {"asset": asset, "trade": trade, "ref": ref,
           "building": building, "ledger": ledger_full, "floors": floors,
           "deals": deals, "stat": stat}
    _cache_put(_ck, res)
    return res


@app.get("/stats/tx-region-pulse")
def tx_region_pulse(asset: str = "apt"):
    """시도별 + 전국 실거래 신고 펄스 (매매 기준).

    한 시도 row 당:
      - filed_total/current/prev: 어제 적재된 거래수 (계약일 이번달/지난달 split)
      - current_month_count:  이번 달 누적 거래 (계약일 기준)
      - prev_month_count:     지난 달 누적 거래
      - current_month_pred / prev_month_pred:
          작년 같은 달의 동일-일자 누적 vs 총합 비율로 보정한 예측 총합.
      - yoy_actual:    전년 동월 총 거래
      - avg3y_actual:  최근 3년 같은 달 평균 (가용한 만큼)
      - *_change: 예측 / 비교 기준 - 1

    PIVOT pattern + 인덱스(deal_ymd, date(inserted_at)) 활용해 단일 쿼리로
    전부 가져옴.
    """
    from datetime import date, timedelta
    # 아파트·오피스텔 외 우리가 수집하는 실거래도 지원(전부 sgg_cd·deal_year/month·is_cancelled·inserted_at 보유).
    # 빌라(연립·다세대)=rh, 단독·다가구=sh, 상가·사무실=nrg, 분양권=silv. rh/sh/nrg/silv는 2024-07~라 옛 연도 비교는 가용분만.
    TABLE_MAP = {
        "apt": ["transactions"],
        "offi": ["offi_transactions"],
        "all": ["transactions", "offi_transactions"],
        "silv": ["silv_transactions"],
        "villa": ["rh_transactions"],
        "house": ["sh_transactions"],
        "nrg": ["nrg_transactions"],
    }
    if asset not in TABLE_MAP:
        raise HTTPException(400, "asset must be apt|offi|all|silv|villa|house|nrg")
    tables = TABLE_MAP[asset]

    today = date.today()
    cur_y, cur_m = today.year, today.month
    if cur_m == 1:
        prev_y, prev_m = cur_y - 1, 12
    else:
        prev_y, prev_m = cur_y, cur_m - 1
    yesterday = (today - timedelta(days=1)).isoformat()
    yoy_y_cur, yoy_m_cur = cur_y - 1, cur_m
    yoy_y_prev, yoy_m_prev = prev_y - 1, prev_m
    years_3 = (cur_y - 1, cur_y - 2, cur_y - 3)
    try:
        ly_today_str = today.replace(year=cur_y - 1).isoformat()
    except ValueError:
        ly_today_str = (today - timedelta(days=365)).isoformat()

    # 단일 PIVOT 쿼리 — 필요한 deal_year/month 만 WHERE 로 좁히고 CASE 분기.
    needed_years = sorted(set([cur_y, prev_y, yoy_y_cur, yoy_y_prev, *years_3, prev_y - 1]))
    needed_months = sorted(set([cur_m, prev_m]))
    yr_placeholders = ",".join(["?"] * len(needed_years))
    mo_placeholders = ",".join(["?"] * len(needed_months))

    def pivot_sql(table: str) -> str:
        return f"""
        SELECT substr(sgg_cd,1,2) AS sido,
          SUM(CASE WHEN date(inserted_at,'+9 hours')=? THEN 1 ELSE 0 END) AS filed_total,
          SUM(CASE WHEN date(inserted_at,'+9 hours')=? AND deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS filed_cur,
          SUM(CASE WHEN date(inserted_at,'+9 hours')=? AND deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS filed_prev,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS cum_cur,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS cum_prev,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS yoy_cur,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS yoy_prev,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS y1_cur,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS y2_cur,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS y3_cur,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS y1_prev,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS y2_prev,
          SUM(CASE WHEN deal_year=? AND deal_month=? THEN 1 ELSE 0 END) AS y3_prev,
          SUM(CASE WHEN deal_year=? AND deal_month=? AND date(inserted_at) <= ? THEN 1 ELSE 0 END) AS yoy_at_today
        FROM {table}
        WHERE sgg_cd IS NOT NULL
          AND is_cancelled = 0
          AND deal_year IN ({yr_placeholders})
          AND deal_month IN ({mo_placeholders})
        GROUP BY sido
        """

    # '오늘 신고접수'의 기준일 — **KST 달력일**이다.
    #
    # 예전엔 MAX(date(inserted_at)) 를 썼는데(자정 넘어 도는 야간수집 대응), 두 가지가 겹쳐
    # 매일 사용자에게 틀린 숫자를 보여줬다:
    #   ① date(inserted_at) 는 UTC라 09시(KST)에 날짜가 바뀐다 → 오전엔 어제 것을 '오늘'로 표시
    #   ② 낮에 부분 재수집이 한 번만 돌아도 MAX가 그쪽으로 튀어, 하루 누적이 그 몇 건으로 붕괴
    #      (2026-07-23 실측: 경기 재수집 120건이 들어오자 전국 1,536 → 117)
    # 15시·18시 refresh 가 돌 때마다 ②가 재현되므로 매일 오후에 숫자가 무너지고 있었다.
    #
    # KST 달력일로 세고, 오늘 적재가 아직 없으면(자정~새벽 수집 전) 어제로 내린다.
    with _open_db() as _c0:
        _today_kst = _c0.execute("SELECT date('now','+9 hours')").fetchone()[0]
        _n = 0
        for _t in tables:
            _n += _c0.execute(
                f"SELECT COUNT(*) FROM {_t} WHERE date(inserted_at,'+9 hours')=?",
                (_today_kst,)).fetchone()[0]
        if _n:
            filed_ref = _today_kst
        else:
            filed_ref = _c0.execute(
                "SELECT date('now','+9 hours','-1 days')").fetchone()[0]

    param_block = (
        filed_ref,                          # filed_total
        filed_ref, cur_y, cur_m,            # filed_cur
        filed_ref, prev_y, prev_m,          # filed_prev
        cur_y, cur_m,                       # cum_cur
        prev_y, prev_m,                     # cum_prev
        yoy_y_cur, yoy_m_cur,               # yoy_cur
        yoy_y_prev, yoy_m_prev,             # yoy_prev
        years_3[0], cur_m,                  # y1_cur
        years_3[1], cur_m,                  # y2_cur
        years_3[2], cur_m,                  # y3_cur
        years_3[0], prev_m,                 # y1_prev
        years_3[1], prev_m,                 # y2_prev
        years_3[2], prev_m,                 # y3_prev
        yoy_y_cur, yoy_m_cur, ly_today_str, # yoy_at_today
        *needed_years, *needed_months,
    )

    cols = ["sido","filed_total","filed_cur","filed_prev",
            "cum_cur","cum_prev","yoy_cur","yoy_prev",
            "y1_cur","y2_cur","y3_cur","y1_prev","y2_prev","y3_prev",
            "yoy_at_today"]

    agg: dict[str, dict] = {}  # sido → cols dict
    with _open_db() as c:
        for table in tables:
            for row in c.execute(pivot_sql(table), param_block).fetchall():
                sido = row[0]
                if not sido:
                    continue
                rec = agg.setdefault(sido, {k: 0.0 for k in cols if k != "sido"})
                for k, v in zip(cols[1:], row[1:]):
                    rec[k] += float(v or 0)

        # filed_total 은 위 PIVOT 안에서 계산하면 안 된다 — PIVOT 은 deal_year/month IN(...)
        # 으로 좁혀진 집합이라, 몇 달 전 계약이 뒤늦게 신고된 건이 통째로 빠진다.
        # 실측(2026-07-23): 경기 적재 469건 중 432건만 잡혀 37건(8%)이 사라졌다.
        # '오늘 신고접수'는 계약월과 무관하게 그날 접수분 전부여야 하므로 따로 센다.
        filed_by_sido: dict[str, float] = {}
        for table in tables:
            for sido, n in c.execute(
                f"SELECT substr(sgg_cd,1,2) sido, COUNT(*) FROM {table} "
                f"WHERE sgg_cd IS NOT NULL AND is_cancelled=0 "
                f"  AND date(inserted_at,'+9 hours')=? GROUP BY sido", (filed_ref,)):
                if sido:
                    filed_by_sido[sido] = filed_by_sido.get(sido, 0.0) + float(n or 0)
        for sido, n in filed_by_sido.items():
            agg.setdefault(sido, {k: 0.0 for k in cols if k != "sido"})["filed_total"] = n
        for sido, rec in agg.items():          # 적재 0인 시도는 0으로 덮어야 옛 값이 안 남는다
            if sido not in filed_by_sido:
                rec["filed_total"] = 0.0

    def _change(now, was):
        if now is None or was is None or was == 0:
            return None
        return (now - was) / was

    # 신고 lag 모델: 거래 신고 의무 30일. M 일짜리 달의 거래는 1일~M+30일
    # 사이에 신고 들어옴. 오늘이 1일부터 cur_dom 일째인 경우,
    # 진행률 = (오늘까지 경과 일수) / (월 길이 + 30).
    # (균등 분포 + 균등 lag 가정. 실제는 직후/마감 직전 몰림 있지만 1차 근사로 OK)
    from calendar import monthrange
    def progress(year: int, month: int) -> float:
        month_len = monthrange(year, month)[1]
        total = month_len + 30
        # 해당 달의 1일부터 오늘까지 경과 일수 (cap month_len+30)
        first = date(year, month, 1)
        elapsed = (today - first).days + 1
        elapsed = max(0, min(elapsed, total))
        return elapsed / total
    prog_cur = progress(cur_y, cur_m)
    prog_prev = progress(prev_y, prev_m)

    def make_rec(sido: str, d: dict) -> dict:
        # 3년 평균 (해당 연도에 데이터 있으면 카운트)
        cur_vals = [d.get(k, 0) for k in ("y1_cur","y2_cur","y3_cur") if d.get(k, 0) > 0]
        prev_vals = [d.get(k, 0) for k in ("y1_prev","y2_prev","y3_prev") if d.get(k, 0) > 0]
        avg3_cur = sum(cur_vals)/len(cur_vals) if cur_vals else None
        avg3_prev = sum(prev_vals)/len(prev_vals) if prev_vals else None

        actual_cur = d.get("cum_cur", 0)
        actual_prev = d.get("cum_prev", 0)
        # 단순 비율 예측: actual / progress. progress<=0 보호.
        pred_cur = (actual_cur / prog_cur) if (actual_cur > 0 and prog_cur > 0) else None
        pred_prev = (actual_prev / prog_prev) if (actual_prev > 0 and prog_prev > 0) else None

        rec = {
            "region_code": sido,
            "region_name": SIDO_NAMES.get(sido, sido),
            "filed_total": int(d.get("filed_total", 0)),
            "filed_current": int(d.get("filed_cur", 0)),
            "filed_prev": int(d.get("filed_prev", 0)),
            "current_month_count": int(actual_cur),
            "prev_month_count": int(d.get("cum_prev", 0)),
            "yoy_cur_actual": int(d.get("yoy_cur", 0)) or None,
            "yoy_prev_actual": int(d.get("yoy_prev", 0)) or None,
            "avg3y_cur_actual": avg3_cur,
            "avg3y_prev_actual": avg3_prev,
            "current_month_pred": pred_cur,
            "prev_month_pred": pred_prev,
        }
        rec["yoy_cur_change"] = _change(pred_cur, rec["yoy_cur_actual"])
        rec["yoy_prev_change"] = _change(pred_prev, rec["yoy_prev_actual"])
        rec["avg3y_cur_change"] = _change(pred_cur, avg3_cur)
        rec["avg3y_prev_change"] = _change(pred_prev, avg3_prev)
        return rec

    # 전국 합계 — 시도는 표준 배열 순서(서울→부산→…→제주)로
    all_sidos = set(agg.keys()) | set(SIDO_NAMES.keys())
    items = []
    nat_agg = {k: 0.0 for k in cols if k != "sido"}
    for sido in sorted(all_sidos, key=sido_rank):
        d = agg.get(sido, {k: 0.0 for k in cols if k != "sido"})
        items.append(make_rec(sido, d))
        for k, v in d.items():
            nat_agg[k] += v
    nat = make_rec("00", nat_agg)
    nat["region_name"] = "전국"

    return {
        "asset": asset,
        "as_of": today.isoformat(),
        "filed_date": filed_ref,
        "current_month": f"{cur_y}-{cur_m:02d}",
        "prev_month": f"{prev_y}-{prev_m:02d}",
        "yoy_cur_month": f"{yoy_y_cur}-{yoy_m_cur:02d}",
        "yoy_prev_month": f"{yoy_y_prev}-{yoy_m_prev:02d}",
        "national": nat,
        "regions": items,
    }


# ===========================================================================
# 중개사무소 리뷰
#
# 두 종류:
#   - 일반리뷰(general): 의견(body)만. 로그인 회원이면 누구나. 바로 게시(published).
#                        별점 없음.
#   - 인증리뷰(verified): 거래 입증 서류(계약서/확인설명서 등)를 첨부 → 'pending'.
#                        관리자가 서류를 확인해 승인하면 'approved' = (거래인증) 뱃지 +
#                        별점이 평점 집계에 반영. 서류 파일은 승인/거부 시점에 삭제
#                        (민감 개인정보라 장기 보관 안 함). 평점 집계는 approved 인증
#                        리뷰만 대상.
#
# 로그인 시스템은 아직 없으므로 author_id 는 NULL, author_name 은 입력값(기본 '익명').
# 리뷰는 스크래핑 데이터와 라이프사이클이 달라 별도 DB(reviews.sqlite)에 보관 —
# collector 의 재수집/재생성에 영향받지 않게.
# ===========================================================================
REVIEWS_DB: Path = DB_PATH.parent / "reviews.sqlite"
REVIEW_DOCS_DIR: Path = DB_PATH.parent / "review_docs"
FORUM_IMG_DIR: Path = DB_PATH.parent / "forum_images"
BIZ_CONTRACT_DIR: Path = DB_PATH.parent / "biz_contracts"   # 계약서 원본(외부 서빙 안 함)
_REVIEW_DOC_MAX_BYTES = 10 * 1024 * 1024  # 10MB
_REVIEW_DOC_EXTS = {".pdf", ".png", ".jpg", ".jpeg", ".webp", ".heic"}


def _init_reviews_db() -> None:
    REVIEW_DOCS_DIR.mkdir(parents=True, exist_ok=True)
    FORUM_IMG_DIR.mkdir(parents=True, exist_ok=True)
    BIZ_CONTRACT_DIR.mkdir(parents=True, exist_ok=True)
    with sqlite3.connect(REVIEWS_DB) as c:
        c.executescript(
            """
            CREATE TABLE IF NOT EXISTS realtor_reviews (
              id          INTEGER PRIMARY KEY AUTOINCREMENT,
              realtor_id  TEXT NOT NULL,
              author_id   TEXT,                 -- 추후 로그인 사용자 id
              author_name TEXT NOT NULL DEFAULT '익명',
              review_type TEXT NOT NULL CHECK (review_type IN ('general','verified')),
              rating      INTEGER,              -- 인증리뷰만 (1~5)
              body        TEXT NOT NULL,
              status      TEXT NOT NULL,        -- general: published / verified: pending|approved|rejected
              doc_path    TEXT,                 -- 검수 대기 동안만 임시 보관, 결정 시 삭제
              doc_name    TEXT,
              reject_reason TEXT,
              created_at  TEXT NOT NULL DEFAULT (datetime('now')),
              decided_at  TEXT
            );
            CREATE INDEX IF NOT EXISTS rr_realtor_idx ON realtor_reviews(realtor_id, status);
            CREATE INDEX IF NOT EXISTS rr_status_idx  ON realtor_reviews(status);

            CREATE TABLE IF NOT EXISTS user_profiles (
              user_id        TEXT PRIMARY KEY,
              member_no      INTEGER,             -- 내부 회원번호(전화인증 시 발급, 100001~)
              phone          TEXT,
              phone_verified INTEGER NOT NULL DEFAULT 0,
              provider       TEXT,                -- 가입 경로: kakao | google | email ...
              updated_at     TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE TABLE IF NOT EXISTS phone_otp (
              user_id    TEXT PRIMARY KEY,
              phone      TEXT NOT NULL,
              code       TEXT NOT NULL,
              expires_at TEXT NOT NULL,
              attempts   INTEGER NOT NULL DEFAULT 0,
              sent_at    TEXT NOT NULL DEFAULT (datetime('now'))
            );

            -- 포인트 거래 원장(감사용). 잔액은 user_profiles.points 에 캐시.
            CREATE TABLE IF NOT EXISTS point_ledger (
              id            INTEGER PRIMARY KEY AUTOINCREMENT,
              user_id       TEXT NOT NULL,
              delta         INTEGER NOT NULL,
              reason        TEXT NOT NULL,   -- signup|ai_use|review|referral|resident|admin
              ref           TEXT,
              balance_after INTEGER,
              created_at    TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE INDEX IF NOT EXISTS pl_user_idx ON point_ledger(user_id, id);

            -- 아파트 단지 리뷰 (한 단지에 여러 건 허용 — 시간당 한도로 스팸 방지)
            CREATE TABLE IF NOT EXISTS complex_reviews (
              id          INTEGER PRIMARY KEY AUTOINCREMENT,
              complex_no  TEXT NOT NULL,
              user_id     TEXT NOT NULL,
              author_name TEXT,
              rating      INTEGER,           -- 1~5
              body        TEXT NOT NULL,
              resident    INTEGER NOT NULL DEFAULT 0,  -- 작성시 입주민 인증 뱃지 여부
              status      TEXT NOT NULL DEFAULT 'published',
              created_at  TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE INDEX IF NOT EXISTS cr_complex_idx ON complex_reviews(complex_no, status);
            CREATE INDEX IF NOT EXISTS cr_user_recent_idx ON complex_reviews(user_id, created_at);

            -- 입주민 인증 (서류 → 관리자 승인 → 입주민 뱃지)
            CREATE TABLE IF NOT EXISTS resident_verifications (
              id            INTEGER PRIMARY KEY AUTOINCREMENT,
              user_id       TEXT NOT NULL,
              complex_no    TEXT NOT NULL,
              doc_path      TEXT,
              doc_name      TEXT,
              status        TEXT NOT NULL DEFAULT 'pending',  -- pending|approved|rejected
              reject_reason TEXT,
              created_at    TEXT NOT NULL DEFAULT (datetime('now')),
              decided_at    TEXT
            );
            CREATE INDEX IF NOT EXISTS rv_user_idx ON resident_verifications(user_id, complex_no);
            CREATE INDEX IF NOT EXISTS rv_status_idx ON resident_verifications(status);

            -- 토론장: 글
            CREATE TABLE IF NOT EXISTS forum_posts (
              id          INTEGER PRIMARY KEY AUTOINCREMENT,
              user_id     TEXT NOT NULL,
              nickname    TEXT NOT NULL,
              title       TEXT NOT NULL,
              body        TEXT NOT NULL DEFAULT '',
              image_path  TEXT,                          -- 첨부 이미지(공유→토론장 등)
              up          INTEGER NOT NULL DEFAULT 0,     -- 추천 수(캐시)
              down        INTEGER NOT NULL DEFAULT 0,     -- 비추천 수(캐시)
              comment_count INTEGER NOT NULL DEFAULT 0,   -- 댓글 수(캐시)
              status      TEXT NOT NULL DEFAULT 'published',  -- published|hidden
              created_at  TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE INDEX IF NOT EXISTS fp_created_idx ON forum_posts(status, created_at DESC);
            CREATE INDEX IF NOT EXISTS fp_user_idx ON forum_posts(user_id);

            -- 토론장: 댓글
            CREATE TABLE IF NOT EXISTS forum_comments (
              id          INTEGER PRIMARY KEY AUTOINCREMENT,
              post_id     INTEGER NOT NULL,
              user_id     TEXT NOT NULL,
              nickname    TEXT NOT NULL,
              body        TEXT NOT NULL,
              up          INTEGER NOT NULL DEFAULT 0,
              down        INTEGER NOT NULL DEFAULT 0,
              status      TEXT NOT NULL DEFAULT 'published',
              created_at  TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE INDEX IF NOT EXISTS fc_post_idx ON forum_comments(post_id, status, created_at);

            -- 토론장: 추천/비추천 (사용자×대상 1표, 토글)
            CREATE TABLE IF NOT EXISTS forum_votes (
              user_id     TEXT NOT NULL,
              target_type TEXT NOT NULL,   -- post|comment
              target_id   INTEGER NOT NULL,
              value       INTEGER NOT NULL, -- +1 추천 / -1 비추천
              created_at  TEXT NOT NULL DEFAULT (datetime('now')),
              PRIMARY KEY (user_id, target_type, target_id)
            );

            -- ── 중개사 라운지 ──────────────────────────────────────────
            -- 계정 ↔ 중개사무소 1:1 연동(전화매칭 또는 서류승인). 여러 곳 매칭 시 사용자가
            -- 하나를 골라 여기 저장 → 라운지 입장 시 이 선택을 사용.
            CREATE TABLE IF NOT EXISTS realtor_members (
              user_id       TEXT PRIMARY KEY,
              realtor_id    TEXT NOT NULL,
              method        TEXT NOT NULL DEFAULT 'phone',  -- phone | doc
              matched_phone TEXT,
              created_at    TEXT NOT NULL DEFAULT (datetime('now')),
              updated_at    TEXT
            );
            -- 정보수정요청 → 관리자 즉시 확인
            CREATE TABLE IF NOT EXISTS realtor_edit_requests (
              id          INTEGER PRIMARY KEY AUTOINCREMENT,
              user_id     TEXT NOT NULL,
              realtor_id  TEXT NOT NULL,
              member_no   INTEGER,
              content     TEXT NOT NULL,
              status      TEXT NOT NULL DEFAULT 'pending',  -- pending|done|rejected
              admin_note  TEXT,
              created_at  TEXT NOT NULL DEFAULT (datetime('now')),
              resolved_at TEXT
            );
            CREATE INDEX IF NOT EXISTS rer_status_idx ON realtor_edit_requests(status, created_at DESC);
            -- 전화매칭 실패 시 서류제출→관리자승인 보조 인증
            CREATE TABLE IF NOT EXISTS realtor_verifications (
              id           INTEGER PRIMARY KEY AUTOINCREMENT,
              user_id      TEXT NOT NULL,
              realtor_id   TEXT,
              claimed_name TEXT,
              doc_path     TEXT,
              status       TEXT NOT NULL DEFAULT 'pending',  -- pending|approved|rejected
              admin_note   TEXT,
              created_at   TEXT NOT NULL DEFAULT (datetime('now')),
              reviewed_at  TEXT
            );
            CREATE INDEX IF NOT EXISTS rvf_status_idx ON realtor_verifications(status, created_at DESC);
            -- 홈페이지 상담신청 리드(라운지·관리자에서 확인)
            CREATE TABLE IF NOT EXISTS consultation_leads (
              id          INTEGER PRIMARY KEY AUTOINCREMENT,
              realtor_id  TEXT NOT NULL,
              name        TEXT,
              phone       TEXT,
              message     TEXT,
              source      TEXT DEFAULT 'homepage',
              status      TEXT NOT NULL DEFAULT 'new',  -- new|read|done
              created_at  TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE INDEX IF NOT EXISTS leads_realtor_idx ON consultation_leads(realtor_id, status, created_at DESC);
            -- 중개사 홈페이지(빌더 산출물) — Phase B
            CREATE TABLE IF NOT EXISTS realtor_homepages (
              realtor_id   TEXT PRIMARY KEY,
              user_id      TEXT NOT NULL,
              slug         TEXT,
              slogan       TEXT,
              intro        TEXT,
              specialties  TEXT,
              biz_hours    TEXT,
              kakao_url    TEXT,
              consult_tel  TEXT,
              map_memo     TEXT,
              photo_apt    TEXT,
              photo_rep    TEXT,
              photo_office TEXT,
              published    INTEGER NOT NULL DEFAULT 0,
              created_at   TEXT NOT NULL DEFAULT (datetime('now')),
              updated_at   TEXT
            );
            CREATE UNIQUE INDEX IF NOT EXISTS rh_slug_unique
              ON realtor_homepages(slug) WHERE slug IS NOT NULL;
            CREATE TABLE IF NOT EXISTS realtor_fav_complexes (
              user_id      TEXT NOT NULL,
              complex_no   TEXT NOT NULL,
              complex_name TEXT,
              created_at   TEXT NOT NULL DEFAULT (datetime('now')),
              PRIMARY KEY (user_id, complex_no)
            );
            CREATE TABLE IF NOT EXISTS realtor_fav_offices (
              user_id      TEXT NOT NULL,
              realtor_id   TEXT NOT NULL,
              created_at   TEXT NOT NULL DEFAULT (datetime('now')),
              PRIMARY KEY (user_id, realtor_id)
            );
            CREATE TABLE IF NOT EXISTS push_subscriptions (
              user_id     TEXT NOT NULL,
              endpoint    TEXT NOT NULL,
              p256dh      TEXT NOT NULL,
              auth        TEXT NOT NULL,
              ua          TEXT,
              created_at  TEXT NOT NULL DEFAULT (datetime('now')),
              PRIMARY KEY (endpoint)
            );
            CREATE INDEX IF NOT EXISTS push_user_idx ON push_subscriptions(user_id);

            -- 직원(소속공인중개사·중개보조원) 초대장 — 대표가 발송, 해당 번호가 전화인증하면 자동 승인
            CREATE TABLE IF NOT EXISTS realtor_staff_invites (
              id           INTEGER PRIMARY KEY AUTOINCREMENT,
              realtor_id   TEXT NOT NULL,
              phone_digits TEXT NOT NULL,      -- 숫자만
              role         TEXT NOT NULL,      -- assoc(소속공인중개사) | assist(중개보조원)
              name         TEXT,
              invited_by   TEXT NOT NULL,      -- 대표 user_id
              created_at   TEXT NOT NULL DEFAULT (datetime('now')),
              used_at      TEXT
            );
            CREATE INDEX IF NOT EXISTS rsi_phone_idx ON realtor_staff_invites(phone_digits, used_at);

            -- 고객 요건 — 한 고객이 여러 건을 갖는다(구함 2 + 내놓음 1 …).
            -- 고객 원장의 한 행이자, 매칭·거래계획의 단위. 설계안 design/lounge_customer_ledger_설계안.md
            CREATE TABLE IF NOT EXISTS biz_needs (
              id           INTEGER PRIMARY KEY AUTOINCREMENT,
              client_uid   TEXT,               -- 클라이언트 생성 UUID. 오프라인 재전송이 같은 행을
                                               -- 두 번 만들지 않게 하는 멱등키(설계안 §2-4)
              user_id      TEXT NOT NULL,
              realtor_id   TEXT,
              customer_id  INTEGER,
              kind         TEXT NOT NULL DEFAULT '구함',   -- 구함 | 내놓음
              ptype        TEXT,               -- 물건 종류(아파트·상가·토지…). 매물의 type 과 같은 말.
                                               -- 이게 없으면 상가 손님에게 아파트를 들이밀게 된다
              trade        TEXT,               -- A1 매매 | B1 전세 | B2 월세
              role         TEXT,               -- 주안 | 대안 | 보유
              budget_min   INTEGER, budget_max INTEGER,
              ask_price    INTEGER,
              sido TEXT, sigungu TEXT, dong TEXT, complex_no TEXT, address TEXT,
              listing_id   INTEGER,            -- 내놓은 요건이 가리키는 우리 매물장 행
              bld_dong     TEXT,               -- 내놓음: 건물 동(지역 동과 다르다)
              ho           TEXT,               -- 내놓음: 호
              area_m2      REAL,               -- 내놓음: 전용면적(하나). 구하는 쪽만 범위를 쓴다
              floor_info   TEXT,               -- 내놓음: 층
              area_min     REAL, area_max REAL,
              status       TEXT NOT NULL DEFAULT '문의',   -- 문의|미팅|보류|완료
              settle_date  TEXT,               -- 잔금 시기. 구함·내놓음 양쪽에 공통인 축이다
                                               -- (파는 쪽에 '입주 희망'은 말이 안 된다)
              raw_text     TEXT,               -- 원문. 구조화가 실패해도 이건 남는다
              extra_json   TEXT,               -- 사용자 정의 열
              src_request_id INTEGER,          -- 콕집요청에서 승격된 경우
              sort_key     REAL,
              memo         TEXT,
              created_at   TEXT NOT NULL DEFAULT (datetime('now')),
              updated_at   TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE UNIQUE INDEX IF NOT EXISTS bzn_uid ON biz_needs(client_uid)
              WHERE client_uid IS NOT NULL;
            CREATE INDEX IF NOT EXISTS bzn_rid ON biz_needs(realtor_id, updated_at DESC);
            CREATE INDEX IF NOT EXISTS bzn_cust ON biz_needs(customer_id);

            -- 계약서 업로드 → AI 파싱 (관리자 가오픈, 추후 중개사 회원 개방)
            CREATE TABLE IF NOT EXISTS biz_contracts (
              id           INTEGER PRIMARY KEY AUTOINCREMENT,
              user_id      TEXT NOT NULL,
              realtor_id   TEXT,               -- 연동 사무소(있으면)
              doc_path     TEXT,
              parsed_json  TEXT,               -- Gemini 추출 결과(JSON)
              status       TEXT NOT NULL DEFAULT 'parsed',   -- parsed|confirmed
              created_at   TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE INDEX IF NOT EXISTS bzc_user_idx ON biz_contracts(user_id, created_at DESC);

            -- 중개사 자체 캘린더 일정 (계약일·중도금·잔금·입주·만기 등)
            CREATE TABLE IF NOT EXISTS biz_events (
              id           INTEGER PRIMARY KEY AUTOINCREMENT,
              user_id      TEXT NOT NULL,
              realtor_id   TEXT,
              contract_id  INTEGER,            -- 출처 계약서(수기 입력이면 NULL)
              title        TEXT NOT NULL,
              event_date   TEXT NOT NULL,      -- YYYY-MM-DD
              event_time   TEXT,               -- HH:MM (선택)
              event_type   TEXT NOT NULL DEFAULT '기타',  -- 계약|중도금|잔금|입주|만기|기타
              memo         TEXT,
              created_at   TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE INDEX IF NOT EXISTS bze_user_date_idx ON biz_events(user_id, event_date);

            -- 고객(계약 당사자) — 중개사 **본인 사무소 전용** CRM. 계약서에서 추출한 임대인·임차인·
            -- 매도인·매수인을 (이름+연락처)로 dedupe해 누적. 주민등록번호·계좌는 저장하지 않는다.
            -- 다른 기능(상담리드·매물 등)에서 customer_id로 연결한다.
            CREATE TABLE IF NOT EXISTS biz_customers (
              id           INTEGER PRIMARY KEY AUTOINCREMENT,
              user_id      TEXT NOT NULL,
              realtor_id   TEXT,
              name         TEXT NOT NULL,
              phone        TEXT,
              address      TEXT,
              is_company   INTEGER NOT NULL DEFAULT 0,
              memo         TEXT,
              created_at   TEXT NOT NULL DEFAULT (datetime('now')),
              updated_at   TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE UNIQUE INDEX IF NOT EXISTS bzcu_uniq ON biz_customers(user_id, name, COALESCE(phone,''));
            CREATE INDEX IF NOT EXISTS bzcu_user_idx ON biz_customers(user_id, updated_at DESC);

            -- 계약 ↔ 고객(역할) 연결 — 한 고객이 여러 계약에, 한 계약에 여러 당사자
            CREATE TABLE IF NOT EXISTS biz_contract_parties (
              contract_id  INTEGER NOT NULL,
              customer_id  INTEGER NOT NULL,
              role         TEXT NOT NULL,      -- 임대인|임차인|매도인|매수인|중개사
              PRIMARY KEY (contract_id, customer_id, role)
            );
            CREATE INDEX IF NOT EXISTS bzcp_cust_idx ON biz_contract_parties(customer_id);

            -- 고객 활동 기록 — 언제 통화했고 뭘 보냈는지. 요건(무엇을 원하는가)만으로는
            -- '이 손님 어디까지 얘기했더라'가 안 남아서, 중개사가 결국 수첩을 따로 쓴다.
            -- 사람이 적는 것(통화·문자·방문·메모)과 시스템이 남기는 것(요건 등록·진행 변경)을
            -- auto 로만 구분해 한 줄기로 쌓는다.
            CREATE TABLE IF NOT EXISTS biz_activities (
              id           INTEGER PRIMARY KEY AUTOINCREMENT,
              user_id      TEXT NOT NULL,
              realtor_id   TEXT,
              customer_id  INTEGER NOT NULL,
              need_id      INTEGER,           -- 특정 요건에 걸린 일이면
              kind         TEXT NOT NULL,     -- 통화|문자|방문|메모|발송|요건|진행
              body         TEXT,
              auto         INTEGER NOT NULL DEFAULT 0,
              created_at   TEXT NOT NULL DEFAULT (datetime('now'))
            );
            CREATE INDEX IF NOT EXISTS bza_cust_idx ON biz_activities(customer_id, id DESC);
            CREATE INDEX IF NOT EXISTS bza_rid_idx ON biz_activities(realtor_id, id DESC);
            """
        )
        # 기존 테이블에 신규 컬럼 보강(있으면 무시) — 전화번호=유니크 비즈니스키, 회원번호=내부키
        for ddl in (
            "ALTER TABLE biz_contracts ADD COLUMN doc_hash TEXT",   # 동일 파일 재파싱 방지(비용 0)
            # biz_needs 는 먼저 배포된 적이 있다 — CREATE TABLE IF NOT EXISTS 는 기존
            # 테이블에 no-op 이라 새 컬럼은 여기서 붙여야 한다.
            "ALTER TABLE biz_needs ADD COLUMN listing_id INTEGER",
            "ALTER TABLE biz_needs ADD COLUMN settle_date TEXT",
            "ALTER TABLE biz_needs ADD COLUMN bld_dong TEXT",
            "ALTER TABLE biz_needs ADD COLUMN ho TEXT",
            "ALTER TABLE biz_needs ADD COLUMN area_m2 REAL",
            "ALTER TABLE biz_needs ADD COLUMN floor_info TEXT",
            "ALTER TABLE biz_needs ADD COLUMN ptype TEXT",
            # doc_hash 보강 뒤에 인덱스(컬럼 생성 전에 만들면 실패) — 재업로드 조회용
            "CREATE INDEX IF NOT EXISTS bzc_hash_idx ON biz_contracts(user_id, doc_hash)",
            "ALTER TABLE user_profiles ADD COLUMN member_no INTEGER",
            "ALTER TABLE user_profiles ADD COLUMN provider TEXT",
            "ALTER TABLE user_profiles ADD COLUMN points INTEGER NOT NULL DEFAULT 0",
            "ALTER TABLE user_profiles ADD COLUMN referred_by INTEGER",       # 추천인 member_no
            "ALTER TABLE user_profiles ADD COLUMN signup_awarded INTEGER NOT NULL DEFAULT 0",  # 가입(로그인) 30p
            "ALTER TABLE user_profiles ADD COLUMN phone_bonus_awarded INTEGER NOT NULL DEFAULT 0",  # 전화인증 100p
            "ALTER TABLE user_profiles ADD COLUMN nickname TEXT",             # 글·리뷰·AI 호칭용
            "ALTER TABLE user_profiles ADD COLUMN agreed_terms_at TEXT",      # 이용약관·개인정보 동의 시각
            "ALTER TABLE user_profiles ADD COLUMN consent_version TEXT",      # 동의한 약관/방침 버전
            "ALTER TABLE user_profiles ADD COLUMN marketing_opt_in INTEGER NOT NULL DEFAULT 0",  # 마케팅 수신(선택)
            "ALTER TABLE user_profiles ADD COLUMN marketing_opt_in_at TEXT",  # 마케팅 동의/철회 시각
            "ALTER TABLE user_profiles ADD COLUMN age_confirmed_at TEXT",     # 만14세 이상 자가확인 시각
            "ALTER TABLE user_profiles ADD COLUMN nickname_awarded INTEGER NOT NULL DEFAULT 0",  # 닉네임 20p 1회
            # 직원 시스템 — 기존 연결자(전화매칭=대표번호 인증)는 전부 대표(owner)·활성(active)
            "ALTER TABLE realtor_members ADD COLUMN role TEXT NOT NULL DEFAULT 'owner'",   # owner|assoc|assist
            "ALTER TABLE realtor_members ADD COLUMN status TEXT NOT NULL DEFAULT 'active'",  # active|pending
            "ALTER TABLE realtor_members ADD COLUMN staff_name TEXT",  # 직원 명단에서 고른/입력한 이름
            "ALTER TABLE realtor_verifications ADD COLUMN role TEXT NOT NULL DEFAULT 'owner'",  # 서류인증 역할(owner|assoc|assist)
        ):
            try:
                c.execute(ddl)
            except sqlite3.OperationalError:
                pass  # 이미 존재
        # 인증된 전화번호는 전 회원 통틀어 유일 (취소 시 phone=NULL 처리되어 재사용 가능)
        c.execute(
            "CREATE UNIQUE INDEX IF NOT EXISTS up_phone_unique "
            "ON user_profiles(phone) WHERE phone IS NOT NULL AND phone_verified=1"
        )
        # 닉네임 전 회원 통틀어 유일 (대소문자 무시)
        c.execute(
            "CREATE UNIQUE INDEX IF NOT EXISTS up_nickname_unique "
            "ON user_profiles(lower(nickname)) WHERE nickname IS NOT NULL"
        )
        # 단지리뷰 1인1건 제약 제거 — 여러 건 허용(시간당 한도로 스팸 방지).
        c.execute("DROP INDEX IF EXISTS cr_user_complex")
        c.commit()


_init_reviews_db()


# ─── 포인트 · 계급 시스템 ───────────────────────────────────
# 계급: 누적(획득) 포인트 임계값 기준. 사용으로 잔액이 줄어도 계급은 유지(획득 누계로 산정).
RANKS = [
    # 시장(4,000)까지는 완만, 그 위부터 가파르게 → 대통령 15만
    # 가입 인증만으로 100P → 부린이 유지. 임장러(200)부터 추가 활동 필요.
    # (임계 누적P, 계급명, 대표 이모지)
    (0, "부린이", "🐣"), (200, "임장러", "👟"), (400, "동대표", "🏠"),
    (700, "관리소장", "🧰"), (1100, "단지대표", "🏘️"), (1600, "통장", "🤝"),
    (2200, "주민센터장", "🏢"), (3000, "구청장", "🏛️"), (4000, "시장", "🎖️"),
    (8000, "도지사", "🗺️"), (15000, "장관", "💼"), (26000, "국무총리", "🎩"),
    (45000, "국회의원", "⚖️"), (85000, "국회의장", "🔨"), (150000, "대통령", "👑"),
    # "조물주 위에 건물주" 밈 — 대통령 위 조물주, 그 위 건물주(부동산 앱 최종 등급).
    (300000, "조물주", "🌌"), (500000, "건물주", "🏰"),
]
POINTS = {
    "signup": 30,          # 가입(첫 로그인) 즉시 지급
    "nickname": 20,        # 닉네임 최초 설정 시(활동 유도)
    "phone_verify": 100,   # 전화번호 인증 완료 시
    "ai_use": -10,         # AI 1회 사용
    "review": 5,           # 일반 리뷰 작성(중개사/단지)
    "review_verified": 100,# 인증 리뷰(서류 검증 → 관리자 승인 시)
    "comment": 1,          # 토론장 댓글
    "referral": 100,       # 추천으로 가입 1명 성사
    "resident": 50,        # 입주민 인증 승인
    "forum_post": 10,      # 토론장 글 작성
    "admin": 0,            # 관리자 수동 조정(금액은 호출 시 지정)
}
FORUM_POST_DAILY_CAP = 10     # 글 작성 포인트는 하루 최대 N건만(스팸 파밍 방지)
FORUM_COMMENT_DAILY_CAP = 20  # 댓글 포인트 일일 캡(스팸 파밍 방지)
AI_COST = -POINTS["ai_use"]  # AI 1회 비용(양수)


def _rank_for(earned: int) -> dict:
    """누적 획득 포인트 → 계급 정보."""
    idx = 0
    for i, (th, _nm, _em) in enumerate(RANKS):
        if earned >= th:
            idx = i
    nxt = RANKS[idx + 1] if idx + 1 < len(RANKS) else None
    return {"rank": RANKS[idx][1], "emoji": RANKS[idx][2], "level": idx,
            "next_rank": nxt[1] if nxt else None,
            "next_emoji": nxt[2] if nxt else None,
            "next_at": nxt[0] if nxt else None}


def _user_points(c: sqlite3.Connection, user_id: str) -> tuple[int, int]:
    """(현재 잔액, 누적 획득) — 누적은 ledger 의 양수 합."""
    bal = c.execute("SELECT points FROM user_profiles WHERE user_id=?", (user_id,)).fetchone()
    earned = c.execute(
        "SELECT COALESCE(SUM(delta),0) FROM point_ledger WHERE user_id=? AND delta>0 AND reason!='ai_refund'",
        (user_id,)).fetchone()[0]
    return (bal[0] if bal else 0), earned


HOURLY_CREATE_CAP = 30  # 아이디별 시간당 작성 한도(리뷰·토론장 글). 댓글은 제한 없음.


def _enforce_hourly(c: sqlite3.Connection, table: str, user_col: str, user_id: str,
                    cap: int = HOURLY_CREATE_CAP) -> None:
    """최근 1시간 작성 건수가 cap 이상이면 429. 스팸/파밍 방지."""
    n = c.execute(
        f"SELECT COUNT(*) FROM {table} WHERE {user_col}=? AND created_at >= datetime('now','-1 hour')",
        (user_id,)).fetchone()[0]
    if n >= cap:
        raise HTTPException(429, f"시간당 작성 한도({cap}건)를 초과했어요. 잠시 후 다시 시도해주세요.")


def _rank_map(c: sqlite3.Connection, user_ids: list[str]) -> dict:
    """user_id 목록 → {user_id: {rank, emoji, level}} (글·댓글 작성자 계급 표시용)."""
    ids = list({u for u in user_ids if u})
    if not ids:
        return {}
    ph = ",".join("?" * len(ids))
    earned = {r[0]: r[1] for r in c.execute(
        f"SELECT user_id, SUM(delta) FROM point_ledger "
        f"WHERE delta>0 AND user_id IN ({ph}) GROUP BY user_id", ids).fetchall()}
    out = {}
    for u in ids:
        rk = _rank_for(earned.get(u, 0))
        out[u] = {"rank": rk["rank"], "emoji": rk["emoji"], "level": rk["level"],
                  "is_admin": _is_admin_uid(u)}
    return out


def _nick_map(c: sqlite3.Connection, user_ids: list[str]) -> dict:
    """user_id 목록 → {user_id: nickname}. 리뷰 등 작성자 표기를 항상 현재 별명으로
    덮어쓰기 위해 사용 (실명·이메일 등 개인정보는 타인에게 절대 노출 안 함)."""
    ids = list({u for u in user_ids if u})
    if not ids:
        return {}
    ph = ",".join("?" * len(ids))
    return {r[0]: r[1] for r in c.execute(
        f"SELECT user_id, nickname FROM user_profiles "
        f"WHERE user_id IN ({ph}) AND nickname IS NOT NULL", ids).fetchall()}


def _award_points(c: sqlite3.Connection, user_id: str, reason: str,
                  delta: int | None = None, ref: str | None = None) -> int:
    """포인트 적립/차감 + 원장 기록. user_profiles 행이 없으면 생성. 새 잔액 반환.
    호출부가 트랜잭션(commit)을 책임진다."""
    d = POINTS.get(reason, 0) if delta is None else delta
    c.execute("INSERT INTO user_profiles(user_id, updated_at) VALUES(?, datetime('now')) "
              "ON CONFLICT(user_id) DO NOTHING", (user_id,))
    c.execute("UPDATE user_profiles SET points = points + ?, updated_at=datetime('now') "
              "WHERE user_id=?", (d, user_id))
    bal = c.execute("SELECT points FROM user_profiles WHERE user_id=?", (user_id,)).fetchone()[0]
    c.execute("INSERT INTO point_ledger(user_id, delta, reason, ref, balance_after) "
              "VALUES(?,?,?,?,?)", (user_id, d, reason, ref, bal))
    return bal


def _points_block(user_id: str) -> dict:
    """/me·계정용 포인트+계급 묶음."""
    with _reviews_db() as c:
        bal, earned = _user_points(c, user_id)
    return {"points": bal, "earned": earned, "ai_cost": AI_COST, **_rank_for(earned)}


def _spend_ai(user_id: str) -> int:
    """AI 1회 비용 차감. 잔액 부족이면 402(insufficient_points). 새 잔액 반환."""
    with _reviews_db() as c:
        bal, _ = _user_points(c, user_id)
        if bal < AI_COST:
            raise HTTPException(402, detail={
                "code": "insufficient_points", "points": bal, "needed": AI_COST,
                "message": f"포인트가 부족해요. AI 1회에 {AI_COST}P가 필요한데 현재 {bal}P예요. "
                           "리뷰 작성·친구 추천으로 포인트를 모을 수 있어요.",
            })
        new_bal = _award_points(c, user_id, "ai_use")
        c.commit()
    return new_bal


def _refund_ai(user_id: str) -> None:
    """AI 처리 실패 시 차감한 포인트 환불(누적획득·계급엔 미반영). 실패해도 조용히 넘어간다."""
    try:
        with _reviews_db() as c:
            _award_points(c, user_id, "ai_refund", delta=AI_COST)
            c.commit()
    except Exception:
        pass


# (인증/관리자 의존성 current_user·admin_user 는 파일 앞부분 _open_db 근처에 정의됨)


# 이용약관·개인정보처리방침 버전. 문서를 개정하면 이 값을 올려서 재동의를 유도한다.
CONSENT_VERSION = "2026-06-16"


@app.get("/me")
def me(user: dict = Depends(current_user)) -> dict:
    """로그인 사용자 본인 정보 + 관리자 여부 + 인증 전화번호 + 회원번호 + 포인트·계급."""
    with _reviews_db() as c:
        row = c.execute(
            "SELECT phone, phone_verified, member_no, nickname, agreed_terms_at, marketing_opt_in "
            "FROM user_profiles WHERE user_id=?",
            (user["id"],)).fetchone()
        bal, earned = _user_points(c, user["id"])
        is_realtor_member = bool(c.execute(
            "SELECT 1 FROM realtor_members WHERE user_id=?", (user["id"],)).fetchone())
    # 중개사 홍보: 인증번호가 중개사무소와 일치하는데 아직 라운지 미연결이면 안내 노출
    user["realtor_promo"] = None
    if row and row[1] and row[0] and not is_realtor_member:
        cands = _realtor_candidates_by_phone(row[0])
        if cands:
            user["realtor_promo"] = {"office_name": cands[0].get("realtor_name")}
    user["is_realtor_member"] = is_realtor_member   # 라운지 인증 회원 → 로그인 시 라운지로 라우팅
    user["phone_verified"] = bool(row and row[1])
    user["member_no"] = row[2] if row else None
    if row and row[0]:
        user["phone"] = row[0]
    user["nickname"] = row[3] if row else None
    user["needs_nickname"] = not (row and row[3])   # 닉네임 미설정 → 최초 1회 선택 유도
    user["needs_consent"] = not (row and row[4])    # 약관·개인정보 미동의 → 최초 1회 동의 유도
    user["marketing_opt_in"] = bool(row and row[5])
    user["consent_version"] = CONSENT_VERSION
    user["points"] = bal
    user["points_earned"] = earned   # 누적 획득(등급·다음레벨 계산 기준)
    user["ai_cost"] = AI_COST
    rk = _rank_for(earned)
    user.update({k: v for k, v in rk.items()})  # rank, level, next_rank, next_at
    user["next_remaining"] = (rk["next_at"] - earned) if rk["next_at"] is not None else None
    return user


class PageView(BaseModel):
    path: str          # 정규화된 페이지 키(예: /complex/:id, /finder) — 프런트가 정규화
    ref: str | None = None       # 대상 id(단지번호·중개사id 등)
    referrer: str | None = None  # 유입 출처(document.referrer) — 외부 유입경로 집계용


def _referrer_host(ref: str | None) -> str | None:
    """referrer URL → 호스트(소문자, www 제거). 없으면 None."""
    if not ref:
        return None
    try:
        from urllib.parse import urlparse
        h = (urlparse(ref).hostname or "").lower()
        if h.startswith("www."):
            h = h[4:]
        return h[:80] or None
    except Exception:  # noqa: BLE001
        return None


def _traffic_source(host: str | None) -> str:
    """유입 호스트 → 사람이 읽는 유입경로 분류."""
    if not host or host == "(direct)":
        return "직접·앱·북마크"
    h = host
    if "koczip" in h:
        return "사이트 내 이동"
    if "google." in h:
        return "구글 검색"
    if "naver" in h:
        if "search.naver" in h or h.startswith("m.search"):
            return "네이버 검색"
        if "blog.naver" in h:
            return "네이버 블로그"
        if "cafe.naver" in h:
            return "네이버 카페"
        return "네이버(기타)"
    if "search.daum" in h or "daum.net" in h:
        return "다음"
    if "bing." in h:
        return "빙 검색"
    if "instagram" in h:
        return "인스타그램"
    if "facebook" in h or h == "fb.com" or "l.facebook" in h:
        return "페이스북"
    if "youtube" in h or "youtu.be" in h:
        return "유튜브"
    if h == "t.co" or "twitter" in h or h == "x.com":
        return "X(트위터)"
    if "kakao" in h:
        return "카카오"
    return f"기타 · {h}"


@app.post("/events/pageview")
async def log_pageview(pv: PageView, request: Request):
    """SPA 라우트 이동당 1건 — 정확한 '페이지뷰'. API 호출 단위 로그(view_complex 등)는
    단지 1방문에 8~10건이 쌓여 방문수가 부풀므로, 이 깨끗한 이벤트로 페이지 분석을 한다.
    로그인 여부와 무관하게 기록(uid 있으면 귀속). referrer(호스트)로 유입경로도 집계.
    실패는 조용히 무시."""
    p = (pv.path or "").split("?")[0][:120]
    if not p.startswith("/"):
        return {"ok": False}
    uid, email = _jwt_user(request.headers.get("authorization"))
    host = _referrer_host(pv.referrer)
    _log_event(
        "page", user_id=uid, email=email, member_no=_member_no(uid),
        path=p, method="GET", ref=(pv.ref or None), status=200,
        ip=_client_ip(request), user_agent=request.headers.get("user-agent"),
        detail={"r": host or "(direct)"})   # 유입경로 집계용 — 없으면 (direct)
    return {"ok": True}


@app.get("/admin/page-analytics")
def admin_page_analytics(_admin: dict = Depends(admin_user), days: int = 7):
    """페이지별 분석 — 깨끗한 페이지뷰(kind='page') 기준. 페이지마다 조회수·방문자(IP)·
    로그인사용자(uid) + 일별 추이 + 인기 단지(중복 방문 아닌 실제 방문수)."""
    days = min(max(int(days), 1), 90)
    T = f"kind='page' AND date(ts,'+9 hours') >= date('now','+9 hours','-{days} days')"
    with _logs_db() as c:
        has = c.execute("SELECT COUNT(*) FROM event_log WHERE kind='page'").fetchone()[0]
        summary = c.execute(
            f"SELECT COUNT(*), COUNT(DISTINCT ip), COUNT(DISTINCT user_id) FROM event_log WHERE {T}").fetchone()
        pages = [{"key": p, "label": _page_label(p), "views": n, "visitors": v, "users": u}
                 for p, n, v, u in c.execute(
                     f"SELECT path, COUNT(*) n, COUNT(DISTINCT ip) v, COUNT(DISTINCT user_id) u "
                     f"FROM event_log WHERE {T} GROUP BY path ORDER BY n DESC LIMIT 60")]
        # 같은 라벨(예: /complex/:id 여러 단지)로 묶은 집계도 제공
        bylabel: dict = {}
        for pg in pages:
            a = bylabel.setdefault(pg["label"], {"label": pg["label"], "views": 0, "visitors": 0, "users": 0})
            a["views"] += pg["views"]; a["visitors"] += pg["visitors"]; a["users"] += pg["users"]
        grouped = sorted(bylabel.values(), key=lambda x: -x["views"])
        trend = [{"day": d, "views": n, "visitors": v} for d, n, v in c.execute(
            f"SELECT date(ts,'+9 hours') d, COUNT(*), COUNT(DISTINCT ip) FROM event_log WHERE {T} GROUP BY d ORDER BY d")]
        top_complex = [{"ref": r, "visits": n, "visitors": v} for r, n, v in c.execute(
            f"SELECT ref, COUNT(*), COUNT(DISTINCT ip) FROM event_log "
            f"WHERE {T} AND path LIKE '/complex%' AND ref IS NOT NULL AND ref<>'' "
            f"GROUP BY ref ORDER BY 2 DESC LIMIT 15")]
    return {"days": days, "has_data": bool(has), "summary": {
        "views": summary[0], "visitors": summary[1], "users": summary[2]},
        "pages": grouped, "pages_raw": pages, "trend": trend, "top_complex": top_complex}


@app.get("/admin/traffic-sources")
def admin_traffic_sources(_admin: dict = Depends(admin_user), days: int = 7):
    """유입경로 분석 — 페이지뷰(kind='page')의 referrer 호스트를 분류해 접속 IP·조회수로 집계.
    referrer는 배포 이후 기록분만 존재(detail.r). '(direct)'=출처 없는 직접 유입."""
    days = min(max(int(days), 1), 90)
    T = (f"kind='page' AND date(ts,'+9 hours') >= date('now','+9 hours','-{days} days') "
         f"AND json_extract(detail,'$.r') IS NOT NULL")
    agg: dict = {}
    with _logs_db() as c:
        total_pv, tracked = c.execute(
            f"SELECT SUM(CASE WHEN kind='page' AND date(ts,'+9 hours') >= date('now','+9 hours','-{days} days') THEN 1 ELSE 0 END), "
            f"SUM(CASE WHEN {T} THEN 1 ELSE 0 END) FROM event_log").fetchone()
        # 호스트별 집계 → 분류로 합산(외부/직접만; 사이트 내 이동은 별도 표기)
        for host, n, v in c.execute(
                f"SELECT json_extract(detail,'$.r'), COUNT(*), COUNT(DISTINCT ip) FROM event_log WHERE {T} GROUP BY 1"):
            src = _traffic_source(host)
            a = agg.setdefault(src, {"source": src, "views": 0, "visitors": 0})
            a["views"] += n
            a["visitors"] += v
    items = sorted(agg.values(), key=lambda x: -x["visitors"])
    return {"days": days, "items": items,
            "coverage": {"tracked": tracked or 0, "total": total_pv or 0}}


@app.post("/events/login")
def log_login(request: Request, user: dict = Depends(current_user)) -> dict:
    """프런트가 로그인(SIGNED_IN) 직후 호출 — 로그인 기록을 남긴다."""
    _log_event(
        "login", user_id=user["id"], email=user.get("email"),
        provider=user.get("provider"), member_no=_member_no(user["id"]),
        path="/events/login", method="POST", status=200,
        ip=_client_ip(request), user_agent=request.headers.get("user-agent"),
        detail={"name": user.get("name")})
    # 가입(첫 로그인) 즉시 30p — 최초 1회만(signup_awarded 플래그)
    awarded = 0
    with _reviews_db() as c:
        c.execute("INSERT INTO user_profiles(user_id, provider, updated_at) "
                  "VALUES(?,?,datetime('now')) ON CONFLICT(user_id) DO NOTHING",
                  (user["id"], user.get("provider")))
        sa = c.execute("SELECT signup_awarded FROM user_profiles WHERE user_id=?",
                       (user["id"],)).fetchone()
        if not (sa and sa[0]):
            _award_points(c, user["id"], "signup")
            c.execute("UPDATE user_profiles SET signup_awarded=1 WHERE user_id=?", (user["id"],))
            awarded = POINTS["signup"]
            c.commit()
            total = c.execute("SELECT COUNT(*) FROM user_profiles WHERE signup_awarded=1").fetchone()[0]
    if awarded:   # 신규 가입(첫 로그인) — 텔레그램 보고
        try:
            from scripts.tg_notify import tg_send_async
            # 텔레그램은 국외 서버 — 실명 등 개인정보를 싣지 않는다(첫 글자만 마스킹)
            _nm = (user.get("name") or "").strip()
            _masked = (_nm[0] + "*" * (len(_nm) - 1)) if _nm else "이름없음"
            tg_send_async(f"👤 신규 가입 #{total} — {_masked} "
                          f"({_provider_kr(user.get('provider'))})")
        except Exception:
            pass
    return {"ok": True, "awarded": awarded}


def _reviews_db() -> sqlite3.Connection:
    c = sqlite3.connect(REVIEWS_DB)
    c.row_factory = sqlite3.Row
    return c


# ─── 웹 푸시 알림 (TWA/PWA — VAPID) ─────────────────────────────────
def _vapid():
    """(private, public, subject) — env. 미설정이면 None."""
    priv = os.getenv("VAPID_PRIVATE_KEY")
    pub = os.getenv("VAPID_PUBLIC_KEY")
    if not priv or not pub:
        return None
    return priv, pub, os.getenv("VAPID_SUBJECT", "mailto:admin@koczip.com")


def _send_web_push(user_ids, title: str, body: str, url: str = "/", tag: str = "koczip",
                   icon: str = "https://koczip.com/icon-192.png") -> dict:
    """user_ids(list) 의 모든 구독에 웹푸시 발송. 죽은 구독(404/410)은 삭제. 발송 통계 반환."""
    v = _vapid()
    if not v:
        return {"sent": 0, "error": "VAPID not configured"}
    from pywebpush import webpush, WebPushException
    priv, _pub, subject = v
    payload = _json.dumps({"title": title, "body": body, "url": url, "tag": tag, "icon": icon},
                          ensure_ascii=False)
    sent = failed = 0
    dead = []
    ids = [user_ids] if isinstance(user_ids, str) else list(user_ids)
    if not ids:
        return {"sent": 0}
    ph = ",".join("?" * len(ids))
    with _reviews_db() as c:
        subs = c.execute(
            f"SELECT endpoint, p256dh, auth FROM push_subscriptions WHERE user_id IN ({ph})",
            ids).fetchall()
        for s in subs:
            try:
                webpush(
                    subscription_info={"endpoint": s["endpoint"],
                                       "keys": {"p256dh": s["p256dh"], "auth": s["auth"]}},
                    data=payload,
                    vapid_private_key=priv,
                    vapid_claims={"sub": subject},
                    timeout=10)
                sent += 1
            except WebPushException as e:
                failed += 1
                code = getattr(getattr(e, "response", None), "status_code", None)
                if code in (404, 410):       # 만료/해지 구독 → 정리
                    dead.append(s["endpoint"])
            except Exception:
                failed += 1
        for ep in dead:
            c.execute("DELETE FROM push_subscriptions WHERE endpoint=?", (ep,))
    return {"sent": sent, "failed": failed, "pruned": len(dead)}


@app.get("/push/vapid-public-key")
def push_vapid_public_key():
    v = _vapid()
    return {"key": v[1] if v else None}


@app.post("/push/subscribe")
def push_subscribe(body: dict, request: Request, user: dict | None = Depends(current_user_optional)):
    """브라우저 PushSubscription 저장. 로그인 불필요 — 미로그인은 익명(user_id='')으로 저장해
    공지·오늘의 급매 같은 일반 알림을 받게 한다. 로그인하면 같은 endpoint가 그 user_id로 승격
    (ON CONFLICT) 되어 관심단지 등 개인 알림까지 받는다."""
    sub = body.get("subscription") or body
    ep = sub.get("endpoint")
    keys = sub.get("keys") or {}
    if not ep or not keys.get("p256dh") or not keys.get("auth"):
        raise HTTPException(400, "invalid subscription")
    uid = user["id"] if user else ""   # 익명 구독은 빈 문자열
    with _reviews_db() as c:
        # 미로그인 재구독이 기존 로그인 구독을 익명으로 덮어쓰지 않게: uid가 빈 값이면 user_id 유지.
        c.execute(
            "INSERT INTO push_subscriptions(user_id,endpoint,p256dh,auth,ua) VALUES(?,?,?,?,?) "
            "ON CONFLICT(endpoint) DO UPDATE SET "
            "user_id=CASE WHEN excluded.user_id!='' THEN excluded.user_id ELSE push_subscriptions.user_id END, "
            "p256dh=excluded.p256dh, auth=excluded.auth",
            (uid, ep, keys["p256dh"], keys["auth"],
             (request.headers.get("user-agent") or "")[:200]))
    return {"ok": True}


@app.post("/push/unsubscribe")
def push_unsubscribe(body: dict, user: dict = Depends(current_user)):
    ep = (body.get("endpoint") or "").strip()
    with _reviews_db() as c:
        if ep:
            c.execute("DELETE FROM push_subscriptions WHERE endpoint=? AND user_id=?", (ep, user["id"]))
        else:
            c.execute("DELETE FROM push_subscriptions WHERE user_id=?", (user["id"],))
    return {"ok": True}


class PushSendBody(BaseModel):
    title: str
    body: str
    url: str = "/"
    target: str = "all"      # all | user:<uid>


@app.post("/admin/push/send")
def admin_push_send(req: PushSendBody, _admin: dict = Depends(admin_user)):
    """관리자 수동 푸시 발송. target=all(구독 전체·익명 포함) 또는 user:<uid>."""
    if req.target.startswith("user:"):
        ids = [req.target.split(":", 1)[1]]
    else:
        with _reviews_db() as c:
            # 익명('') 포함 모든 구독 — 로그인 안 한 사용자도 공지·급매 알림 받음
            ids = [r[0] for r in c.execute("SELECT DISTINCT user_id FROM push_subscriptions").fetchall()]
    res = _send_web_push(ids, req.title.strip(), req.body.strip(), req.url or "/", tag="admin")
    return {"targets": len(ids), **res}


@app.get("/me/favorites")
def my_favorites(user: dict = Depends(current_user)):
    """내 관심단지 목록(일반 사용자 — 멤버십 불필요). 16시 알림 대상."""
