# ─────────────────────────────────────────────────────────────
# 중개사 라운지 — 계정↔중개사무소 연동(전화매칭/서류), 정보수정요청, 상담리드
# ─────────────────────────────────────────────────────────────
import re as _re_lounge
LOUNGE_DOC_DIR: Path = DB_PATH.parent / "realtor_docs"
LOUNGE_DOC_DIR.mkdir(parents=True, exist_ok=True)


def _digits(s) -> str:
    return _re_lounge.sub(r"\D", "", s or "")


def _my_phone(c, user_id):
    r = c.execute("SELECT phone FROM user_profiles WHERE user_id=? AND phone_verified=1",
                  (user_id,)).fetchone()
    return r[0] if r else None


def _realtor_candidates_by_phone(phone) -> list[dict]:
    """인증 휴대폰과 일치하는 중개사무소 후보.
    ① naver_realtors 연락처(휴대폰/대표전화) ② vworld 등록전화(한 필드에 여러 번호 공백구분)
    → realtor_match로 naver realtor_id 연결. 사무소가 vworld에 등록한 여러 번호 중 어느 것으로
    인증해도 사무소를 찾도록 한다(naver엔 대표번호 1개만 있어 누락되던 케이스 보완)."""
    d = _digits(phone)
    if len(d) < 9:
        return []
    out, seen = [], set()
    with _open_db() as c:
        # 통합 사전 인덱스(realtor_phone_index = naver 연락처 + vworld 등록전화 다중번호 split).
        # 인덱스 조회 1회(<1ms). 인덱스 미생성 시에만 라이브 naver 스캔으로 폴백.
        try:
            rids = [r[0] for r in c.execute(
                "SELECT DISTINCT realtor_id FROM realtor_phone_index WHERE phone_digits=?", (d,)).fetchall()]
            for rid in rids:
                if not rid or rid in seen:
                    continue
                seen.add(rid)
                br = _office_brief(rid)
                out.append({"realtor_id": rid, "realtor_name": br.get("realtor_name"),
                            "address": br.get("address"), "representative": br.get("representative")})
            return out
        except sqlite3.OperationalError:
            pass  # 인덱스 테이블 미생성 → 라이브 폴백
        for rid, name, addr, rep in c.execute(
            "SELECT realtor_id, realtor_name, address, representative_name FROM naver_realtors "
            "WHERE replace(replace(IFNULL(cell_phone_no,''),'-',''),' ','')=? "
            "   OR replace(replace(IFNULL(representative_tel_no,''),'-',''),' ','')=?",
            (d, d)).fetchall():
            if rid in seen:
                continue
            seen.add(rid)
            out.append({"realtor_id": rid, "realtor_name": name, "address": addr, "representative": rep})
    return out


def _office_brief(realtor_id):
    if realtor_id == "koczip-test":   # 관리자 데모 사무소
        return dict(_KT_OFFICE)
    with _open_db() as c:
        r = c.execute(
            "SELECT realtor_id, realtor_name, address, representative_name, "
            "representative_tel_no, cell_phone_no, latitude, longitude "
            "FROM naver_realtors WHERE realtor_id=?", (realtor_id,)).fetchone()
    if not r and realtor_id.startswith("vw") and realtor_id[2:].isdigit():
        # 합성 ID(네이버 미등록 vworld 사무소) — 프로비저닝 전에도 vworld 정보로 표시
        with _open_db() as c:
            v = c.execute("SELECT business_name, address, representative, phone "
                          "FROM vworld_brokers WHERE sys_regno=?", (realtor_id[2:],)).fetchone()
        if v:
            return {"realtor_id": realtor_id, "realtor_name": v[0], "address": v[1],
                    "representative": v[2], "tel": (v[3] or "").split()[0] if v[3] else None,
                    "cell": None, "latitude": None, "longitude": None}
    if not r:
        return {"realtor_id": realtor_id, "realtor_name": None}
    return {"realtor_id": r[0], "realtor_name": r[1], "address": r[2],
            "representative": r[3], "tel": r[4], "cell": r[5],
            "latitude": r[6], "longitude": r[7]}


def _require_member(c, uid) -> str:
    m = c.execute("SELECT realtor_id, status FROM realtor_members WHERE user_id=?", (uid,)).fetchone()
    if not m:
        raise HTTPException(403, "중개사 인증이 필요합니다")
    if (m[1] or "active") != "active":
        raise HTTPException(403, "대표님 승인 대기 중입니다")
    return m[0]


def _require_owner(c, uid) -> str:
    """대표(owner) 전용 기능 가드 — 직원관리 등."""
    m = c.execute("SELECT realtor_id, role, status FROM realtor_members WHERE user_id=?", (uid,)).fetchone()
    if not m or (m[2] or "active") != "active":
        raise HTTPException(403, "중개사 인증이 필요합니다")
    if (m[1] or "owner") != "owner":
        raise HTTPException(403, "대표님만 사용할 수 있는 기능입니다")
    return m[0]


def _provision_vworld_office(rid: str) -> None:
    """합성 ID(vw{sys_regno}) 사무소를 naver_realtors에 등록(멱등) — 상세페이지·검색·브리핑용."""
    if not (rid.startswith("vw") and rid[2:].isdigit()):
        return
    with _open_db() as c:
        if c.execute("SELECT 1 FROM naver_realtors WHERE realtor_id=?", (rid,)).fetchone():
            return
        v = c.execute("SELECT business_name, representative, address, phone, ra_regno, sgg_cd "
                      "FROM vworld_brokers WHERE sys_regno=?", (rid[2:],)).fetchone()
        if not v:
            return
        c.execute(
            "INSERT OR IGNORE INTO naver_realtors(realtor_id, realtor_name, representative_name, "
            "address, establish_registration_no, representative_tel_no, cortar_no, raw_json, fetched_at) "
            "VALUES(?,?,?,?,?,?,?,?,datetime('now'))",
            (rid, v[0], v[1], v[2], v[4], (v[3] or "").split()[0] if v[3] else None,
             (v[5] + "00000") if v[5] else None,
             _json.dumps({"source": "vworld_auto", "sys_regno": rid[2:]}, ensure_ascii=False)))
        c.commit()


def _auto_attribute_hidden_listings(rid: str) -> None:
    """네이버 ID 숨김 사무소의 매물 자동 귀속(정확도 우선, 백그라운드 스레드용).

    후보: 같은 시군구 + 상호 '정확일치'인 NULL-ID 매물. 검증: 후보 상세 API의
    개설등록번호 == vworld 등록번호(숫자 정규화)일 때만 hidden_realtor_map 등록·적용.
    등록번호 불일치가 하나라도 나오면 중단(동명 사무소 혼재) + 텔레그램 수동확인 요청.
    """
    if not (rid.startswith("vw") and rid[2:].isdigit()):
        return
    try:
        with _open_db() as c:
            v = c.execute("SELECT business_name, sgg_cd, ra_regno FROM vworld_brokers "
                          "WHERE sys_regno=?", (rid[2:],)).fetchone()
            if not v or not v[1]:
                return
            name, sgg, ra_regno = v[0], v[1], _re_lounge.sub(r"\D", "", v[2] or "")
            if c.execute("SELECT 1 FROM hidden_realtor_map WHERE realtor_name=? AND cortar_prefix=?",
                         (name, sgg)).fetchone():
                return   # 이미 매핑됨
            arts = [r[0] for r in c.execute(
                "SELECT l.article_no FROM listings_current l JOIN complexes cx "
                "ON cx.complex_no=l.complex_no WHERE l.realtor_id IS NULL "
                "AND l.realtor_name=? AND cx.cortar_no LIKE ? LIMIT 5",
                (name, sgg + "%")).fetchall()]
        if not arts or not ra_regno:
            return
        from collector.article_detail import fetch_article_detail
        from collector.creds import ensure_creds
        creds = ensure_creds()
        confirmed = mismatched = 0
        for an in arts[:3]:
            st_, d = fetch_article_detail(an, None, creds)
            if st_ != 200 or not d:
                continue
            reg = _re_lounge.sub(r"\D", "", ((d.get("articleRealtor") or {}).get("establishRegistrationNo") or ""))
            if not reg:
                continue
            if reg == ra_regno:
                confirmed += 1
            else:
                mismatched += 1
        if mismatched or not confirmed:
            if mismatched:
                try:
                    from scripts.tg_notify import tg_send_async
                    tg_send_async(f"⚠️ 숨김ID 매물 자동귀속 보류 — {name}({sgg}) 등록번호 불일치 "
                                  f"{mismatched}건(동명 사무소 혼재 의심). 수동 확인 필요: {rid}")
                except Exception:
                    pass
            return
        # 확정 — 매핑 등록 + 즉시 적용(단지형+비단지)
        with _open_db() as c:
            c.execute("CREATE TABLE IF NOT EXISTS hidden_realtor_map (realtor_name TEXT NOT NULL, "
                      "cortar_prefix TEXT NOT NULL, realtor_id TEXT NOT NULL, note TEXT, "
                      "PRIMARY KEY (realtor_name, cortar_prefix))")
            c.execute("INSERT OR IGNORE INTO hidden_realtor_map VALUES (?,?,?,?)",
                      (name, sgg, rid, f"자동귀속 — 상세 등록번호 {confirmed}건 확인(2026 auto)"))
            n = c.execute("UPDATE listings_current SET realtor_id=? WHERE realtor_id IS NULL "
                          "AND realtor_name=? AND complex_no IN (SELECT complex_no FROM complexes "
                          "WHERE cortar_no LIKE ?)", (rid, name, sgg + "%")).rowcount
            c.commit()
        n2 = 0
        for cat, dbf in _NONRESI_DB.items():
            path = DB_PATH.parent / dbf
            if not path.exists():
                continue
            try:
                with sqlite3.connect(path) as rc:
                    n2 += rc.execute(
                        "UPDATE listings SET realtor_id=? WHERE (realtor_id IS NULL OR realtor_id='') "
                        "AND realtor_name=? AND cortar_no LIKE ?", (rid, name, sgg + "%")).rowcount
                    rc.commit()
            except sqlite3.Error:
                pass
        try:
            from scripts.tg_notify import tg_send_async
            tg_send_async(f"🔗 숨김ID 매물 자동귀속 — {name}({sgg}) → {rid}: "
                          f"단지형 {n}건·비단지 {n2}건 (등록번호 {confirmed}건 검증)")
        except Exception:
            pass
    except Exception:
        pass   # 자동귀속 실패는 본 기능(연결)에 무영향


@app.get("/lounge/status")
def lounge_status(user: dict = Depends(current_user)):
    """라운지 접근 상태: need_phone / select(후보 여러개) / no_match / doc_pending / linked."""
    uid = user["id"]
    with _reviews_db() as c:
        phone = _my_phone(c, uid)
        m = c.execute("SELECT realtor_id, method, role, status, staff_name FROM realtor_members "
                      "WHERE user_id=?", (uid,)).fetchone()
        pend = c.execute("SELECT 1 FROM realtor_verifications WHERE user_id=? AND status='pending' "
                         "LIMIT 1", (uid,)).fetchone()
        has_hp = c.execute("SELECT 1 FROM realtor_homepages WHERE realtor_id=? LIMIT 1",
                           (m[0],)).fetchone() if m else None
    if m:
        if (m[3] or "active") != "active":   # 직원 승인 대기
            return {"state": "staff_pending", "phone_verified": bool(phone),
                    "office": _office_brief(m[0]), "role": m[2], "staff_name": m[4]}
        return {"state": "linked", "phone_verified": bool(phone),
                "office": _office_brief(m[0]), "method": m[1],
                "role": m[2] or "owner", "staff_name": m[4],
                "has_homepage": bool(has_hp)}
    # 관리자는 인증 없이 입장 — 아무 사무소나 연결해 둘러볼 수 있다.
    if user.get("is_admin"):
        return {"state": "admin_pick", "phone_verified": bool(phone), "is_admin": True}
    if not phone:
        return {"state": "need_phone", "phone_verified": False}
    cands = _realtor_candidates_by_phone(phone)
    if cands:
        return {"state": "select", "phone_verified": True, "candidates": cands}
    if pend:
        return {"state": "doc_pending", "phone_verified": True}
    return {"state": "no_match", "phone_verified": True}


# ── 직원(소속공인중개사·중개보조원) 시스템 ─────────────────────────────
# vworld는 대표 본인 번호만 등록 → 직원은 전화매칭 불가. 흐름: 역할 선택 → 전화인증 →
# 사무소 검색 → 공부상 명단(vworld_employees)에서 본인 선택 → 대표 승인(pending→active).
# 대표가 초대장(SMS)을 보내둔 번호는 전화인증 즉시 자동 승인(phone_verify 훅).

_STAFF_ROLE_KR = {"assoc": "소속공인중개사", "assist": "중개보조원", "owner": "대표"}


@app.get("/lounge/office-roster")
def lounge_office_roster(realtor_id: str, user: dict = Depends(current_user)):
    """사무소의 공부상 직원 명단(대표 제외) — 직원 가입 시 본인 선택용."""
    with _open_db() as dc:
        rows = dc.execute(
            "SELECT ve.employee_name, ve.role, ve.position FROM vworld_employees ve "
            "JOIN realtor_match rm ON rm.sys_regno=ve.sys_regno "
            "WHERE rm.realtor_id=? AND ve.status='영업' AND ve.position!='대표' "
            "AND ve.employee_name IS NOT NULL AND ve.employee_name!='' "
            "ORDER BY CASE WHEN ve.role='공인중개사' THEN 0 ELSE 1 END, ve.employee_name",
            (realtor_id,)).fetchall()
    return {"items": [{"name": r[0],
                       "role": "assoc" if r[1] == "공인중개사" else "assist",
                       "role_kr": "소속공인중개사" if r[1] == "공인중개사" else "중개보조원"}
                      for r in rows]}


@app.post("/lounge/staff/apply")
def lounge_staff_apply(body: dict, user: dict = Depends(current_user)):
    """직원 가입 신청 — 전화인증 필수, 대표 승인 대기(pending)로 저장."""
    rid = (body.get("realtor_id") or "").strip()
    role = body.get("role") or ""
    name = (body.get("name") or "").strip()[:20]
    if not rid or role not in ("assoc", "assist"):
        raise HTTPException(400, "realtor_id/role required")
    uid = user["id"]
    with _reviews_db() as c:
        phone = _my_phone(c, uid)
        if not phone:
            raise HTTPException(403, "전화인증이 필요합니다")
        c.execute(
            "INSERT INTO realtor_members(user_id,realtor_id,method,matched_phone,role,status,staff_name,updated_at) "
            "VALUES(?,?,'staff',?,?,'pending',?,datetime('now')) "
            "ON CONFLICT(user_id) DO UPDATE SET realtor_id=excluded.realtor_id, method='staff', "
            "role=excluded.role, status='pending', staff_name=excluded.staff_name, updated_at=datetime('now')",
            (uid, rid, phone, role, name))
        c.commit()
        # 대표(들)에게 즉시 푸시 — 승인 요청
        owners = [r[0] for r in c.execute(
            "SELECT user_id FROM realtor_members WHERE realtor_id=? AND role='owner' AND status='active'",
            (rid,)).fetchall()]
    if owners:
        try:
            _send_web_push(owners, "직원 가입 승인 요청 👤",
                           f"{name or '직원'}({_STAFF_ROLE_KR.get(role, role)})님이 가입을 신청했어요. "
                           "직원관리에서 승인해 주세요.", url="/biz/staff", tag="staff-apply")
        except Exception:
            pass
    return {"ok": True, "status": "pending"}


@app.get("/lounge/staff")
def lounge_staff_list(user: dict = Depends(current_user)):
    """직원관리(대표 전용) — 승인대기·활동중 직원 + 미사용 초대장."""
    with _reviews_db() as c:
        rid = _require_owner(c, user["id"])
        members = [dict(zip(("user_id", "role", "status", "staff_name", "matched_phone", "created_at"), r))
                   for r in c.execute(
                       "SELECT user_id, role, status, staff_name, matched_phone, created_at "
                       "FROM realtor_members WHERE realtor_id=? AND role!='owner' "
                       "ORDER BY CASE status WHEN 'pending' THEN 0 ELSE 1 END, created_at DESC",
                       (rid,)).fetchall()]
        # 닉네임 붙이기(표시용)
        for m in members:
            n = c.execute("SELECT nickname FROM user_profiles WHERE user_id=?", (m["user_id"],)).fetchone()
            m["nickname"] = n[0] if n else None
            m["role_kr"] = _STAFF_ROLE_KR.get(m["role"], m["role"])
        invites = [dict(zip(("id", "phone_digits", "role", "name", "created_at"), r)) | {
                       "role_kr": _STAFF_ROLE_KR.get(r[2], r[2])}
                   for r in c.execute(
                       "SELECT id, phone_digits, role, name, created_at FROM realtor_staff_invites "
                       "WHERE realtor_id=? AND used_at IS NULL ORDER BY created_at DESC", (rid,)).fetchall()]
    return {"members": members, "invites": invites}


