def _ml_price_text(v) -> str:
    v = int(v or 0)
    if not v:
        return ""
    e, man = divmod(v, 10000)
    return (f"{e}억" + (f" {man:,}" if man else "")) if e else f"{man:,}"


_SIDO_SHORT = {
    "서울시": "서울", "부산시": "부산", "대구시": "대구", "인천시": "인천", "광주시": "광주",
    "대전시": "대전", "울산시": "울산", "세종시": "세종", "경기도": "경기", "강원도": "강원",
    "충청북도": "충북", "충청남도": "충남", "전라북도": "전북", "전북도": "전북",
    "전라남도": "전남", "경상북도": "경북", "경상남도": "경남", "제주도": "제주",
    # 현행 명칭 → 짧은 표기(브레드크럼·OG 카드 등 공간 제약 표시용). 권역 short는 광주/전남 유지.
    "전남광주통합특별시 (광주권)": "광주", "전남광주통합특별시 (전남권)": "전남",
    "강원특별자치도": "강원", "전북특별자치도": "전북",
}


def _short_sido(name: str) -> str:
    """'서울특별시'·'서울시' → '서울', '충청남도' → '충남'. 매물장·중개사 매물 주소 표기용."""
    n = (name or "").strip()
    if not n:
        return ""
    if n in _SIDO_SHORT:
        return _SIDO_SHORT[n]
    for suf in ("특별자치시", "특별자치도", "광역시", "특별시", "시", "도"):
        if n.endswith(suf) and len(n) > len(suf):
            return _SIDO_SHORT.get(n, n[: -len(suf)])
    return n


def _region_addr_map(conn, cortars) -> dict:
    """cortar_no(10자리) → '서울 강남구 역삼동'. 시도는 축약, 없는 단계는 건너뜀."""
    cts = {c for c in cortars if c}
    if not cts:
        return {}
    need = set()
    for ct in cts:
        need |= {ct, ct[:5] + "00000", ct[:2] + "00000000"}
    ph = ",".join("?" * len(need))
    nm = {r[0]: r[1] for r in conn.execute(
        f"SELECT cortar_no, cortar_name FROM regions WHERE cortar_no IN ({ph})", list(need)).fetchall()}
    out = {}
    for ct in cts:
        parts = [_short_sido(nm.get(ct[:2] + "00000000", "")),
                 nm.get(ct[:5] + "00000", ""), nm.get(ct, "")]
        out[ct] = " ".join(x for x in parts if x)
    return out


def _short_addr_text(addr: str) -> str:
    """'서울특별시 강남구 역삼동 813-14' → '서울 강남구 역삼동 813-14'(시도만 축약)."""
    a = (addr or "").strip()
    if not a:
        return ""
    head, _, rest = a.partition(" ")
    s = _short_sido(head)
    return f"{s} {rest}".strip() if rest else s


def _coord_addr_map(coords) -> dict:
    """(lat,lng) 반올림키 → 지번주소. build_coord_addr.py가 채운 VWorld 역지오코딩 캐시.
    비단지는 네이버 원본에 지번이 없어 좌표로만 지번을 얻는다([[naverreal-nonresi-addr]])."""
    keys = {k for k in coords if k}
    if not keys:
        return {}
    p = DB_PATH.parent / "coord_addr.sqlite"
    if not p.exists():
        return {}
    out = {}
    try:
        with sqlite3.connect(f"file:{p}?mode=ro", uri=True) as cc:
            cc.execute("PRAGMA busy_timeout=8000")
            ks = list(keys)
            for i in range(0, len(ks), 900):        # SQLite 변수 한도 회피
                chunk = ks[i:i + 900]
                ph = ",".join("?" * len(chunk))
                for k, addr in cc.execute(
                        f"SELECT ckey, addr FROM coord_addr WHERE status='ok' AND addr IS NOT NULL "
                        f"AND ckey IN ({ph})", chunk):
                    out[k] = _short_addr_text(addr)
    except sqlite3.Error:
        return {}
    return out


def _ckey(lat, lng) -> str:
    try:
        return f"{round(float(lat), 5)},{round(float(lng), 5)}"
    except (TypeError, ValueError):
        return ""


def _find_listing_owner(article_no: str):
    """네이버 매물번호 → (realtor_id, realtor_name). 단지형·비단지 전 DB 탐색. 못 찾으면 None."""
    with _open_db() as dc:
        r = dc.execute("SELECT realtor_id, realtor_name FROM listings_current WHERE article_no=? LIMIT 1",
                       (article_no,)).fetchone()
    if r and (r[0] or r[1]):
        return (r[0] or "", r[1] or "")
    snap = "snapshot_date=(SELECT MAX(snapshot_date) FROM listings)"
    for dbkey in _NONRESI_DB:
        p = DB_PATH.parent / _NONRESI_DB[dbkey]
        if not p.exists():
            continue
        try:
            with sqlite3.connect(f"file:{p}?mode=ro", uri=True) as nc:
                nc.execute("PRAGMA busy_timeout=15000")
                r = nc.execute(f"SELECT realtor_id, realtor_name FROM listings "
                               f"WHERE article_no=? AND {snap} LIMIT 1", (article_no,)).fetchone()
            if r and (r[0] or r[1]):
                return (r[0] or "", r[1] or "")
        except sqlite3.Error:
            continue
    return None


def _collect_realtor_listings(rid: str, code: str | None, cat: str) -> list:
    """중개사(realtor_id)의 매물 통합 — 단지형(listings_current) + 비단지(7종 별도 DB).
    매물장·중개사 세부페이지 공용. code=거래코드(A1/B1/B2) 또는 None, cat=유형 한글 필터."""
    if rid == "koczip-test":   # 관리자 데모 — 전 카테고리 샘플(프로덕션 DB 미접근)
        kt = [dict(x) for x in _KOCZIP_TEST_LISTINGS]
        if cat:
            kt = [x for x in kt if x.get("type") == cat]
        return kt
    items: list = []
    # 1) 단지 매물(아파트·오피스텔·분양권). cat='단지형'이면 셋 다, 개별이면 해당만.
    if cat in ("", "단지형", "아파트", "오피스텔", "분양권"):
        w = ["l.realtor_id=?"]; p: list = [rid]
        if code:
            w.append("l.trade_type=?"); p.append(code)
        sql = ("SELECT l.article_no,l.complex_no,c.complex_name,l.trade_type,l.real_estate_type,l.area_name,"
               "l.area1_m2,l.area2_m2,l.floor_info,l.direction,l.deal_or_warrant_price_text,l.rent_price_text,"
               "l.deal_or_warrant_price,l.article_confirm_ymd,l.building_name,l.tag_list_json,l.same_addr_cnt,"
               "l.same_addr_min_price,l.same_addr_max_price,l.article_feature_desc,l.cp_pc_article_url,"
               "l.cp_name,l.verification_type,l.latitude,l.longitude,c.dong_name,c.road_address,c.detail_address,"
               "c.parking_possible_count,c.parking_per_household,c.total_household_count,c.use_approve_ymd,"
               "c.construction_company,c.management_office_tel,c.cortar_no "
               "FROM listings_current l LEFT JOIN complexes c ON c.complex_no=l.complex_no "
               f"WHERE {' AND '.join(w)}")
        with _open_db() as dc:
            rows = dc.execute(sql, p).fetchall()
            cx_addr = _region_addr_map(dc, {r[34] for r in rows})
        for r in rows:
            tkor = _RET_KOR.get(r[4], "아파트")
            if cat in ("아파트", "오피스텔", "분양권") and cat != tkor:
                continue
            try:
                tags = _json.loads(r[15]) if r[15] else []
            except Exception:
                tags = []
            # 주소 = '서울 강남구 역삼동 222'(시도축약+시군구+동+지번). 지번(detail_address) 없으면 도로명.
            dong = r[25] or ""
            base = cx_addr.get(r[34], "")
            if not base:                       # regions 미매칭 시 동만이라도
                base = dong
            elif dong and not base.endswith(dong):
                base = f"{base} {dong}"
            bunji = (r[27] or "").strip() or (r[26] or "").strip()
            full_addr = " ".join(x for x in [base, bunji] if x).strip()
            items.append({
                "article_no": r[0], "complex_no": r[1], "complex_name": r[2],
                "trade_type": _TRADE_KOR.get(r[3], r[3]), "type": tkor, "area_name": r[5],
                "area1_m2": r[6], "area2_m2": r[7], "floor_info": r[8], "direction": r[9],
                "price_text": r[10], "rent_price_text": r[11], "price": r[12] or 0, "confirm_ymd": r[13] or "",
                "building_name": r[14], "tags": tags, "same_addr_cnt": r[16], "same_addr_min": r[17],
                "same_addr_max": r[18], "feature_desc": r[19],
                "naver_url": f"https://m.land.naver.com/article/info/{r[0]}", "cp_name": r[21],
                "verification_type": r[22], "lat": r[23], "lng": r[24],
                "dong": dong, "address": full_addr,
                "parking_total": r[28], "parking_per": r[29], "households": r[30],
                "approve_ymd": r[31], "builder": r[32], "mgmt_tel": r[33],
            })
    # vworld-only(vw{sys_regno}) 사무소 — 비단지 CP매물이 realtor_id 없이 등록번호로 귀속됨
    # ([[naverreal-region-office-attribution]]) → realtor_id 조회로는 0. (정규화이름, sgg)로 매칭.
    region_by_sgg: dict = {}
    _sysreg = _office_region_sys_regno(rid)
    if _sysreg:
        _attr = DB_PATH.parent / "office_attribution.sqlite"
        if _attr.exists():
            try:
                with sqlite3.connect(f"file:{_attr}?mode=ro", uri=True) as _ac:
                    for _nm, _sgg in _ac.execute(
                            "SELECT norm_name, sgg5 FROM region_office_attribution WHERE sys_regno=?", (_sysreg,)):
                        region_by_sgg.setdefault(_sgg, set()).add(_nm)
            except sqlite3.Error:
                pass
    _norm_office = None
    if region_by_sgg:
        from collector.realtor_matching import normalize_name as _norm_office  # noqa: E402

    # 2) 비단지 매물(빌라·상가·사무실·단독·토지·공장·빌딩) — 별도 DB
    for ckor, dbkey in _REGION_CATS:
        if cat and cat != ckor:
            continue
        path = DB_PATH.parent / _NONRESI_DB[dbkey]
        if not path.exists():
            continue
        _sel_nr = ("SELECT article_no,real_estate_type_name,trade_type,deal_or_warrant_price,rent_price,"
                   "area1_m2,area2_m2,floor_info,direction,building_name,article_confirm_ymd,latitude,longitude,"
                   "cortar_no,raw,realtor_name FROM listings ")
        _snap = "snapshot_date=(SELECT MAX(snapshot_date) FROM listings)"
        _tc = " AND trade_type=?" if code else ""
        try:
            rconn = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
            # ① 직접 귀속(realtor_id=rid) — 항상. vw 사무소도 귀속배치가 realtor_id를 세팅하므로 필수.
            rrows = list(rconn.execute(
                _sel_nr + f"WHERE realtor_id=? AND {_snap}{_tc}",
                [rid] + ([code] if code else [])).fetchall())
            # ② vw 사무소면 숨김(빈 realtor_id) 매물도 사무소 sgg+이름정규화로 추가
            if region_by_sgg:
                _sggs = list(region_by_sgg.keys())
                _w = ["(realtor_id IS NULL OR realtor_id='')",
                      f"substr(cortar_no,1,5) IN ({','.join('?' * len(_sggs))})", _snap]
                _p = list(_sggs) + ([code] if code else [])
                hidden = rconn.execute(
                    _sel_nr + "WHERE " + " AND ".join(_w) + _tc, _p).fetchall()
                rrows += [r for r in hidden
                          if r[15] and _norm_office(r[15]) in region_by_sgg.get((r[13] or "")[:5], set())]
            rconn.close()
        except Exception:
            rrows = []
        cortars = {r[13] for r in rrows if r[13]}
        dongmap: dict = {}
        addrmap: dict = {}
        if cortars:
            with _open_db() as dc:
                ph = ",".join("?" * len(cortars))
                dongmap = {x[0]: x[1] for x in dc.execute(
                    f"SELECT cortar_no, cortar_name FROM regions WHERE cortar_no IN ({ph})", list(cortars)).fetchall()}
                # 비단지는 원본에 지번이 없어(detailAddress 공백) '시도 시군구 동'까지 구성
                addrmap = _region_addr_map(dc, cortars)
        # 좌표 역지오코딩 캐시가 있으면 지번까지(없으면 위 지역주소로 폴백)
        coordmap = _coord_addr_map({_ckey(r[11], r[12]) for r in rrows})
        for r in rrows:
            feat, tags, sa_cnt, sa_min, sa_max, vtype = "", [], 0, 0, 0, ""
            try:
                rw = _json.loads(r[14]) if r[14] else {}
                feat = rw.get("articleFeatureDesc") or ""
                tags = rw.get("tagList") or []
                sa_cnt = int(rw.get("sameAddrCnt") or 0)
                sa_min = int(rw.get("sameAddrMinPrc") or 0)
                sa_max = int(rw.get("sameAddrMaxPrc") or 0)
                vtype = rw.get("verificationTypeName") or rw.get("verificationTypeCode") or ""
            except Exception:
                pass
            dong = dongmap.get(r[13], "") or ""
            # 지번주소(좌표 캐시) 우선, 없으면 '시도 시군구 동'. 건물명은 카드에서 따로 노출.
            full_addr = coordmap.get(_ckey(r[11], r[12]), "") or addrmap.get(r[13], "") or dong
            items.append({
                "article_no": r[0], "complex_no": None, "complex_name": None,
                "trade_type": _TRADE_KOR.get(r[2], r[2]), "type": ckor,
                "area_name": r[1] or ckor, "area1_m2": r[5], "area2_m2": r[6], "floor_info": r[7] or "",
                "direction": r[8] or "", "price_text": _ml_price_text(r[3]),
                "rent_price_text": _ml_price_text(r[4]), "price": r[3] or 0, "confirm_ymd": r[10] or "",
                "building_name": r[9] or "", "tags": tags, "same_addr_cnt": sa_cnt, "same_addr_min": sa_min,
                "same_addr_max": sa_max, "feature_desc": feat,
                "naver_url": f"https://m.land.naver.com/article/info/{r[0]}",
                "cp_name": "", "verification_type": vtype, "lat": r[11], "lng": r[12],
                "dong": dong, "address": full_addr,
                "parking_total": None, "parking_per": None, "households": None,
                "approve_ymd": None, "builder": None, "mgmt_tel": None,
            })
    return items


def _sort_listings(items: list, sort: str) -> list:
    if sort == "price_desc":
        items.sort(key=lambda x: x["price"] or 0, reverse=True)
    elif sort == "price_asc":
        items.sort(key=lambda x: x["price"] or 0)
    else:
        items.sort(key=lambda x: x["confirm_ymd"] or "", reverse=True)
    return items


@app.get("/realtor/{realtor_id}/listings")
def realtor_listings_public(realtor_id: str, cat: str = "", trade: str = "",
                            sort: str = "confirm", limit: int = 600):
    """중개사 세부페이지 — 그 중개사 매물 전체(단지형+비단지), 유형(cat)·거래(trade) 필터. 공개."""
    items = _collect_realtor_listings(realtor_id, _TRADE_CODE.get(trade), cat)
    items = _sort_listings(items, sort)[:min(max(int(limit), 1), 2000)]
    return {"realtor_id": realtor_id, "count": len(items), "listings": items}


@app.get("/lounge/listings")
def lounge_listings(user: dict = Depends(current_user), q: str = "", trade: str = "",
                    cat: str = "", manager: str = "", sort: str = "confirm", limit: int = 1500,
                    private: int = 0, private_only: int = 0):
    """매물장 — 내 중개사무소(realtor_id)의 매물 통합. trade=매매/전세/월세, cat=유형, manager=담당자.
    private=1 이면 비공개매물도 함께, private_only=1 이면 비공개매물만(공개범위 규칙 적용)."""
    with _reviews_db() as rc:
        rid = _require_member(rc, user["id"])
        _ensure_lounge_notes(rc)
        notes = {r[0]: (r[1], r[2], r[3]) for r in rc.execute(
            "SELECT article_no, memo, contact, manager FROM lounge_notes WHERE realtor_id=?", (rid,)).fetchall()}
        priv = []
        if private or private_only:
            rc.row_factory = sqlite3.Row
            priv = _collect_private_listings(rc, rid, user["id"], _TRADE_CODE.get(trade), cat)
    items = [] if private_only else _collect_realtor_listings(rid, _TRADE_CODE.get(trade), cat)

    # 메모/연락처/담당자 결합 → 검색·담당자 필터 → 정렬 → 컷
    for it in items:
        m, ct, mg = notes.get(it["article_no"], ("", "", ""))
        it["memo"], it["contact"], it["manager"] = m or "", ct or "", mg or ""
    # 비공개매물을 앞에 둔다 — 아래 정렬이 안정 정렬이라 확인일이 같으면 이쪽이 먼저 온다.
    # 방금 등록한 물건이 오늘 확인된 네이버 매물 수백 건 뒤로 밀려 안 보이던 문제.
    # (비공개매물은 자체 memo/contact/manager 를 이미 갖고 있어 위 결합을 타지 않는다)
    items = priv + items
    if q.strip():
        ql = q.strip()
        # 네이버 매물번호도 검색 대상(중개사가 번호로 바로 자기 물건을 찾는 흐름)
        items = [it for it in items if ql in ((it["article_no"] or "") + (it["complex_name"] or "")
                 + (it["building_name"] or "") + (it["area_name"] or "") + (it["address"] or "")
                 + (it["feature_desc"] or ""))]
    if manager == "미지정":
        items = [it for it in items if not it["manager"]]
    elif manager:
        items = [it for it in items if it["manager"] == manager]
    if sort == "price_desc":
        items.sort(key=lambda x: x["price"] or 0, reverse=True)
    elif sort == "price_asc":
        items.sort(key=lambda x: x["price"] or 0)
    else:
        items.sort(key=lambda x: x["confirm_ymd"] or "", reverse=True)
    items = items[:min(max(int(limit), 1), 3000)]
    return {"realtor_id": rid, "count": len(items), "listings": items}


# ── 비공개매물 ──────────────────────────────────────────────────────────────
# 네이버 연동이 아니라 대표·직원이 콕집에 직접 등록하는 매물. 공개범위(me=작성자만 /
# office=사무실 전체)를 등록자가 고른다. 항목은 네이버 매물 수준으로 넓게 두되 **전부 선택**
