def _ensure_private_listings(c) -> None:
    cols = ", ".join(f"{f} TEXT" for f in _PL_FIELDS)
    c.executescript(f"""
    CREATE TABLE IF NOT EXISTS private_listings(
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      realtor_id TEXT NOT NULL,
      created_by TEXT NOT NULL,
      visibility TEXT NOT NULL DEFAULT 'office',   -- me | office
      status TEXT NOT NULL DEFAULT 'active',       -- active | closed
      photos TEXT,                                 -- JSON [filename,...] (모자이크 완료본만)
      source_article_no TEXT,                      -- 네이버에서 옮겨온 경우 원 매물번호
      source_saved_at TEXT,
      {cols},
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')));
    CREATE INDEX IF NOT EXISTS pl_rid ON private_listings(realtor_id, status);
    """)
    # 기존 테이블 마이그레이션 — 인덱스보다 **먼저** 컬럼을 채워야 한다.
    # (CREATE TABLE IF NOT EXISTS 는 기존 테이블에 no-op 이라, 새 컬럼을 참조하는 인덱스를
    #  같은 스크립트에 두면 'no such column' 으로 터진다.)
    have = {r[1] for r in c.execute("PRAGMA table_info(private_listings)")}
    for col in ("source_article_no", "source_saved_at", "lat", "lng", "settle_ymd",
                "land_area_m2", "total_area_m2", "land_category", "land_use",
                "premium", "bunyang_premium", "ceiling_h", "power_kw",
                "vat_separate", "violation", "rent_income", "deposit_sum",
                "road_contact", "current_biz", "tenant_until",
                "bc_rat", "vl_rat", "main_purpose", "height", "reg_kind"):
        if col not in have:
            c.execute(f"ALTER TABLE private_listings ADD COLUMN {col} TEXT")
    c.execute("CREATE INDEX IF NOT EXISTS pl_src ON private_listings(realtor_id, source_article_no)")


def _geocode_addr(addr: str):
    """주소 → (lat, lng). 직접 등록한 비공개매물을 지도에 찍기 위해 최선노력으로 좌표를 구한다.
    실패해도 저장은 계속된다(좌표 없는 매물은 지도에서만 빠짐)."""
    a = (addr or "").strip()
    if len(a) < 6:
        return None
    key = os.getenv("VWORLD_KEY", "").strip()
    if not key:
        return None
    import urllib.parse as _up, urllib.request as _ur
    for typ in ("parcel", "road"):
        try:
            q = _up.urlencode({"service": "address", "request": "getcoord", "version": "2.0",
                               "crs": "epsg:4326", "address": a, "format": "json",
                               "type": typ, "key": key})
            req = _ur.Request(f"https://api.vworld.kr/req/address?{q}",
                              headers={"User-Agent": "koczip/1.0"})
            with _ur.urlopen(req, timeout=6) as r:
                d = _json.loads(r.read().decode("utf-8"))
            res = d.get("response", {})
            if res.get("status") == "OK":
                pt = res["result"]["point"]
                return (float(pt["y"]), float(pt["x"]))
        except Exception:
            continue
    return None


def _parse_price_man(txt) -> str | None:
    """'1억 2,000' · '3,000' · '5억' → 만원 단위 문자열. 네이버 매물의 가격 텍스트용."""
    if txt in (None, ""):
        return None
    s = str(txt).replace(",", "").replace(" ", "")
    try:
        if "억" in s:
            head, _, tail = s.partition("억")
            man = int(float(head or 0)) * 10000
            digits = "".join(ch for ch in tail if ch.isdigit())
            return str(man + (int(digits) if digits else 0))
        digits = "".join(ch for ch in s if ch.isdigit())
        return digits or None
    except (TypeError, ValueError):
        return None


def _pl_visible_sql(uid: str) -> tuple:
    """공개범위 필터 — office 는 사무실 전원, me 는 작성자 본인만."""
    return ("(visibility='office' OR created_by=?)", [uid])


# 중개대상물 표시·광고 명시사항(공인중개사법 시행령 §17-2, 세부기준 고시).
# 매물점검 엔진(collector/listing_audit.py)이 쓰는 13개 항목과 같은 목록을 쓴다 —
# 매물장에서 미리 채워 두면 광고를 낼 때 점검에 걸리지 않는다.
_AD_ITEMS = [
    (1, "소재지·층", ("address", "dong", "floor_info")),
    (2, "전용면적", ("area2_m2",)),
    (3, "가격", ("price", "rent_price")),
    (4, "중개대상물 종류", ("type",)),
    (5, "거래형태", ("trade_type",)),
    (6, "총 층수", ("total_floor",)),
    (7, "입주가능일", ("move_in",)),
    (8, "방·욕실 수", ("room_cnt",)),
    (9, "사용승인일", ("approve_ymd",)),
    (10, "주차", ("parking",)),
    (11, "관리비", ("maintenance_fee",)),
    (12, "방향", ("direction",)),
]


# 비주거는 방·욕실·방향을 적을 이유가 없다. 주택 기준으로 세면 상가가 늘 '빠진 항목'이 된다.
_AD_SKIP_NONRESI = {8, 12}
_NONRESI_TYPES = {"상가", "사무실", "공장", "토지", "건물", "빌딩", "창고", "지식산업센터"}


def _pl_ad_check(g) -> dict:
    """이 매물이 표시·광고 명시사항을 몇 개나 갖췄는지.

    광고를 내기 전에 무엇이 비었는지 이 화면에서 바로 보이게 하려는 것이다.
    빠진 항목은 과태료 대상이라 '나중에 채우면 되는 것'이 아니다.
    항목은 유형에 따라 다르다 — 상가에 방 수를 요구하면 영영 채워지지 않는다.
    """
    nonresi = str(g("type") or "").strip() in _NONRESI_TYPES
    items = [x for x in _AD_ITEMS if not (nonresi and x[0] in _AD_SKIP_NONRESI)]
    done, miss = [], []
    for no, label, keys in items:
        ok = any(str(g(k) or "").strip() not in ("", "0", "0.0") for k in keys)
        (done if ok else miss).append({"no": no, "item": label})
    return {"done": len(done), "total": len(items), "missing": miss}


def _pl_auto_tags(g, num) -> list:
    """비공개매물 태그 — 저장된 값에서 그때그때 만든다.

    저장 시점에 굳혀 두면 준공연도·층 같은 게 바뀌었을 때 태그만 옛날 값으로 남는다.
    네이버 매물 카드와 같은 자리에 같은 모양으로 붙는다.
    """
    t = []
    ap = (g("approve_ymd") or "")[:4]
    if ap.isdigit():
        age = _dt_now_year() - int(ap)
        # 준공 연도는 위 스펙 줄에 이미 있다 — 태그에는 '새 건물' 이라는 정보일 때만 붙인다
        if age <= 1:
            t.append("신축")
        elif age <= 10:
            t.append(f"{5 if age <= 5 else 10}년이내")
    fl, tf = num("floor"), num("total_floor")
    if fl:
        t.append("1층" if fl == 1 else "저층" if fl <= 3 else "고층" if tf and fl >= tf - 2 else f"{int(fl)}층")
    rc, bc = num("room_cnt"), num("bath_cnt")
    if rc:
        t.append(f"방{int(rc)}" + (f"/욕실{int(bc)}" if bc else ""))
    if num("parking"):
        t.append("주차가능")
    if (g("elevator") or "") in ("있음", "Y", "y", "1"):
        t.append("엘리베이터")
    mi = (g("move_in") or "").strip()
    if mi in ("즉시", "즉시입주", "빈집", "공실"):
        t.append("즉시입주")
    if (g("options") or "").strip():
        t.append(str(g("options")).strip()[:8])
    return t[:6]


def _dt_now_year() -> int:
    import datetime as _d
    return (_d.datetime.utcnow() + _d.timedelta(hours=9)).year


def _pl_row_to_item(r) -> dict:
    """비공개매물 행 → 매물장 카드가 쓰는 공통 형태(네이버 매물과 같은 키)."""
    g = lambda k: r[k] if k in r.keys() else None          # noqa: E731
    def num(k):
        v = g(k)
        try: return float(v) if v not in (None, "") else None
        except (TypeError, ValueError): return None
    try:
        tags = _json.loads(g("tags") or "[]")
    except Exception:
        tags = []
    try:
        photos = _json.loads(g("photos") or "[]")
    except Exception:
        photos = []
    price = num("price") or 0
    return {
        "article_no": f"P{r['id']}", "private_id": r["id"], "is_private": True,
        "source_article_no": g("source_article_no"), "source_saved_at": g("source_saved_at"),
        "visibility": g("visibility"), "created_by": g("created_by"),
        "complex_no": g("complex_no"), "complex_name": g("complex_name"),
        "trade_type": g("trade_type") or "", "type": g("type") or "",
        "area_name": g("area_name") or "", "area1_m2": num("area1_m2"), "area2_m2": num("area2_m2"),
        "floor_info": g("floor_info") or "", "direction": g("direction") or "",
        "price_text": _ml_price_text(price), "rent_price_text": _ml_price_text(num("rent_price") or 0),
        "price": price, "confirm_ymd": g("confirm_ymd") or (g("created_at") or "")[:10].replace("-", ""),
        "building_name": g("building_name") or "", "tags": tags or _pl_auto_tags(g, num),
        "same_addr_cnt": 0, "same_addr_min": 0, "same_addr_max": 0,
        "feature_desc": g("feature_desc") or "",
        "naver_url": "", "cp_name": "", "verification_type": "",
        "lat": num("lat"), "lng": num("lng"), "dong": g("dong") or "",
        "address": " ".join(x for x in [g("address") or "", g("address_detail") or ""] if x).strip(),
        "parking_total": None, "parking_per": num("parking"), "households": None,
        "approve_ymd": g("approve_ymd"), "builder": None, "mgmt_tel": None,
        "memo": g("memo") or "", "contact": g("contact") or "", "manager": g("manager") or "",
        "photos": photos,
        # 광고 문안을 이 카드만 보고 쓸 수 있어야 한다 — 필요한 값을 위로 올린다
        "area_py": num("area_py"), "room_cnt": num("room_cnt"), "bath_cnt": num("bath_cnt"),
        "total_floor": num("total_floor"), "settle_ymd": g("settle_ymd") or "",
        "move_in": g("move_in") or "", "maintenance_fee": num("maintenance_fee"),
        "deposit": num("deposit"), "owner_name": g("owner_name") or "",
        "heating": g("heating") or "", "elevator": g("elevator") or "",
        "options": g("options") or "", "ho": g("ho") or "",
        "ad_check": _pl_ad_check(g),
        # 비공개 전용 부가정보(상세에서 노출)
        "extra": {k: g(k) for k in ("ho", "room_cnt", "bath_cnt", "deposit", "maintenance_fee",
                                    "loan_amount", "move_in", "settle_ymd", "elevator", "pets", "heating",
                                    "options", "owner_name", "owner_tel", "total_floor", "area_py")},
    }


def _collect_private_listings(c, rid: str, uid: str, code: str | None, cat: str) -> list:
    _ensure_private_listings(c)
    where, params = _pl_visible_sql(uid)
    sql = f"SELECT * FROM private_listings WHERE realtor_id=? AND status='active' AND {where}"
    rows = c.execute(sql, [rid] + params).fetchall()
    out = [_pl_row_to_item(r) for r in rows]
    if code:
        want = _TRADE_KOR.get(code, "")
        out = [x for x in out if x["trade_type"] == want]
    if cat:
        out = [x for x in out if x["type"] == cat]
    return out


@app.get("/lounge/private-listings")
def lounge_private_list(user: dict = Depends(current_user)):
    with _reviews_db() as c:
        c.row_factory = sqlite3.Row
        rid = _require_member(c, user["id"])
        items = _collect_private_listings(c, rid, user["id"], None, "")
    items.sort(key=lambda x: x["confirm_ymd"] or "", reverse=True)
    return {"count": len(items), "listings": items}


# ── 자연어 빠른 입력 ────────────────────────────────────────────
# 중개사가 한 줄로 치거나 문자·카톡을 붙여넣으면 매물/고객 항목으로 옮긴다.
# 규칙 파서로는 실제 메시지를 못 다룬다(설계안 §2-2-3 실측: 카톡 타임스탬프를
# 입주월로, 호칭 '사장님'을 이름으로 잡는 조용한 오류). 그래서 모델을 쓰되
# 스키마를 강제하고, 확신 낮은 항목은 따로 표시해 사람이 확인하게 한다.

# 매물 유형은 우리가 쓰는 말로만 받는다. 자유 문자열로 두었더니 단지명('용산이편한세상')과
# 사전에 없는 말('단독주택'·'농지')이 들어와 유형별 분기가 전부 어긋났다.
_QA_TYPES = ["아파트", "오피스텔", "빌라", "단독", "상가", "사무실", "토지", "공장",
             "건물", "지식산업센터", "재개발", "원룸", "분양권"]

# 문장에서 물건 종류를 읽는다. 매물뿐 아니라 **고객 요건**에도 쓴다 —
# '역삼동 상가 찾는 손님'의 종류가 비어 있으면 매칭이 아파트를 물어 온다.
# 순서가 뜻을 가른다: '상가주택'은 상가가 아니라 건물이고, '아파트형공장'은
# 지식산업센터이며, '다가구 원룸건물'은 원룸이 아니라 단독이다.
_PTYPE_WORDS = [
    (r"지식산업센터|지산|아파트형\s*공장", "지식산업센터"),
    (r"상가주택|통건물|통임대|꼬마빌딩|빌딩", "건물"),
    (r"분양권|입주권", "분양권"),
    (r"재개발|재건축", "재개발"),
    (r"아파트|아팟", "아파트"),
    (r"오피스텔|오피(?!스)", "오피스텔"),
    (r"빌라|다세대|연립|타운하우스", "빌라"),
    (r"다가구|단독주택|전원주택|단독", "단독"),
    (r"원룸|투룸|고시원", "원룸"),
    (r"상가|점포|근린생활|근생|매장", "상가"),
    (r"사무실|사무소|오피스", "사무실"),
    # '대지'는 단독·공장 설명에도 나오지만(대지 60평 연면적 120평) 그쪽은 위에서 먼저 걸린다
    (r"토지|나대지|농지|임야|전답|필지|대지|땅", "토지"),
    (r"공장|창고", "공장"),
]


def _ptype_from_text(t) -> str:
    """문장 → 물건 종류. 못 읽으면 빈 문자열(억지로 정하지 않는다)."""
    t = str(t or "")
    if not t:
        return ""
    for pat, tp in _PTYPE_WORDS:
        if _re.search(pat, t):
            return tp
    return ""

