@app.get("/admin/realtor-verifications/{vid}/document")
def admin_realtor_verification_doc(vid: int, _admin: dict = Depends(admin_user)):
    with _reviews_db() as c:
        r = c.execute("SELECT doc_path FROM realtor_verifications WHERE id=?", (vid,)).fetchone()
    if not r or not r[0] or not Path(r[0]).exists():
        raise HTTPException(404, "문서 없음")
    ext = Path(r[0]).suffix.lower()
    mt = {".pdf": "application/pdf", ".png": "image/png", ".jpg": "image/jpeg",
          ".jpeg": "image/jpeg", ".webp": "image/webp"}.get(ext, "application/octet-stream")
    return Response(content=Path(r[0]).read_bytes(), media_type=mt)


@app.post("/admin/realtor-verifications/{vid}")
def admin_resolve_verification(vid: int, body: dict, _admin: dict = Depends(admin_user)):
    """승인 시 해당 user를 realtor_id에 연동(method='doc')."""
    action = (body.get("action") or "").strip()   # approve | reject
    note = body.get("admin_note") or None
    with _reviews_db() as c:
        r = c.execute("SELECT user_id, realtor_id, status, role, claimed_name, doc_path "
                      "FROM realtor_verifications WHERE id=?", (vid,)).fetchone()
        if not r:
            raise HTTPException(404, "없음")
        uid, rid = r[0], (body.get("realtor_id") or r[1])
        vrole = r[3] or "owner"
        if action == "approve":
            if not rid:
                raise HTTPException(400, "연동할 realtor_id가 필요합니다")
            c.execute(
                "INSERT INTO realtor_members(user_id,realtor_id,method,role,status,staff_name,updated_at) "
                "VALUES(?,?,'doc',?,'active',?,datetime('now')) "
                "ON CONFLICT(user_id) DO UPDATE SET realtor_id=excluded.realtor_id, method='doc', "
                "role=excluded.role, status='active', staff_name=excluded.staff_name, "
                "updated_at=datetime('now')",
                (uid, rid, vrole, (r[4] if vrole != "owner" else None)))
            c.execute("UPDATE realtor_verifications SET status='approved', realtor_id=?, "
                      "admin_note=?, reviewed_at=datetime('now'), doc_path=NULL WHERE id=?", (rid, note, vid))
        elif action == "reject":
            c.execute("UPDATE realtor_verifications SET status='rejected', admin_note=?, "
                      "reviewed_at=datetime('now'), doc_path=NULL WHERE id=?", (note, vid))
        else:
            raise HTTPException(400, "action must be approve|reject")
        c.commit()
    # 인증 서류 원본은 확인 즉시 파기(입주민·리뷰 인증과 동일 원칙) — DB 경로 제거 후 물리 삭제
    _docp = r[5]
    if _docp and Path(_docp).exists():
        try: Path(_docp).unlink()
        except OSError: pass
    if action == "approve" and rid and str(rid).startswith("vw"):
        _provision_vworld_office(str(rid))
        _threading.Thread(target=_auto_attribute_hidden_listings, args=(str(rid),), daemon=True).start()
    if action == "approve":
        try:
            _send_web_push([uid], "중개사 인증 승인 완료 🎉",
                           "관리자 확인이 끝났어요. 이제 콕집 중개사의 모든 기능을 쓸 수 있습니다.",
                           url="/biz", tag="verify-ok")
        except Exception:
            pass
    return {"ok": True}


